/* Savol banki — ЗРУ-684 · ПП-332 · ВМ-276 · ПҚ-104
   239 ta savol · lex.uz amaldagi tahririga qarshi tekshirilgan (2026-08-03) */
window.QUESTIONS = [{"id":"vm-b-01","doc":"ВМ-276","topic":"Umumiy","ref":"п.2","difficulty":1,"q":"ВМ-276 п.2 dagi ta'rifga ko'ra «авансовый платеж» nimalardan tashkil topadi?","options":[{"t":"Faqat задаток dan","ok":false,"why":"Задаток авансовый платеж ning bir qismi, lekin yolg'iz o'zi emas — п.2 da ikki element birgalikda ko'rsatilgan"},{"t":"Комиссионный сбор va задаток yig'indisidan","ok":true,"why":"п.2 aynan shunday ta'riflaydi: аванс to'lovi = давлат харидлари электрон тизими операторининг комиссионный сбор i + томонларнинг задатоги"},{"t":"Shartnoma summasining 15% oldindan to'lovidan (предоплата)","ok":false,"why":"Bu shartnoma bo'yicha предоплата sharti bilan aralashtiriladi (п.23), п.2 ta'rifi bilan aloqasi yo'q"},{"t":"Faqat комиссионный сбор dan","ok":false,"why":"Faqat комиссионный сбор — bu byudjet buyurtmachisi uchun amaldagi holat (п.8), umumiy ta'rif emas"}],"exp":"ВМ-276 п.2 ga ko'ra «авансовый платеж» = elektron tizim operatorining комиссионный сбор i + tomonlarning задатоги. п.8 esa uni subyektlar bo'yicha ajratadi: korporativ buyurtmachi va ishtirokchilar ikkalasini ham, byudjet buyurtmachisi faqat комиссионный сбор ni РКП dagi shaxsiy hisobiga o'tkazadi.","tags":["ta'rif","to'lov"]},{"id":"vm-b-02","doc":"ВМ-276","topic":"Umumiy","ref":"п.2","difficulty":1,"q":"ВМ-276 п.2 bo'yicha РКП (расчетно-клиринговая палата) qanday vazifani bajaradi?","options":[{"t":"Elektron tizim оператори ning tarkibiy bo'linmasi bo'lib, ягона шартномалар реестри ni yuritadi","ok":false,"why":"Ikki xato bir joyda: п.2 ga ko'ra РКП оператор ning emas, давлат харидлари электрон тизими ning tarkibiy bo'linmasi; ягона шартномалар реестри ni esa ваколатли орган yuritadi (п.206)"},{"t":"Davlat xaridlari bo'yicha shikoyatlarni ko'rib chiqadi","ok":false,"why":"Shikoyatlar qonunchilikda belgilangan alohida tartibda, Давлат харидлари соҳасидаги шикоятларни кўриб чиқиш комиссияси orqali ko'riladi (п.163, п.214) — РКП vakolatiga kirmaydi"},{"t":"Ягона таъминотчилар реестри ni har yili qayta ko'rib chiqadi","ok":false,"why":"Amaldagi tahrirda bu Саноат кооперацияси ва давлат харидлари агентлиги ning (Рақобат қўмитаси, Техник тартибга солиш агентлиги va Markaz bilan birgalikda) vazifasi — Қарор п.3¹, ВМ-393 tahriri; РКП emas"},{"t":"Давлат харидлари электрон тизими ning tarkibiy bo'linmasi bo'lib, аванс to'lovlarini депонирование qilish va hisobga olish orqali ishtirokchilarga elektron xaridlarga kirishni ta'minlaydi","ok":true,"why":"п.2 ta'rifi aynan shunday: РКП — электрон тизим ning tarkibiy bo'linmasi, funksiyasi депонирование va hisobga olish"}],"exp":"ВМ-276 п.2 РКП ni давлат харидлари электрон тизими ning tarkibiy bo'linmasi sifatida ta'riflaydi (оператор ning bo'linmasi EMAS — bu tez-tez uchraydigan xato): u shartnoma majburiyatlarini bajaruvchi ishtirokchilarning аванс to'lovlarini депонирование qiladi va hisobga oladi. Amaliyotda РКП orqali задаток bloklanadi (п.13) va ijro tasdiqlangach to'lov o'tkaziladi (п.31-32).","tags":["ta'rif","operator"]},{"id":"vm-b-03","doc":"ВМ-276","topic":"Umumiy","ref":"Қарор п.3¹","difficulty":2,"q":"Qarorning 3¹-bandiga ko'ra, 01.01.2026 dan byudjet buyurtmachisi tovarlar bo'yicha xariddan oldin nima qiladi?","options":[{"t":"O'z reja-grafigiga biriktirilgan mahalliy ishlab chiqaruvchilar ofertalarini o'rganadi va talab/ehtiyojlariga mos ofertani tanlaydi","ok":true,"why":"Қарор п.3¹ (УП-259, 26.12.2025 tahriri, kuchga kirish 01.01.2026) aynan shu majburiyatni belgilaydi; ofertadagi texnik parametrlar mos kelmasa boshqa xarid usullariga o'tish mumkin"},{"t":"Barcha xaridlarni faqat «Миллий магазин» sahifasi orqali amalga oshiradi","ok":false,"why":"«Миллий магазин» — «электронный магазин» ning qo'shimcha sahifasi (п.45-46), majburiy yagona kanal emas"},{"t":"Mahalliy ishlab chiqaruvchilar bilan protsedurasiz to'g'ridan-to'g'ri shartnoma tuzadi","ok":false,"why":"Oferta tanlash прямой договор asosini bermaydi — прямой договор faqat ЗРУ-684 71-moddasi hollarida (п.185)"},{"t":"Har bir xarid uchun Iqtisodiyot va moliya vazirligidan alohida ruxsat oladi","ok":false,"why":"Bunday ruxsat talabi ВМ-276 da yo'q; amaldagi tahrirda vazirlik bu rolda umuman ko'rsatilmagan — Ягона таъминотчилар реестри ni Саноат кооперацияси ва давлат харидлари агентлиги qayta ko'rib chiqadi (Қарор п.3¹)"}],"exp":"Қарор п.3¹ ning ikkinchi xatboshisi: 01.01.2026 dan byudjet buyurtmachisi tovarlar bo'yicha reja-grafigiga biriktirilgan mahalliy ishlab chiqaruvchilar ofertalarini o'rganishi va mosini tanlashi shart; texnik parametrlar ehtiyojga mos kelmasa — boshqa xarid usullaridan foydalanadi. Birinchi xatboshi ВМ-393 (20.07.2026) tahririda: Ягона таъминотчилар реестри ro'yxatini Саноат кооперацияси ва давлат харидлари агентлиги Рақобат қўмитаси, Техник тартибга солиш агентлиги va ГУ «Лойиҳалар ва харидлар самарадорлигини ошириш маркази» bilan birgalikda har yil yakuni bo'yicha qayta ko'rib chiqadi. Положение п.6¹ ga ko'ra reja-grafik joylashtirilganda ma'lumot mahalliy ishlab chiqaruvchilarga avtomatik yuboriladi.","tags":["mahalliy ishlab chiqaruvchi","reja-grafik"]},{"id":"vm-b-04","doc":"ВМ-276","topic":"Umumiy","ref":"п.5","difficulty":2,"q":"Reja-grafiklarga o'zgartirish va to'ldirishlar qachon kiritilishi mumkin?","options":[{"t":"Xarid protsedurasidan kamida 5 ish kuni oldin","ok":false,"why":"5 ish kuni — bu отбор va аукцион e'loni muddati (п.78, п.49), reja-grafik o'zgartirishi emas"},{"t":"Xarid protsedurasidan kamida 10 ish kuni oldin","ok":false,"why":"10 ish kuni — g'olib aniqlangandan keyin shartnoma tuzish muddati (п.103, п.161)"},{"t":"Xarid protsedurasidan kamida 3 ish kuni oldin","ok":true,"why":"п.5 aynan shu muddatni belgilaydi — o'zgartirish protseduradan ≥3 ish kuni oldin kiritiladi"},{"t":"Xohlagan vaqtda, muddat cheklovisiz","ok":false,"why":"п.5 qat'iy muddat belgilagan; cheklovsiz o'zgartirish ishtirokchilar uchun oldindan bilish imkonini yo'qotadi"}],"exp":"ВМ-276 п.5: reja-grafiklar ЗРУ-684 29-moddasi tartibida portalga joylashtiriladi, o'zgartirish va to'ldirishlar esa xarid protsedurasidan kamida 3 ish kuni oldin kiritilishi mumkin. Ekspertizada reja-grafik va e'lon sanalari solishtiriladi — kech kiritilgan o'zgartirish protsedura qonuniyligini shubha ostiga qo'yadi.","tags":["muddat","reja-grafik"]},{"id":"vm-b-05","doc":"ВМ-276","topic":"Umumiy","ref":"п.6","difficulty":2,"q":"ВМ-276 п.6 ga ko'ra reja-grafikda quyidagilardan qaysi biri majburiy ko'rsatiladi?","options":[{"t":"G'olib ishtirokchining nomi va СТИР raqami","ok":false,"why":"G'olib xarid protsedurasi yakunida aniqlanadi (п.96, п.156) — reja-grafik esa xariddan oldin tuziladi"},{"t":"Xaridni o'tkazish oyi","ok":true,"why":"п.6 majburiy tarkibida aynan «месяц проведения закупок» — xaridni o'tkazish oyi ko'rsatilgan"},{"t":"Xarid komissiyasi a'zolarining ro'yxati","ok":false,"why":"Komissiya ЗРУ-684 20, 57 va 65-moddalari tartibida tuziladi (п.59, п.108) va reja-grafik elementi emas"},{"t":"Shartnoma loyihasining to'liq matni","ok":false,"why":"Shartnoma loyihasi xarid hujjatlari tarkibida ishlab chiqiladi (п.66, п.115), reja-grafikda emas"}],"exp":"ВМ-276 п.6 reja-grafikning majburiy tarkibini belgilaydi: xarid predmeti; predmet miqdori va narxi; xaridni o'tkazish oyi; buyurtmachi nomi va manzili; moliyalashtirish manbalari va muddatlari; yetkazib berish/ish bajarish/xizmat ko'rsatish joyi (manzili). Ekspertizada arizadagi predmet va summa reja-grafikdagiga mos kelishi tekshiriladi.","tags":["reja-grafik","tarkib"]},{"id":"vm-b-06","doc":"ВМ-276","topic":"Umumiy","ref":"п.8","difficulty":3,"q":"Byudjet buyurtmachisi РКП dagi shaxsiy hisobga nimani o'tkazadi?","options":[{"t":"Комиссионный сбор va задаток yig'indisini","ok":false,"why":"Bu korporativ buyurtmachi va ishtirokchilar uchun belgilangan tartib (п.8), byudjet buyurtmachisi uchun emas"},{"t":"Shartnoma summasining 3% ini задаток sifatida","ok":false,"why":"3% — «электронный магазин» va аукцион da ishtirokchi задатоги (п.14), byudjet buyurtmachisining аванс to'lovi emas"},{"t":"Hech nimani — byudjet buyurtmachisi РКП dan umuman foydalanmaydi","ok":false,"why":"Отбор va tender shartnomasi bo'yicha РКП shaxsiy hisobisiz to'laydi (п.23), lekin комиссионный сбор baribir РКП ga o'tkaziladi"},{"t":"Faqat комиссионный сбор ni — задаток talab qilinmaydi","ok":true,"why":"п.8 aynan shuni belgilaydi: byudjet buyurtmachisi uchun faqat operator komissiya yig'imi, задаток o'tkazish talab qilinmaydi"}],"exp":"ВМ-276 п.8: korporativ buyurtmachi va ishtirokchilar РКП ga комиссионный сбор + задаток o'tkazadi, byudjet buyurtmachisi esa faqat комиссионный сбор ni; band alohida ta'kidlaydi — byudjet buyurtmachisidan задаток o'tkazish talab qilinmaydi. п.10 ga ko'ra byudjet buyurtmachisi uchun qo'shimcha shart — e'lon yoki oferta summasining ИСУГФ da bloklangan bo'lishi.","tags":["to'lov","byudjet"]},{"id":"vm-b-07","doc":"ВМ-276","topic":"Tender","ref":"п.14","difficulty":2,"q":"«Электронный магазин» da ishtirokchining задатоги qanday miqdorda belgilanadi?","options":[{"t":"Ishtirokchi ofertasi qiymatining 3% miqdorida","ok":true,"why":"п.14 «электронный магазин» uchun aynan ofertaning 3% ini belgilaydi"},{"t":"Стартовая цена ning 5% miqdorida","ok":false,"why":"5% — bu tender uchun taklif ta'minotining yuqori chegarasi (п.15), «электронный магазин» emas"},{"t":"Ishtirokchi ofertasining 10% miqdorida","ok":false,"why":"10% ВМ-276 da qo'shimcha ish va xizmatlar qiymatining chegarasi (п.215), задаток stavkasi emas"},{"t":"Komissiya belgilaydigan, lekin 3% dan oshmaydigan miqdorda","ok":false,"why":"Komissiya belgilaydigan «3% dan oshmasin» qoidasi отбор uchun (п.15); «электронный магазин» da 3% qat'iy stavka"}],"exp":"ВМ-276 п.14: korporativ buyurtmachilar va ishtirokchilar РКП dagi shaxsiy hisobiga задаток kiritadi — «электронный магазин» da ishtirokchi ofertasi qiymatining 3% i, аукцион da esa стартовая цена ning 3% i. Отбор va tenderda esa п.15 boshqacha ishlaydi: задаток talab qilish zarurati va miqdorini xarid komissiyasi belgilaydi, lekin отбор da 3%, tenderda 5% dan oshmasligi kerak.","tags":["задаток","elektron magazin"]},{"id":"vm-b-08","doc":"ВМ-276","topic":"Tender","ref":"п.15","difficulty":3,"q":"Отбор va tender uchun taklif ta'minoti (задаток) ning yuqori chegarasi qanday?","options":[{"t":"Отбор — 5%, tender — 3% dan oshmasligi kerak","ok":false,"why":"Foizlar almashtirilgan: п.15 da отбор uchun 3%, tender uchun 5% belgilangan"},{"t":"Ikkalasi ham 3% dan oshmasligi kerak","ok":false,"why":"3% отбор uchun to'g'ri, lekin tenderda chegara 5%"},{"t":"Отбор — 3%, tender — 5% dan oshmasligi kerak","ok":true,"why":"п.15 aynan shu ikki chegarani belgilaydi (tovar/ish/xizmat qiymatidan), miqdorni esa xarid komissiyasi belgilaydi"},{"t":"Ikkalasi ham 5% dan oshmasligi kerak","ok":false,"why":"5% tender uchun to'g'ri, lekin отбор da chegara 3%"}],"exp":"ВМ-276 п.15: отбор va tenderda задаток kiritish zarurati va miqdorini xarid komissiyasi belgilaydi, lekin отбор da tovar (ish, xizmat) qiymatining 3%, tenderda 5% dan oshmasligi kerak. G'olib shartnoma tuzishdan bosh tortsa задаток qaytarilmaydi — buyurtmachining tegishli hisobiga (byudjet buyurtmachisining budjetdan tashqari hisobiga) o'tkaziladi. Komissiya задаток dan tashqari залог yoki гарантия shaklida ta'minot ham talab qilishi mumkin.","tags":["задаток","chegara"]},{"id":"vm-b-09","doc":"ВМ-276","topic":"Tender","ref":"п.39","difficulty":3,"q":"Byudjet buyurtmachisi «электронный магазин» orqali bir xil turdagi tovarlarni yiliga qancha miqdorda xarid qila oladi?","options":[{"t":"5 000 БҲМ gacha","ok":false,"why":"Bunday chegara ВМ-276 п.39 da yo'q — qo'shni raqam bilan chalg'itadi"},{"t":"10 000 БҲМ gacha","ok":true,"why":"п.39 byudjet buyurtmachisi uchun bir xil turdagi tovarlar bo'yicha bir moliya yili limitini aynan 10 000 БҲМ qilib belgilaydi"},{"t":"25 000 БҲМ gacha","ok":false,"why":"25 000 БҲМ — рамочное соглашение uchun quyi chegara (п.170) hamda прямой договор bo'yicha korporativ buyurtmachi uchun Markaz kompleks ekspertizasi bo'sag'asi (п.189)"},{"t":"6 000 БҲМ gacha","ok":false,"why":"6 000 БҲМ — прямой договор bo'yicha byudjet buyurtmachisi uchun Markaz kompleks ekspertizasi bo'sag'asi (п.189), «электронный магазин» limiti emas"}],"exp":"ВМ-276 п.39: milliy klassifikator bo'yicha guruhlangan bir xil turdagi tovarlar «электронный магазин» orqali byudjet buyurtmachisi uchun bir moliya yilida 10 000 БҲМ dan oshmagan summaga xarid qilinadi; bir xil turdagi ish va xizmatlar bo'yicha limit esa byudjet uchun 500 БҲМ, korporativ buyurtmachi uchun 1 000 БҲМ. Limitning oshirilishi predmetni sun'iy bo'lakchalarga bo'lish (дробление) belgisi bo'lishi mumkin.","tags":["chegara","elektron magazin"]},{"id":"vm-b-10","doc":"ВМ-276","topic":"Tender","ref":"п.43","difficulty":3,"q":"«Электронный магазин» da narx 20% va undan ko'p past bo'lsa, ofertasi 2 500 БҲМ dan oshmaydigan ishtirokchidan qancha qo'shimcha задаток talab qilinadi?","options":[{"t":"1 000 БҲМ dan oshmagan miqdorda","ok":false,"why":"1 000 БҲМ chegarasi oferta summasi 2 500 БҲМ dan oshgan holatda qo'llaniladi"},{"t":"Farq summasining to'liq miqdorida, cheklovsiz","ok":false,"why":"Qo'shimcha задаток farq miqdorida hisoblanadi, lekin п.43 unga aniq yuqori chegara qo'yadi"},{"t":"Qo'shimcha задаток umuman talab qilinmaydi","ok":false,"why":"Aksincha — qo'shimcha задаток bo'lmasa taklif elektron tizim tomonidan avtomatik rad etiladi"},{"t":"100 БҲМ dan oshmagan miqdorda","ok":true,"why":"п.43 oferta summasi 2 500 БҲМ dan oshmaganda qo'shimcha задаток ni 100 БҲМ bilan cheklaydi"}],"exp":"ВМ-276 п.43 («электронный магазин» — запрос цен) va п.54 (аукцион) демпинг qoidasi: narx tanlangan oferta/стартовая цена dan 20 va undan ko'p foizga past bo'lsa, ishtirokchi oldindan farq miqdorida qo'shimcha задаток kiritishi shart. Oferta/стартовая цена 2 500 БҲМ dan oshmasa — qo'shimcha задаток 100 БҲМ dan, oshsa — 1 000 БҲМ dan oshmasligi kerak. Qo'shimcha задаток bo'lmasa taklif avtomatik rad etiladi.","tags":["demping","задаток"]},{"id":"vm-b-11","doc":"ВМ-276","topic":"Tender","ref":"п.49","difficulty":2,"q":"Аукцион o'tkazish haqidagi e'lon qancha muddat oldin joylashtiriladi?","options":[{"t":"Kamida 5 ish kuni oldin","ok":true,"why":"п.49 аукцион tugash sanasigacha aynan «kamida 5 ish kuni» muddatini belgilaydi"},{"t":"Kamida 12 ish kuni oldin","ok":false,"why":"12 ish kuni — tender e'loni uchun quyi chegara (п.128), аукцион uchun emas"},{"t":"Kamida 3 ish kuni oldin","ok":false,"why":"3 ish kuni — reja-grafikka o'zgartirish kiritish muddati (п.5)"},{"t":"Kamida 7 kalendar kun oldin","ok":false,"why":"7 kun — аукцион da yetkazib berishning minimal muddati (п.55), e'lon muddati emas"}],"exp":"ВМ-276 п.49: buyurtmachi аукцион tugash sanasidan kamida 5 ish kuni oldin reja-grafikka muvofiq e'lonni maxsus axborot portali orqali elektron tizimga joylashtiradi. Bu отбор uchun belgilangan 5 ish kuni (п.78) bilan bir xil, ammo tenderdan farq qiladi — u yerda 12-30 ish kuni oralig'i qo'llaniladi (п.128). Diqqat: 01.01.2026 dan kuchga kirgan п.56¹ («местный аукцион» qo'shimcha sahifasi, УП-259) byudjet buyurtmachisi uchun e'lonni kamida 2 ish kuniga joylashtirishni nazarda tutadi — bu alohida rejim, umumiy 5 ish kuni qoidasi o'rniga emas.","tags":["muddat","auktsion"]},{"id":"vm-b-12","doc":"ВМ-276","topic":"Tender","ref":"п.52","difficulty":2,"q":"Аукцион da narx pasaytirish qadami (размер шага) eng ko'pi bilan qancha bo'lishi mumkin?","options":[{"t":"Стартовая цена ning 5% i","ok":false,"why":"5% — tenderda taklif ta'minotining yuqori chegarasi (п.15), аукцион qadami emas"},{"t":"Стартовая цена ning 10% i","ok":false,"why":"10% — shartnoma bo'yicha qo'shimcha ish va xizmatlar qiymatining chegarasi (п.215)"},{"t":"Стартовая цена ning 3% i","ok":true,"why":"п.52 narxni pog'onali pasaytirishda qadamni стартовая цена ning maksimum 3% i bilan cheklaydi"},{"t":"Оператор ваколатли орган bilan kelishmasdan, xohlagan foizni belgilaydi","ok":false,"why":"п.52 ikki cheklov qo'yadi: qadamni оператор ваколатли орган bilan KELISHGAN holda belgilaydi va u стартовая цена ning 3% idan oshmaydi"}],"exp":"ВМ-276 п.2 «размер шага» ni стартовая цена va/yoki oldingi ishtirokchi narxini pasaytiruvchi, foizda belgilanadigan pul oralig'i sifatida ta'riflaydi; п.52 esa uni ваколатли орган bilan kelishilgan holda оператор belgilashini va стартовая цена ning 3% idan oshmasligini nazarda tutadi. Bir ishtirokchi belgilangan qadam miqdorida narxni ketma-ket bir necha marta pasaytirishi mumkin. Diqqat: 3% raqami п.14 dagi задаток stavkasi bilan bir xil, lekin bu ikki har xil institut.","tags":["auktsion","qadam"]},{"id":"vm-b-13","doc":"ВМ-276","topic":"Tender","ref":"п.55","difficulty":3,"q":"Аукцион natijasida tovarlarni yetkazib berish muddati kamida qancha bo'lishi kerak?","options":[{"t":"Kamida 5 ish kuni","ok":false,"why":"5 ish kuni — аукцион e'loni muddati (п.49), yetkazib berish muddati emas"},{"t":"Kamida 7 kun","ok":true,"why":"п.55 yetkazib berish muddatini kamida 7 kun qilib belgilaydi (miqdor, hajm, noyoblik va ishlab chiqarish/import vaqti hisobga olinadi)"},{"t":"Kamida 10 ish kuni","ok":false,"why":"10 ish kuni — g'olib aniqlangandan keyin shartnoma tuzish muddati (п.103, п.161)"},{"t":"Kamida 3 ish kuni","ok":false,"why":"3 ish kuni — tovar qabul qilingani haqida ma'lumot kiritish muddati (п.28-29)"}],"exp":"ВМ-276 п.55: аукцион da yetkazib berish muddati kamida 7 kun bo'lishi kerak — tovar miqdori, hajmi, noyobligi hamda respublika hududida ishlab chiqarish yoki importga sarflanadigan vaqt va boshqa xususiyatlar hisobga olingan holda. Ayni paytda yetkazib beruvchi shartnomada belgilangan muddatdan oldin ham yetkazib berishi mumkin. Bu norma sun'iy qisqa muddat orqali raqobatni cheklashning oldini oladi.","tags":["muddat","auktsion"]},{"id":"vm-b-14","doc":"ВМ-276","topic":"Shartnoma","ref":"п.31-32","difficulty":2,"q":"Tovar qabul qilingani haqida ma'lumot kiritilgach, operator to'lov topshirig'ini qancha muddatda yuboradi?","options":[{"t":"3 ish kuni ichida","ok":false,"why":"3 ish kuni — buyurtmachi tomonidan tovar qabul qilingani haqida ma'lumot kiritish muddati (п.28-29), operator harakati emas"},{"t":"10 ish kuni ichida","ok":false,"why":"10 ish kuni — korporativ buyurtmachining РКП dagi shaxsiy hisobiga summa o'tkazish muddati (п.24)"},{"t":"5 ish kuni ichida","ok":false,"why":"Bunday muddat п.31-32 da yo'q — qo'shni raqam bilan chalg'itadi"},{"t":"1 ish kuni ichida (shu muddatda задаток ham qaytariladi)","ok":true,"why":"п.31-32 operator uchun 1 ish kuni muddatini belgilaydi: elektron to'lov topshirig'i yuboriladi va задаток blokdan chiqarilib qaytariladi"}],"exp":"ВМ-276 п.28-29 ga ko'ra buyurtmachi tovar (ish, xizmat) to'liq qabul qilingach 3 ish kuni ichida operatorga (korporativ) yoki ИСУГФ ga (byudjet) ma'lumot kiritadi; п.31 ga ko'ra operator 1 ish kuni ichida elektron to'lov topshirig'ini shakllantirib yuboradi va ijrochi hamda korporativ buyurtmachining задатоги ni blokdan chiqaradi; п.32 ga ko'ra отбор/tender natijasida shartnoma tuzilgach ham задаток 1 ish kuni ichida qaytariladi. Zanjirning buzilishi п.34 bo'yicha mablag'larni bloklashga olib keladi.","tags":["muddat","operator","to'lov"]},{"id":"vm-b-15","doc":"ВМ-276","topic":"Tender","ref":"п.78","difficulty":2,"q":"Tasdiqlangan отбор xarid hujjatlari, shartnoma loyihasi va e'lon qachon elektron tizimga joylashtiriladi?","options":[{"t":"Takliflar qabul qilish muddati tugashidan kamida 5 ish kuni oldin","ok":true,"why":"п.78 aynan shu muddatni belgilaydi — отбор uchun quyi chegara 5 ish kuni"},{"t":"Takliflar qabul qilish muddati tugashidan kamida 12 ish kuni oldin","ok":false,"why":"12 ish kuni — tender uchun quyi chegara (п.128), отбор uchun emas"},{"t":"Takliflar qabul qilish muddati tugashidan kamida 2 ish kuni oldin","ok":false,"why":"2 ish kuni — tushuntirish berish va dastlabki elektron protokolni muhokama qilish muddati (п.87, п.98)"},{"t":"Komissiya qarori qabul qilingan kundan 3 ish kuni ichida","ok":false,"why":"3 ish kuni — komissiya yig'ilishi protokolini tizimga joylashtirish muddati (п.102), e'lon muddati emas"}],"exp":"ВМ-276 п.78: tasdiqlangan отбор xarid hujjatlari, shartnoma loyihasi va отбор o'tkazish haqidagi e'lon ishtirokchilardan takliflar qabul qilish muddati tugash sanasidan kamida 5 ish kuni oldin elektron tizimga joylashtiriladi. Diqqat — отбор da faqat quyi chegara bor, tenderda esa п.128 bo'yicha ham quyi (12), ham yuqori (30 ish kuni) chegara mavjud.","tags":["muddat","otbor"]},{"id":"vm-b-16","doc":"ВМ-276","topic":"Tender","ref":"п.87","difficulty":2,"q":"Отбор da ishtirokchi ochiq elektron chat orqali tushuntirish so'rasa, buyurtmachi qancha muddatda javob beradi?","options":[{"t":"1 ish kuni ichida","ok":false,"why":"1 ish kuni — задаток (taklif ta'minoti) maqbulligini tasdiqlash so'roviga javob muddati: отбор da п.87 ning oxirgi xatboshisi, tenderda п.142; tushuntirish muddati emas"},{"t":"5 ish kuni ichida","ok":false,"why":"5 ish kuni — отбор e'loni muddati (п.78), tushuntirish muddati emas"},{"t":"2 ish kuni ichida","ok":true,"why":"п.87 buyurtmachi uchun aynan 2 ish kuni muddatini belgilaydi (javob ochiq elektron chat orqali beriladi)"},{"t":"3 ish kuni ichida","ok":false,"why":"3 ish kuni — komissiya yig'ilishi protokolini elektron tizimga joylashtirish muddati (п.102)"}],"exp":"ВМ-276 п.87: ishtirokchi ochiq elektron chat orqali tushuntirish so'raydi, buyurtmachi so'rov kelgan sanadan 2 ish kuni ichida chat orqali javob beradi. Muhimi — tushuntirishlar xarid hujjatlarining mohiyatini o'zgartira olmaydi. Shu bandning oxirgi xatboshisi alohida holatni belgilaydi: задаток maqbulligini tasdiqlash so'roviga javob 1 ish kuni. Tenderda bir xil bo'linish: п.140-141 — 2 ish kuni, п.142 — 1 ish kuni.","tags":["muddat","otbor","tushuntirish"]},{"id":"vm-b-17","doc":"ВМ-276","topic":"Tender","ref":"п.90","difficulty":2,"q":"ВМ-276 п.90 da отбор bo'yicha taklifni avtomatik chiqarib yuborish asoslaridan qaysi biri ko'rsatilgan?","options":[{"t":"Ishtirokchining lokalizatsiya darajasi 15% dan past bo'lsa","ok":false,"why":"15% — mahalliy ishlab chiqaruvchiga qo'shimcha ball formulasidagi koeffitsient (п.95¹), rad etish asosi emas"},{"t":"Taklif narxi стартовая цена dan yuqori bo'lsa","ok":true,"why":"п.90 avtomatik chiqarib yuborish asoslaridan biri sifatida aynan shuni ko'rsatadi"},{"t":"Ishtirokchi bitta lotga ikkita taklif yuborsa","ok":false,"why":"Bir lotga bitta taklif qoidasi п.84 da belgilangan, lekin п.90 dagi avtomatik chiqarib yuborish asoslari ro'yxatiga kirmaydi"},{"t":"Taklif narxi boshqa ishtirokchilarnikidan 20% past bo'lsa","ok":false,"why":"20% демпинг qoidasi «электронный магазин» (п.43) va аукцион (п.54) da qo'shimcha задаток talab qiladi, п.90 asosi emas"}],"exp":"ВМ-276 п.90 ga ko'ra tizim taklifni avtomatik chiqarib yuboradi, agar: taklif narxi стартовая цена dan yuqori bo'lsa; majburiy maydonlar to'ldirilmagan bo'lsa; majburiy fayllar mavjud bo'lmasa. Fayl va taklif mosligini tekshirish esa mas'ul kotib zimmasida (п.88-90). Tenderda bir xil qoida — п.145.","tags":["otbor","rad etish"]},{"id":"vm-b-18","doc":"ВМ-276","topic":"Tender","ref":"п.98-101","difficulty":2,"q":"Отбор bo'yicha dastlabki elektron protokol muhokama uchun qancha muddatga joylashtiriladi?","options":[{"t":"1 ish kuniga","ok":false,"why":"1 ish kuni — operatorning задаток blokdan chiqarish va qaytarish muddati (п.31-32), muhokama muddati emas"},{"t":"5 ish kuniga","ok":false,"why":"5 ish kuni — отбор e'loni muddati (п.78)"},{"t":"3 ish kuniga","ok":false,"why":"3 ish kuni — komissiya yig'ilishi protokolini elektron tizimga joylashtirish muddati (п.102)"},{"t":"2 ish kuniga (shu muddatda e'tiroz kelmasa — shartnoma tuziladi)","ok":true,"why":"п.98-100: protokol 2 ish kunga muhokamaga qo'yiladi, e'tiroz bo'lmasa shartnoma tuziladi"}],"exp":"ВМ-276 п.98-102: dastlabki elektron protokol rasmiylashtirilgan kuni elektron tizimda 2 ish kunga muhokama uchun joylashtiriladi; istalgan ishtirokchi e'tiroz yuborishi mumkin (п.99). 2 ish kuni ichida e'tiroz kelmasa shartnoma tuziladi (п.100); e'tiroz kelsa komissiya yana 2 ish kuni ichida ko'rib chiqadi (п.101), yig'ilish protokoli esa imzolangan kundan 3 ish kuni ichida tizimga joylashtiriladi (п.102).","tags":["muddat","otbor","protokol"]},{"id":"vm-b-19","doc":"ВМ-276","topic":"Shartnoma","ref":"п.103","difficulty":2,"q":"Отбор natijalari bo'yicha shartnoma qachon tuziladi?","options":[{"t":"G'olib aniqlanganidan keyin kechi bilan 10 ish kuni ichida","ok":true,"why":"п.103 aynan shu muddatni belgilaydi — shartnoma xarid hujjatlari va g'olib taklifi shartlari bo'yicha tuziladi"},{"t":"G'olib aniqlanganidan keyin kechi bilan 5 ish kuni ichida","ok":false,"why":"5 ish kuni — отбор e'loni muddati (п.78), shartnoma muddati emas"},{"t":"Dastlabki protokol joylashtirilgan kundan 3 ish kuni ichida","ok":false,"why":"3 ish kuni — protokolni tizimga joylashtirish muddati (п.102), shartnoma muddati emas"},{"t":"G'olib aniqlanganidan keyin 30 kalendar kun ichida","ok":false,"why":"30 ish kuni — tender e'loni uchun yuqori chegara (п.128); bu yerda kalendar kunga ham noto'g'ri almashtirilgan"}],"exp":"ВМ-276 п.103: отбор natijalari bo'yicha shartnoma g'olib aniqlangan paytdan kechi bilan 10 ish kunida tuziladi. п.104 ga ko'ra u elektron shaklda tuziladi va Ягона шартномалар реестри ga kiritiladi. Tenderda ham xuddi shu 10 ish kuni qo'llaniladi (п.161), рамочное соглашение ning 2-bosqichida ham (п.183).","tags":["muddat","shartnoma","otbor"]},{"id":"vm-b-20","doc":"ВМ-276","topic":"Tender","ref":"п.168","difficulty":2,"q":"Рамочное соглашение protsedurasidan kim foydalanishga haqli emas?","options":[{"t":"Korporativ buyurtmachi","ok":false,"why":"Aynan korporativ buyurtmachi bu protsedurani qo'llaydi (п.176)"},{"t":"Mahalliy ishlab chiqaruvchilar","ok":false,"why":"Ular protsedura ishtirokchisi bo'la oladi; п.168 dagi cheklov buyurtmachiga nisbatan"},{"t":"Byudjet buyurtmachisi","ok":true,"why":"п.168 to'g'ridan-to'g'ri byudjet buyurtmachisiga рамочное соглашение protsedurasini taqiqlaydi"},{"t":"Ягона таъминотчилар реестри dagi ta'minotchilar","ok":false,"why":"Реестр to'g'ri shartnoma instituti bilan bog'liq (п.190-196), рамочное соглашение bilan emas"}],"exp":"ВМ-276 п.168: рамочное соглашение 5-ilovadagi sxema bo'yicha o'tkaziladi va byudjet buyurtmachisi bu protseduradan foydalanishga haqli emas — u faqat korporativ buyurtmachilar uchun. Ekspertizada byudjet mablag'i bilan рамочное соглашение loyihasi kelsa, bu п.168 ga to'g'ridan-to'g'ri zid bo'ladi.","tags":["рамочное соглашение","subyekt"]},{"id":"vm-b-21","doc":"ВМ-276","topic":"Tender","ref":"п.170","difficulty":3,"q":"Рамочное соглашение protsedurasini qo'llash uchun bir bitim qiymati qanday bo'lishi kerak?","options":[{"t":"6 000 БҲМ dan ortiq","ok":false,"why":"6 000 БҲМ — byudjet buyurtmachisi uchun Markaz ekspertizasi bo'sag'asi (п.189), рамочное chegarasi emas"},{"t":"25 000 БҲМ dan ortiq","ok":true,"why":"п.170 bir рамочное соглашение qiymati uchun aynan 25 000 БҲМ dan ortiq shartini belgilaydi"},{"t":"10 000 БҲМ dan ortiq","ok":false,"why":"10 000 БҲМ — byudjet buyurtmachisi uchun «электронный магазин» orqali bir xil turdagi TOVAR ning bir moliya yilidagi limiti (п.39)"},{"t":"2 500 БҲМ dan ortiq","ok":false,"why":"2 500 БҲМ — демпинг holatida qo'shimcha задаток ning yuqori chegarasini aniqlovchi bo'sag'a (п.43, п.54)"}],"exp":"ВМ-276 п.170 uchta shart bir vaqtda bajarilishini talab qiladi: g'olibni aniqlash kriteriylari narx bilan birga miqdor va sifat bahosini ham o'z ichiga oladi; bir рамочное соглашение bo'yicha tovar (ish, xizmat) qiymati 25 000 БҲМ dan ortiq; korporativ buyurtmachining joriy ishlab chiqarish jarayonlari uchun uzluksizlikni ta'minlash zarurati (3 yildan ko'p bo'lmagan davr). п.173 ga ko'ra amal qilish muddati 3 yildan oshmaydi.","tags":["chegara","рамочное соглашение"]},{"id":"vm-b-22","doc":"ВМ-276","topic":"Tender","ref":"п.175","difficulty":3,"q":"Рамочное соглашение ning 1-bosqichida ishtirokchilar nimani taqdim etadi?","options":[{"t":"Ham texnik, ham narx qismini","ok":false,"why":"1-bosqichda narx taklifi umuman taqdim etilmaydi — narx faqat 2-bosqichdagi запрос цен da paydo bo'ladi"},{"t":"Faqat narx taklifini","ok":false,"why":"Bu teskari: п.175 ga ko'ra aynan narx emas, texnik qism taqdim etiladi"},{"t":"Texnik qism va to'liq shartnoma loyihasini","ok":false,"why":"Shartnoma va рамочное соглашение loyihalarini buyurtmachi xarid hujjatlariga ilova qiladi (п.176), ishtirokchi emas"},{"t":"Faqat texnik qismni — narx takliflari taqdim etilmaydi","ok":true,"why":"п.175 aynan shuni belgilaydi: 1-bosqichda faqat texnik qism"}],"exp":"ВМ-276 п.175: рамочное соглашение ning 1-bosqichi tender protseduralari (VI bob) bo'yicha o'tadi, ammo xarid hujjatlariga taklifning faqat texnik qismi taqdim etilishi va tovar (ish, xizmat) umumiy hajm hamda boshlang'ich narx doirasida yetkazilishi sharti kiritiladi; narx takliflari esa taqdim etilmaydi. Narx 2-bosqichdagi запрос цен orqali olinadi va п.182 ga ko'ra 1-bosqichda belgilangan стартовая цена doirasida bo'lishi shart.","tags":["рамочное соглашение","bosqich"]},{"id":"vm-b-24","doc":"ВМ-276","topic":"Tender","ref":"п.180-181","difficulty":3,"q":"Рамочное соглашение ning 2-bosqichida запрос цен yuborilganda ishtirokchilarga qancha muddat beriladi?","options":[{"t":"Kamida 2 ish kuni","ok":false,"why":"2 ish kuni — tushuntirish berish va dastlabki protokolni muhokama qilish muddati (п.87, п.98)"},{"t":"Kamida 3 ish kuni","ok":false,"why":"3 ish kuni — рамочное соглашение va uning asosidagi shartnoma haqidagi ma'lumotni portalga joylashtirish muddati (п.174, п.184)"},{"t":"Kamida 5 ish kuni","ok":true,"why":"п.180 запрос цен ga javob berish uchun aynan kamida 5 ish kunini belgilaydi"},{"t":"Kamida 12 ish kuni","ok":false,"why":"12 ish kuni — tender e'loni uchun quyi chegara (п.128), 2-bosqich muddati emas"}],"exp":"ВМ-276 п.180-181: korporativ buyurtmachi 1-bosqichdan o'tgan va рамочное соглашение tuzgan barcha ishtirokchilarga запрос цен yuboradi, ishtirokchilar taklif yuborish uchun kamida 5 ish kuniga ega. So'rovda рамочное соглашение ga havola, talab qilinadigan hajm va so'nggi muddat ko'rsatiladi. Har запрос цен bo'yicha faqat 1 g'olib aniqlanadi va 10 ish kunidan kechiktirmay shartnoma tuziladi (п.183).","tags":["muddat","рамочное соглашение"]},{"id":"vm-b-25","doc":"ВМ-276","topic":"Shartnoma","ref":"п.186-187","difficulty":2,"q":"To'g'ridan-to'g'ri shartnoma tuzilganda buyurtmachi ma'lumotni qachon maxsus axborot portaliga joylashtiradi va buning oqibati qanday?","options":[{"t":"10 ish kuni ichida; muddat buzilsa shartnoma bekor qilinadi","ok":false,"why":"10 ish kuni — g'olib aniqlangandan keyin shartnoma tuzish muddati; ВМ-276 bu yerda bekor qilish emas, to'lovni to'xtatish oqibatini belgilaydi"},{"t":"3 ish kuni ichida; ma'lumot joylashtirilmasa to'lov amalga oshirilmaydi","ok":true,"why":"п.186 muddatni, п.187 esa oqibatni aynan shunday belgilaydi"},{"t":"1 ish kuni ichida; muddat buzilsa jarima solinadi","ok":false,"why":"1 ish kuni — operatorning задаток bo'yicha muddati (п.31-32); jarima esa п.187 da nazarda tutilmagan"},{"t":"5 ish kuni ichida; oqibati belgilanmagan","ok":false,"why":"Muddat ham noto'g'ri, ham п.187 aniq oqibatni — to'lov qilinmasligini — belgilagan"}],"exp":"ВМ-276 п.186: tuzilgan to'g'ri shartnomalar haqidagi ma'lumot tuzilgan paytdan 3 ish kuni ichida maxsus axborot portaliga joylashtirilishi shart (qonunchilikda boshqacha nazarda tutilgan hollar bundan mustasno). п.187: ma'lumot joylashtirilmagan bo'lsa, bunday shartnomalar bo'yicha to'lov amalga oshirilmaydi. Yagona ta'minotchi bilan tuzilgan shartnomaga ham xuddi shu 3 ish kuni qo'llaniladi (п.192). Bu п.213 dagi Ягона реестр qoidasi bilan bir xil mantiqda ishlaydi.","tags":["muddat","to'g'ri shartnoma","to'lov"]},{"id":"vm-b-26","doc":"ВМ-276","topic":"Ekspertiza","ref":"п.189","difficulty":3,"q":"To'g'ridan-to'g'ri shartnoma bo'yicha Markaz kompleks ekspertizasi qaysi summagacha talab qilinmaydi?","options":[{"t":"Har qanday summada — to'g'ri shartnomalar umuman ekspertiza qilinmaydi","ok":false,"why":"п.189 faqat chegaradan past shartnomalarni ozod qiladi; chegaradan oshsa ekspertiza majburiy"},{"t":"Bir shartnoma bo'yicha 6 000 БҲМ gacha (byudjet buyurtmachisi uchun 25 000 БҲМ gacha)","ok":false,"why":"Chegaralar subyektlar bo'yicha almashtirilgan — byudjet uchun pastroq (6 000), umumiy holat uchun 25 000 БҲМ"},{"t":"Bir shartnoma bo'yicha 100 000 БҲМ gacha","ok":false,"why":"Bunday chegara ВМ-276 da yo'q"},{"t":"Bir shartnoma bo'yicha 25 000 БҲМ gacha (byudjet buyurtmachisi uchun — 6 000 БҲМ gacha)","ok":true,"why":"п.189 aynan shu ikki chegarani belgilaydi: shartnoma va unga qo'shimcha kelishuvlar bir shartnoma bo'yicha shu summagacha bo'lsa Markazga taqdim etilmaydi"}],"exp":"ВМ-276 п.189: Prezident farmon va qarorlari hamda Vazirlar Mahkamasi qarorlari bilan to'g'ri shartnoma asosida xarid qilishga ruxsat etilgan hollarda, shartnoma va unga qo'shimcha kelishuvlar bir shartnoma bo'yicha tovar (ish, xizmat) qiymati 25 000 БҲМ gacha (byudjet buyurtmachilari uchun — 6 000 БҲМ gacha) bo'lsa, Kompleks ekspertiza markazida kompleks ekspertizadan o'tkazilmaydi. Chegaradan oshsa — ekspertiza majburiy. Bu band Markaz vakolatining pastki chegarasi hisoblanadi.","tags":["chegara","ekspertiza","to'g'ri shartnoma"]},{"id":"vm-b-27","doc":"ВМ-276","topic":"Shartnoma","ref":"п.193-196","difficulty":2,"q":"Ягона таъминотчилар реестри ga kiritilmagan kontragent bilan to'g'ridan-to'g'ri shartnoma tuzish mumkinmi?","options":[{"t":"Yo'q — реестр da bo'lmagan kontragent bilan bunday shartnoma tuzib bo'lmaydi","ok":true,"why":"п.195 to'g'ridan-to'g'ri shuni belgilaydi: kontragent Реестр da bo'lmasa, buyurtmachi to'g'ri shartnoma tuzishga haqli emas"},{"t":"Ha, agar shartnoma summasi 25 000 БҲМ dan kam bo'lsa","ok":false,"why":"25 000 БҲМ — Markaz ekspertizasi bo'sag'asi (п.189); u Реестр da bo'lish talabini bekor qilmaydi"},{"t":"Ha, agar buyurtmachi asoslantirilgan xat taqdim etsa","ok":false,"why":"Asoslantirish Реестр talabini almashtirmaydi — Реестр vakolatli organ tomonidan yuritiladi (п.193)"},{"t":"Ha, agar ma'lumot 3 ish kuni ichida portalga joylashtirilsa","ok":false,"why":"3 ish kuni — ma'lumotni portalga joylashtirish muddati (п.186, п.192); u alohida talab bo'lib, Реестр shartini bekor qilmaydi"}],"exp":"ВМ-276 п.190-196: yagona ta'minotchidan xarid ЗРУ-684 72-moddasida belgilangan hollarda amalga oshiriladi; Реестр maxsus axborot portalida vakolatli organ tomonidan yuritiladigan axborot resursi (п.193), unda ruxsat etilgan tovar (ish, xizmat) ro'yxati va ta'minotchilar ro'yxati bo'ladi (п.194) hamda u umumfoydalanish uchun ochiq (п.196). п.195: kontragent Реестр da bo'lmasa, to'g'ri shartnoma tuzilishi mumkin emas. Ekspertizada avval kontragentning Реестр da borligi tekshiriladi.","tags":["yagona ta'minotchi","reyestr"]},{"id":"vm-b-28","doc":"ВМ-276","topic":"Shartnoma","ref":"п.213","difficulty":2,"q":"Ягона шартномалар реестри ga kiritilmagan shartnomaning oqibati nima?","options":[{"t":"Shartnoma haqiqiy emas deb topiladi","ok":false,"why":"п.213 shartnomani haqiqiy emas deb topmaydi — u faqat to'lovni to'sadi"},{"t":"Buyurtmachiga ma'muriy jarima solinadi","ok":false,"why":"Javobgarlik п.218 bo'yicha alohida qonunchilikda; п.213 da jarima emas, to'lov oqibati ko'rsatilgan"},{"t":"Bunday shartnoma bo'yicha to'lov amalga oshirilmaydi","ok":true,"why":"п.213 matni aynan shu: ma'lumoti Ягона реестр ga kiritilmagan shartnomalar bo'yicha to'lovlar amalga oshirilmaydi"},{"t":"Shartnoma avtomatik ravishda bekor qilinadi","ok":false,"why":"Avtomatik bekor qilish ВМ-276 da nazarda tutilmagan; avtomatik amal — реестр ga kiritilish (п.208)"}],"exp":"ВМ-276 п.213: ma'lumoti Ягона шартномалар реестри ga kiritilmagan shartnomalar bo'yicha to'lov amalga oshirilmaydi. п.207-209 ga ko'ra «электронный магазин», аукцион, отбор, tender va рамочное соглашение shartnomalari elektron tizimda ro'yxatdan o'tgach avtomatik kiritiladi, to'g'ri shartnomalar bo'yicha esa ma'lumotni buyurtmachi maxsus axborot portaliga kiritgandan keyin avtomatik shakllantiriladi.","tags":["reyestr","to'lov"]},{"id":"vm-b-29","doc":"ВМ-276","topic":"Shartnoma","ref":"п.215","difficulty":3,"q":"ВМ-276 п.215 ga ko'ra shartnoma bo'yicha qo'shimcha bajariladigan ish/xizmatlar qiymati qanchagacha oshishi mumkin?","options":[{"t":"Boshlang'ich shartnoma summasining 15% igacha","ok":false,"why":"15% — mahalliy ishlab chiqaruvchiga qo'shimcha ball formulasidagi koeffitsient (п.95¹, п.155¹), shartnoma chegarasi emas"},{"t":"Boshlang'ich shartnoma summasining 10% igacha","ok":true,"why":"п.215 qo'shimcha ish/xizmatlar qiymatini shartnoma bo'yicha umumiy boshlang'ich summaning 10% i bilan cheklaydi"},{"t":"Boshlang'ich shartnoma summasining 20% igacha","ok":false,"why":"20% — демпинг aniqlanadigan narx og'ish chegarasi (п.43 «электронный магазин», п.54 аукцион)"},{"t":"Boshlang'ich shartnoma summasining 5% igacha","ok":false,"why":"5% — п.15 dagi задаток ning tenderdagi yuqori chegarasi (отбор da — 3%), shartnoma o'zgartirish chegarasi emas"}],"exp":"ВМ-276 п.215 xarid protsedurasi natijalari bo'yicha tuzilgan shartnomaning muhim shartlarini o'zgartirishni taqiqlaydi: tovar (ish, xizmat)ni o'zgartirish; sifat va assortimentni o'zgartirish; tovar miqdori va narxini oshirish; yetkazib berish muddatini cho'zish (fors-major holatlari bundan mustasno); bajarilishi lozim qo'shimcha ish va xizmatlar qiymatini shartnoma bo'yicha umumiy boshlang'ich summaning 10% idan ortiq oshirish. Shu bandning oxirgi xatboshisiga ko'ra qonunchilik hujjatlariga muvofiq tuzilgan TO'G'RI shartnomalarning muhim shartlarini o'zgartirish uchun shu shartnoma shartlariga muvofiq qo'shimcha kelishuv tuzilishi mumkin.","tags":["10%","shartnoma o'zgartirish"]},{"id":"vm-b-30","doc":"ВМ-276","topic":"Umumiy","ref":"п.217","difficulty":2,"q":"ВМ-276 п.217 ga ko'ra maxsus axborot portaliga joylashtiriladigan ma'lumotlarning haqqoniyligi uchun kim javobgar?","options":[{"t":"Elektron tizim operatori","ok":false,"why":"Operator o'z majburiyatlarini lozim darajada bajarish, jumladan buyurtmachi va ishtirokchilar oldidagi to'lov majburiyatlarini o'z vaqtida bajarish uchun javobgar (п.217 ikkinchi xatboshi), portal ma'lumotlari haqqoniyligi uchun emas"},{"t":"Xarid komissiyasining mas'ul kotibi","ok":false,"why":"Mas'ul kotib takliflarning rasmiylashtirilishini tekshiradi va baholash natijalarini tizimga kiritadi (отбор — п.60, tender — п.109), ammo portal ma'lumotlari uchun javobgar emas"},{"t":"Iqtisodiyot va moliya vazirligi","ok":false,"why":"Bu ESKI norma — hozir amal qilmaydi: ВМ-393 (20.07.2026) tahririda п.2 dagi «вакolatli organ» = Агентство промышленной кооперации и государственных закупок; u реестр yuritadi (п.193, п.206), lekin buyurtmachining portalga qo'ygan ma'lumotlari uchun javob bermaydi"},{"t":"Buyurtmachi","ok":true,"why":"п.217 javobgarlikni aynan buyurtmachiga yuklaydi — portalga joylashtiriladigan ma'lumotlar haqqoniyligi ham shu ro'yxatda"}],"exp":"ВМ-276 п.217: buyurtmachi qonunchilik hujjatlariga rioya qilinishi, shartnomalarning qonunchilikka muvofiq tuzilishi, shartnoma bo'yicha majburiyatlarning lozim darajada bajarilishi, maxsus axborot portaliga joylashtiriladigan ma'lumotlar va vakolatli organlarga taqdim etilgan hujjatlar haqqoniyligi hamda qog'oz va elektron shakldagi hujjatlarning o'zaro mosligi uchun javobgar. Operator esa o'z majburiyatlari va to'lovlarning o'z vaqtida bajarilishi uchun javobgar. Diqqat: ВМ-393 (20.07.2026) dan boshlab vakolatli organ — Агентство промышленной кооперации и государственных закупок.","tags":["javobgarlik","buyurtmachi"]},{"id":"zru-c-01","doc":"ЗРУ-684","topic":"Texnik topshiriq","ref":"ст.34","difficulty":1,"q":"ЗРУ-684 ст.34 ga ko'ra davlat xaridi tavsifi (описание закупки / ТЗ) qanday xarakterga ega bo'lishi shart?","options":[{"t":"Individual va aniq ishlab chiqaruvchiga yo'naltirilgan","ok":false,"why":"Aksincha — ст.34 3-qismi aynan aniq ishlab chiqaruvchiga havolani taqiqlaydi"},{"t":"Batafsil, konstruktiv va aniq modelga bog'langan","ok":false,"why":"Konstruktsiya va modelga havola ст.34 3-qismi bilan taqiqlangan; bu chalg'ituvchi «batafsillik» talabi"},{"t":"Obyektiv, funksional va umumiy","ok":true,"why":"ст.34 1-qismi aynan shu uch belgini talab qiladi; texnik, sifat va zarur bo'lsa ekspluatatsiya xarakteristikalari ko'rsatiladi"},{"t":"Faqat texnik va narx xarakteristikalaridan iborat","ok":false,"why":"Narx — ст.32 baholash mezoni, tavsif tarkibi emas; tavsif esa funksional bo'lishi kerak"}],"exp":"ЗРУ-684 ст.34 1-qismi: xarid tavsifi obyektiv, funksional va umumiy xarakterga ega. Amalda bu Markaz ekspertining birinchi filtri — ТЗ konkret modelning «ko'chirmasi» bo'lsa, u obyektiv emas va raqobatni cheklaydi.","tags":["ТЗ","tavsif","raqobat"]},{"id":"zru-c-02","doc":"ЗРУ-684","topic":"Texnik topshiriq","ref":"ст.34","difficulty":2,"q":"Raqobatli xarid protsedurasi tavsifiga (ТЗ) aniq tovar belgisi, patent, konstruktsiya yoki ishlab chiqaruvchiga havola qaysi holatda istisno tariqasida kiritilishi mumkin?","options":[{"t":"Tovar (ish, xizmat) xarakteristikasini yetarlicha aniq tavsiflashning boshqa usuli bo'lmasa — bunda tavsifga «yoki analog» so'zlari kiritiladi","ok":true,"why":"ст.34 3-qismidagi raqobatli protseduralar uchun yagona asos aynan shunday shakllantirilgan va «или аналог» formulasi bilan birga qo'llaniladi"},{"t":"Davlat buyurtmachisi rahbarining asoslantirilgan qarori bilan istalgan holatda","ok":false,"why":"Qonun buyurtmachi rahbariga bunday diskretsiya bermaydi — istisno hujjat emas, holat bilan belgilanadi"},{"t":"Agar xarid summasi 6 000 БҲМ dan kam bo'lsa","ok":false,"why":"6 000 БҲМ chegarasi ст.56/64 dagi protsedura turini tanlashga taalluqli, brend taqiqiga emas"},{"t":"Agar ishlab chiqaruvchi Yagona ta'minotchilar reyestriga kiritilgan bo'lsa","ok":false,"why":"Reyestr ст.72-73 bo'yicha to'g'ri shartnoma asosi; u ТЗ da brendni ochishga ruxsat bermaydi"}],"exp":"ст.34 3-qismi tovar belgisi, nomi, patent, konstruktsiya/model, kelib chiqish manbasi yoki ishlab chiqaruvchiga havolani taqiqlaydi. Raqobatli protseduralarda yagona asos — xarakteristikani yetarlicha aniq tavsiflashning boshqa usuli yo'qligi, va bunda tavsifga «yoki analog» so'zlari kiritiladi. Alohida chiqarma — «электронный магазин» orqali qilingan xaridlar.","tags":["ТЗ","brend","yoki analog"]},{"id":"zru-c-03","doc":"ЗРУ-684","topic":"Texnik topshiriq","ref":"ст.34","difficulty":3,"q":"Brendga havola qilinganda «yoki analog» so'zlarini tavsifga kiritish qaysi holatda talab qilinmaydi?","options":[{"t":"Import kontrakti bo'yicha xaridlarda","ok":false,"why":"ст.34 da import kontraktlari uchun alohida ozodlik yo'q; import kontrakti alohida ekspertiza predmeti, brend qoidasining istisnosi emas"},{"t":"Tovarlarning nomuvofiqligi (несовместимость товаров) holatlarida","ok":true,"why":"ст.34 3-qismi «за исключением случаев несовместимости товаров» deb aynan shu holatni istisno qiladi"},{"t":"Kafolat muddati 3 yildan oshganda","ok":false,"why":"Kafolat muddati ст.34 ning boshqa qismi predmeti va «yoki analog» qoidasiga umuman ta'sir qilmaydi"},{"t":"Byudjet buyurtmachisi xarid qilganda","ok":false,"why":"Buyurtmachi turi (byudjet/korporativ) summa chegaralariga ta'sir qiladi, brend qoidasiga emas"}],"exp":"«Yoki analog» formulasidan chekinish yagona asosga ega — tovarlarning nomuvofiqligi (masalan, ishlayotgan platformaga qo'shimcha modul). Amalda ekspert bu istisnoni faqat texnik nomuvofiqlik hujjatlashtirilgan bo'lsa qabul qiladi.","tags":["ТЗ","yoki analog","istisno"]},{"id":"zru-c-04","doc":"ЗРУ-684","topic":"Texnik topshiriq","ref":"ст.34 (ЗРУ-1005 tahriri)","difficulty":3,"q":"Aniq tovar belgisi va ishlab chiqaruvchiga havola qilish taqiqi qaysi usul orqali qilingan xaridlarga umuman qo'llanilmaydi?","options":[{"t":"Аукцион на понижение стартовой цены","ok":false,"why":"ст.52 аукцион uchun tovar standart xususiyatlarga ega bo'lishini talab qiladi, lekin brend taqiqidan ozodlik bermaydi"},{"t":"Отбор наилучших предложений","ok":false,"why":"Отбор xarid hujjatlarida ТЗ bo'ladi (ст.59) va ст.34 qoidalari to'liq amal qiladi"},{"t":"Tender","ok":false,"why":"Tenderda ст.34 talablari eng qat'iy qo'llaniladi — xarid hujjatlari Markaz ekspertizasiga kiradi (ст.67)"},{"t":"Электронный магазин","ok":true,"why":"ст.34 3-qismining amaldagi tahriri taqiqdan «закупки, совершенные посредством электронного магазина» ni bevosita chiqarib tashlagan"}],"exp":"ЗРУ-1005 tahririda ст.34 3-qismi brend taqiqiga ikkita chiqarma qo'ydi: «электронный магазин» orqali qilingan xaridlar va boshqa aniq tavsiflash usuli bo'lmagan holatlar. «Электронный магазин» orqali oferta bevosita marka/parametr bilan joylashtirilgani uchun taqiq mantiqan qo'llanilmaydi.","tags":["ТЗ","brend","elektron magazin"]},{"id":"zru-c-05","doc":"ЗРУ-684","topic":"Texnik topshiriq","ref":"ст.34","difficulty":2,"q":"ЗРУ-684 ст.34 ga ko'ra xarid tavsifi majburiy ravishda nimalarni o'z ichiga olishi shart?","options":[{"t":"Tovarlar miqdori; bajariladigan ishlar (xizmatlar); yetkazib berish yoki bajarish joyi; istalgan yoki talab etiladigan muddatlar (mavjud bo'lsa)","ok":true,"why":"ст.34 4-qismi aynan shu to'rt pozitsiyani sanaydi"},{"t":"Boshlang'ich narx (стартовая цена) hisob-kitobi metodikasi va manbalar ro'yxati","ok":false,"why":"Narxni baholash ст.33 predmeti — tavsifning majburiy tarkibi emas"},{"t":"Ishtirokchining benefitsiar egasi va INN raqami","ok":false,"why":"Bu ma'lumot ст.47 bo'yicha Yagona shartnomalar reyestrining rekviziti, ТЗ tarkibi emas"},{"t":"Xarid komissiyasi tarkibi va kvorum shartlari","ok":false,"why":"Komissiya tarkibi ст.57 (отбор, ≥5) va ст.65 (tender, ≥7) bilan belgilanadi, tavsifga kirmaydi"}],"exp":"ст.34 4-qismi tavsifning minimal to'rt elementini belgilaydi: miqdor, ishlar/xizmatlar, joy, muddatlar. Amalda «joy» yoki «muddat» tushib qolgan ТЗ — доработка uchun tipik asos, chunki ular baholash va shartnoma ijrosi uchun bazaviy.","tags":["ТЗ","majburiy tarkib"]},{"id":"zru-c-06","doc":"ЗРУ-684","topic":"Texnik topshiriq","ref":"ст.34","difficulty":2,"q":"Xarid hujjatlari sotib olinayotgan tovar (ish, xizmat) ko'rsatkichlari bo'yicha nimani belgilashi kerak?","options":[{"t":"Faqat bozorda shakllangan o'rtacha qiymatlarni","ok":false,"why":"O'rtacha bozor qiymati ст.33 bo'yicha narx tahlili uchun, ko'rsatkich chegaralari uchun emas"},{"t":"Maksimal va/yoki minimal qiymatlarni, shuningdek o'zgartirib bo'lmaydigan qiymatlarni","ok":true,"why":"ст.34 5-qismi aynan shu uch toifani talab qiladi"},{"t":"Faqat minimal qiymatlarni; maksimal chegara qo'yish taqiqlanadi","ok":false,"why":"Maksimal qiymat ham nazarda tutilgan — taqiq yo'q, aksincha ruxsat"},{"t":"Aniq ishlab chiqaruvchi datasheetidagi qiymatlarni","ok":false,"why":"Bu aniq modelga bog'lanish demakdir va ст.34 3-qismidagi taqiqni buzadi"}],"exp":"ст.34 5-qismi: xarid hujjatlari muvofiqlikni aniqlash imkonini beruvchi ko'rsatkichlarni, shu jumladan maksimal va/yoki minimal qiymatlarni va o'zgartirib bo'lmaydigan qiymatlarni o'z ichiga oladi. Bu ekspert uchun brend-lok tekshiruvining asosiy asbobi: qat'iy «faqat shunday» qiymatlar guruhi ko'pincha bitta vendorni ko'rsatadi.","tags":["ТЗ","ko'rsatkich","brend-lok"]},{"id":"zru-c-07","doc":"ЗРУ-684","topic":"Texnik topshiriq","ref":"ст.34","difficulty":1,"q":"Yetkazib beriladigan tovar holati bo'yicha ЗРУ-684 ст.34 qanday qoida belgilaydi?","options":[{"t":"Tovar 1 yildan oshmagan foydalanishda bo'lishi mumkin","ok":false,"why":"Qonunda bunday «yoshi» chegarasi yo'q — o'ylab topilgan mezon"},{"t":"Tovar holati faqat shartnomada belgilanadi, qonunda qoida yo'q","ok":false,"why":"Qoida aynan qonunda — ст.34 da dispozitiv shaklda mavjud"},{"t":"Tovar yangi bo'lishi kerak, agar xarid tavsifida boshqacha nazarda tutilmagan bo'lsa","ok":true,"why":"ст.34: «Поставляемый товар должен быть новым, если иное не предусмотрено описанием»"},{"t":"Tovar yangi bo'lishi shart, hech qanday istisno yo'q","ok":false,"why":"Qoida dispozitiv — tavsifda boshqacha ko'rsatilishi mumkin, imperativ emas"}],"exp":"ст.34 tovarning yangiligini default qoida qilib belgilaydi, lekin xarid tavsifida boshqacha nazarda tutilishi mumkin. Shuning uchun ekspert restavratsiya qilingan (refurbished) uskuna taklif qilinsa, buni ТЗ da aniq yozilgan-yozilmaganini tekshiradi.","tags":["ТЗ","yangi tovar"]},{"id":"zru-c-08","doc":"ЗРУ-684","topic":"Texnik topshiriq","ref":"ст.34","difficulty":2,"q":"Yangi mashina va uskunalar yetkazib beriladigan hollarda buyurtmachi xarid hujjatlarida QO'SHIMCHA ravishda nimani belgilaydi?","options":[{"t":"Uskunani 10 yil davomida bepul almashtirish majburiyatini","ok":false,"why":"Qonunda bunday muddat yoki majburiyat yo'q"},{"t":"Ishlab chiqaruvchi mamlakatining eksport litsenziyasini","ok":false,"why":"Eksport litsenziyasi bojxona/tashqi savdo qonunchiligi predmeti, ст.34 talabi emas"},{"t":"Ijrochining bank kafolatini shartnoma summasining 30% miqdorida","ok":false,"why":"Bu shartnoma ijrosini ta'minlash bilan chalg'itadi; ст.34 da foiz belgilanmagan"},{"t":"Ishlab chiqaruvchi va/yoki ta'minotchi kafolatini taqdim etish talabini va uning amal qilish muddatini","ok":true,"why":"ст.34: yangi mashina/uskuna uchun aynan shu qo'shimcha talab belgilanadi, kafolat tovar bilan birga beriladi"}],"exp":"Har qanday mashina/uskuna uchun ст.34 kafolat muddati, sifat kafolati hajmi, kafolatli xizmat va (texnik hujjatda nazarda tutilgan bo'lsa) montaj/sozlash talablarini belgilashni nazarda tutadi; YANGI mashina/uskuna uchun esa qo'shimcha — ishlab chiqaruvchi va/yoki ta'minotchi kafolati va uning amal qilish muddati. Kafolat tovar bilan birga taqdim etiladi.","tags":["ТЗ","kafolat","uskuna"]},{"id":"zru-c-09","doc":"ЗРУ-684","topic":"Texnik topshiriq","ref":"ст.34","difficulty":2,"q":"ЗРУ-684 ст.34 xarid hujjatlariga nimani kiritishni bevosita taqiqlaydi?","options":[{"t":"Asosiy printsiplarga zid bo'lgan, ishlab chiqaruvchiga va ishtirokchiga (jumladan uning kvalifikatsiyasiga) qo'yiladigan oshirib yuborilgan (завышенные) talablarni","ok":true,"why":"ст.34 ning tegishli qismi aynan shu taqiqni, jumladan sifat va funksional xarakteristikalar shaklidagi yashirin talablarni ham qamrab oladi"},{"t":"Sifat va texnik xarakteristikalarga qo'yiladigan har qanday talabni","ok":false,"why":"Sifat va texnik talablar qo'yish qonuniy; taqiq faqat OSHIRIB YUBORILGAN talablarga"},{"t":"Kafolatli xizmat ko'rsatishga oid talablarni","ok":false,"why":"Aksincha — ст.34 buyurtmachiga kafolatli xizmat talabini belgilashga aniq ruxsat beradi"},{"t":"Montaj va sozlash majburiyligiga oid talablarni","ok":false,"why":"Montaj va sozlash talablari ст.34 da bevosita nazarda tutilgan, taqiqlanmagan"}],"exp":"ст.34: xarid hujjatlariga — shu jumladan sifat, texnik yoki funksional (iste'mol) xususiyatlariga talab shaklida — ishlab chiqaruvchiga va ishtirokchiga oshirib yuborilgan talablarni kiritish mumkin emas. Bu ст.46 dagi «kvalifikatsiya talablarini oshirib yuborish» (завышение требований к их квалификации) taqiqi bilan bir tizimda ishlaydi.","tags":["ТЗ","ortiqcha talab","raqobat"]},{"id":"zru-c-10","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.34","difficulty":2,"q":"Xarid protsedurasi yakunida tuzilgan shartnomaga qo'shimcha kelishuv (доп. соглашение) qaysi holatda tuzilishi MUMKIN EMAS?","options":[{"t":"Agar u davlat buyurtmachisi tashabbusi bilan tuzilsa","ok":false,"why":"Tashabbus egasi ahamiyatsiz — mezon shartlarning mohiyati"},{"t":"Agar u xarid komissiyasi bilan kelishilmagan bo'lsa","ok":false,"why":"ст.34 komissiya bilan kelishuvni emas, muhim shartlarning o'zgarmasligini mezon qilib qo'yadi"},{"t":"Agar u muhim shartlarni o'zgartirsa — tovar (ish, xizmat), uning sifati va assortimenti, miqdori va narxining oshishi, yetkazib berish muddatining cho'zilishi","ok":true,"why":"ст.34 o'ninchi qismi aynan shu ro'yxatni muhim shartlarga misol qilib keltiradi (qonunchilikda nazarda tutilgan hollar bundan mustasno)"},{"t":"Agar shartnoma summasi 6 000 БҲМ dan oshsa","ok":false,"why":"6 000 БҲМ — protsedura turini tanlash chegarasi (ст.56/64), qo'shimcha kelishuv chegarasi emas"}],"exp":"ст.34 o'ninchi qismi (ЗРУ-1005 tahriri): xarid protsedurasi natijasida tuzilgan shartnomaga qo'shimcha kelishuv muhim shartlarni — tovar/ish/xizmatni, uning sifati va assortimentini, miqdor va narxning oshishini, yetkazib berish muddati cho'zilishini — o'zgartirmasa tuzilishi mumkin. Amalda bu Markaz uchun ДС ekspertizasining asosiy testi.","tags":["shartnoma","доп.соглашение","muhim shart"]},{"id":"zru-c-11","doc":"ЗРУ-684","topic":"Tender","ref":"ст.32","difficulty":2,"q":"ЗРУ-684 ст.32 ga ko'ra takliflarni baholash mezonlari qatoriga quyidagilardan qaysi biri KIRADI?","options":[{"t":"Ishtirokchining ustav fondi hajmi","ok":false,"why":"Bu ishtirokchining moliyaviy resurslariga talab (ст.36 doirasi), taklifni baholash mezoni emas"},{"t":"Ekspluatatsiya xarajatlari, jumladan ma'lum davrda foydalanish va ta'mirlash xarajatlari","ok":true,"why":"ст.32 mezonlar ro'yxatida aynan shu ifoda bor"},{"t":"Ishtirokchi xodimlarining o'rtacha oylik ish haqi","ok":false,"why":"Qonunda bunday mezon yo'q; kadrlar resursi ст.36 bo'yicha ishtirokchiga qo'yiladigan mezon"},{"t":"Ishtirokchi ilgari tuzgan shartnomalar soni","ok":false,"why":"Tajriba ko'rsatkichi ст.37 bo'yicha qo'shimcha talab bo'lishi mumkin, ammo ст.32 mezonlar ro'yxatida yo'q"}],"exp":"ст.32 mezonlar ro'yxati: narx; yetkazib berish bazisi; yetkazib berish muddatlari; xususiyatlar va sifat ko'rsatkichlari; ekspluatatsiya (foydalanish) muddati; to'lov va kafolat shartlari; ekspluatatsiya xarajatlari; qonunchilikka zid bo'lmagan boshqa mezonlar. Ishtirokchining o'ziga qo'yiladigan talablar esa ст.36-37 doirasida — ularni baholash mezoniga aylantirish tipik xato.","tags":["mezon","baholash"]},{"id":"zru-c-12","doc":"ЗРУ-684","topic":"Tender","ref":"ст.32","difficulty":2,"q":"Davlat xaridi shartlari baholash mezonlari bo'yicha nimani o'z ichiga olishi shart?","options":[{"t":"Faqat mezonlarning ro'yxatini","ok":false,"why":"Ro'yxat yetarli emas — nisbiy ahamiyat va qo'llash tartibi ham talab qilinadi"},{"t":"Mezonlar ro'yxati va g'olibning taxminiy ballini","ok":false,"why":"«Taxminiy ball» qonunda yo'q; bu natijani oldindan belgilash bo'lib, ст.10 raqobat va obyektivlik printsipiga zid"},{"t":"Mezonlarni, ularning nisbiy ahamiyatini (вес) va baholash protsedurasi doirasida qo'llash tartibini","ok":true,"why":"ст.32 2-qismi aynan shu uch elementni talab qiladi"},{"t":"Mezonlarni va xarid komissiyasi a'zolarining shaxsiy baholarini","ok":false,"why":"ст.32 2-qismi faqat mezon, uning nisbiy ahamiyati va qo'llash tartibini talab qiladi — a'zolarning shaxsiy baholari xarid shartlari tarkibiga kirmaydi"}],"exp":"ст.32 2-qismi: xarid shartlari mezonlarni, ularning nisbiy ahamiyatini va baholash protsedurasi doirasida qo'llash tartibini o'z ichiga olishi kerak. Vazni ko'rsatilmagan yoki «komissiya qarori bo'yicha» deb qoldirilgan mezon — доработка uchun asos, chunki natija oldindan tekshirib bo'lmaydigan bo'lib qoladi.","tags":["mezon","vazn"]},{"id":"zru-c-13","doc":"ЗРУ-684","topic":"Tender","ref":"ст.32","difficulty":1,"q":"Takliflarni baholashda va g'olibni aniqlashda buyurtmachi qaysi mezonlardan foydalanadi?","options":[{"t":"Baholash jarayonida xarid komissiyasi qo'shimcha kiritgan mezonlardan ham","ok":false,"why":"Protsedura boshlangach mezon qo'shish mumkin emas — bu ст.32 3-qismini bevosita buzadi"},{"t":"Bozorda shakllangan har qanday obyektiv mezondan","ok":false,"why":"«Obyektivlik» o'z-o'zidan asos bermaydi — mezon xarid hujjatlarida ko'rsatilgan bo'lishi shart"},{"t":"Vakolatli organ tavsiya etgan namunaviy mezonlardan","ok":false,"why":"ст.32 3-qismi manba sifatida faqat konkret xarid hujjatlarini tan oladi; tavsiyaviy namunaviy ro'yxat baholashga asos bo'lolmaydi"},{"t":"Faqat xarid hujjatlarida ko'rsatilgan mezonlar va protseduralardan, hujjatlarda bayon etilgan tartibda","ok":true,"why":"ст.32 3-qismi aynan shunday: «использует только те критерии и процедуры... в порядке, изложенном в ней»"}],"exp":"ст.32 3-qismi mezonlarning yopiq ro'yxatini o'rnatadi: baholashda faqat xarid hujjatlarida e'lon qilingan mezonlar va faqat o'sha yerda bayon etilgan tartibda qo'llaniladi. Bu shikoyat komissiyasidagi eng ko'p uchraydigan bahs predmeti.","tags":["mezon","g'olib"]},{"id":"zru-c-14","doc":"ЗРУ-684","topic":"Tender","ref":"ст.32","difficulty":2,"q":"Ekologik mezonlar (energo-samaradorlik, qayta tiklanadigan energiya manbalari, ikkilamchi xom-ashyo) ЗРУ-684 bo'yicha qanday maqomga ega?","options":[{"t":"Takliflarni baholashda va ijrochini aniqlashda ishlatilishi MUMKIN","ok":true,"why":"ст.32 oxirgi qismi «могут использоваться» deydi — dispozitiv imkoniyat"},{"t":"Har qanday davlat xaridida majburiy qo'llaniladi","ok":false,"why":"Qonun majburiylik o'rnatmaydi — bu imkoniyat, talab emas"},{"t":"Faqat qurilish va kapital ta'mir xaridlarida majburiy","ok":false,"why":"ст.32 sohaviy cheklov qo'ymaydi va majburiylik ham belgilamaydi"},{"t":"ЗРУ-684 da nazarda tutilmagan, faqat idoraviy hujjatlarda mavjud","ok":false,"why":"Ekologik mezonlar aynan ст.32 matnida bevosita sanab o'tilgan"}],"exp":"ст.32: ekologik muhitni yaxshilash yoki salbiy ta'sirni kamaytirish maqsadida energo-samaradorlik, tabiiy resurslardan ratsional foydalanish, ekologik materiallar va ikkilamchi xom-ashyo, qayta tiklanadigan energiya kabi mezonlar ishlatilishi mumkin. Agar buyurtmachi ularni qo'llasa — vazni va qo'llash tartibi ст.32 2-qismi bo'yicha hujjatda ochilishi shart.","tags":["mezon","ekologiya"]},{"id":"zru-c-15","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.36","difficulty":3,"q":"ЗРУ-684 ст.36 (amaldagi tahriri) ga ko'ra ishtirokchiga qo'yiladigan mezonlardan biri quyidagilardan qaysi biri?","options":[{"t":"Shu sohada kamida 3 yillik ish tajribasi mavjudligi","ok":false,"why":"ст.36 da tajriba mezoni yo'q; u faqat ст.37 doirasidagi qo'shimcha talab sifatida, ПКО bilan qo'yilishi mumkin"},{"t":"Bosh prokuratura huzuridagi Majburiy ijro byurosi ma'lumotlar bazalarida sud qarorlari bo'yicha bajarilmagan majburiyatlar yo'qligi","ok":true,"why":"Bu mezon ст.36 ga ЗРУ-1005 bilan qo'shilgan va amaldagi ro'yxatning bir qismi"},{"t":"ISO 9001 sifat menejmenti sertifikati mavjudligi","ok":false,"why":"Sertifikat talabi ст.36 ro'yxatida yo'q; asoslanmagan holda universal talab qilinsa, ст.34 dagi «oshirib yuborilgan talab» taqiqiga tushishi mumkin"},{"t":"Ustav fondida davlat ulushi bo'lmasligi","ok":false,"why":"Davlat ulushi ст.19 bo'yicha korporativ BUYURTMACHI maqomini belgilaydi, ishtirokchiga talab emas"}],"exp":"ст.36 ishtirokchi mezonlari: zarur texnik, moliyaviy, moddiy, kadrlar va boshqa resurslar; shartnoma tuzishga huquqiylik; muddati o'tgan soliq qarzi yo'qligi; Majburiy ijro byurosi bazalarida sud qarorlari bo'yicha bajarilmagan majburiyatlar yo'qligi; to'lovga qobiliyatsizlik protseduralari kiritilmaganligi; Insofsiz ijrochilar reyestrida yozuv yo'qligi. Bu ro'yxatdan tashqaridagi talab ст.37 bo'yicha alohida asoslanishi kerak.","tags":["ishtirokchi","kvalifikatsiya"]},{"id":"zru-c-16","doc":"ЗРУ-684","topic":"Tender","ref":"ст.37","difficulty":1,"q":"Ishtirokchilarga qo'shimcha talablar belgilangan davlat xaridida ishtirok etish uchun ishtirokchilar umumiy qoida bo'yicha nimadan o'tadi?","options":[{"t":"Xarid komissiyasining og'zaki suhbatidan","ok":false,"why":"Qonun og'zaki suhbat shaklini nazarda tutmaydi; ст.40 esa g'olib aniqlanguncha muzokaralarni taqiqlaydi"},{"t":"Vakolatli organ akkreditatsiyasidan","ok":false,"why":"Akkreditatsiya protsedurasi ст.37 da yo'q — ПКО ni buyurtmachi o'tkazadi"},{"t":"Kompleks ekspertiza Markazi ekspertizasidan","ok":false,"why":"Markaz ekspertizasi ТЗ va xarid hujjatlariga taalluqli (ст.58, ст.66-67), ishtirokchining o'ziga emas"},{"t":"Предварительный квалификационный отбор (ПКО) dan","ok":true,"why":"ст.37 4-qismi: qo'shimcha talablar bilan xaridda ishtirok etish uchun ishtirokchilar ПКО dan o'tadi"}],"exp":"ст.37: buyurtmachi tovar (ish, xizmat) ning o'ziga xos xususiyatlaridan kelib chiqib qo'shimcha talablar belgilashi mumkin, ular asosiy printsiplarga zid bo'lmasligi va e'lon paytida ko'rsatilishi shart, ishtirokchilar esa ПКО dan o'tadi. ЗРУ-1005 bilan qo'shilgan 5-9-qismlar bo'yicha buyurtmachilar ПКО dan o'tgan kvalifikatsiyalangan ishtirokchilar ro'yxatini yuritishi mumkin — shu ro'yxatdagilar отбор, tender va ikki bosqichli xaridlarda ПКО dan qayta o'tmaydi. Qo'shimcha talab e'londan keyin paydo bo'lsa — bu ст.46 bo'yicha raqobatni cheklash.","tags":["PKO","qo'shimcha talab"]},{"id":"zru-c-17","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.71 п.14 (ЗРУ-1057 tahriri)","difficulty":3,"q":"Shartnoma bo'yicha qo'shimcha ish va xizmatlarni bajarish uchun xarajatlar qaysi chegarada to'g'ri shartnoma (прямой договор) asosida rasmiylashtirilishi mumkin?","options":[{"t":"Shartnomaning dastlabki umumiy summasining 5 foizidan oshmagan holda","ok":false,"why":"Qo'shni raqam: qonunda 5 emas, 10 foiz belgilangan"},{"t":"Shartnomaning dastlabki umumiy summasining 10 foizidan oshmagan holda — ст.34 o'n birinchi qismida nazarda tutilgan holat bundan mustasno","ok":true,"why":"ЗРУ-1057 (17.04.2025) tahriridagi amaldagi п.14 aynan shunday: «расходы, не превышающие 10 процентов от первоначальной общей суммы договора... за исключением случая, предусмотренного частью одиннадцатой статьи 34»"},{"t":"O'zgartirilgan (joriy) shartnoma summasining 10 foizidan oshmagan holda","ok":false,"why":"Foiz to'g'ri, lekin baza xato — hisob DASTLABKI (первоначальная) umumiy summadan yuritiladi, ketma-ket ДС lardan keyingi joriy summadan emas"},{"t":"Shartnomaning dastlabki umumiy summasining 10 foizidan oshmagan holda, hech qanday istisnosiz","ok":false,"why":"Bu eski norma — п.14 ning ЗРУ-1057 gacha bo'lgan tahriri; 17.04.2025 dan boshlab ст.34 o'n birinchi qismidagi holat (андеррайтер xizmatlari) istisno qilingan, shuning uchun «istisnosiz» formulasi hozir amal qilmaydi"}],"exp":"ст.71 п.14 (ЗРУ-1057 tahriri) shartnoma bo'yicha qo'shimcha ish va xizmatlar uchun dastlabki umumiy summaning 10 foizidan oshmaydigan xarajatlarni to'g'ri shartnoma asosi qilib belgilaydi. Yangi istisno — ст.34 ning o'n birinchi qismi (ЗРУ-1057 bilan qo'shilgan): davlat ulushi 50 va undan ortiq foiz bo'lgan korxonalarga xizmat ko'rsatuvchi андеррайтер lar qimmatli qog'ozlarni shartnomada nazarda tutilganidan yuqori narxda va/yoki ko'proq miqdorda joylashtirsa, dastlabki summaning 10 foizidan ortiq to'lovga ruxsat etiladi. Baza — har doim DASTLABKI summa.","tags":["shartnoma","10 foiz","to'g'ri shartnoma"]},{"id":"zru-c-18","doc":"ЗРУ-684","topic":"Tender","ref":"ст.41","difficulty":2,"q":"Ishtirokchi xarid hujjatlari bo'yicha tushuntirish so'rasa, buyurtmachi qanday muddatda va qanday shaklda javob beradi?","options":[{"t":"3 ish kuni ichida, faqat yozma shaklda","ok":false,"why":"3 ish kuni — ст.69 bo'yicha TENDER NATIJALARI yuzasidan tushuntirish muddati, hujjatlar bo'yicha emas"},{"t":"2 ish kuni ichida, so'rov bilan bir xil shaklda","ok":true,"why":"ст.41: 2 ish kuni ichida va so'rov qanday shaklda kelgan bo'lsa, shu shaklda"},{"t":"5 ish kuni ichida, faqat elektron tizim orqali","ok":false,"why":"5 ish kuni — e'lon (ст.58) va tuzilgan shartnoma ma'lumotini joylashtirish (ст.70) muddatlari bilan chalg'itadi"},{"t":"10 kalendar kun ichida, buyurtmachi tanlagan shaklda","ok":false,"why":"Qonunda kalendar kun emas, ish kuni; shakl ham buyurtmachi ixtiyorida emas"}],"exp":"ст.41: tushuntirish so'rovi olingach, buyurtmachi yoki u jalb qilgan ixtisoslashgan tashkilot 2 ish kuni ichida so'ralgan tushuntirishni beradi, javob so'rov bilan bir xil shaklda taqdim etiladi. Tenderda esa (ст.67) so'rov muddat tugashiga kamida 2 ish kun qolganida kelgan bo'lishi kerak va tushuntirish hujjat mohiyatini o'zgartirmaydi.","tags":["muddat","tushuntirish"]},{"id":"zru-c-19","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.47","difficulty":2,"q":"ЗРУ-684 ст.47 ga ko'ra Yagona shartnomalar reyestriga quyidagilardan qaysi biri kiritiladi?","options":[{"t":"Shartnomani bekor qilish haqida ma'lumot — bekor qilish sabablari va asoslari ko'rsatilgan holda","ok":true,"why":"ст.47 ro'yxatida «информация о расторжении договора с указанием причин и оснований его расторжения» bevosita bor"},{"t":"Ishtirokchilarning rad etilgan takliflari to'liq matni","ok":false,"why":"Rad etish sabablari ст.69 bo'yicha takliflarni ko'rib chiqish bayonnomasida qayd etiladi, shartnomalar reyestrida emas"},{"t":"Xarid komissiyasi a'zolarining shaxsiy ovozlari","ok":false,"why":"Komissiya qarori bayonnoma bilan rasmiylashtiriladi; a'zolarning shaxsiy ovozlari reyestr rekviziti emas"},{"t":"Kompleks ekspertiza Markazi xulosasining to'liq matni","ok":false,"why":"ст.47 ro'yxatida Markaz xulosasi yo'q; reyestr shartnoma va uning ijrosi ma'lumotini yuritadi"}],"exp":"ст.47 Yagona shartnomalar reyestriga buyurtmachi nomi, moliyalashtirish manbasi, ijrochini aniqlash usuli, shartnoma tuzish sanasi, narx va ijro muddati, birlik narxi, ishlab chiqaruvchi mamlakati, ijrochi rekvizitlari va benefitsiar egasi, shartnoma o'zgarishi, ijrosi (to'lov, jarima/penya) va bekor qilinishi haqidagi ma'lumotni kiritadi. Ya'ni reyestr — ijro monitoringining hujjatli asosi.","tags":["reyestr","bekor qilish","monitoring"]},{"id":"zru-c-20","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.67","difficulty":1,"q":"Tender bo'yicha xarid hujjatlari bilan shartnoma loyihasi o'rtasidagi bog'liqlik qanday?","options":[{"t":"Shartnoma loyihasi faqat g'olib aniqlangandan keyin tuziladi","ok":false,"why":"Loyiha xarid hujjatlari bilan birga e'lon qilinadi — ishtirokchi shartlarni oldindan biladi"},{"t":"Shartnoma loyihasini Kompleks ekspertiza Markazi tayyorlaydi","ok":false,"why":"Markaz hujjatga ekspertiza beradi, uni tayyorlamaydi; loyiha buyurtmachiniki"},{"t":"Shartnoma loyihasi xarid hujjatlariga ilova qilinadi va uning ajralmas qismi hisoblanadi","ok":true,"why":"ст.67: «К закупочной документации по тендеру прилагается проект договора, который является ее неотъемлемой частью»"},{"t":"Shartnoma loyihasi alohida hujjat bo'lib, g'olib bilan muzokarada kelishiladi","ok":false,"why":"ст.40 g'olib aniqlanguncha muzokaralarni taqiqlaydi; shartnoma hujjat va taklif shartlarida tuziladi"}],"exp":"ст.59 (отбор) va ст.67 (tender) bo'yicha shartnoma loyihasi xarid hujjatlarining ajralmas qismidir. Shuning uchun Markaz ekspertizasida ТЗ va shartnoma loyihasi bir paketda ko'riladi: loyihadagi to'lov, kafolat va muddat shartlari ТЗ ga zid bo'lsa — bu ziddiyat замечание bo'ladi.","tags":["shartnoma loyihasi","tender hujjatlari"]},{"id":"zru-c-21","doc":"ЗРУ-684","topic":"Tender","ref":"ст.67","difficulty":3,"q":"Tender bo'yicha xarid hujjatlariga o'zgartirish kiritilsa, takliflar topshirish muddati kamida qanchaga uzaytiriladi?","options":[{"t":"Kamida 3 ish kuniga","ok":false,"why":"3 ish kuni — ст.59 bo'yicha ОТБОР uchun uzaytirish muddati, tender uchun emas"},{"t":"Kamida 5 ish kuniga","ok":false,"why":"5 ish kuni — отбор e'lonining minimal joylashtirish muddati (ст.58) bilan chalg'itadi"},{"t":"Kamida 12 ish kuniga","ok":false,"why":"12 ish kuni — ст.66 bo'yicha tender e'lonining minimal muddati, uzaytirish emas"},{"t":"Kamida 10 ish kuniga","ok":true,"why":"ст.67: o'zgartirish kiritilganda muddat kamida 10 ish kuniga uzaytiriladi"}],"exp":"ст.67: buyurtmachi komissiya bilan kelishgan holda tender hujjatlariga o'zgartirish kiritish qarorini takliflar topshirish tugashiga kamida 1 ish kun qolganida qabul qilishi mumkin, bunda muddat kamida 10 ish kuniga uzaytiriladi va tovar (ish, xizmat) nomini o'zgartirish taqiqlanadi. Отборда esa bu muddat 3 ish kuni (ст.59).","tags":["muddat","o'zgartirish","tender"]},{"id":"zru-c-22","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.67","difficulty":2,"q":"Tuzilgan shartnomalar, import kontraktlari va ularga qo'shimcha kelishuvlarning xarid hujjatlariga muvofiqligi va haqqoniyligi uchun kim javobgar?","options":[{"t":"Davlat buyurtmachisi","ok":true,"why":"ст.67 oxirgi qismi javobgarlikni bevosita davlat buyurtmachisiga yuklaydi"},{"t":"Kompleks ekspertiza Markazi","ok":false,"why":"Markaz hujjat bo'yicha xulosa beradi; imzolangan shartnomaning muvofiqligi uchun javobgarlik unga o'tmaydi"},{"t":"Xarid komissiyasi raisi","ok":false,"why":"Komissiya qarorlari bayonnoma bilan rasmiylashtiriladi; shartnoma matnining muvofiqligi ст.67 bo'yicha buyurtmachi zimmasida"},{"t":"Elektron tizim operatori","ok":false,"why":"ст.25 bo'yicha operator elektron hujjatlar mazmunini o'zgartira olmaydi va ular uchun huquqiy javobgarlik ko'tarmaydi"}],"exp":"ст.67: «Ответственность за соответствие заключенных договоров, импортных контрактов и дополнительных соглашений к ним закупочной документации и их подлинность несет государственный заказчик». Bu Markaz xulosasining chegarasini belgilaydi — ijobiy xulosa buyurtmachidan javobgarlikni olib tashlamaydi.","tags":["javobgarlik","import kontrakt"]},{"id":"zru-c-23","doc":"ЗРУ-684","topic":"Ekspertiza","ref":"ст.66","difficulty":2,"q":"Tender o'tkazish haqidagi e'lon qachon joylashtiriladi?","options":[{"t":"Xarid komissiyasi hujjatlarni tasdiqlagan zahoti","ok":false,"why":"Komissiya bilan kelishuv va buyurtmachi tasdig'i — zarur, lekin yetarli emas: Markaz xulosasi ham talab qilinadi"},{"t":"Faqat tender bo'yicha xarid hujjatlari (закупочная документация по тендеру) bo'yicha Kompleks ekspertiza Markazining ijobiy xulosasi olingandan keyin","ok":true,"why":"ст.66 2-qismi aynan shunday shakllantirilgan"},{"t":"Moliya vazirligi byudjet limitini tasdiqlagandan keyin","ok":false,"why":"Moliyalashtirish manbasining tasdig'i ст.46 talabi, lekin e'lon shartini ст.66 aynan Markaz xulosasi bilan bog'laydi"},{"t":"Faqat texnik topshiriq bo'yicha Markaz ijobiy xulosasi olingandan keyin","ok":false,"why":"Faqat ТЗ bo'yicha xulosa sharti отборга tegishli va u ham shartli (ст.58 2-qismi); tenderda butun xarid hujjatlari bo'yicha xulosa talab qilinadi"}],"exp":"ст.66 2-qismi: tender e'loni faqat tender bo'yicha xarid hujjatlariga Markazning ijobiy xulosasi olingandan keyin joylashtiriladi; ст.67 esa hujjatlarning belgilangan tartibda Markaz ekspertizasiga kiritilishini nazarda tutadi. Отборда predmet torroq va shartli — Prezident/Vazirlar Mahkamasi hujjatlari bilan tendersiz xarid huquqi berilgan hollarda texnik topshiriq bo'yicha xulosa talab qilinadi (ст.58 2-qismi).","tags":["ekspertiza","e'lon","Markaz"]},{"id":"zru-c-24","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.63","difficulty":2,"q":"Отбор bo'yicha xarid hujjatlarida buyurtmachi shartnoma tuzish uchun qanday qo'shimcha shart qo'yishi mumkin?","options":[{"t":"G'olib shartnoma summasining 30% avansini qaytarishi","ok":false,"why":"Qonunda bunday avans foizi yoki uni qaytarish sharti belgilanmagan"},{"t":"G'olib bank kafolatini Kompleks ekspertiza Markazi bilan kelishishi","ok":false,"why":"Markaz ta'minot hujjatini kelishmaydi — bu buyurtmachi va ijrochi o'rtasidagi shart"},{"t":"Shartnoma g'olib tomonidan shartnoma shartlari ijrosini ta'minlash (обеспечение исполнения) taqdim etilganidan keyin tuzilishi","ok":true,"why":"ст.63 2-qismi: «может быть выставлено условие, предусматривающее заключение договора после представления победителем обеспечения исполнения условий договора»"},{"t":"G'olib Yagona ta'minotchilar reyestriga kiritilishi","ok":false,"why":"Bu reyestr ст.72-73 bo'yicha to'g'ri shartnoma asosi; raqobatli отбор g'olibiga bunday talab qo'yilmaydi"}],"exp":"ст.63 2-qismi buyurtmachiga xarid hujjatlarida shartnoma ijrosini ta'minlash taqdim etilishini shartnoma tuzish sharti qilib qo'yish huquqini beradi. Bu ст.39 dagi TAKLIF ta'minotidan farq qiladi: taklif ta'minoti hujjati shartnoma kuchga kirib, ijro ta'minoti berilgach 1 ish kunida qaytariladi.","tags":["ta'minot","shartnoma tuzish"]},{"id":"zru-c-25","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.70","difficulty":3,"q":"Tender g'olibi shartnoma tuzishdan bosh tortsa, rezerv g'olib bilan shartnoma qanday narxda tuziladi?","options":[{"t":"Har doim rezerv g'olibning o'z taklif narxida","ok":false,"why":"Umumiy qoida — g'olib narxi; rezerv g'olibning narxi faqat u pastroq bo'lgandagina qo'llaniladi"},{"t":"Boshlang'ich narxda (стартовая цена)","ok":false,"why":"Boshlang'ich narx (стартовая цена) — yuqori chegara, shartnoma narxi emas"},{"t":"Ikki taklifning o'rtacha qiymatida","ok":false,"why":"Qonunda o'rtacha qiymat mexanizmi umuman yo'q"},{"t":"G'olib taklif qilgan narxda — rezerv g'olibning narxi undan past bo'lgan hollar bundan mustasno","ok":true,"why":"ст.70 2-qismi aynan shu formulani beradi; rezerv g'olib bosh tortish huquqini ham saqlaydi"}],"exp":"ст.70 2-qismi: g'olib bosh tortsa garov puli (задаток) unga qaytarilmaydi, shartnoma tuzish huquqi rezerv g'olibga o'tadi va u g'olib taklif qilgan narxda shartnoma tuzadi (agar o'z narxi pastroq bo'lmasa) yoki bosh tortishi mumkin. Rezerv g'olib aniqlanmagan yoki u ham bosh tortsa — yangi tender o'tkaziladi.","tags":["rezerv g'olib","narx","zadatok"]},{"id":"zru-c-26","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.47","difficulty":1,"q":"Yagona shartnomalar reyestriga ma'lumoti kiritilmagan shartnomalar bo'yicha nima bo'ladi?","options":[{"t":"Bunday shartnomalar bo'yicha to'lovlar amalga oshirilmaydi","ok":true,"why":"ст.47 oxirgi qismi: «Платежи по договорам, информация о которых не включена в Единый реестр договоров, не осуществляются»"},{"t":"Shartnoma haqiqiy emas deb topiladi","ok":false,"why":"Qonun shartnomani haqiqiy emas deb topmaydi — u faqat to'lovni to'sadi"},{"t":"Buyurtmachiga jarima solinadi va shartnoma qayta ro'yxatdan o'tkaziladi","ok":false,"why":"ст.47 sanksiya sifatida jarima emas, to'lovni to'xtatishni belgilaydi"},{"t":"Ijrochi Insofsiz ijrochilar reyestriga kiritiladi","ok":false,"why":"ст.48 asoslari boshqa — shartnomadan bosh tortish, majburiyatni bajarmaslik, yolg'on hujjat va h.k."}],"exp":"ст.47 to'lovni reyestrga kiritilganlik bilan bevosita bog'laydi — bu davlat xaridida moliyaviy nazoratning asosiy tugmasi. Shu bilan bir qatorda ст.71 to'g'ri shartnomalar uchun ham alohida qoida beradi: ma'lumot 5 ish kuni ichida maxsus axborot portaliga joylashtirilmasa, to'lov amalga oshirilmaydi.","tags":["reyestr","to'lov"]},{"id":"zru-b-01","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.30","difficulty":2,"q":"ЗРУ-684 30-moddasida sanab o'tilgan xarid protseduralari turlari orasida quyidagilardan qaysi biri YO'Q?","options":[{"t":"Двухэтапные государственные закупки","ok":false,"why":"XATO — bu tur 30-modda ro'yxatida bor (ЗРУ-1005 tahriri), ст.702-707 bilan tartibga solingan"},{"t":"Упрощенная процедура закупки малой стоимости","ok":false,"why":"XATO — 30-modda ro'yxatida bor, ст.511-512 bilan tartibga solingan"},{"t":"Конкурс","ok":true,"why":"TO'G'RI — 30-modda yopiq ro'yxatida «конкурс» degan tur yo'q; ЗРУ-684 bu atamani xarid usuli sifatida umuman ishlatmaydi"},{"t":"Аукцион на понижение стартовой цены","ok":false,"why":"XATO — 30-moddada bor, ст.52-55 bilan tartibga solingan"}],"exp":"ЗРУ-684 30-moddasi xarid protseduralarining yopiq ro'yxatini beradi: электронный магазин; упрощенная процедура закупки малой стоимости; аукцион на понижение стартовой цены; отбор наилучших предложений; тендер; двухэтапные государственные закупки; государственные закупки по прямым договорам; hamda Prezident farmon/qarorlari va VM qarorlari bilan ruxsat etilgan boshqa raqobatli turlar. «Конкурс» bu ro'yxatda yo'q — ariza hujjatlarida shunday atama uchrasa, u ЗРУ-684 bo'yicha xarid usuli hisoblanmaydi.","tags":["usullar","ro'yxat"]},{"id":"zru-b-02","doc":"ЗРУ-684","topic":"Tender","ref":"ст.64","difficulty":2,"q":"ЗРУ-684 64-moddasiga ko'ra byudjet buyurtmachisi uchun bitta shartnoma bo'yicha tender o'tkazish majburiy bo'ladigan summa chegarasi qanday?","options":[{"t":"6 000 БҲМ dan ortiq","ok":true,"why":"TO'G'RI — 64-modda byudjet buyurtmachilari uchun aynan «свыше шести тысяч БРВ» deb belgilaydi"},{"t":"25 000 БҲМ dan ortiq","ok":false,"why":"XATO — 25 000 БҲМ korporativ buyurtmachi uchun chegara, byudjet uchun emas"},{"t":"2 500 БҲМ dan ortiq","ok":false,"why":"XATO — 2 500 БҲМ byudjet buyurtmachisi uchun «электронный магазин» orqali TOVAR xaridi chegarasi (ст.49)"},{"t":"50 000 БҲМ dan ortiq","ok":false,"why":"XATO — ЗРУ-684 da 50 000 БҲМ degan chegara umuman yo'q"}],"exp":"ст.64 tenderni ikki shart bir vaqtda bajarilganda majburiy qiladi: g'olibni aniqlash mezonlari faqat pulli emas, miqdor va sifat bahosini ham o'z ichiga oladi hamda bitta shartnoma qiymati 25 000 БҲМ (byudjet buyurtmachilari uchun — 6 000 БҲМ) dan oshadi. Amalda ekspertizada aynan shu 6 000 БҲМ chegarasi buyurtmachining usulni to'g'ri tanlaganini tekshirish uchun asos bo'ladi.","tags":["chegara","summa","tender"]},{"id":"zru-b-03","doc":"ЗРУ-684","topic":"Tender","ref":"ст.64","difficulty":2,"q":"Korporativ buyurtmachi uchun bitta shartnoma bo'yicha tender majburiy bo'ladigan summa chegarasi (ЗРУ-684 64-modda)?","options":[{"t":"100 БҲМ dan ortiq","ok":false,"why":"XATO — 100 БҲМ «электронный магазин» orqali ish/xizmat xaridi chegarasi (ст.49), tender chegarasi emas"},{"t":"6 000 БҲМ dan ortiq","ok":false,"why":"XATO — 6 000 БҲМ byudjet buyurtmachisi uchun chegara, korporativ uchun emas"},{"t":"10 000 БҲМ dan ortiq","ok":false,"why":"XATO — 10 000 БҲМ byudjet buyurtmachisining bir yilda «электронный магазин» orqali bir xil turdagi tovar xaridi limiti (ст.49)"},{"t":"25 000 БҲМ dan ortiq","ok":true,"why":"TO'G'RI — 64-modda «свыше двадцати пяти тысяч БРВ» deb belgilaydi (korporativ buyurtmachilar uchun umumiy qoida)"}],"exp":"ЗРУ-684 da chegaralar juftlik bo'lib beriladi: umumiy (korporativ) chegara 25 000 БҲМ, byudjet buyurtmachisi uchun esa pasaytirilgan chegara. Tenderda bu 25 000 / 6 000 БҲМ. Xuddi shu juftlik отбор (ст.56) va аукцион (ст.52) da ham uchraydi, faqat u yerda «gacha», tenderda esa «dan ortiq».","tags":["chegara","summa","tender"]},{"id":"zru-b-04","doc":"ЗРУ-684","topic":"Tender","ref":"ст.56","difficulty":3,"q":"Отбор наилучших предложений qaysi summa oralig'ida o'tkaziladi (ЗРУ-684 56-modda)?","options":[{"t":"Bitta shartnoma bo'yicha 25 000 БҲМ gacha, byudjet buyurtmachisi uchun — 2 500 БҲМ gacha","ok":false,"why":"XATO — 2 500 БҲМ byudjet uchun «электронный магазин» orqali tovar chegarasi (ст.49); отборда byudjet chegarasi 6 000 БҲМ"},{"t":"Bitta shartnoma bo'yicha 25 000 БҲМ gacha, byudjet buyurtmachisi uchun — 6 000 БҲМ gacha","ok":true,"why":"TO'G'RI — 56-modda «до двадцати пяти тысяч (для бюджетных заказчиков — до шести тысяч) БРВ» deb belgilaydi"},{"t":"Bitta shartnoma bo'yicha 6 000 БҲМ gacha, byudjet buyurtmachisi uchun — 100 БҲМ gacha","ok":false,"why":"XATO — 6 000 БҲМ byudjet chegarasi, umumiy chegara emas; 100 БҲМ esa «электронный магазин» bo'yicha ish/xizmat chegarasi"},{"t":"Summa cheklovi yo'q — faqat baholash mezonlari muhim","ok":false,"why":"XATO — 56-modda ikki shartni bir vaqtda talab qiladi: mezonlar + summa chegarasi (istisno faqat 56-modda 2-qismida)"}],"exp":"ст.56 отборни ikki shart bir vaqtda bajarilganda ruxsat etadi: g'olibni aniqlash mezonlari faqat pulli emas, miqdor va sifat bahosini ham o'z ichiga oladi hamda qiymat 25 000 БҲМ (byudjet — 6 000 БҲМ) gacha bo'ladi. Bu chegaradan oshsa — tender (ст.64). Yagona istisno — 56-modda 2-qismi (tendersiz xarid huquqi berilgan holat).","tags":["chegara","otbor","summa"]},{"id":"zru-b-05","doc":"ЗРУ-684","topic":"Ekspertiza","ref":"ст.56 ч.2","difficulty":3,"q":"Prezident farmon/qarorlari yoki VM qarori bilan buyurtmachiga tendersiz xarid o'tkazish huquqi berilgan bo'lsa, ЗРУ-684 56-modda 2-qismi nimani talab qiladi?","options":[{"t":"Xarid umuman protsedurasiz, to'g'ridan-to'g'ri shartnoma bilan amalga oshiriladi","ok":false,"why":"XATO — tendersiz huquq protsedurasizlikni anglatmaydi; 56-modda 2-qismi отбор o'tkazishni majburiy qiladi"},{"t":"Аукцион o'tkaziladi, chunki summa chegarasi olib tashlanadi","ok":false,"why":"XATO — modda аукцион emas, aynan отборни ko'rsatadi; qolaversa ish/xizmat аукцион obyekti bo'la olmaydi (ст.52)"},{"t":"Отбор summadan qat'i nazar o'tkaziladi; qiymat 25 000 (byudjet — 6 000) БҲМ dan oshsa, texnik topshiriq Markaz ekspertizasiga kiritiladi","ok":true,"why":"TO'G'RI — 56-modda 2-qismining so'zma-so'z mazmuni: «независимо от суммы» + ТЗ Kompleks ekspertiza Markaziga"},{"t":"Отбор faqat 25 000 БҲМ gacha o'tkaziladi, undan yuqorisi baribir tender bo'ladi","ok":false,"why":"XATO — aynan shu norma summa chegarasini bekor qiladi: «закупочная процедура осуществляется путем проведения отбора независимо от суммы»"}],"exp":"ст.56 2-qismi Markaz vakolatining asosiy manbalaridan biri: yuqori hujjat bilan tendersiz xarid huquqi berilganda protsedura отбор shaklida o'tadi, summa chegarasi qo'llanilmaydi, lekin 25 000 (byudjet — 6 000) БҲМ dan oshsa ТЗ Markaz ekspertizasiga kiritiladi. Bu tenderdagi holatdan farq qiladi — u yerda ekspertizaga butun закупочная документация kiritiladi (ст.67).","tags":["ekspertiza","otbor","chegara"]},{"id":"zru-b-06","doc":"ЗРУ-684","topic":"Ekspertiza","ref":"ст.58 ч.2","difficulty":3,"q":"Buyurtmachiga tendersiz xarid huquqi berilgan holda отбор o'tkazish haqidagi e'lon qachon joylashtiriladi (ЗРУ-684 58-modda)?","options":[{"t":"Markazning texnik topshiriq (ТЗ) bo'yicha ijobiy xulosasi olingandan keyin","ok":true,"why":"TO'G'RI — 58-modda 2-qismi: «только после получения положительного заключения по техническому заданию... Центра комплексной экспертизы»"},{"t":"Markazning закупочная документация bo'yicha ijobiy xulosasi olingandan keyin","ok":false,"why":"XATO — bu tender uchun qoida (ст.66 ч.2); отборда ekspertiza predmeti aynan ТЗ"},{"t":"Vakolatli organ (Iqtisodiyot va moliya vazirligi) roziligi olingandan keyin","ok":false,"why":"XATO — subyekt almashtirilgan: 58-moddada vakolatli organ emas, Markaz xulosasi talab qilinadi"},{"t":"Xarid komissiyasi protokoli tasdiqlangan zahoti — qo'shimcha xulosa talab qilinmaydi","ok":false,"why":"XATO — komissiya protokoli Markaz xulosasi o'rnini bosmaydi; e'lonni joylashtirish sharti buzilgan bo'ladi"}],"exp":"ст.58 2-qismi отбор e'lonini Markazning ТЗ bo'yicha ijobiy xulosasiga bog'laydi. Amalda bu «bosqich tartibi» qoidasi: e'lon xulosadan OLDIN joylashtirilgan bo'lsa, protsedura buzilgan hisoblanadi. Tender uchun esa ekspertiza predmeti butun закупочная документация (ст.66, ст.67).","tags":["ekspertiza","otbor","tartib"]},{"id":"zru-b-07","doc":"ЗРУ-684","topic":"Ekspertiza","ref":"ст.66 ч.2","difficulty":2,"q":"ЗРУ-684 66-moddasiga ko'ra tender o'tkazish haqidagi e'lon qaysi shart bajarilgandan keyin joylashtiriladi?","options":[{"t":"Markazning faqat texnik topshiriq bo'yicha ijobiy xulosasi olingandan keyin","ok":false,"why":"XATO — ТЗ bo'yicha xulosa отбор uchun (ст.58 ч.2); tenderda ekspertiza predmeti kengroq"},{"t":"Shikoyatlarni ko'rib chiqish komissiyasi roziligi olingandan keyin","ok":false,"why":"XATO — subyekt almashtirilgan; Shikoyatlar komissiyasi shikoyatlarni ko'radi (ст.78-79), e'lonni tasdiqlamaydi"},{"t":"Yillik reja-grafik maxsus axborot portalida joylashtirilgan zahoti","ok":false,"why":"XATO — reja-grafik joylashtirish (ст.29) alohida majburiyat; u Markaz xulosasi o'rnini bosmaydi"},{"t":"Markazning tender bo'yicha закупочная документация ga nisbatan ijobiy xulosasi olingandan keyin","ok":true,"why":"TO'G'RI — 66-modda 2-qismi: «только после получения положительного заключения Центра комплексной экспертизы по закупочной документации по тендеру»"}],"exp":"ст.66 2-qismi va ст.67 oxirgi qismlari birgalikda Markaz vakolatini belgilaydi: tender закупочная документация si belgilangan tartibda Markaz ekspertizasiga kiritiladi, e'lon esa faqat ijobiy xulosadan keyin joylashtiriladi. ТЗ bu hujjatning tarkibiy qismi, lekin tenderda ekspertiza butun paket bo'yicha o'tadi.","tags":["ekspertiza","tender","tartib"]},{"id":"zru-b-08","doc":"ЗРУ-684","topic":"Tender","ref":"ст.66 ч.3","difficulty":3,"q":"Tender e'loni takliflar qabul qilish muddati tugashidan qancha vaqt oldin joylashtirilishi kerak (ЗРУ-684 66-modda)?","options":[{"t":"Kamida 5 ish kuni oldin","ok":false,"why":"XATO — 5 ish kuni отбор e'loni (ст.58 ч.3) va аукцион e'loni (ст.53) uchun minimum"},{"t":"Kamida 12 ish kuni va ko'pi bilan 30 ish kuni oldin","ok":true,"why":"TO'G'RI — 66-modda 3-qismi: «не менее чем за двенадцать рабочих дней и не более чем за тридцать рабочих дней»"},{"t":"Kamida 20 ish kuni oldin","ok":false,"why":"XATO — 20 ish kuni ikki bosqichli davlat xaridlari e'loni uchun (ст.704), tender uchun emas"},{"t":"Kamida 12 kalendar kuni oldin","ok":false,"why":"XATO — raqam to'g'ri, birlik noto'g'ri: qonunda «рабочих дней», ya'ni ish kuni; kalendar kun emas"}],"exp":"Tender e'loni uchun ЗРУ-684 nafaqat quyi (12 ish kuni), balki yuqori chegarani ham (30 ish kuni) belgilaydi — bu boshqa usullarda yo'q. Ekspertizada muddat tekshirilganda «kalendar kun ↔ ish kuni» almashinuvi eng ko'p uchraydigan xato hisoblanadi.","tags":["muddat","tender","e'lon"]},{"id":"zru-b-09","doc":"ЗРУ-684","topic":"Tender","ref":"ст.58 ч.3","difficulty":2,"q":"Отбор o'tkazish haqidagi e'lon va закупочная документация takliflar qabuli tugashidan qancha oldin joylashtiriladi (ЗРУ-684 58-modda)?","options":[{"t":"Kamida 3 ish kuni oldin","ok":false,"why":"XATO — 3 ish kuni bu hujjatga o'zgartirish kiritilganda muddatning uzaytirilishi (ст.59), e'lon muddati emas"},{"t":"Kamida 12 ish kuni oldin","ok":false,"why":"XATO — 12 ish kuni tender e'loni uchun minimum (ст.66 ч.3)"},{"t":"Kamida 5 ish kuni oldin","ok":true,"why":"TO'G'RI — 58-modda 3-qismi: «не менее чем за пять рабочих дней до даты окончания срока приема предложений»"},{"t":"Kamida 10 kalendar kuni oldin","ok":false,"why":"XATO — ham raqam, ham birlik noto'g'ri: qonunda 5 ish kuni; 10 ish kuni esa отбор takliflarini baholash muddati (ст.61)"}],"exp":"ст.58 3-qismi отбор e'loni uchun minimum 5 ish kunini belgilaydi; xarid predmetining o'ziga xosligiga qarab buyurtmachi bu muddatni uzaytirishga haqli (4-qism). Tenderdan farqi — отборда yuqori chegara yo'q (tenderda 12–30 ish kuni oralig'i, ст.66). Amaldagi tahrirda 2-qism ham muhim: tendersiz xarid huquqi berilgan hollarda e'lon faqat Kompleks ekspertiza Markazining ТЗ bo'yicha ijobiy xulosasidan KEYIN joylashtiriladi.","tags":["muddat","otbor","e'lon"]},{"id":"zru-b-10","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.52","difficulty":1,"q":"ЗРУ-684 52-moddasiga ko'ra аукцион на понижение стартовой цены obyekti nima bo'la OLMAYDI?","options":[{"t":"Ishlar va xizmatlar аукцион obyekti bo'la olmaydi","ok":true,"why":"TO'G'RI — 52-modda: «Государственная закупка услуг и работ не может являться объектом аукциона»"},{"t":"Standart xususiyatlarga ega tovarlar","ok":false,"why":"XATO — aksincha, aynan standart xususiyatli tovar аукцион shartlaridan biri (52-modda 1-qism)"},{"t":"Byudjet buyurtmachilarining xaridlari","ok":false,"why":"XATO — byudjet buyurtmachisi ham аукцион o'tkazishi mumkin, faqat chegara pasaytirilgan (6 000 БҲМ gacha)"},{"t":"Import qilinadigan tovarlar","ok":false,"why":"XATO — ЗРУ-684 аукционда tovarning kelib chiqishi bo'yicha bunday taqiq belgilamaydi"}],"exp":"ст.52 аукцион o'tkazishga uch shart bir vaqtda bajarilganda ruxsat etadi: tovar standart xususiyatlarga ega; texnik/eksplutatsion xarakteristikalarni baholash zarurati yo'q; bitta shartnoma bo'yicha qiymat 25 000 (byudjet — 6 000) БҲМ gacha. Bundan tashqari ish va xizmatlar аукцион obyekti bo'la olmaydi — g'olib faqat eng past narx bo'yicha aniqlangani uchun sifat baholanmaydi. Shu bilan birga eng past narx qoidasi belgilangan sifat standartlariga muvofiq tovar yetkazib berish talabini bekor qilmaydi.","tags":["auktsion","usullar"]},{"id":"zru-b-11","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.49","difficulty":3,"q":"«Электронный магазин» orqali bitta shartnoma bo'yicha TOVAR xarid qilish chegarasi qanday (ЗРУ-684 49-modda)?","options":[{"t":"50 БҲМ gacha (byudjet buyurtmachisi uchun — 25 БҲМ gacha)","ok":false,"why":"XATO — bu упрощенная процедура закупки малой стоимости chegarasi (ст.51-1), «электронный магазин» emas"},{"t":"100 БҲМ gacha (byudjet buyurtmachisi uchun — 50 БҲМ gacha)","ok":false,"why":"XATO — bu «электронный магазин» dagi ISH va XIZMAT chegarasi; savol tovar haqida"},{"t":"6 000 БҲМ gacha (byudjet buyurtmachisi uchun — 2 500 БҲМ gacha)","ok":false,"why":"XATO — 6 000 БҲМ аукцион/отбор uchun byudjet chegarasi (ст.52, ст.56), «электронный магазин» da ishlatilmaydi"},{"t":"25 000 БҲМ gacha (byudjet buyurtmachisi uchun — 2 500 БҲМ gacha)","ok":true,"why":"TO'G'RI — 49-modda: tovarlar «до двадцати пяти тысяч БРВ (для бюджетных заказчиков — до двух тысяч пятисот БРВ)»"}],"exp":"ст.49 «электронный магазин» uchun to'rt raqamni belgilaydi: tovar — 25 000 БҲМ (byudjet — 2 500); ish/xizmat — 100 БҲМ (byudjet — 50); bir xil turdagi tovar byudjet buyurtmachisi uchun yiliga 10 000 БҲМ; bir xil turdagi ish/xizmat byudjet uchun yiliga 500 БҲМ, korporativ uchun 1 000 БҲМ. Byudjet chegarasi 2 500 БҲМ aynan shu moddaga xos — boshqa usullarda uchramaydi.","tags":["chegara","elektron magazin","summa"]},{"id":"zru-b-12","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.37","difficulty":2,"q":"Ishtirokchilarga qo'shimcha talablar qo'yilgan davlat xaridida ЗРУ-684 37-moddasi nimani majburiy qiladi?","options":[{"t":"Xarid faqat tender shaklida o'tkaziladi","ok":false,"why":"XATO — 37-modda usulni cheklamaydi; qo'shimcha talablar отбор, tender va ikki bosqichli xaridlarda ham qo'llanilishi mumkin"},{"t":"Ishtirokchilar предварительный квалификационный отбор (PKO) dan o'tadi","ok":true,"why":"TO'G'RI — 37-modda 4-qismi: «участники проходят предварительный квалификационный отбор»"},{"t":"Qo'shimcha talablar faqat shartnoma imzolash bosqichida e'lon qilinadi","ok":false,"why":"XATO — 37-modda 3-qismi: qo'shimcha talablar xarid e'lon qilingan PAYTDA ma'lumotda ko'rsatilishi shart"},{"t":"Qo'shimcha talablar Markaz bilan oldindan kelishiladi","ok":false,"why":"XATO — subyekt almashtirilgan: 37-modda Markaz bilan kelishuvni talab qilmaydi; PKO va protsedura tartibini VM belgilaydi"}],"exp":"ст.37 qo'shimcha talablarni tovar/ish/xizmatning o'ziga xos xususiyatlari bilan cheklaydi, ular asosiy printsiplarga zid bo'lmasligi va e'lon paytida ochiq ko'rsatilishi shart, ishtirokchilar esa PKO dan o'tadi. Buyurtmachi kvalifikatsiyalangan ishtirokchilar ro'yxatini yuritishi mumkin — ro'yxatga kiritilganlarga отбор, tender va ikki bosqichli xaridlarda PKO dan o'tish talabi qo'llanilmaydi; ro'yxat kamida olti oyda bir marta yangilanadi, talab yoki shartlardagi o'zgarishlar esa 1 ish kuni ichida portalga joylashtiriladi. PKO va kvalifikatsiyalangan ishtirokchilar orasida protsedura o'tkazish tartibini VM belgilaydi (ст.62-1, ст.70-1).","tags":["PKO","mezon","ishtirokchi"]},{"id":"zru-b-13","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.511","difficulty":3,"q":"Упрощенная процедура закупки малой стоимости xarid komissiyasisiz bitta shartnoma bo'yicha qaysi summagacha o'tkazilishi mumkin (ЗРУ-684 51-1-modda)?","options":[{"t":"100 БҲМ gacha (byudjet buyurtmachisi uchun — 50 БҲМ gacha)","ok":false,"why":"XATO — bu «электронный магазин» dagi ish/xizmat chegarasi (ст.49), soddalashtirilgan protsedura emas"},{"t":"500 БҲМ gacha (byudjet buyurtmachisi uchun — 250 БҲМ gacha)","ok":false,"why":"XATO — 500 БҲМ byudjet buyurtmachisining YILLIK limiti, bitta shartnoma chegarasi emas"},{"t":"50 БҲМ gacha (byudjet buyurtmachisi uchun — 25 БҲМ gacha)","ok":true,"why":"TO'G'RI — 51-1-modda: «на сумму не более пятидесяти БРВ (для бюджетных заказчиков — не более двадцати пяти БРВ) по одному договору»"},{"t":"1 000 БҲМ gacha (byudjet buyurtmachisi uchun — 500 БҲМ gacha)","ok":false,"why":"XATO — 1 000 va 500 БҲМ bir moliya yili ichidagi yig'ma limitlar (korporativ / byudjet), bitta shartnoma emas"}],"exp":"ст.51-1 ikki qatlamli chegara belgilaydi: bitta shartnoma bo'yicha 50 БҲМ (byudjet — 25 БҲМ) hamda bir moliya yili ichida bitta korporativ buyurtmachi uchun 1 000 БҲМ, bitta byudjet buyurtmachisi uchun 500 БҲМ. Faqat shu doirada xarid komissiyasisiz ish ko'rish mumkin; yillik limit oshirilsa raqobatli usulga o'tish talab qilinadi. 5-1-bob ЗРУ-1005 bilan kiritilgan va 01.03.2025 dan kuchga kirgan.","tags":["chegara","summa","kichik xarid"]},{"id":"zru-b-14","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.511 ч.2","difficulty":2,"q":"Упрощенная процедура закупки малой стоимости da g'olib qanday aniqlanadi (ЗРУ-684 51-1-modda)?","options":[{"t":"Ochiq manbalardan olingan narxlarni solishtirish yoki kamida uchta potensial ta'minotchidan narx so'rash orqali, e'lon joylashtirmasdan","ok":true,"why":"TO'G'RI — 51-1-modda 2-qismi: «путем сравнения цен, полученных из открытых источников информации, либо путем запроса цен не менее чем у трех потенциальных поставщиков... без размещения объявления»"},{"t":"Kamida ikkita potensial ta'minotchidan narx so'rash orqali","ok":false,"why":"XATO — qo'shni raqam: qonunda kamida UCHTA ta'minotchi talab qilinadi"},{"t":"Elektron tizim avtomatik ravishda eng past narxni tanlash orqali","ok":false,"why":"XATO — avtomatik tanlov «электронный магазин» (ст.51) va аукцион (ст.54) mexanizmi; soddalashtirilgan protsedurada g'olibni buyurtmachi aniqlaydi"},{"t":"E'lon joylashtirilib, kamida 5 ish kuni takliflar qabul qilinishi orqali","ok":false,"why":"XATO — 51-1-modda aynan «без размещения объявления» deydi; 5 ish kuni esa отбор/аукцион e'loni muddati"}],"exp":"ст.51-1 2-qismi kichik summali xaridda ham narx asoslanishini talab qiladi: yo ochiq manbalardagi narxlarni solishtirish, yo kamida uchta potensial ta'minotchidan narx so'rovi. E'lon joylashtirish shart emas, lekin protsedurani o'tkazish asoslari, tuzilgan shartnoma va qo'shimcha kelishuvlar haqidagi ma'lumot tuzilgan kundan 5 ish kunidan kechiktirmay portalga joylashtiriladi (ст.51-2).","tags":["kichik xarid","narx","mezon"]},{"id":"zru-b-15","doc":"ЗРУ-684","topic":"Tender","ref":"ст.65","difficulty":2,"q":"Tender o'tkazish uchun tuziladigan xarid komissiyasiga ЗРУ-684 65-moddasi qanday talab qo'yadi?","options":[{"t":"Kamida 3 a'zo, kvorum — a'zolarning yarmi","ok":false,"why":"XATO — ЗРУ-684 da 3 a'zoli komissiya nazarda tutilmagan"},{"t":"Kamida 5 a'zo, kvorum — 2/3","ok":false,"why":"XATO — 5 a'zo отбор komissiyasi uchun minimum (ст.57), tender uchun emas; kvorum esa ikkala protsedurada ham 2/3"},{"t":"Kamida 7 a'zo, kvorum — a'zolarning yarmidan ko'pi","ok":false,"why":"XATO — a'zolar soni to'g'ri, lekin kvorum buzilgan: qonunda 2/3, yarmi emas"},{"t":"Kamida 7 a'zo, kvorum — umumiy sonning kamida 2/3 qismi","ok":true,"why":"TO'G'RI — 65-modda: «в составе не менее семи членов» va «не менее двух третей от общего числа членов»"}],"exp":"ст.65 tender komissiyasi uchun kamida 7 a'zo va 2/3 kvorumni belgilaydi, har bir qaror protokol bilan rasmiylashtiriladi. Отборда esa kamida 5 a'zo, ular buyurtmachi xodimlari orasidan tayinlanadi, kvorum baribir 2/3 (ст.57) — ya'ni farq a'zolar SONIDA, kvorumda emas. Ikki bosqichli xaridlarda tenderdagi kabi kamida 7 a'zo va 2/3 kvorum talab qilinadi (ст.70-3).","tags":["komissiya","tender","kvorum"]},{"id":"zru-b-16","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.48","difficulty":1,"q":"Единый реестр недобросовестных исполнителей ga kiritilgan ijrochi qancha muddat davlat xaridlarida ishtirok eta olmaydi (ЗРУ-684 48-modda)?","options":[{"t":"1 yil","ok":false,"why":"XATO — qo'shni raqam; qonunda ikki yil belgilangan"},{"t":"2 yil","ok":true,"why":"TO'G'RI — 48-modda: «не может участвовать в государственных закупках в течение двух лет», shundan keyin reyestrdan chiqarilgan hisoblanadi"},{"t":"3 yil","ok":false,"why":"XATO — 3 yil bu loyiha bo'yicha постпроектный мониторинг muddati (ст.77), reyestr muddati emas"},{"t":"5 yil","ok":false,"why":"XATO — ЗРУ-684 da bunday muddat yo'q"}],"exp":"ст.48 reyestrga kiritish asoslarini beradi: shartnoma tuzishdan bosh tortgan yoki boshqa yo'l bilan bo'yin tovlagan g'oliblar; majburiyatlarni bajarmagan yoki lozim darajada bajarmagan ijrochilar (yengib bo'lmas kuch holatlaridan tashqari); yolg'on/soxta hujjat taqdim etganlar, bir lotda qatnashgan affiliatsiyalangan shaxslar yoki manfaatlar to'qnashuvi haqidagi ma'lumotni oshkor qilmaganlar; sud qarori bilan firibgarlik, fal'sifikatsiya va korruptsiyada aybdor deb topilganlar. Cheklov muddati — 2 yil; qaror sud tartibida shikoyat qilinishi mumkin. Reyestrdagi yozuv ishtirokchini chetlatish asosi hamdir (ст.36, ст.42).","tags":["reyestr","javobgarlik","muddat"]},{"id":"zru-b-17","doc":"ЗРУ-684","topic":"Tender","ref":"ст.67","difficulty":3,"q":"Tender закупочная документация siga o'zgartirish kiritilsa, takliflar topshirish muddati qancha uzaytiriladi (ЗРУ-684 67-modda)?","options":[{"t":"Kamida 3 ish kuniga","ok":false,"why":"XATO — 3 ish kuni отбор hujjatlariga o'zgartirish kiritilgandagi uzaytirish (ст.59), tender uchun emas"},{"t":"Kamida 5 ish kuniga","ok":false,"why":"XATO — 5 ish kuni отбор e'lonining minimal muddati (ст.58), uzaytirish muddati emas"},{"t":"Kamida 10 ish kuniga","ok":true,"why":"TO'G'RI — 67-modda: «срок окончания подачи предложений в этом тендере продлевается не менее чем на десять рабочих дней»"},{"t":"Kamida 12 ish kuniga","ok":false,"why":"XATO — 12 ish kuni tender e'lonining minimal muddati (ст.66 ч.3), uzaytirish emas"}],"exp":"ст.67 uchta bog'liq qoidani beradi: o'zgartirish takliflar topshirish tugashiga kamida 1 ish kun qolganda kiritiladi; muddat kamida 10 ish kuniga uzaytiriladi; tovar (ish, xizmat) NOMINI o'zgartirish taqiqlanadi. Отборда ayni tartib, lekin uzaytirish 3 ish kuni va tovarning (ish, xizmatning) o'zini o'zgartirish taqiqlanadi (ст.59).","tags":["muddat","tender","hujjat"]},{"id":"zru-b-18","doc":"ЗРУ-684","topic":"Tender","ref":"ст.59","difficulty":3,"q":"Отбор закупочная документация siga o'zgartirish kiritilganda takliflar topshirish muddati qancha uzaytiriladi (ЗРУ-684 59-modda)?","options":[{"t":"Kamida 3 ish kuniga","ok":true,"why":"TO'G'RI — 59-modda: «срок окончания подачи предложений в данном отборе продлевается не менее чем на три рабочих дня»"},{"t":"Kamida 10 ish kuniga","ok":false,"why":"XATO — 10 ish kuni tender hujjatlariga o'zgartirish kiritilgandagi uzaytirish (ст.67)"},{"t":"Kamida 5 ish kuniga","ok":false,"why":"XATO — 5 ish kuni отбор e'lonining minimal muddati (ст.58), uzaytirish muddati emas"},{"t":"Muddat uzaytirilmaydi — e'lon bekor qilinadi va yangisi joylashtiriladi","ok":false,"why":"XATO — 59-modda hujjatga o'zgartirish kiritishga ochiq ruxsat beradi, faqat muddatni uzaytirishni talab qiladi"}],"exp":"ст.59 bo'yicha buyurtmachi xarid komissiyasi bilan kelishgan holda отбор hujjatlariga o'zgartirish kiritishi mumkin — takliflar qabuli tugashiga kamida 1 ish kun qolganda; muddat kamida 3 ish kuniga uzaytiriladi; e'londagi ma'lumot o'zgargan bo'lsa, e'lonning o'ziga ham bir vaqtda o'zgartirish kiritiladi; tovar (ish, xizmat) ning o'zini o'zgartirish esa taqiqlanadi. Hujjatga shartnoma loyihasi ilova qilinadi va u ajralmas qism hisoblanadi.","tags":["muddat","otbor","hujjat"]},{"id":"zru-b-19","doc":"ЗРУ-684","topic":"Tender","ref":"ст.69","difficulty":2,"q":"Tender ishtirokchilari takliflarini ko'rib chiqish va baholash muddati qancha (ЗРУ-684 69-modda)?","options":[{"t":"10 ish kunidan oshmaydi","ok":false,"why":"XATO — 10 ish kuni отбор takliflarini baholash muddati (ст.61)"},{"t":"20 ish kunidan oshmaydi","ok":false,"why":"XATO — 20 ish kuni ikki bosqichli xaridlarda har bosqich bo'yicha baholash muddati (ст.70-6)"},{"t":"30 kalendar kunidan oshmaydi","ok":false,"why":"XATO — ham raqam, ham birlik noto'g'ri: 30 ish kuni tender e'lonining yuqori chegarasi (ст.66 ч.3), baholash muddati emas"},{"t":"45 ish kunidan oshmaydi","ok":true,"why":"TO'G'RI — 69-modda 1-qismi: «не может превышать сорока пяти рабочих дней с момента окончания подачи предложений»"}],"exp":"ст.69 baholash muddatini takliflar qabuli tugagan paytdan boshlab 45 ish kuni bilan cheklaydi. Baholash odatda ikki bosqichda o'tadi: 1-bosqich — texnik qism; 2-bosqich 1-bosqichdan o'tgan kamida ikkita ishtirokchi bo'lganda o'tkaziladi; miqdoriy parametrlar, jumladan narx qismi, elektron tizim tomonidan avtomatik baholanadi. Sotib olinayotgan tovar (ish, xizmat) ning texnik xususiyatlaridan kelib chiqib tender bir bosqichda ham o'tkazilishi mumkin — bu закупочная документация da ko'rsatiladi. Tender natijalari bo'yicha tushuntirish so'rovi 3 ish kuni ichida javoblanadi.","tags":["muddat","tender","baholash"]},{"id":"zru-b-20","doc":"ЗРУ-684","topic":"Tender","ref":"ст.61","difficulty":2,"q":"Отбор ishtirokchilari takliflarini ko'rib chiqish va baholash muddati qancha (ЗРУ-684 61-modda)?","options":[{"t":"5 ish kunidan oshmaydi","ok":false,"why":"XATO — 5 ish kuni отбор e'lonining minimal muddati (ст.58), baholash muddati emas"},{"t":"10 ish kunidan oshmaydi","ok":true,"why":"TO'G'RI — 61-modda: «не может превышать десяти рабочих дней с момента окончания подачи предложений»"},{"t":"45 ish kunidan oshmaydi","ok":false,"why":"XATO — 45 ish kuni tender takliflarini baholash muddati (ст.69)"},{"t":"15 kalendar kunidan oshmaydi","ok":false,"why":"XATO — ham raqam, ham birlik noto'g'ri; qonunda 10 ISH kuni"}],"exp":"ст.61 bo'yicha отбор bo'lib o'tgan deb topiladi, agar xarid hujjatlari talablariga javob beruvchi kamida ikkita taklif kelgan bo'lsa; bitta yoki umuman taklif bo'lmasa — bo'lmagan deb topiladi va buyurtmachi yangi отбор o'tkazishi yoxud «электронный магазин» (ст.49), упрощенная процедура закупки малой стоимости (ст.51-1) yoki аукцион orqali xarid qilishi mumkin. Baholash muddati — 10 ish kunidan ko'p emas. Protokol rasmiylashtirilgan kuni muhokama uchun 2 ish kuniga elektron tizimga joylashtiriladi (ст.62).","tags":["muddat","otbor","baholash"]},{"id":"zru-b-21","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.67","difficulty":2,"q":"Tuzilgan shartnomalar, import kontraktlari va ularga qo'shimcha kelishuvlarning закупочная документация ga muvofiqligi hamda haqiqiyligi uchun kim javobgar (ЗРУ-684 67-modda)?","options":[{"t":"Kompleks ekspertiza Markazi","ok":false,"why":"XATO — Markaz hujjatga ekspertiza xulosasi beradi, lekin tuzilgan shartnomaning muvofiqligi uchun javobgarlikni o'z zimmasiga olmaydi"},{"t":"Xarid komissiyasi raisi","ok":false,"why":"XATO — komissiya g'olibni aniqlaydi va protokol rasmiylashtiradi; 67-modda javobgarlikni komissiya raisiga yuklamaydi"},{"t":"Davlat buyurtmachisi","ok":true,"why":"TO'G'RI — 67-modda oxirgi qismi: «Ответственность за соответствие заключенных договоров, импортных контрактов и дополнительных соглашений к ним закупочной документации и их подлинность несет государственный заказчик»"},{"t":"Elektron tizim operatori","ok":false,"why":"XATO — operator tizim uzluksizligini ta'minlaydi va hujjatlar mazmuniga aralashishga haqli emas (ст.25)"}],"exp":"ст.67 oxirgi ikki qismi ekspertiza va javobgarlikni ajratadi: закупочная документация belgilangan tartibda Kompleks ekspertiza Markazi ekspertizasiga kiritiladi, ammo tuzilgan shartnoma, import kontrakti va qo'shimcha kelishuvlarning hujjatga muvofiqligi hamda haqiqiyligi uchun javobgarlik davlat buyurtmachisida qoladi. Amalda bu Markaz xulosasidagi «замечания» ni bartaraf etish majburiyati buyurtmachida ekanini anglatadi.","tags":["javobgarlik","shartnoma","tender"]},{"id":"zru-b-22","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.71 п.8","difficulty":3,"q":"Ilgari yetkazib berilgan tovar (ish, xizmat) ni postgarantiya va joriy xizmat ko'rsatish (ehtiyot qismlar), shuningdek ilgari sotib olingan dasturiy mahsulotni сопровождение va funksional kengaytirish — ЗРУ-684 71-moddasining qaysi bandi?","options":[{"t":"п.8","ok":true,"why":"TO'G'RI — 71-modda 1-qismi 8-bandi aynan postgarantiya/joriy xizmat (ehtiyot qismlar) va dasturiy mahsulotni сопровождение hamda funksional kengaytirishni qamrab oladi"},{"t":"п.5","ok":false,"why":"XATO — 5-band aql-zakovat faoliyati natijalari muallifi yoki eksklyuziv huquq egasidan xarid haqida"},{"t":"п.14","ok":false,"why":"XATO — 14-band shartnoma boshlang'ich umumiy summasining 10% dan oshmaydigan qo'shimcha ish va xizmatlar haqida"},{"t":"п.21","ok":false,"why":"XATO — 21-band aloqa, Internet va teleradioeshittirish xizmatlariga taalluqli"}],"exp":"ст.71 п.8 ikki holatni birlashtiradi: (1) o'sha ta'minotchi tomonidan ilgari yetkazilgan tovar (ish, xizmat) ga postgarantiya va joriy xizmat ko'rsatish — ehtiyot qismlar sotib olish, agar bunday xizmatni boshqa ta'minotchi ko'rsata olmasa; (2) ilgari sotib olingan dasturiy mahsulotni сопровождение va (yoki) funksional kengaytirish. Ekspertizada bu band uchun asos — ilgari tuzilgan shartnoma va boshqa ta'minotchi orqali xizmat imkonsizligining tasdig'i. ⚠️ ЭСЛАТМА: ст.71 ga 07.07.2026 dagi ЗРУ-1157 bilan o'zgartirish kiritilgan, lex.uz da ruscha norasmiy tarjima hali yangilanmagan — bandlar raqamlanishini o'zbekcha rasmiy matndan qayta tekshirish tavsiya etiladi.","tags":["pryamoy dogovor","band","ПО"]},{"id":"zru-b-23","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.71 п.21","difficulty":3,"q":"ЗРУ-684 71-modda 21-bandidagi «по ранее заключенным договорам» asosi qaysi xizmatlarga taalluqli?","options":[{"t":"Oldingi shartnoma mavjud bo'lsa — har qanday tovar, ish yoki xizmatga","ok":false,"why":"XATO — band predmet bo'yicha qat'iy cheklangan; «oldingi shartnoma bor» degani o'z-o'zidan asos bermaydi"},{"t":"Ilgari sotib olingan dasturiy mahsulotni сопровождение va funksional kengaytirishga","ok":false,"why":"XATO — bu 8-band predmeti; 21-band dasturiy mahsulotni qamramaydi"},{"t":"Tabiiy monopoliya subyektining har qanday xizmatiga","ok":false,"why":"XATO — tabiiy monopoliya subyekti ст.72 (единый поставщик) asosi, ст.71 п.21 emas"},{"t":"Aloqa, Internet va teleradioeshittirish xizmatlariga","ok":true,"why":"TO'G'RI — 71-modda 21-bandi: «государственная закупка услуг связи, Интернета и телерадиовещания у поставщиков по ранее заключенным договорам»"}],"exp":"ст.71 п.21 to'g'ridan-to'g'ri shartnomaga faqat uchta predmet bo'yicha yo'l ochadi: aloqa, Internet va teleradioeshittirish xizmatlari, hamda faqat ilgari tuzilgan shartnomalar bo'yicha ta'minotchilardan. Shu sababli ekspertizada oldingi shartnomaning paketda bo'lishi majburiy — u yo'q bo'lsa, asos tasdiqlanmagan hisoblanadi va ariza qaytariladi. ⚠️ ЭСЛАТМА: ст.71 ga 07.07.2026 dagi ЗРУ-1157 bilan o'zgartirish kiritilgan, ruscha norasmiy tarjima hali yangilanmagan — band raqamini o'zbekcha rasmiy matndan qayta tekshirish tavsiya etiladi.","tags":["pryamoy dogovor","band","aloqa"]},{"id":"zru-b-24","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.71 п.14","difficulty":2,"q":"ЗРУ-684 71-modda 14-bandiga ko'ra shartnoma bo'yicha qo'shimcha ish va xizmatlarni to'g'ridan-to'g'ri shartnoma bilan bajartirish xarajati qanday chegaralangan (ЗРУ-1057, 17.04.2025 tahriri)?","options":[{"t":"Shartnoma boshlang'ich umumiy summasining 5% dan oshmasligi","ok":false,"why":"XATO — qo'shni raqam; qonunda 10 foiz belgilangan"},{"t":"Shartnoma boshlang'ich umumiy summasining 10% dan oshmasligi — ст.34 o'n birinchi qismida nazarda tutilgan holat bundan mustasno","ok":true,"why":"TO'G'RI — amaldagi tahrir: «расходы, не превышающие 10 процентов от первоначальной общей суммы договора для выполнения дополнительных работ и услуг по нему, за исключением случая, предусмотренного частью одиннадцатой статьи 34 настоящего Закона»"},{"t":"Shartnoma boshlang'ich umumiy summasining 10% dan oshmasligi — hech qanday istisnosiz","ok":false,"why":"XATO — bu ESKI norma, hozir amal qilmaydi: ЗРУ-1057 (17.04.2025) п.14 ni yangi tahrirda bayon qilib, ст.34 ning yangi o'n birinchi qismiga istisno havolasini kiritdi (davlat ulushi 50% va undan yuqori korxonalarga xizmat ko'rsatuvchi андеррайтер qimmatli qog'ozlarni shartnomada nazarda tutilganidan yuqori narxda va (yoki) ko'proq miqdorda joylashtirsa, 10% dan ortiq to'lovga ruxsat etiladi)"},{"t":"Shartnoma boshlang'ich umumiy summasining 20% dan oshmasligi","ok":false,"why":"XATO — chegara ikki barobar oshirib ko'rsatilgan; qonunda 10 foiz"}],"exp":"ст.71 п.14 qo'shimcha ish va xizmatlar uchun 10 foizlik chegara belgilaydi va u shartnomaning BOSHLANG'ICH umumiy summasidan hisoblanadi (keyinchalik oshirilgan summadan emas). ЗРУ-1057 (17.04.2025) shu bandga yagona istisnoni qo'shdi — ст.34 ning yangi o'n birinchi qismi: андеррайтер xizmatlari uchun 10 foizdan ortiq to'lov. Band ст.34 10-qismi bilan birga o'qiladi: qo'shimcha kelishuv shartnomaning muhim shartlarini — tovar (ish, xizmat) ni, uning sifati va assortimentini, miqdor va narxning oshirilishini, yetkazib berish muddatining uzaytirilishini — o'zgartirmasligi kerak. ⚠️ ЭСЛАТМА: ст.71 ga 07.07.2026 dagi ЗРУ-1157 bilan yana o'zgartirish kiritilgan, ruscha tarjima hali yangilanmagan.","tags":["pryamoy dogovor","foiz","qo'shimcha kelishuv"]},{"id":"zru-b-25","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.71 п.5","difficulty":3,"q":"Aql-zakovat faoliyati natijalari muallifidan yoki bu natijalardan foydalanishga eksklyuziv huquq egasidan xarid — ЗРУ-684 71-moddasining qaysi bandi?","options":[{"t":"п.1 — Единый поставщик реестрига kiritilgan ta'minotchidan xarid","ok":false,"why":"XATO — 1-band Реестр единых поставщиков ga kiritilgan yagona ta'minotchi haqida; u mualliflik/eksklyuziv huquq asosidan farq qiladi"},{"t":"п.2 — Prezident farmon/qarorlari va VM qarorlari asosidagi xarid","ok":false,"why":"XATO — 2-band yuqori hujjat asosini nazarda tutadi, intellektual mulk huquqini emas"},{"t":"п.5","ok":true,"why":"TO'G'RI — 71-modda 5-bandi aql-zakovat faoliyati natijalari muallifi yoki litsenziya shartnomasi asosida eksklyuziv huquqqa ega ta'minotchidan xaridni nazarda tutadi"},{"t":"п.13 — O'zbekiston ishlab chiqaruvchilaridan yangi avtotransport va maxsus texnika xaridi","ok":false,"why":"XATO — 13-band avtotransport, maxsus va qishloq xo'jaligi texnikasini ishlab chiqaruvchilardan yoki ularning rasmiy dilerlari/distribyutorlaridan xarid haqida"}],"exp":"ст.71 п.5 ikki holatni qamraydi: mahsulotni boshqa ta'minotchi yetkazib bera olmasligi litsenziya shartnomasi (shartnoma, kontrakt) bilan tasdiqlanganda muallif yoki eksklyuziv huquq egasidan xarid; hamda fan, adabiyot va san'at asarlari, ijrolar, fonogrammalar, efir yoki kabel eshittirish tashkilotlari uzatuvlari bo'yicha shu obyektga eksklyuziv huquqqa ega yagona shaxsdan xarid. Ekspertizada bu bandning asosi — huquqni tasdiqlovchi hujjat (litsenziya shartnomasi, mualliflik guvohnomasi), «boshqa yetkazib beruvchi yo'q» degan xatning o'zi emas. ⚠️ ЭСЛАТМА: ст.71 ga 07.07.2026 dagi ЗРУ-1157 bilan o'zgartirish kiritilgan, ruscha norasmiy tarjima hali yangilanmagan — bandlar raqamlanishini o'zbekcha rasmiy matndan qayta tekshirish tavsiya etiladi.","tags":["pryamoy dogovor","band","intellektual mulk"]},{"id":"zru-b-26","doc":"ЗРУ-684","topic":"Ekspertiza","ref":"ст.71","difficulty":2,"q":"Prezident farmoni/qarori yoki VM qarori bilan to'g'ridan-to'g'ri shartnoma asosida xarid ruxsat etilgan bo'lsa, ЗРУ-684 71-moddasi nimani talab qiladi?","options":[{"t":"Shartnoma va unga qo'shimcha kelishuvlar Markazning kompleks ekspertizasiga kiritiladi (qonunchilikda belgilangan istisnolardan tashqari)","ok":true,"why":"TO'G'RI — 71-modda: «договор и дополнительные соглашения к нему подлежат комплексной экспертизе в Центре комплексной экспертизы, за исключением случаев, установленных законодательством»"},{"t":"Faqat texnik topshiriq ekspertizaga kiritiladi, shartnomaning o'zi kiritilmaydi","ok":false,"why":"XATO — ТЗ ekspertizasi отбор uchun qoida (ст.56 ikkinchi qism, ст.58); to'g'ridan-to'g'ri shartnomada ekspertiza predmeti aynan shartnoma va qo'shimcha kelishuvlar"},{"t":"Ekspertiza talab qilinmaydi, chunki asos yuqori hujjat hisoblanadi","ok":false,"why":"XATO — yuqori hujjat usulni tanlashga asos beradi, ammo ekspertiza majburiyatini bekor qilmaydi"},{"t":"Ekspertiza faqat summa 25 000 БҲМ dan oshgan holda talab qilinadi","ok":false,"why":"XATO — 71-modda bu talabga summa sharti qo'ymaydi; 25 000 БҲМ (byudjet buyurtmachilari uchun 6 000) — ст.56/ст.64 dagi отбор↔tender chegarasi"}],"exp":"ст.71 to'g'ridan-to'g'ri shartnomalar uchun uchta majburiyatni belgilaydi: tuzilgan shartnoma haqidagi ma'lumot 5 ish kuni ichida maxsus axborot portaliga joylashtiriladi; joylashtirilmasa to'lov amalga oshirilmaydi; Prezident/VM hujjati asosidagi to'g'ridan-to'g'ri shartnoma va qo'shimcha kelishuvlar Markaz kompleks ekspertizasiga kiritiladi — qonunchilikda belgilangan istisnolardan tashqari (masalan ПҚ-104 bilan chiqarilgan toifalar). Bu Markazning «прямой контракт» yo'nalishidagi ish hajmining huquqiy asosi. ⚠️ ст.71 ga ЗРУ-1157 (07.07.2026) bilan o'zgartirish kiritilgan, lex.uz dagi ruscha norasmiy tarjima hali shu o'zgartirishgacha bo'lgan tahrirda — bandlar ro'yxatini o'zbekcha rasmiy matndan tekshirish kerak.","tags":["ekspertiza","pryamoy dogovor","shartnoma"]},{"id":"zru-b-27","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.72","difficulty":2,"q":"ЗРУ-684 72-moddasiga ko'ra yagona ta'minotchidan (единый поставщик) xarid qaysi holatda mumkin?","options":[{"t":"Buyurtmachi ta'minotchini ishonchli va sinalgan deb hisoblasa","ok":false,"why":"XATO — 72-modda subyektiv baholashni asos qilib olmaydi; istisno holatlar ro'yxati yopiq"},{"t":"Shu ta'minotchi bilan ilgari shartnoma tuzilgan bo'lsa","ok":false,"why":"XATO — «oldingi shartnoma» mantiqi ст.71 п.8 va п.21 ga tegishli, ст.72 ga emas"},{"t":"Ta'minotchining taklif narxi bozordagi eng past narx bo'lsa","ok":false,"why":"XATO — eng past narx аукцион va «электронный магазин» da g'olibni aniqlash mezoni, yagona ta'minotchi asosi emas"},{"t":"Ta'minotchi tabiiy monopoliya subyekti bo'lsa (yoki bozorda analogi yo'q texnik murakkab tovar va shu kabi holatlar)","ok":true,"why":"TO'G'RI — 72-modda «государственная закупка товаров (работ, услуг) субъекта естественной монополии» ni istisno holatlar ro'yxatiga kiritadi"}],"exp":"ст.72 yagona ta'minotchidan xaridni beshta istisno holat bilan cheklaydi: bozorda analogi yo'q va faqat yagona ta'minotchidan olish mumkin bo'lgan texnik murakkab tovar/ish/xizmat; madaniy boyliklar; Prezident farmoni/qarorlari yoki VM qarorlarida yagona ta'minotchi deb belgilangan subyektlar; tabiiy monopoliya subyekti; faqat davlat hokimiyati va boshqaruv organlari yoki ularga qarashli davlat muassasalari bajarishi mumkin bo'lgan ish/xizmatlar. Bunday ta'minotchi Реестр единых поставщиков ga kiritilgan bo'lishi shart (ст.72 birinchi qism, ст.71 п.1, ст.73), shartnoma haqidagi ma'lumot esa 5 ish kuni ichida portalga joylashtiriladi.","tags":["yagona ta'minotchi","monopoliya","pryamoy dogovor"]},{"id":"zru-b-28","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.46","difficulty":2,"q":"ЗРУ-684 46-moddasiga ko'ra xaridlar hajmini bo'laklarga bo'lish (дробление) qaysi holatda taqiqlanadi?","options":[{"t":"Har qanday holatda — xaridni lotlarga bo'lish ham taqiqlanadi","ok":false,"why":"XATO — lotlash aniq ruxsat etilgan (ст.59, ст.67): har bir tovar/ish/xizmat alohida birlik bo'lishi mumkin"},{"t":"Raqobatli usullardan qochish maqsadida bo'lingan bo'lsa","ok":true,"why":"TO'G'RI — 46-modda: «дробление объема государственных закупок на части с целью уклонения от конкурентных способов осуществления государственных закупок»"},{"t":"Faqat byudjet buyurtmachilariga nisbatan","ok":false,"why":"XATO — subyekt asossiz toraytirilgan; 46-modda barcha xarid subyektlariga taalluqli"},{"t":"Faqat bir moliya yili ichida ikki va undan ko'p marta takrorlansa","ok":false,"why":"XATO — modda takrorlanish sonini emas, maqsadni (raqobatli usuldan qochish) mezon qilib oladi"}],"exp":"ст.46 xarid jarayonidagi taqiqlar ro'yxatini beradi. Дробление uchun hal qiluvchi belgi — maqsad: raqobatli usuldan (аукцион, отбор, tender) qochish. Shu moddada демпинг ham taqiqlanadi (sun'iy pasaytirilgan narx bilan taklif berib, keyin shartnomani imzolamaslik yoki lozim darajada bajarmaslik), shuningdek texnologik va funksional jihatdan o'zaro bog'liq bo'lmagan tovar/ish/xizmatlarni bitta xaridga kiritish, raqobatsiz usulni noqonuniy tanlash, ishtirokchilar sonini asossiz cheklash yoki kvalifikatsiya talablarini oshirib yuborish, manfaatlar to'qnashuvi, yaqin qarindoshlar ishtiroki hamda moliyalashtirish manbasi va hajmi tasdiqlanmagan (yoki ajratilgan mablag'dan ortiq summadagi) xaridni o'tkazish.","tags":["cheklov","drobleniye","raqobat"]},{"id":"zru-b-29","doc":"ЗРУ-684","topic":"Shartnoma","ref":"ст.47","difficulty":1,"q":"ЗРУ-684 47-moddasiga ko'ra Единый реестр договоров ga kiritilmagan shartnoma bo'yicha qanday oqibat yuzaga keladi?","options":[{"t":"Shartnoma haqiqiy emas deb topiladi","ok":false,"why":"XATO — 47-modda shartnomaning haqiqiyligiga ta'sir qilmaydi, u to'lovni bloklaydi"},{"t":"Buyurtmachiga jarima solinadi","ok":false,"why":"XATO — 47-moddada jarima nazarda tutilmagan; javobgarlik umumiy tartibda (ст.81)"},{"t":"Bunday shartnomalar bo'yicha to'lov amalga oshirilmaydi","ok":true,"why":"TO'G'RI — 47-modda: «Платежи по договорам, информация о которых не включена в Единый реестр договоров, не осуществляются»"},{"t":"Ijrochi Единый реестр недобросовестных исполнителей ga kiritiladi","ok":false,"why":"XATO — reyestrlar almashtirilgan: insofsiz ijrochilar reyestrining asoslari ст.48 da, ular boshqa"}],"exp":"ст.47 Единый реестр договоров tarkibini belgilaydi: buyurtmachi nomi, moliyalashtirish manbasi, ijrochini aniqlash usuli, xarid natijalari sanasi va shartnoma tuzish asosini tasdiqlovchi hujjat rekvizitlari, shartnoma tuzilgan sana, tovar nomi, shartnoma narxi va ijro muddati, birlik narxi, kelib chiqish mamlakati va ishlab chiqaruvchi, ijrochi rekvizitlari va benefitsiar mulkdor haqida ma'lumot, shartnomaning o'zgarishi, ijrosi (jumladan to'lov va moliyaviy sanksiyalar) hamda bekor qilinishi haqidagi ma'lumotlar. Reyestrga kiritilmagan shartnoma bo'yicha to'lov o'tmaydi — bu ekspertizada shartnoma bandlarini tekshirishda amaliy ahamiyatga ega.","tags":["reyestr","to'lov","shartnoma"]},{"id":"zru-b-30","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.79","difficulty":3,"q":"Shikoyat kelib tushganda Shikoyatlarni ko'rib chiqish komissiyasi qanday muddatlarda ish ko'radi (ЗРУ-684 79-modda)?","options":[{"t":"3 ish kuni ichida buyurtmachini xabardor qiladi va xarid protsedurasini jami 10 ish kunigacha to'xtatadi; shikoyat olingandan keyin 7 ish kuni ichida qaror chiqaradi","ok":true,"why":"TO'G'RI — 79-modda birinchi va uchinchi qismlari aynan shu uch raqamni belgilaydi: 3 / 10 / 7 ish kuni"},{"t":"5 ish kuni ichida xabardor qiladi va 15 ish kuni ichida qaror chiqaradi","ok":false,"why":"XATO — ikkala raqam ham qonunda yo'q; xabardor qilish 3, qaror 7 ish kuni"},{"t":"3 ish kuni ichida xabardor qiladi va 30 kalendar kuni ichida qaror chiqaradi","ok":false,"why":"XATO — birinchi muddat to'g'ri, lekin qaror muddati 7 ISH kuni; kalendar kun hisobi qo'llanilmaydi"},{"t":"10 ish kuni ichida xabardor qiladi va protsedurani 7 ish kuniga to'xtatadi","ok":false,"why":"XATO — raqamlar joyi almashtirilgan: 10 ish kuni — to'xtatish muddati, 7 ish kuni — qaror muddati"}],"exp":"ст.79 bo'yicha komissiya shikoyat kelib tushgan kundan boshlab 3 ish kuni ichida buyurtmachini xabardor qiladi va xarid protsedurasini jami 10 ish kunigacha to'xtatadi, shikoyat olingandan keyin 7 ish kuni ichida qaror qabul qilib, u haqidagi ma'lumotni maxsus axborot portaliga joylashtiradi. Shikoyat asosli deb topilsa komissiya noqonuniy harakatlarni taqiqlashi, buyurtmachi qarorlarini qisman yoki to'liq bekor qilishi, protseduralarni tugatish to'g'risida qaror chiqarishi va ijrochini Insofsiz ijrochilar reyestriga kiritishi mumkin. Qarorlar barcha xarid subyektlari uchun majburiy, ijrochi esa ularni sudda shikoyat qilishi mumkin. ЗРУ-1005 bilan qo'shilgan ст.79¹ komissiya a'zolari uchun manfaatlar to'qnashuvi va affiliatsiya holatida o'z-o'zini rad etish (самоотвод) qoidasini belgilaydi.","tags":["shikoyat","muddat","komissiya"]},{"id":"vm-a-01","doc":"ВМ-276","topic":"Tender","ref":"п.128","difficulty":3,"q":"Tasdiqlangan tender hujjatlari va e'lon elektron tizimga qancha vaqt oldin joylashtiriladi?","options":[{"t":"Takliflar qabul qilish muddati tugashidan kamida 5 ish kun oldin","ok":false,"why":"5 ish kun — отбор e'loni muddati (п.78) va аукцион e'loni (п.49); tender uchun bu juda qisqa"},{"t":"Takliflar qabul qilish muddati tugashidan kamida 12 ish kun va ko'pi bilan 30 ish kun oldin","ok":true,"why":"п.128 aynan shu ikki tomonlama chegarani belgilaydi — pastki 12, yuqori 30 ish kun"},{"t":"Takliflar qabul qilish muddati tugashidan kamida 12 kalendar kun va ko'pi bilan 30 kalendar kun oldin","ok":false,"why":"Raqamlar to'g'ri, lekin п.128 da «иш куни» (ish kuni) deyilgan — kalendar kun emas, bu muddatni sezilarli qisqartiradi"},{"t":"Takliflar qabul qilish muddati tugashidan kamida 10 ish kun va ko'pi bilan 45 ish kun oldin","ok":false,"why":"10 ish kun — g'olibdan keyin shartnoma tuzish muddati (п.161), 45 ish kun — рамочное соглашение bo'yicha 1-bosqich baholash muddati (п.179)"}],"exp":"ВМ-276 п.128 bo'yicha tasdiqlangan tender xarid hujjatlari va tender e'loni takliflar qabul qilish muddati tugashidan kamida 12 va ko'pi bilan 30 ish kun oldin elektron tizimga joylashtiriladi. Bu ЗРУ-684 66-moddasi uchinchi qismidagi qoidani takrorlaydi; shu modda ikkinchi qismiga ko'ra e'lon faqat Kompleks ekspertiza markazining ijobiy xulosasi olingandan keyin joylashtiriladi. Ekspertizada muddat 12 ish kundan qisqa bo'lsa — raqobat sun'iy cheklangan deb baholanadi, 30 ish kundan uzun bo'lsa — protsedura buzilishi.","tags":["muddat","e'lon","tender"]},{"id":"vm-a-02","doc":"ВМ-276","topic":"Tender","ref":"п.78","difficulty":2,"q":"«Отбор наилучших предложений» e'loni (tender e'lonidan farqli) qancha vaqt oldin joylashtiriladi?","options":[{"t":"Takliflar qabul qilish muddati tugashidan kamida 12 ish kun oldin","ok":false,"why":"12 ish kun — tender e'lonining pastki chegarasi (п.128), отбор uchun emas"},{"t":"Takliflar qabul qilish muddati tugashidan kamida 3 ish kun oldin","ok":false,"why":"3 ish kun — reja-grafikka o'zgartirish kiritish muddati (п.5), e'lon muddati emas"},{"t":"Takliflar qabul qilish muddati tugashidan kamida 10 ish kun oldin","ok":false,"why":"10 ish kun — g'olib aniqlangandan keyin shartnoma tuzish muddati (п.103/п.161)"},{"t":"Takliflar qabul qilish muddati tugashidan kamida 5 ish kun oldin","ok":true,"why":"п.78 отбор xarid hujjatlari, shartnoma loyihasi va e'lon uchun kamida 5 ish kunni belgilaydi"}],"exp":"Отбор uchun ВМ-276 п.78 — kamida 5 ish kun, tender uchun п.128 — 12-30 ish kun. Ikki protsedura muddatini almashtirish eng ko'p uchraydigan xato. Ekspertizada avval protsedura turi aniqlanadi, keyin muddat tekshiriladi.","tags":["muddat","otbor","e'lon"]},{"id":"vm-a-03","doc":"ВМ-276","topic":"Tender","ref":"п.15","difficulty":3,"q":"Tender bo'yicha taklif ta'minoti (задаток) miqdori eng ko'pi bilan qancha bo'lishi mumkin?","options":[{"t":"5% dan ortiq bo'lishi mumkin emas","ok":true,"why":"п.15 tender uchun aynan 5% yuqori chegarasini belgilaydi"},{"t":"3% dan ortiq bo'lishi mumkin emas","ok":false,"why":"3% — отбор uchun chegara (п.15) hamda «электронный магазин» va аукцион uchun задаток miqdori (п.14)"},{"t":"10% dan ortiq bo'lishi mumkin emas","ok":false,"why":"10% — shartnoma bo'yicha qo'shimcha ish/xizmatlar qiymati chegarasi (п.215), taklif ta'minotiga aloqasi yo'q"},{"t":"15% dan ortiq bo'lishi mumkin emas","ok":false,"why":"15% — mahalliy ishlab chiqaruvchiga qo'shimcha ball formulasidagi koeffitsent (п.155¹), ta'minot miqdori emas"}],"exp":"ВМ-276 п.15 bo'yicha taklif ta'minoti komissiya tomonidan belgilanadi: отборда 3%, tenderda 5% dan ortiq bo'lishi mumkin emas. Komissiya taklif ta'minotidan tashqari залог yoki гарантия ham talab qilishi mumkin (ЗРУ-684 39-modda). G'olib shartnomadan bosh tortsa задаток qaytarilmaydi.","tags":["ta'minot","foiz","chegara"]},{"id":"vm-a-04","doc":"ВМ-276","topic":"Tender","ref":"п.130","difficulty":2,"q":"Tender hujjatlarida har bir tovar (ish, xizmat) alohida lot deb e'lon qilinsa, natija qanday bo'ladi?","options":[{"t":"Barcha lotlar bo'yicha bitta umumiy g'olib aniqlanadi va u bilan bitta shartnoma tuziladi","ok":false,"why":"Aksincha — lotlashning maqsadi bir nechta ishtirokchi bilan alohida shartnomalar tuzish imkonini berish"},{"t":"Har lot uchun kamida ikki g'olib (asosiy va zaxira) bilan shartnoma tuziladi","ok":false,"why":"п.130 har lot uchun FAQAT BITTA g'olib aniqlanishini belgilaydi; zaxira g'olib (резервный победитель) parallel shartnoma tomoni emas — shartnoma tuzish huquqi unga faqat g'olib bosh tortganda o'tadi (ЗРУ-684 71-modda)"},{"t":"Har lot uchun faqat bitta g'olib aniqlanadi va bir nechta ishtirokchi bilan alohida shartnomalar tuzilishi mumkin","ok":true,"why":"п.130 aynan shuni belgilaydi: lot — alohida birlik, har lotga 1 g'olib"},{"t":"Lotlash faqat отбор protsedurasida mumkin, tenderda ta'qiqlanadi","ok":false,"why":"п.130 tender uchun bevosita lotlashni nazarda tutadi (ЗРУ-684 67-moddasi ham)"}],"exp":"ВМ-276 п.130 bo'yicha buyurtmachi tender hujjatlarida har tovar/ish/xizmatni alohida lot deb e'lon qilishi mumkin; bunda har lot uchun faqat bitta g'olib aniqlanadi va bir nechta ishtirokchi bilan alohida shartnomalar tuzilishi mumkin. Amalda texnologik va funksional bog'liq bo'lmagan predmetlarni sun'iy birlashtirish ЗРУ-684 46-moddasi bilan bevosita ta'qiqlanadi.","tags":["lot","g'olib","raqobat"]},{"id":"vm-a-05","doc":"ВМ-276","topic":"Tender","ref":"п.121","difficulty":2,"q":"Tender xarid hujjatlarida majburiy ahamiyatdagi kriteriylarni belgilashda nima ta'qiqlanadi?","options":[{"t":"Miqdoriy ko'rsatkichlar uchun minimal va maksimal qiymatlarni belgilash","ok":false,"why":"п.153 aynan min/max qiymatlarni belgilashga ruxsat beradi — bu ta'qiq emas"},{"t":"ЗРУ-684 34-moddasiga muvofiq raqobatni cheklovchi talablarni kiritish","ok":true,"why":"п.121 majburiy kriteriylarni belgilashda raqobatni cheklovchi talablarni bevosita ta'qiqlaydi"},{"t":"Texnik qism uchun nomiqdoriy (ekspert) kriteriylardan foydalanish","ok":false,"why":"п.118 texnik qismni miqdoriy yoki nomiqdoriy ko'rsatkichlar bo'yicha aniqlashga ruxsat beradi"},{"t":"Kafolat muddati bo'yicha talab qo'yish","ok":false,"why":"ЗРУ-684 34-moddasi kafolat muddati va kafolatli xizmat talablarini belgilashni bevosita ruxsat etadi"}],"exp":"ВМ-276 п.121 bo'yicha tender hujjatlarida majburiy ahamiyatdagi kriteriylar belgilanishi mumkin, ammo ЗРУ-684 34-moddasiga muvofiq bunda raqobatni cheklovchi talablar kiritilishi ta'qiqlanadi. Bu Markaz ekspertizasidagi eng ko'p ishlatiladigan asos: brendga bog'lash, ortiqcha kvalifikatsiya, bitta ishlab chiqaruvchi parametrlari — hammasi shu band bilan qaytariladi.","tags":["mezon","raqobat","ta'qiq"]},{"id":"vm-a-06","doc":"ВМ-276","topic":"Tender","ref":"п.121","difficulty":2,"q":"Majburiy ahamiyatdagi kriteriyga muvofiq bo'lmagan tender taklifi bilan nima qilinadi?","options":[{"t":"Faqat narx qismi baholanmaydi, texnik qism baholashda qoladi","ok":false,"why":"п.121 qisman baholashni emas, ishtirokchini butunlay chetlatishni (отстранение) nazarda tutadi"},{"t":"Faqat birinchi bosqichda — rasmiylashtirish tekshiruvida chiqarib yuboriladi","ok":false,"why":"п.121 «tenderning istalgan bosqichida» deydi — chetlatish rasmiylashtirish bosqichi bilan cheklanmagan"},{"t":"Ishtirokchiga 2 ish kun ichida tuzatish uchun qaytariladi","ok":false,"why":"2 ish kun — tushuntirish berish muddati (п.141); taklifni tuzatib qayta topshirish tartibi nazarda tutilmagan"},{"t":"Baholashning istalgan bosqichida chiqarib yuboriladi","ok":true,"why":"п.121 majburiy kriteriyga nomuvofiqlik istalgan bosqichda elektron tizim orqali chetlatishga olib kelishini belgilaydi"}],"exp":"ВМ-276 п.121: majburiy ahamiyatdagi kriteriyga taklifning nomuvofiqligi tenderning istalgan bosqichida ishtirokchini elektron tizim orqali chetlatishga olib keladi. Shuning uchun majburiy kriteriylar mazmuni ekspertizada alohida tekshiriladi — noto'g'ri qo'yilgan majburiy kriteriy ishtirokchini asossiz chiqarib yuborish vositasiga aylanadi.","tags":["mezon","rad etish"]},{"id":"vm-a-07","doc":"ВМ-276","topic":"Tender","ref":"п.155","difficulty":2,"q":"Tender ishtirokchisining kvalifikatsiyasini baholashda buyurtmachi nimaga haqli emas?","options":[{"t":"Kvalifikatsiyani xarid hujjatlarida nazarda tutilmagan kriteriylar bo'yicha baholashga va hujjatlarda ko'zda tutilmagan hujjatlarni talab qilishga","ok":true,"why":"п.155 ikkala ta'qiqni ham bevosita belgilaydi — nazarda tutilmagan kriteriy ham, nazarda tutilmagan hujjat talabi ham mumkin emas"},{"t":"Kvalifikatsiya talablariga muvofiqlikni tasdiqlovchi hujjatlarni elektron tizimga ilova qilishni talab qilishga","ok":false,"why":"п.155 ning birinchi jumlasi aynan buni ruxsat etadi — agar bu tender xarid hujjatlarida nazarda tutilgan bo'lsa"},{"t":"Texnik qismni nomiqdoriy (ekspert) kriteriylar bo'yicha baholashga","ok":false,"why":"п.118 va п.152 nomiqdoriy kriteriylarni komissiya ovoz berishi orqali baholashni nazarda tutadi"},{"t":"Bal usulida har bir kriteriyga nisbiy ahamiyat berishga","ok":false,"why":"п.120 bal usulida har kriteriyga nisbiy ahamiyat belgilashni ruxsat etadi"}],"exp":"ВМ-276 п.155 bo'yicha tender hujjatlarida kvalifikatsiya talablariga muvofiqlikni tasdiqlovchi hujjatlarni ilova qilish nazarda tutilishi mumkin, ammo buyurtmachi kvalifikatsiyani hujjatlarda ko'zda tutilmagan kriteriylar bo'yicha baholashga va nazarda tutilmagan hujjatlarni talab qilishga haqli emas. Bu ЗРУ-684 32-moddasidagi «faqat xarid hujjatlarida ko'rsatilgan mezonlar va protseduralar qo'llaniladi» qoidasining protsedura darajasidagi ifodasi.","tags":["mezon","hujjat","baholash"]},{"id":"vm-a-08","doc":"ВМ-276","topic":"Tender","ref":"п.154","difficulty":2,"q":"Moliyaviy resurslar, tajriba va obro', inson resurslari kabi qo'shimcha kvalifikatsion kriteriylarni tenderda kim belgilashi mumkin?","options":[{"t":"Faqat Markaz o'z ekspertiza xulosasida","ok":false,"why":"Markaz xarid hujjatlari ekspertizasini o'tkazadi, baholash kriteriylarini o'zi belgilamaydi"},{"t":"Elektron tizim operatori","ok":false,"why":"Operator xarid jarayoniga aralashishi va hujjatlar mazmunini o'zgartirishi bevosita ta'qiqlangan (ЗРУ-684 25-modda)"},{"t":"Xarid komissiyasi — xarid predmetining o'ziga xosligidan kelib chiqib","ok":true,"why":"п.154 aynan komissiyaga bunday kriteriylarni belgilash huquqini beradi"},{"t":"Vazirlar Mahkamasi har bir xarid uchun alohida qaror bilan","ok":false,"why":"VM umumiy tartibni belgilaydi (ВМ-276 ning o'zi), ayrim xaridning kriteriylarini emas"}],"exp":"ВМ-276 п.154 bo'yicha komissiya xarid predmeti xususiyatlaridan kelib chiqib kasbiy-texnik kvalifikatsiya, kompetensiya, moliyaviy resurslar, uskunalar, boshqaruv kompetensiyasi, ishonchlilik, tajriba va obro' hamda inson resurslari bo'yicha qo'shimcha kriteriylar belgilashi mumkin. Ammo shu bandning o'zi diskriminatsiya, ayrim ishtirokchiga imtiyozli shart-sharoit yoki raqobatni cheklash imkonini beruvchi kriteriylarni qo'llashni ta'qiqlaydi.","tags":["kvalifikatsiya","mezon","komissiya"]},{"id":"vm-a-09","doc":"ВМ-276","topic":"Tender","ref":"п.146","difficulty":3,"q":"Tender takliflari qanday ketma-ketlikda baholanadi?","options":[{"t":"Narx qismi → texnik qism → kvalifikatsiya → rasmiylashtirish","ok":false,"why":"Bu ketma-ketlik teskari: narx eng oxirida ochiladi, rasmiylashtirish esa birinchi tekshiriladi"},{"t":"Kvalifikatsiya → rasmiylashtirish → narx qismi → texnik qism","ok":false,"why":"Rasmiylashtirish kvalifikatsiyadan oldin turadi, narx esa texnik qismdan keyin baholanadi"},{"t":"Rasmiylashtirish → texnik qism → narx qismi → kvalifikatsiya","ok":false,"why":"Kvalifikatsiya baholash oxirida emas, rasmiylashtirishdan keyin ikkinchi o'rinda turadi"},{"t":"Rasmiylashtirish → kvalifikatsiya (hujjatlarda nazarda tutilgan bo'lsa) → texnik qism → narx qismi","ok":true,"why":"п.146 aynan shu to'rt bosqichli ketma-ketlikni belgilaydi"}],"exp":"ВМ-276 п.146 baholashning qat'iy ketma-ketligini belgilaydi: rasmiylashtirish, keyin kvalifikatsiya (agar xarid hujjatlarida nazarda tutilgan bo'lsa), keyin texnik qism va oxirida narx qismi. Ketma-ketlikning buzilishi — protsedura buzilishi, chunki narxni oldin ko'rish texnik baholashga ta'sir qilish imkonini beradi.","tags":["baholash","ketma-ketlik"]},{"id":"vm-a-10","doc":"ВМ-276","topic":"Tender","ref":"п.146","difficulty":2,"q":"Elektron tizim tender taklifining keyingi qismini qachon ochadi?","options":[{"t":"Faqat oldingi qism bo'yicha baholash yakunlangandan keyin","ok":true,"why":"п.146 tizim kvalifikatsiya, texnik va narx qismlaridagi ma'lumotni ketma-ket, oldingi qism yakunlangach ochishini bevosita belgilaydi"},{"t":"Takliflar qabul qilish muddati tugashi bilan barcha qismlar bir vaqtda ochiladi","ok":false,"why":"Bu bir bosqichli tender tartibi bilan chalkashtiradi; п.146 bosqichma-bosqich ochishni talab qiladi"},{"t":"Komissiya raisining so'roviga ko'ra istalgan vaqtda","ok":false,"why":"Rais ochish vaqtini o'zgartira olmaydi — ochish tizim tomonidan avtomatik boshqariladi"},{"t":"Mas'ul kotib ishtirokchidan tushuntirish so'raganidan keyin","ok":false,"why":"Tushuntirish so'rash alohida protsedura (п.150) va qismlarni ochish tartibiga ta'sir qilmaydi"}],"exp":"ВМ-276 п.146 bo'yicha elektron tizim taklifning keyingi qismini faqat oldingisi yakunlangach ochadi. Bu texnik baholashning narxdan mustaqilligini ta'minlaydigan kafolat. Ekspertizada tender hujjatlarida qismlarning ajratilgani va ularning nisbiy ahamiyati belgilangani tekshiriladi (п.116, п.123).","tags":["baholash","elektron tizim"]},{"id":"vm-a-11","doc":"ВМ-276","topic":"Tender","ref":"п.153","difficulty":3,"q":"Miqdoriy kriteriy bo'yicha ishtirokchining ko'rsatkichi xarid hujjatlaridagi maksimumdan yuqori bo'lsa, unga qanday ball beriladi?","options":[{"t":"Ko'rsatkich qancha oshsa, shuncha ko'p qo'shimcha ball beriladi","ok":false,"why":"п.153 maksimumdan yuqori qismni hisobga olmaydi — ball oshirilmaydi"},{"t":"Maksimal ball beriladi — ko'rsatkich qancha oshsa ham","ok":true,"why":"п.153 aynan shuni belgilaydi: ko'rsatkich maksimumdan qanchalik oshishidan qat'i nazar, shu kriteriy bo'yicha maksimal ball qo'yiladi"},{"t":"Taklif belgilangan maksimumdan chetga chiqqani uchun chiqarib yuboriladi","ok":false,"why":"Chetlatish majburiy kriteriyga nomuvofiqlik (п.121) yoki narx «стартовая цена»дан yuqori bo'lgan holatda (п.145) qo'llanadi"},{"t":"Minimal ball beriladi","ok":false,"why":"Minimal ball minimumdan PAST ko'rsatkichga beriladi, maksimumdan yuqorisiga emas"}],"exp":"ВМ-276 п.153 bo'yicha xarid hujjatlarida min va max qiymatlar belgilanishi mumkin: minimumdan past ko'rsatkich minimal ball, maksimumdan yuqorisi maksimal ball oladi, oraliqdagi ko'rsatkich uchun esa ball koeffitsenti uning ko'rsatkichi va (max−min) farqiga nisbat sifatida hisoblanadi. Ball avtomatik ravishda kriteriyning hisobga olinadigan qiymatiga ko'paytiriladi.","tags":["ball","mezon","baholash"]},{"id":"vm-a-12","doc":"ВМ-276","topic":"Tender","ref":"п.155¹","difficulty":3,"q":"Bal usulida mahalliy ishlab chiqaruvchi taklifiga beriladigan qo'shimcha ballar qaysi formula bo'yicha hisoblanadi?","options":[{"t":"ДБ = НБ × 10% × УЛ","ok":false,"why":"Formuladagi koeffitsent 10% emas, 15%; 10% — п.215 dagi qo'shimcha ish chegarasi"},{"t":"ДБ = НБ + 15%","ok":false,"why":"Qo'shimcha ballar oddiy 15% ustama emas — ular lokalizatsiya darajasiga proportsional ko'paytma orqali hisoblanadi"},{"t":"ДБ = НБ × 15% × УЛ","ok":true,"why":"п.155¹ aynan shu formulani belgilaydi: olingan ball × 15% × lokalizatsiya darajasi"},{"t":"ДБ = НБ × УЛ / 15%","ok":false,"why":"Bo'lish amali formulaga kiritilmagan — 15% ko'paytiruvchi koeffitsent"}],"exp":"ВМ-276 п.155¹ (tenderda) va п.95¹ (отборда) bo'yicha mahalliy ishlab chiqaruvchi takliflariga lokalizatsiya darajasiga proportsional qo'shimcha ballar beriladi: ДБ = НБ × 15% × УЛ. Lokalizatsiya darajasi VM 28.10.2024 № 712 qarori bilan tasdiqlangan Nizomga muvofiq aniqlanadi, ballarni esa elektron tizim avtomatik hisoblab, protokolda qayd etadi.","tags":["ball","mahalliy ishlab chiqaruvchi","formula"]},{"id":"vm-a-13","doc":"ВМ-276","topic":"Tender","ref":"п.155¹","difficulty":3,"q":"Mahalliy ishlab chiqaruvchiga qo'shimcha ballar qaysi holatda umuman berilmaydi?","options":[{"t":"Narxi boshqa ishtirokchilarning eng past narxidan 5% dan ko'p bo'lsa","ok":false,"why":"Chegara 5% emas — п.155¹ da 15% ko'rsatilgan"},{"t":"Narxi «стартовая цена»дан 10% dan ko'proq past bo'lsa","ok":false,"why":"Narxning pastligi bo'yicha qoida — демпинг (20% va undan past narxda qo'shimcha задаток, п.43/п.54), qo'shimcha ballarga aloqasi yo'q"},{"t":"Lokalizatsiya darajasi 50% dan past bo'lsa","ok":false,"why":"Lokalizatsiya darajasi cheklov emas — u formulaga ko'paytuvchi sifatida kiradi (УЛ)"},{"t":"Narxi boshqa ishtirokchilarning eng past narxidan 15% dan ko'p bo'lsa","ok":true,"why":"п.155¹ aynan shu cheklovni belgilaydi — bunday holda qo'shimcha ballar berilmaydi"}],"exp":"ВМ-276 п.155¹ bo'yicha mahalliy ishlab chiqaruvchining narx taklifi boshqa ishtirokchilar taklif qilgan eng past narxdan 15% dan ko'proq oshsa, qo'shimcha ballar berilmaydi. Ya'ni preferentsiya cheklangan — u narx farqi maqbul doirada bo'lgandagina ishlaydi.","tags":["ball","chegara","foiz"]},{"id":"vm-a-14","doc":"ВМ-276","topic":"Tender","ref":"п.156","difficulty":3,"q":"Bal usulida ikki ishtirokchi bir xil ball to'plasa, g'olib qanday aniqlanadi?","options":[{"t":"Eng past narx taklif qilgan ishtirokchi g'olib deb topiladi","ok":true,"why":"п.156 bal usulida ballar teng bo'lganda narx bo'yicha hal qilishni belgilaydi"},{"t":"Texnik qismi eng optimal bo'lgan ishtirokchi g'olib deb topiladi","ok":false,"why":"Bu «eng past narx» usulidagi teng holat qoidasi — bal usuli uchun teskari qo'llanadi"},{"t":"Taklifni birinchi bo'lib topshirgan ishtirokchi g'olib deb topiladi","ok":false,"why":"Taklif topshirilgan vaqt g'olibni aniqlash mezoni sifatida nazarda tutilmagan"},{"t":"Komissiya raisining hal qiluvchi ovozi bilan g'olib aniqlanadi","ok":false,"why":"Raisning hal qiluvchi ovozi ovozlar tengligida komissiya qarorlari uchun qo'llanadi (ЗРУ-684 20-modda), g'olibni aniqlash mezoni emas"}],"exp":"ВМ-276 п.156 bo'yicha bal usulida ballar teng bo'lsa g'olib eng past narx bo'yicha, eng past narx usulida esa — eng optimal texnik qism bo'yicha aniqlanadi. Zaxira g'olib (резервный победитель) ham xuddi shu tartibda belgilanadi.","tags":["g'olib","ball","narx"]},{"id":"vm-a-15","doc":"ВМ-276","topic":"Tender","ref":"п.156","difficulty":2,"q":"«Eng past narx» usulida tender g'olibi kim bo'ladi?","options":[{"t":"Barcha ishtirokchilar ichida eng past narx taklif qilgan, texnik baholash natijasidan qat'i nazar","ok":false,"why":"Narx qismi faqat texnik baholashdan keyin ochiladi (п.146) — texnikdan o'tmagan taklif narx bo'yicha yutolmaydi"},{"t":"Texnik qism baholash natijalariga ko'ra tenderda keyingi ishtirokka qo'yilganlar ichida eng past narx taklif qilgan","ok":true,"why":"п.156 aynan shu shartni belgilaydi: avval texnik qism baholanadi, keyin qo'yilganlar orasidan eng past narx"},{"t":"Eng ko'p ball to'plagan ishtirokchi","ok":false,"why":"Ballar bo'yicha g'olib aniqlash — bal usuli, «eng past narx» usuli emas"},{"t":"«Стартовая цена»га eng yaqin narx taklif qilgan ishtirokchi","ok":false,"why":"«Стартовая цена» — yuqori chegara: undan yuqori takliflar tizim tomonidan rad etiladi (п.145), unga yaqinlik afzallik bermaydi"}],"exp":"ВМ-276 п.156 bo'yicha eng past narx usulida g'olib — texnik qism baholash natijalariga ko'ra tenderda keyingi ishtirokka qo'yilganlar ichida eng past narx taklif qilgan ishtirokchi. Bu usulda texnik kriteriylar ball bermaydi, faqat «muvofiq / muvofiq emas» ni aniqlaydi (п.120).","tags":["g'olib","narx","usul"]},{"id":"vm-a-16","doc":"ВМ-276","topic":"Shartnoma","ref":"п.161","difficulty":2,"q":"Tender natijalari bo'yicha shartnoma qachon tuziladi?","options":[{"t":"G'olib aniqlangandan keyin 3 ish kun ichida","ok":false,"why":"3 ish kun — отбор bo'yicha yakuniy protokolni (п.102) va to'g'ri shartnoma ma'lumotini portalga joylashtirish (п.186) muddati, shartnoma tuzish muddati emas"},{"t":"G'olib aniqlangandan keyin 5 ish kun ichida","ok":false,"why":"5 ish kun — отбор e'loni (п.78) va «рамочное соглашение» 2-bosqichidagi takliflar muddati (п.180)"},{"t":"G'olib aniqlangandan keyin kech 10 ish kunda","ok":true,"why":"п.161 shartnomani g'olib aniqlangandan keyin 10 ish kundan kech bo'lmagan muddatda tuzishni belgilaydi"},{"t":"G'olib aniqlangandan keyin 30 kalendar kun ichida","ok":false,"why":"30 — tender e'lonining yuqori chegarasi (п.128) va u ish kunlarida hisoblanadi"}],"exp":"ВМ-276 п.161 bo'yicha tender natijalari bo'yicha shartnoma xarid hujjatlari va g'olib taklifi shartlariga muvofiq, g'olib aniqlangandan keyin kech 10 ish kunda tuziladi. Xuddi shu muddat отбор (п.103) va «рамочное соглашение» (п.183) uchun ham qo'llanadi.","tags":["muddat","shartnoma"]},{"id":"vm-a-17","doc":"ВМ-276","topic":"Tender","ref":"п.15","difficulty":2,"q":"Tender g'olibi shartnoma tuzishdan bosh tortsa, uning garov puli (задаток) bilan nima bo'ladi?","options":[{"t":"Darhol to'liq qaytariladi","ok":false,"why":"п.162 qaytarish asoslarini sanab o'tadi (ta'minot hujjati muddati tugashi, shartnoma kuchga kirishi, xarid bekor qilinishi, taklifni muddatdan oldin qaytarib olish) — g'olibning bosh tortishi ular orasida yo'q"},{"t":"Zaxira g'olib hisobiga o'tkaziladi","ok":false,"why":"Zaxira g'olibga faqat shartnoma tuzish huquqi o'tadi (п.156), boshqa ishtirokchining garov puli emas"},{"t":"Yarmi qaytariladi, yarmi buyurtmachida qoladi","ok":false,"why":"п.15 qisman qaytarishni nazarda tutmaydi — garov puli summasi to'liq qaytarilmaydi"},{"t":"Qaytarilmaydi va operator tomonidan buyurtmachining tegishli hisobiga o'tkaziladi","ok":true,"why":"п.15: «в случае отказа победителя от заключения договора сумма его задатка не возвращается и данные средства зачисляются оператором на соответствующий счет государственных заказчиков (на соответствующий внебюджетный счет бюджетного заказчика)»"}],"exp":"ВМ-276 п.15 bo'yicha отбор yoki tender g'olibining garov puli shartnoma tuzilgunga qadar bloklanadi; g'olib shartnoma tuzishdan bosh tortsa — garov puli qaytarilmaydi va operator tomonidan buyurtmachining tegishli hisobiga (byudjet buyurtmachisida — byudjetdan tashqari hisobiga) o'tkaziladi. Shu п.15 garov puli chegarasini ham beradi: отборда tovar (ish, xizmat) qiymatining 3 % dan, tenderda 5 % dan oshmasligi kerak.","tags":["ta'minot","javobgarlik"]},{"id":"vm-a-18","doc":"ВМ-276","topic":"Tender","ref":"п.159","difficulty":2,"q":"Buyurtmachi tenderni qachon bekor qilishi mumkin?","options":[{"t":"G'olib taklifi aksept qilinishidan oldin istalgan vaqtda, asoslangan sabablarni elektron xaridlar tizimida e'lon qilib","ok":true,"why":"п.159 aynan akseptgacha bo'lgan istalgan vaqtni belgilaydi va sabablarni «в электронной системе государственных закупок» e'lon qilishni talab qiladi"},{"t":"Faqat takliflar qabul qilish muddati boshlanishidan oldin","ok":false,"why":"Bekor qilish huquqi protsedura boshlanishi bilan tugamaydi — п.159 uni akseptgacha saqlaydi"},{"t":"Faqat Shikoyatlarni ko'rib chiqish komissiyasi qarori asosida","ok":false,"why":"Komissiya qarori bilan protsedurani to'xtatish — alohida asos; п.159 buyurtmachining o'z huquqini hech qanday tashqi qarorga bog'lamaydi"},{"t":"Shartnoma imzolangunga qadar istalgan vaqtda","ok":false,"why":"Chegara — aksept momenti, shartnoma imzolash emas; п.161 ga ko'ra shartnoma g'olib aniqlangandan keyin 10 ish kuni ichida tuziladi"}],"exp":"ВМ-276 п.159 bo'yicha buyurtmachi tenderni g'olib taklifi aksept qilinishidan oldin istalgan vaqtda bekor qilishi mumkin va bu qarorning asoslangan sabablarini elektron xaridlar tizimida e'lon qiladi (maxsus axborot portalida emas). п.160 ga ko'ra buyurtmachi tenderni bekor qilgani uchun javobgar bo'lmaydi — bekor qilish uning o'zining qonunga xilof harakati (harakatsizligi) oqibati bo'lgan holatlardan tashqari.","tags":["bekor qilish","protsedura"]},{"id":"vm-a-19","doc":"ВМ-276","topic":"Tender","ref":"п.141","difficulty":2,"q":"Ishtirokchi tender hujjatlari bo'yicha tushuntirish so'rasa, buyurtmachi qancha muddatda javob beradi?","options":[{"t":"1 ish kun ichida","ok":false,"why":"1 ish kun — ta'minotning maqbulligini tasdiqlash so'roviga javob (п.142) va operatorning to'lov topshirig'i / garov pulini qaytarish muddati (п.31-32); tushuntirishga aloqasi yo'q"},{"t":"2 ish kun ichida","ok":true,"why":"п.141: «Государственный заказчик в течение двух рабочих дней с даты поступления запроса должен направить разъяснения ... через открытый электронный чат»"},{"t":"3 ish kun ichida","ok":false,"why":"3 ish kun — отбор bo'yicha komissiya bayonnomasini joylashtirish (п.102) va to'g'ri shartnoma ma'lumotini portalga kiritish (п.186) muddati"},{"t":"5 ish kun ichida","ok":false,"why":"5 ish kun — отбор e'loni muddati (п.78); tenderda esa e'lon kamida 12 va ko'pi bilan 30 ish kun oldin joylashtiriladi (п.128)"}],"exp":"ВМ-276 п.140-141 bo'yicha ishtirokchi ochiq elektron chat orqali tushuntirish so'raydi, buyurtmachi so'rov kelgan kundan boshlab 2 ish kuni ichida shu chat orqali javob beradi. Muhim cheklov: tushuntirishlar tender xarid hujjatlarining mohiyatini o'zgartira olmaydi — mazmuniy o'zgarish faqat hujjatlarga rasmiy o'zgartirish kiritish orqali qilinadi. Отборда xuddi shu qoida п.87 da berilgan.","tags":["muddat","tushuntirish"]},{"id":"vm-a-21","doc":"ВМ-276","topic":"Tender","ref":"п.143-145","difficulty":2,"q":"Ishtirokchining tender taklifidagi narx «стартовая цена»дан yuqori bo'lsa nima bo'ladi?","options":[{"t":"Taklif rad etiladi va keyingi baholashga o'tkazilmaydi","ok":true,"why":"п.145: narx «стартовая цена»дан oshsa, elektron tizim taklifni rad etish sabablarini aniq ko'rsatgan holda avtomatik rad etadi"},{"t":"Taklif baholanadi, lekin narx qismi bo'yicha minimal ball oladi","ok":false,"why":"Minimal ball — miqdoriy kriteriy qiymati hisobga olinadigan minimumdan past bo'lgan holat qoidasi (п.153), «стартовая цена» chegarasi uchun emas"},{"t":"Ishtirokchi farq miqdorida qo'shimcha garov puli (задаток) kiritishi shart","ok":false,"why":"Qo'shimcha garov puli — демпинг qoidasi: narx 20 % va undan ko'p PAST bo'lganda (electron do'kon — п.43, аукцион — п.54); bu esa teskari holat"},{"t":"Komissiya ishtirokchiga narxni «стартовая цена»гача tushirishni taklif qiladi","ok":false,"why":"Bunday muzokara tartibi ВМ-276 da yo'q — п.145 avtomatik rad etishni belgilaydi, п.150 esa faqat tushuntirish so'rashga yo'l qo'yadi"}],"exp":"ВМ-276 п.143-145 bo'yicha tizim takliflarni avtomatik tekshiradi: «стартовая цена»дан yuqori narx, to'ldirilmagan majburiy maydonlar va biriktirilishi shart bo'lgan fayllarning yo'qligi — rad etish asoslari. Biriktirilgan fayllardagi ma'lumot taklifdagi ma'lumotga mos kelishini esa komissiyaning mas'ul kotibi tekshiradi. Отборда xuddi shu qoida п.90 sifatida ifodalangan.","tags":["narx","rad etish"]},{"id":"vm-a-22","doc":"ВМ-276","topic":"Tender","ref":"п.115","difficulty":1,"q":"Tender o'tkazish qarori qabul qilingach, tender xarid hujjatlari, shartnoma va e'lon matnini kim ishlab chiqadi?","options":[{"t":"Elektron tizim operatori","ok":false,"why":"Operator faqat tipovoy shakllarni belgilaydi (п.132) va protsedura xizmatlarini ko'rsatadi — xarid hujjatlari tarkibini shakllantirmaydi"},{"t":"Markaz — ekspertiza xulosasi bilan birga","ok":false,"why":"Markaz tayyor hujjatlarga kompleks ekspertiza o'tkazadi (qiyoslash uchun п.189), ularni ishlab chiqmaydi — aks holda ekspertiza mustaqilligi buziladi"},{"t":"Faqat ixtisoslashgan tashkilot","ok":false,"why":"п.115 ixtisoslashgan tashkilotni umuman tilga olmaydi — hujjatni buyurtmachi tomoni ishlab chiqadi"},{"t":"Buyurtmachining mutaxassislari yoki xaridni tashkil qilish va o'tkazishga mas'ul shaxs","ok":true,"why":"п.115 aynan «специалистами государственного заказчика или лицом, ответственным за организацию и проведение тендера» deb ko'rsatadi"}],"exp":"ВМ-276 п.115 bo'yicha buyurtmachi tender o'tkazish qarorini qabul qilgach, uning mutaxassislari yoki tenderni tashkil qilish va o'tkazishga mas'ul shaxs tender xarid hujjatlarini, shartnomani va e'lon matnini ishlab chiqadi. Keyin hujjat п.122 ga ko'ra komissiyaga kelishishga kiritiladi. Отбор uchun xuddi shu qoida п.66 da berilgan; отборда bundan tashqari п.78 e'lon bilan birga shartnoma loyihasini ham joylashtirishni to'g'ridan-to'g'ri talab qiladi.","tags":["hujjat","buyurtmachi"]},{"id":"vm-a-23","doc":"ВМ-276","topic":"Tender","ref":"п.123","difficulty":2,"q":"Tender komissiyasi tender xarid hujjatlarini ko'rib chiqishda nimalarni belgilaydi?","options":[{"t":"«Стартовая цена»ни va xaridning moliyalashtirish manbasini","ok":false,"why":"п.123 ro'yxatida bular yo'q; moliyalashtirish manbai reja-jadvalda ko'rsatiladi (п.6)"},{"t":"Takliflar qabul qilish muddatini, baholash usullari va kriteriylarini, taklif qismlarining nisbiy ahamiyatini, taklif ta'minoti hajmi va shaklini","ok":true,"why":"п.123 aynan shu to'rt guruh masalani komissiya vakolatiga beradi"},{"t":"G'olib bilan tuziladigan shartnoma narxini va to'lov jadvalini","ok":false,"why":"Shartnoma g'olib taklifi shartlari asosida tuziladi (п.161), komissiya tomonidan oldindan belgilanmaydi"},{"t":"Ishtirokchilar ro'yxatini va ularning kvalifikatsiyasini oldindan","ok":false,"why":"Kvalifikatsiya takliflarni baholash ketma-ketligida tekshiriladi (п.146), hujjatni kelishish bosqichida emas"}],"exp":"ВМ-276 п.123 bo'yicha komissiya tender xarid hujjatlarini Qonun talablariga muvofiqligini yuzma-yuz majlisda yoki masofadan ko'rib chiqadi va: takliflar qabul qilish muddatini; baholash usullari va kriteriylarini; taklif qismlarining (zarur hollarda — texnik qism har bir kriteriyasining) nisbiy ahamiyatini; taklif ta'minotining hajmi va shaklini belgilaydi. Отбор uchun xuddi shu vakolat п.74 da ifodalangan.","tags":["komissiya","hujjat","mezon"]},{"id":"vm-a-24","doc":"ВМ-276","topic":"Tender","ref":"п.127","difficulty":1,"q":"Komissiya bilan kelishilgan tender xarid hujjatlari qanday tasdiqlanadi?","options":[{"t":"Buyurtmachi rahbarining qog'oz buyrug'i bilan","ok":false,"why":"Tender п.106 ga ko'ra majburiy elektron shaklda o'tkaziladi — tasdiqlash ham elektron amalga oshiriladi"},{"t":"Komissiya raisining hal qiluvchi ovozi bilan","ok":false,"why":"Komissiya hujjatni kelishadi (п.122-126), tasdiqlash esa п.127 bo'yicha buyurtmachi zimmasida qoladi"},{"t":"Buyurtmachi tomonidan elektron raqamli imzo (ЭЦП) orqali","ok":true,"why":"п.127: «Государственный заказчик утверждает согласованную закупочную документацию по тендеру посредством ЭЦП»"},{"t":"Elektron tizim operatori tomonidan avtomatik","ok":false,"why":"Operator hujjatni tasdiqlamaydi; avtomatik rejim п.143-145 va п.156 dagi tekshirish va g'olibni aniqlashga tegishli"}],"exp":"ВМ-276 п.127 bo'yicha komissiya bilan kelishilgan tender xarid hujjatlarini buyurtmachi ЭЦП orqali tasdiqlaydi; tasdiqlangan hujjat va e'lon п.128 ga ko'ra takliflar qabuli tugash sanasidan kamida 12 va ko'pi bilan 30 ish kuni oldin joylashtiriladi. п.9 ga ko'ra tizim orqali ЭЦП bilan imzolangan davlat xaridi shartnomalari tegishli shaklda tuzilgan hisoblanadi. Отборда bunga п.77 mos keladi.","tags":["ЭЦП","hujjat"]},{"id":"vm-a-25","doc":"ВМ-276","topic":"Tender","ref":"п.112-114","difficulty":2,"q":"Tender komissiyasi raisida affiliatsiya aloqalari aniqlansa nima bo'ladi?","options":[{"t":"Rais faqat ovoz berishdan chetlashtiriladi, jarayon davom etadi","ok":false,"why":"п.114 ga ko'ra rais umuman ovoz berishdan voz kecha olmaydi; affiliatsiya holatida esa п.113 butun jarayonni to'xtatadi"},{"t":"Tender bekor qilinadi va qaytadan e'lon qilinadi","ok":false,"why":"To'xtatish (приостановление) bekor qilish emas — bekor qilish alohida asos (п.159); yangi rais tayinlangach protsedura o'z o'rnidan davom etadi"},{"t":"Buyurtmachi vaqtinchalik yangi rais tayinlagunga qadar tender jarayoni to'xtatiladi","ok":true,"why":"п.113: «процесс проведения тендера приостанавливается до момента назначения государственным заказчиком временного нового председателя закупочной комиссии»"},{"t":"Qaror komissiyaning qolgan a'zolari ovozi bilan qabul qilinadi","ok":false,"why":"Kvorum saqlansa ham п.113 jarayonni davom ettirishga yo'l qo'ymaydi — u shartsiz to'xtatishni belgilaydi"}],"exp":"ВМ-276 п.112 bo'yicha har bir komissiya a'zosi, jumladan rais, shaxsiy kabinetga birinchi marta kirganda xo'jalik yurituvchi subyektlar bilan affiliatsiya xarakteridagi aloqalari haqidagi ma'lumotni kiritishi shart (bu ma'lumot maxfiyligi uchun operator javobgar). п.113 ga ko'ra raisda affiliatsiya bo'lsa — tender jarayoni buyurtmachi VAQTINCHALIK yangi rais tayinlagunga qadar to'xtatiladi. Отборда xuddi shu qoida п.64 da («временного» so'zisiz). п.114: belgilangan muddatda ovoz bermagan a'zo voz kechgan hisoblanadi, rais yoki uning v.b. esa ovoz berishdan voz kecha olmaydi.","tags":["affiliatsiya","komissiya"]},{"id":"vm-a-26","doc":"ВМ-276","topic":"Tender","ref":"п.157-158","difficulty":2,"q":"Tender takliflarini ko'rib chiqish va baholash bayonnomasida quyidagilardan qaysi biri majburiy ravishda ko'rsatiladi?","options":[{"t":"Har bir ishtirokchi taklifining tannarx kalkulyatsiyasi","ok":false,"why":"п.158 ro'yxatida bunday rekvizit yo'q — tannarx kalkulyatsiyasi ishtirokchining ichki hujjati"},{"t":"Har bir komissiya a'zosining ismma-ism qanday ovoz bergani","ok":false,"why":"п.158 hozir bo'lgan a'zolar TARKIBINI talab qiladi; shaxsiy ovozlarni ismma-ism yozish majburiy rekvizit sifatida belgilanmagan"},{"t":"Markaz kompleks ekspertizasi xulosasining raqami va sanasi","ok":false,"why":"Ekspertiza xarid hujjatlari bosqichiga tegishli; п.158 dagi bayonnoma rekvizitlari ro'yxatida u yo'q"},{"t":"Rad etilgan ishtirokchilar — rad etishning aniq sabablari va asoslari ko'rsatilgan holda","ok":true,"why":"п.158: «об участниках тендера, тендерные предложения которых были отклонены, с указанием конкретных причин и обоснований их отклонения»"}],"exp":"ВМ-276 п.158 bo'yicha bayonnomada: ko'rib chiqish va baholash sanasi hamda vaqti; hozir bo'lgan komissiya a'zolari va ishtirokchilarning vakolatli vakillari tarkibi; takliflari ko'rib chiqilgan ishtirokchilar; har bir taklifni baholash natijalari; rad etilgan ishtirokchilar aniq sabab va asoslari bilan; g'olib (zaxira g'olib) haqidagi qaror; g'olibning nomi/F.I.Sh. va joylashgan joyi ko'rsatiladi. п.157 ga ko'ra a'zolar tizimda avtomatik shakllangan bayonnomani ЭЦП bilan tasdiqlaydi, ko'chirma esa avtomatik e'lon qilinadi.","tags":["protokol","rad etish"]},{"id":"vm-a-27","doc":"ВМ-276","topic":"Shartnoma","ref":"п.166","difficulty":2,"q":"Tender natijalari bo'yicha shartnoma qanday rasmiylashtiriladi?","options":[{"t":"Qog'oz shaklda tuziladi, keyin skan qilinib portalga yuklanadi","ok":false,"why":"Tender п.106 ga ko'ra elektron shaklda o'tkaziladi — п.166 shartnomani elektron hujjat sifatida talab qiladi"},{"t":"Elektron hujjat shaklida tuziladi va operator tomonidan Yagona shartnomalar reyestriga kiritiladi","ok":true,"why":"п.166: «Договор по результатам тендера заключается в форме электронного документа и вносится оператором в Единый реестр договоров»; п.208 buni avtomatik rejim sifatida tasdiqlaydi"},{"t":"Elektron shaklda tuziladi, lekin reyestrga buyurtmachi qo'lda kiritadi","ok":false,"why":"Buyurtmachining portalga kiritishi TO'G'RIDAN-TO'G'RI shartnomalarga tegishli (п.209); tender shartnomasi п.208 ga ko'ra avtomatik kiritiladi"},{"t":"Faqat Markazning ijobiy xulosasi olingandan keyin reyestrga kiritiladi","ok":false,"why":"п.208 reyestrga kiritishni tizimda ro'yxatdan o'tishga bog'laydi, ekspertiza xulosasiga emas"}],"exp":"ВМ-276 п.166 bo'yicha tender natijalari bo'yicha shartnoma elektron hujjat shaklida tuziladi va operator tomonidan Yagona shartnomalar reyestriga kiritiladi; п.208 ga ko'ra electron do'kon, аукцион, отбор, tender va ramka bitimi shartnomalari tizimda ro'yxatdan o'tgach reyestrga AVTOMATIK kiritiladi. п.213 ga ko'ra Yagona reyestrga kiritilmagan shartnoma bo'yicha to'lov amalga oshirilmaydi; reyestr tarkibi esa Qonun 47-moddasi ikkinchi qismiga muvofiq belgilanadi (п.210).","tags":["shartnoma","reyestr"]},{"id":"vm-a-28","doc":"ВМ-276","topic":"Shartnoma","ref":"п.167","difficulty":3,"q":"Qaysi holatda tender xarid protsedurasini elektron shaklda o'tkazish majburiy emas?","options":[{"t":"Shartnoma summasi 6 000 БҲМ dan kam bo'lganda","ok":false,"why":"6 000 БҲМ — byudjet buyurtmachisi uchun to'g'ridan-to'g'ri shartnomani Markaz kompleks ekspertizasidan ozod qilish chegarasi (п.189), shartnoma shakliga aloqasi yo'q"},{"t":"Buyurtmachi byudjet tashkiloti bo'lganda","ok":false,"why":"Byudjet buyurtmachisi uchun ham elektron shakl majburiy — farq to'lov tartibida: u отбор/tender shartnomasi bo'yicha to'lovni РКП shaxsiy hisoblarisiz amalga oshiradi (п.23)"},{"t":"Ishchi-xizmatchini fuqarolik-huquqiy shartnoma asosida jalb qilishda va xalqaro reyting olishda","ok":true,"why":"п.167 aynan shu ikki holatni istisno sifatida belgilaydi"},{"t":"Ijrochi norezident bo'lganda","ok":false,"why":"п.167 ishtirokchining rezidentligini umuman tilga olmaydi — istisnolar ro'yxati yopiq"}],"exp":"ВМ-276 п.167 bo'yicha buyurtmachilar tomonidan xodimlarni fuqarolik-huquqiy shartnoma asosida jalb qilish va xalqaro reytinglar olishni nazarda tutuvchi xarid protsedurasini elektron shaklda o'tkazish majburiy emas. Ammo shu holatda ham komissiya faoliyatini tartibga solish, takliflarni taqdim etish, ularni ko'rib chiqish va baholash, g'olib va zaxira g'olibni aniqlash hamda natijalarni rasmiylashtirish Qonunda belgilangan tartibda amalga oshiriladi. Отбор uchun xuddi shu istisno п.105 da berilgan.","tags":["istisno","shartnoma"]},{"id":"vm-a-29","doc":"ВМ-276","topic":"Tender","ref":"п.163","difficulty":2,"q":"ВМ-276 п.163 tender ishtirokchilariga qanday huquq beradi?","options":[{"t":"G'olib e'lon qilingandan keyin o'z taklif narxini qayta ko'rib chiqish","ok":false,"why":"п.161 ga ko'ra shartnoma xarid hujjatlari va ishtirokchi bergan taklif shartlari bo'yicha tuziladi — narxni qayta ko'rib chiqish nazarda tutilmagan"},{"t":"Tender shartlari va o'tkazish protsedurasi buzilgan taqdirda tender NATIJALARI ustidan belgilangan tartibda shikoyat qilish","ok":true,"why":"п.163: «Участники тендера могут обжаловать в установленном порядке результаты тендера в случае нарушения условий и процедуры проведения тендера»"},{"t":"Komissiya qarorini bajarmaslik","ok":false,"why":"п.165 bo'yicha komissiyaning o'z vakolati doirasida qabul qilgan qarorlari barcha ishtirokchilar uchun majburiy"},{"t":"Boshqa ishtirokchilarning takliflari bilan to'liq tanishish","ok":false,"why":"п.134 ga ko'ra takliflarni ochish muddati kelmaguncha ularni ko'rish taqiqlanadi; ma'lumot bayonnoma ko'chirmasi doirasida (п.157) oshkor bo'ladi"}],"exp":"ВМ-276 п.163 ishtirokchilarga tender shartlari va o'tkazish protsedurasi buzilganda tender NATIJALARI ustidan belgilangan tartibda shikoyat qilish huquqini beradi — shikoyat predmeti aynan natijalar. Shikoyatni ko'rib chiqish tartibi ВМ-276 da emas: п.214 ga ko'ra shikoyatlar, nizolar va kelishmovchiliklar qonunchilikda belgilangan tartibda (sud yoki Davlat xaridlari sohasidagi shikoyatlarni ko'rib chiqish komissiyasi orqali) hal qilinadi. Diqqat: отборда bundan farqli ravishda oldindan bayonnoma bo'yicha 2 ish kunlik e'tiroz mexanizmi mavjud (п.98-101), tenderda esa u yo'q.","tags":["shikoyat","huquq"]},{"id":"vm-a-30","doc":"ВМ-276","topic":"Tender","ref":"п.117","difficulty":2,"q":"Tenderda takliflarni baholashning qanday usullari qo'llaniladi va ular qanday belgilanadi?","options":[{"t":"Faqat eng past narx usuli — u qonun bilan bevosita belgilangan","ok":false,"why":"п.117 ikki usulni nazarda tutadi; faqat narx bo'yicha g'olib aniqlash аукционга xos (п.52, п.54)"},{"t":"Eng past narx, bal usuli va аукцион usuli — komissiya tanlaydi","ok":false,"why":"Аукцион — alohida xarid protsedurasi (4-bob), tender ichidagi baholash usuli emas"},{"t":"Faqat bal usuli — chunki tenderda sifat mezonlari majburiy","ok":false,"why":"п.117 eng past narx usulini ham saqlaydi; п.120 esa bu usulda mos/nomuvofiqlikni aniqlovchi kriteriylar belgilanishini ko'rsatadi"},{"t":"Eng past narx usuli yoki bal usuli — buyurtmachi ishlab chiqib komissiya bilan kelishadi","ok":true,"why":"п.117: buyurtmachi usulni (метод наименьшей цены yoki балльный метод) va baholash kriteriylarini ishlab chiqib komissiyaga kelishish uchun kiritadi"}],"exp":"ВМ-276 п.117 bo'yicha baholash usuli (eng past narx yoki bal usuli) va kriteriylar buyurtmachi tomonidan ishlab chiqilib komissiya bilan kelishishga kiritiladi; xarid hujjatlarida ball chegaralari (пороговые значения) ham belgilanishi mumkin — ulardan o'tmagan ishtirokchi tenderdan chetlashtiriladi. Bal usulida п.155-1 (ВМ-712, 28.10.2024 ga havola bilan) mahalliy ishlab chiqaruvchilarga lokalizatsiya darajasiga mutanosib qo'shimcha ball beradi: ДБ = НБ × 15 % × УЛ, ammo uning narxi eng past narxdan 15 % dan ko'proq oshsa — qo'shimcha ball berilmaydi. Usul tanlovi ekspertizada tekshiriladi: sifat va texnik xususiyatlar hal qiluvchi bo'lgan predmetda faqat narx bo'yicha baholash asossiz hisoblanadi.","tags":["baholash","usul","mezon"]},{"id":"zru-a-01","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.2","difficulty":2,"q":"ЗРУ-684 2-moddasiga ko'ra quyidagi xaridlardan qaysi birining tartibi alohida qonunchilik bilan belgilanadi (ya'ni bu Qonun tartibiga tushmaydi)?","options":[{"t":"O'zbekiston Respublikasi Investitsiya dasturida nazarda tutilgan loyihalarni amalga oshirishdagi xaridlar","ok":false,"why":"Aksincha — ст.2 birinchi xatboshi aynan shu xaridlarni Qonun amal doirasiga kiritadi"},{"t":"Xorijiy grantlar va texnik ko'maklashuv mablag'lari hisobidan moliyalashtiriladigan xaridlar","ok":false,"why":"Bular Qonun doirasida; faqat donor protseduralari boshqa tartib belgilagan bo'lsa o'sha tartib qo'llanadi, lekin natijalar baribir portalda e'lon qilinadi"},{"t":"Davlat sirlariga oid, mudofaa qobiliyati va ichki tartibni ta'minlash, shuningdek saylov va referendumlarni tayyorlash uchun xaridlar","ok":true,"why":"ст.2: bu xaridlar hamda davlat muhofazasidagi shaxslar xavfsizligi uchun xaridlar tartibi qonunchilikka muvofiq alohida belgilanadi"},{"t":"Byudjet tashkilotlarida tashkil etilgan boshqa fondlar mablag'i hisobidan xaridlar","ok":false,"why":"ст.2 uchinchi xatboshida bu xaridlar ochiq matnda Qonun doirasiga kiritilgan"}],"exp":"ЗРУ-684 2-moddasi Qonun amal doirasini sanab o'tadi va istisnolarni belgilaydi: davlat muhofazasidagi shaxslar xavfsizligi, mudofaa qobiliyati, ichki tartib, davlat sirlari bilan bog'liq xaridlar hamda Prezident, Oliy Majlis va Kengashlar saylovi/referendum uchun xaridlar tartibi qonunchilikka muvofiq alohida belgilanadi. Keyinchalik moddaga yana ikki qism qo'shilgan: ЗРУ-1070 (23.06.2025) — Qonun banklarni sanatsiya qilish va tugatish bilan bog'liq munosabatlarga tatbiq etilmaydi; ЗРУ-1126 (27.03.2026) — ustav fondida davlat ulushi 50% va undan ortiq kredit tashkilotlarining islom moliyasi doirasida mijozga o'tkazish va likvidlik jalb qilish maqsadidagi xaridlariga Qonun talablari tatbiq etilmaydi. Ekspertizada bu Bosqich 0 — yurisdiksiya filtri: ariza shu toifaga tushsa, umumiy tartib bo'yicha baholanmaydi.","tags":["amal doirasi","istisno","yurisdiksiya"]},{"id":"zru-a-02","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.4","difficulty":2,"q":"ЗРУ-684 4-moddasida «тендер» tushunchasi qanday ta'riflangan?","options":[{"t":"Konkurs bo'lib, unda raqobatli protsedura natijasida shartnomani ijro etishning eng yaxshi shartlarini taklif qilgan ishtirokchi g'olib deb topiladi","ok":true,"why":"ст.4 dagi aynan shu ta'rif: «наилучшие условия исполнения договора о государственных закупках» — mezon faqat narx emas"},{"t":"Bir nechta ishtirokchidan olingan takliflarni solishtirish asosidagi raqobatli usul","ok":false,"why":"Bu «отбор наилучших предложений» ta'rifi — chalg'ituvchi qo'shni tushuncha"},{"t":"G'olibni aniqlashning yagona mezoni narx bo'lgan, maxsus elektron platformadagi raqobatli usul","ok":false,"why":"Bu «аукцион на понижение стартовой цены» ta'rifi"},{"t":"Spetsifik talablar qo'yilmaydigan tovarlar bo'yicha maxsus maydonchada elektron savdo","ok":false,"why":"Bu «электронный магазин» ta'rifi"}],"exp":"ст.4 ga ko'ra тендер — konkurs shaklidagi raqobatli protsedura bo'lib, g'olib shartnoma ijrosining eng yaxshi shartlarini taklif qilgani uchun aniqlanadi. Shu sababli tenderda g'olib faqat eng arzon narx bilan emas, balki e'lon qilingan baholash mezonlari majmui bo'yicha topiladi (ст.65 ikkinchi qism: «лучшие условия исполнения договора определяются закупочной комиссией на основании объявленных критериев оценки»). Ekspertizada tender hujjatlarini ko'rganda mezonlar va ularning nisbiy ahamiyati ko'rsatilganini tekshirish shundan kelib chiqadi (ст.32).","tags":["ta'rif","tender"]},{"id":"zru-a-03","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.4","difficulty":2,"q":"«Отбор наилучших предложений» tushunchasi ЗРУ-684 4-moddasida qanday ochib berilgan?","options":[{"t":"G'olibni aniqlashning yagona mezoni narx bo'lgan elektron platformadagi savdo","ok":false,"why":"Bu аукцион на понижение стартовой цены; отборда mezonlar faqat narx bilan cheklanmaydi"},{"t":"Texnik jihatdan murakkab tovarlarni bir shartnoma bo'yicha ikkita o'zaro bog'liq bosqichda xarid qilish","ok":false,"why":"Bu «двухэтапные государственные закупки» ta'rifi"},{"t":"Ochiq manbalardan olingan narxlarni solishtirish yoki kamida uchta potensial ta'minotchidan narx so'rash","ok":false,"why":"Bu «упрощенная процедура закупки малой стоимости» ta'rifi"},{"t":"Bir nechta ishtirokchidan olingan takliflarni solishtirish asosida amalga oshiriladigan raqobatli xarid usuli","ok":true,"why":"ст.4 dagi aynan shu ta'rif — asos «сравнение предложений, полученных от нескольких участников закупочных процедур»"}],"exp":"ст.4 ga ko'ra отбор наилучших предложений — bir nechta ishtirokchidan kelgan takliflarni solishtirishga asoslangan raqobatli usul. Tenderdan farqi mazmunda emas, chegarada: ст.56 ga ko'ra отбор bitta shartnoma bo'yicha 25 000 БҲМ gacha (byudjet buyurtmachilari uchun 6 000 gacha), ст.64 ga ko'ra tender esa shu chegaradan yuqori summalarda. ст.56 ikkinchi qismi bo'yicha Prezident/VM hujjati bilan tendersiz xarid huquqi berilgan bo'lsa, summadan qat'i nazar отбор o'tkaziladi — bunda chegaradan oshgan holatlarda ТЗ Markaz kompleks ekspertizasiga kiritiladi va e'lon faqat ijobiy xulosadan keyin joylashtiriladi (ст.58). Ekspertizada usul turini manbadan aniqlash kerak — usul o'zboshimchalik bilan default qilinmaydi.","tags":["ta'rif","otbor"]},{"id":"zru-a-04","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.4","difficulty":2,"q":"ЗРУ-684 4-moddasiga ko'ra «электронный магазин» qanday xaridlar uchun mo'ljallangan?","options":[{"t":"Bozorda analogi bo'lmagan texnik jihatdan murakkab tovar (ish, xizmat) xaridi uchun","ok":false,"why":"Bu — ст.72 dagi yagona ta'minotchidan xarid asoslaridan biri, «электронный магазин» emas"},{"t":"Spetsifik talablar qo'yilmaydigan tovar (ish, xizmat) xaridi uchun; savdo elektron tizimning maxsus maydonchasida elektron shaklda o'tkaziladi","ok":true,"why":"ст.4 dagi ta'rif aynan «к которым не предъявляются специфические требования» bandiga asoslanadi"},{"t":"Shartnoma ijrosining eng yaxshi shartlarini taklif qilgan ishtirokchi g'olib bo'ladigan konkurs uchun","ok":false,"why":"Bu тендер ta'rifi"},{"t":"Yagona ta'minotchilar reyestriga kiritilgan tashkilotlardan to'g'ridan-to'g'ri xarid uchun","ok":false,"why":"Bu ст.72-73 dagi yagona ta'minotchi mexanizmi (прямой договор), raqobatli «электронный магазин» emas"}],"exp":"ст.4 «электронный магазин»ни spetsifik talablar qo'yilmaydigan tovar (ish, xizmat) uchun raqobatli usul sifatida belgilaydi. Aynan shu «spetsifik talab yo'q» belgisi tufayli ст.34 uchinchi qismidagi tovar belgisi, patent, model, ishlab chiqaruvchi yoki eksklyuziv huquqqa havola qilish taqiqi «электронный магазин» orqali amalga oshirilgan xaridlarga nisbatan istisno qilingan (bu qism ЗРУ-1005 tahririda, 01.03.2025 dan). Ekspertizada murakkab, spetsifik texnik topshiriqli predmet «электронный магазин»га kiritilgan bo'lsa — bu usul tanlashdagi xato.","tags":["ta'rif","elektron magazin"]},{"id":"zru-a-05","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.4","difficulty":1,"q":"«Аукцион на понижение стартовой цены»da g'olibni aniqlashning yagona mezoni nima?","options":[{"t":"Tovarning sifat va texnik ko'rsatkichlari","ok":false,"why":"Аукционда texnik xarakteristikalar baholanmaydi — bu mezon отбор va tenderga xos"},{"t":"Yetkazib berish muddati va kafolat shartlari","ok":false,"why":"Bular ст.32 dagi baholash mezonlari, lekin аукцион uchun yagona mezon emas"},{"t":"Narx va sifatning optimal nisbati (iqtisodiy jihatdan eng foydali taklif)","ok":false,"why":"Narx va sifat nisbati — ст.8 dagi yondashuv; аукционнинг yagona narx mezoniga zid"},{"t":"Narx","ok":true,"why":"ст.4: «единственным критерием определения победителя является цена»"}],"exp":"ст.4 ga ko'ra аукцион на понижение стартовой цены — davlat xaridlari elektron tizimining maxsus platformasidagi raqobatli usul bo'lib, unda g'olibni aniqlashning yagona mezoni narxdir. Shu sababli texnik xarakteristikalarni baholash zarur bo'lgan predmet аукционга chiqarilmaydi (ст.52 dagi mezonlar). Ekspertizada usul tanlash to'g'riligini shu belgi bo'yicha tekshirish mumkin.","tags":["ta'rif","auktsion","mezon"]},{"id":"zru-a-06","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.4","difficulty":3,"q":"«Упрощенная процедура закупки малой стоимости»da narx so'rovi kamida nechta potensial ta'minotchiga yuboriladi?","options":[{"t":"Kamida ikkitasiga","ok":false,"why":"Qo'shni raqam — ta'rifda ikkita emas, uchta ko'rsatilgan"},{"t":"Kamida beshtasiga","ok":false,"why":"Beshta — ст.57 bo'yicha отбор xarid komissiyasining minimal a'zolar soni, ta'minotchilar soni emas"},{"t":"Kamida uchtasiga","ok":true,"why":"ст.4: «либо посредством запроса цен не менее чем у трех потенциальных поставщиков товаров (работ, услуг)»"},{"t":"Kamida yettitasiga","ok":false,"why":"Yettita — ст.65 bo'yicha tender komissiyasining minimal a'zolar soni bilan chalg'itish"}],"exp":"ст.4 ga ko'ra упрощенная процедура закупки малой стоимости ikki yo'l bilan amalga oshiriladi: xarid protseduralarining ochiq axborot manbalaridan olingan narxlarni solishtirish yoki kamida uchta potensial ta'minotchidan narx so'rash. Bu ta'rif ЗРУ-1005 (27.11.2024) bilan ст.4 ga o'ninchi va o'n birinchi xatboshi tarkibida qo'shilgan va 01.03.2025 dan kuchga kirgan. Uchta narx so'rovi — narxni asoslashning minimal talabi, uni ikkitaga kamaytirish qonun buzilishi hisoblanadi.","tags":["ta'rif","narx","chegara"]},{"id":"zru-a-07","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.4","difficulty":1,"q":"ЗРУ-684 4-moddasiga ko'ra «резервный победитель» kim?","options":[{"t":"Xarid komissiyasi qaroriga ko'ra taklifi g'olib taklifidan keyingi eng optimal deb topilgan ishtirokchi","ok":true,"why":"ст.4 dagi ta'rif: «предложение ... признано наиболее оптимальным, следующим за предложением победителя»"},{"t":"Oldindan kvalifikatsiya tanlovidan o'tgan, ammo taklif topshirmagan ishtirokchi","ok":false,"why":"Oldindan kvalifikatsiya tanlovidan (ПКО) o'tish rezerv g'oliblik maqomini bermaydi — taklif baholangan bo'lishi shart"},{"t":"G'olib bosh tortganda buyurtmachi o'zi tanlaydigan istalgan ishtirokchi","ok":false,"why":"Rezerv g'olibni buyurtmachi emas, xarid komissiyasi qarori bilan aniqlaydi"},{"t":"Eng past narx taklif qilgan, biroq texnik bosqichdan o'tmagan ishtirokchi","ok":false,"why":"Texnik bosqichdan o'tmagan ishtirokchi umuman baholanmaydi va rezerv g'olib bo'la olmaydi"}],"exp":"ст.4 ga ko'ra rezerv g'olib — xarid komissiyasi qarori bilan taklifi g'olibnikidan keyingi eng optimal deb topilgan ishtirokchi. Uning amaliy ma'nosi ст.63 (отбор) va ст.70 (tender) da ochiladi: g'olib shartnoma tuzishdan bosh tortsa, задаток unga qaytarilmaydi, shartnoma tuzish huquqi esa rezerv g'olibga o'tadi — u g'olib taklif qilgan narxda shartnoma tuzadi (o'z narxi pastroq bo'lsa — o'z narxida) yoki rad etishi mumkin. Rezerv g'olib majburiy emas — ст.20 ga ko'ra komissiya uni «при необходимости» aniqlaydi; aniqlanmasa yoki u rad etsa, yangi protsedura o'tkaziladi.","tags":["ta'rif","g'olib"]},{"id":"zru-a-08","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.4","difficulty":2,"q":"ЗРУ-684 4-moddasiga ko'ra «бенефициарный собственник» kim hisoblanadi?","options":[{"t":"Ta'minotchining ustav fondida 50 foiz va undan ortiq ulushga ega yuridik shaxs","ok":false,"why":"50 foiz mezoni — ст.19 dagi korporativ buyurtmachi belgisi; benefitsiar egasi ta'rifida ulush foizi ko'rsatilmagan"},{"t":"Tovar (ish, xizmat) ta'minotchisini pirovard natijada mulk huquqi bilan egallaydigan yoki haqiqatda nazorat qiladigan jismoniy shaxs","ok":true,"why":"ст.4 ta'rifi: aynan «физическое лицо, которое в конечном итоге владеет правами собственности или в действительности контролирует поставщика»"},{"t":"Ijrochi nomidan shartnomani imzolash huquqiga ega mansabdor shaxs","ok":false,"why":"Imzo huquqi — vakillik masalasi; benefitsiar egasi haqiqiy nazoratga qarab aniqlanadi"},{"t":"Ishtirokchi qarorlariga ta'sir ko'rsatuvchi jismoniy yoki yuridik shaxs","ok":false,"why":"Bu «аффилированное лицо» ta'rifi — u yuridik shaxs ham bo'lishi mumkin, benefitsiar esa faqat jismoniy shaxs"}],"exp":"ст.4 ga ko'ra benefitsiar egasi — ta'minotchini pirovardida egallaydigan yoki haqiqatda nazorat qiladigan JISMONIY shaxs. Asosiy benefitsiar egasi haqidagi ma'lumotni oshkor qilish ishtirokchi (ст.23) va ijrochi (ст.24) majburiyati sifatida belgilangan, benefitsiar egasi haqidagi ma'lumot esa Yagona shartnomalar reyestriga kiritiladi (ст.47; madaniy boyliklar yetkazib beruvchi jismoniy shaxs bundan istisno). Insofsiz ijrochilar reyestriga kiritish asosi esa boshqacha shakllangan: ст.48 bir lotda qatnashgan affiliatsiya qilingan shaxslar yoki manfaatlar to'qnashuvi haqidagi ma'lumotni oshkor qilmaslikni nazarda tutadi.","tags":["ta'rif","benefitsiar","oshkoralik"]},{"id":"zru-a-09","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.4","difficulty":2,"q":"Ishtirokchining «аффилированное лицо»si ЗРУ-684 4-moddasida qanday belgilangan?","options":[{"t":"Faqat ishtirokchining ustav fondida ulushga ega yuridik shaxs","ok":false,"why":"Ta'rif ulushga bog'lanmagan — asos qaror qabul qilish huquqi va ta'sir"},{"t":"Ishtirokchi rahbarining yaqin qarindoshlari doirasi","ok":false,"why":"Yaqin qarindoshlar ст.46 dagi alohida cheklov asosi, affiliatsiya ta'rifi emas"},{"t":"Ta'minotchini pirovard natijada nazorat qiluvchi jismoniy shaxs","ok":false,"why":"Bu benefitsiar egasi ta'rifi — affiliatsiya bilan chalkashtiriladigan qo'shni tushuncha"},{"t":"Qaror qabul qilish huquqiga ega bo'lgan va (yoki) shu ishtirokchi qarorlariga, shu jumladan yozma kelishuv asosida ta'sir ko'rsatadigan jismoniy yoki yuridik shaxs, shuningdek ishtirokchining o'zi shunday huquqqa ega bo'lgan shaxs","ok":true,"why":"ст.4 ta'rifining aynan matni — ta'sir ikki tomonlama va yozma kelishuv asosida ham bo'lishi mumkin"}],"exp":"ст.4 ga ko'ra affiliatsiya qilingan shaxs — ishtirokchi qarorlariga qaror qabul qilish huquqi yoki ta'sir orqali bog'liq jismoniy yoki yuridik shaxs, bunda bog'liqlik yozma kelishuvdan ham kelib chiqishi mumkin. Ta'rif ikki tomonlama: ishtirokchining o'zi boshqa shaxsga nisbatan shunday huquqqa ega bo'lsa ham affiliatsiya yuzaga keladi. Amaliy oqibati — ishtirokchi va uning affiliatsiya qilingan shaxsi «электронный магазин», упрощенная процедура, аукцион, отбор, tender va ikki bosqichli xaridning bitta lotida qatnasha olmaydi (ст.23), affiliatsiya aniqlanganda ishtirokchi protseduradan chetlatiladi (ст.42), komissiya a'zosi esa o'z-o'zini rad etishi shart (ст.20).","tags":["ta'rif","affiliatsiya"]},{"id":"zru-a-10","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.4","difficulty":3,"q":"Quyidagilardan qaysi biri ЗРУ-684 4-moddasidagi «субъекты государственных закупок» ro'yxatiga KIRMAYDI?","options":[{"t":"Davlat xaridlari sohasidagi shikoyatlarni ko'rib chiqish komissiyasi","ok":true,"why":"ст.4 ro'yxatida yo'q — u ст.78 bo'yicha vakolatli organ tomonidan tuziladigan va tarkibi Vazirlar Mahkamasi tomonidan tasdiqlanadigan doimiy organ, xarid subyekti emas"},{"t":"Ixtisoslashgan tashkilot","ok":false,"why":"ст.4 ro'yxatida bevosita ko'rsatilgan (ст.21 uning maqomini ochib beradi)"},{"t":"Davlat xaridlari elektron tizimi operatori","ok":false,"why":"ст.4 ro'yxatida bor (ст.25 uning huquq va cheklovlarini belgilaydi)"},{"t":"Ekspert, ekspert tashkiloti","ok":false,"why":"ст.4 ro'yxatining oxirgi elementi (ст.22 batafsil ochib beradi)"}],"exp":"ст.4 subyektlarning yopiq ro'yxatini beradi: davlat buyurtmachisi, xarid protseduralari ishtirokchisi, davlat xaridlari ijrochisi, xarid komissiyasi, elektron tizim operatori, ixtisoslashgan tashkilot hamda ekspert va ekspert tashkiloti. Shikoyatlarni ko'rib chiqish komissiyasi bu ro'yxatga kirmaydi — u nizolarni hal qiluvchi organ (ст.78-79). Bu farq javobgarlik taqsimotida muhim: subyektlarga Qonun majburiyat yuklaydi, komissiya esa ularning harakatlarini baholaydi va uning qarorlari barcha subyektlar uchun majburiy.","tags":["subyektlar","javobgarlik"]},{"id":"zru-a-11","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.4","difficulty":2,"q":"«Единый реестр договоров»ni kim va qayerda yuritadi?","options":[{"t":"Har bir davlat buyurtmachisi o'zining rasmiy veb-saytida","ok":false,"why":"Buyurtmachi o'z saytida faqat e'lon joylashtirishi mumkin (ст.58, ст.66), reyestrni yuritmaydi"},{"t":"Davlat aktivlarini boshqarish agentligi","ok":false,"why":"Agentlik korporativ buyurtmachilar RO'YXATINI yuritadi (ст.19) — shartnomalar reyestrini emas"},{"t":"Davlat xaridlari sohasidagi vakolatli organ — maxsus axborot portalida","ok":true,"why":"ст.4 ta'rifi: reyestrni «уполномоченный орган в области государственных закупок на специальном информационном портале» yuritadi"},{"t":"G'aznachilik xizmati qo'mitasi o'z axborot tizimida","ok":false,"why":"G'aznachilik byudjet buyurtmachilari bo'yicha to'lovlarni amalga oshiradi, lekin reyestrni yuritmaydi"}],"exp":"ст.4 va ст.47 ga ko'ra Yagona shartnomalar reyestrini davlat xaridlari sohasidagi vakolatli organ maxsus axborot portalida yuritadi. Reyestr elektron xarid tizimlari va portal ma'lumotlar bazalari o'rtasida axborot almashinuvi orqali shakllantiriladi, undagi ma'lumot esa haq olinmasdan tanishish uchun ochiq. Amaliy oqibati keskin: ст.47 ga ko'ra ma'lumoti reyestrga kiritilmagan shartnomalar bo'yicha to'lov amalga oshirilmaydi.","tags":["reyestr","shartnoma","to'lov"]},{"id":"zru-a-12","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.5","difficulty":3,"q":"Quyidagilardan qaysi biri ЗРУ-684 5-moddasidagi davlat xaridlarining asosiy printsiplari qatoriga KIRMAYDI?","options":[{"t":"Соразмерность (mutanosiblik)","ok":false,"why":"ст.5 ro'yxatidagi printsip, mazmuni ст.11 da ochib berilgan"},{"t":"Конфиденциальность (maxfiylik)","ok":true,"why":"Maxfiylik ст.15 dagi alohida qoida — u ст.5 dagi asosiy printsiplar ro'yxatiga kiritilmagan"},{"t":"Устойчивость (barqarorlik)","ok":false,"why":"ЗРУ-1005 bilan ст.5 birinchi qismiga sakkizinchi xatboshi sifatida qo'shilgan printsip, mazmuni ст.11¹ da"},{"t":"Недопустимость коррупции (korruptsiyaga yo'l qo'ymaslik)","ok":false,"why":"ст.5 ro'yxatining oxirgi printsipi, mazmuni ст.13 da"}],"exp":"ст.5 asosiy printsiplarni sanaydi: professionallik va javobgarlik; asoslanganlik; moliyaviy mablag'lardan ratsional, tejamkor va samarali foydalanish; ochiqlik va shaffoflik; raqobat va xolislik; mutanosiblik; barqarorlik; tizim yagonaligi va yaxlitligi; korruptsiyaga yo'l qo'ymaslik. Bu printsiplar xarid jarayonining barcha bosqichlarida qo'llanilishi shart. Maxfiylik esa ст.15 da alohida institut sifatida berilgan va printsip deb atalmagan. Xulosada printsipga havola qilganda aynan ст.5 ro'yxatidan foydalanish kerak.","tags":["printsip","ro'yxat"]},{"id":"zru-a-13","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.7","difficulty":2,"q":"«Обоснованность» (asoslanganlik) printsipi ЗРУ-684 bo'yicha nimani talab qiladi?","options":[{"t":"Xarid usuli tovarning riski, qiymati va murakkabligiga mos bo'lishini","ok":false,"why":"Bu mutanosiblik printsipi (ст.11) — qo'shni printsip bilan chalg'itish"},{"t":"Ajratilgan mablag'lardan ratsional va tejamkor foydalanishni","ok":false,"why":"Bu ratsionallik, tejamkorlik va samaradorlik printsipi (ст.8)"},{"t":"Ma'lumotni maxsus axborot portalida to'liq va bepul joylashtirishni","ok":false,"why":"Bu ochiqlik va shaffoflik printsipi (ст.9)"},{"t":"Xaridni o'tkazishning maqsadga muvofiqligi va zarurligini, tanlangan tovar (ish, xizmat)ning, uning iste'mol xossalari, sifat parametrlari va qiymatining buyurtmachi real ehtiyojlarini samarali qondirishi nuqtayi nazaridan asoslanganligini","ok":true,"why":"ст.7 matni aynan shu: целесообразность, необходимость va tanlov asoslanganligi real ehtiyojlarga bog'lanadi"}],"exp":"ст.7 ga ko'ra davlat xaridlari o'tkazishning maqsadga muvofiqligi va zarurligini, tovar (ish, xizmat) tanlovi, uning iste'mol xossalari (tavsifi), sifat parametrlari va qiymati asoslanganligini hisobga olgan holda amalga oshirilishi lozim. Bu printsip ehtiyojni aniqlash bosqichining huquqiy asosi. Ekspertizada «nima uchun aynan shu konfiguratsiya va shu hajm kerak» degan savol aynan ст.7 ga tayanadi.","tags":["printsip","ehtiyoj","asoslash"]},{"id":"zru-a-14","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.6","difficulty":2,"q":"Xarid protsedurasini tashkil etish va o'tkazish uchun mas'ul shaxsda manfaatlar to'qnashuvi mavjud bo'lsa, ЗРУ-684 qanday chorani belgilaydi?","options":[{"t":"U bajarayotgan funksiyalardan chetlatilishi lozim","ok":true,"why":"ст.6 oxirgi qismi: «подлежит отстранению от выполняемых функций» — bu imkoniyat emas, majburiy oqibat"},{"t":"Unga yozma ogohlantirish beriladi, biroq funksiyalari saqlanib qoladi","ok":false,"why":"Qonun ogohlantirish chorasini nazarda tutmaydi — chetlatish majburiy"},{"t":"U faqat ovoz berish huquqidan mahrum qilinadi","ok":false,"why":"Ovozdan chiqarish — affiliatsiyasi aniqlangan xarid komissiyasi a'zosiga nisbatan qoida (ст.20), mas'ul shaxsga emas"},{"t":"Vakolatli organning yozma roziligi bilan u ishini davom ettiradi","ok":false,"why":"Qonunda bunday rozilik mexanizmi yo'q; vakolatli organ xabar oladi (ст.14), lekin ruxsat bermaydi"}],"exp":"ст.6 davlat buyurtmachisini xarid protseduralarini tashkil etish va o'tkazish uchun mas'ul shaxsni belgilashga majbur qiladi va bunday shaxsda manfaatlar to'qnashuvi bo'lsa, u bajarayotgan funksiyalardan chetlatilishini belgilaydi. Mas'ul shaxs malakasini muntazam oshirish esa vakolatli organ tashkil qiladigan o'qish orqali ta'minlanadi. Xarid komissiyasi a'zosiga nisbatan boshqa mexanizm — o'z-o'zini rad etish (самоотвод) qo'llaniladi (ст.20).","tags":["mas'ul shaxs","manfaatlar to'qnashuvi"]},{"id":"zru-a-15","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.8","difficulty":2,"q":"Ratsionallik, tejamkorlik va samaradorlik printsipiga ko'ra tovar (ish, xizmat) sotib olishdan keladigan foyda, sifat va qiymat o'rtasidagi optimal nisbat nimani hisobga olgan holda ta'minlanadi?","options":[{"t":"Faqat taklif etilgan eng past narxni hisobga olgan holda","ok":false,"why":"Eng past narx — аукцион mezoni; ст.8 narxni sifat va foyda bilan birga ko'rishni talab qiladi"},{"t":"Ekspluatatsiya tsikli xarajatlarini hisobga olgan holda","ok":true,"why":"ст.8: «с учетом затрат эксплуатационного цикла» — aynan shu qayd etilgan"},{"t":"Faqat boshlang'ich narx (стартовая цена) bilan solishtirgan holda","ok":false,"why":"Narxni bozor narxlariga solishtirish — ст.33 masalasi, ст.8 dagi optimal nisbat sharti emas"},{"t":"Faqat ishlab chiqaruvchi kafolati muddatini hisobga olgan holda","ok":false,"why":"Kafolat — ст.32 dagi baholash mezonlaridan biri («условия платежа и гарантий»), lekin ст.8 dagi optimal nisbat sharti emas"}],"exp":"ст.8 xaridlar ratsional va tejamkor usulda o'tkazilishini talab qiladi: buyurtmachining xarid o'tkazishga sarflagan xarajatlari va tovar qiymati hisobga olinadi, mablag'lar samarali ishlatiladi va sotib olishdan keladigan foyda, sifat hamda qiymat o'rtasida ekspluatatsiya tsikli xarajatlarini hisobga olgan optimal nisbat ta'minlanadi, xaridlar esa optimal muddatlarda o'tkaziladi. Amalda bu TCO yondashuvining qonuniy asosi: eng arzon taklif har doim ham eng tejamkor emas.","tags":["printsip","tejamkorlik","TCO"]},{"id":"zru-a-16","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.11","difficulty":2,"q":"«Соразмерность» (mutanosiblik) printsipi ЗРУ-684 11-moddasiga ko'ra nimalarning mosligi bilan ta'minlanadi?","options":[{"t":"Shartnoma narxining boshlang'ich narxga (стартовая цена) mosligi bilan","ok":false,"why":"Bu narx nazorati masalasi; ст.11 narx emas, usul va talablar mutanosibligi haqida"},{"t":"Texnik topshiriqning ishlab chiqaruvchi hujjatlariga mosligi bilan","ok":false,"why":"Texnik topshiriq (ТЗ) mazmuni ст.34 bilan tartibga solinadi, ст.11 bilan emas"},{"t":"Xarid usulining tovar (ish, xizmat) riski, qiymati, xususiyati va murakkabligiga; ishtirokchilar kvalifikatsiyasiga qo'yiladigan talablar, baholash mezon va usullarining tovarga (ishga, xizmatga); subyektlar huquq, majburiyat va javobgarligining ularning funksiyalariga mosligi bilan","ok":true,"why":"ст.11 dagi uchta moslik shartining aynan ro'yxati"},{"t":"Reja-grafikning byudjet taqsimotiga mosligi bilan","ok":false,"why":"Reja-grafik ст.29 bilan tartibga solinadi; ст.11 da bunday shart yo'q"}],"exp":"ст.11 mutanosiblikni uchta moslik orqali belgilaydi: xarid usuli — predmet riski, qiymati, xususiyati va murakkabligiga; kvalifikatsiya talablari, baholash mezon va usullari — tovar (ish, xizmat)ning o'ziga; subyektlarning huquq, majburiyat va javobgarligi — ularning funksiyalariga. Amaliy ma'nosi: oddiy tovar uchun ortiqcha og'ir kvalifikatsiya talablari qo'yish aynan shu printsipni buzadi. Bu ст.34 dagi shishirilgan (завышенные) talablar taqiqi va ст.46 dagi asossiz cheklash taqiqi bilan bir zanjirda ishlaydi.","tags":["printsip","mutanosiblik","kvalifikatsiya"]},{"id":"zru-a-17","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.11¹","difficulty":3,"q":"ЗРУ-1005 bilan kiritilgan «устойчивость» (barqarorlik) printsipi nimaga asoslanadi?","options":[{"t":"Xaridlarni ehtiyojni aniqlashdan yakuniy natijalarni baholashgacha bo'lgan jarayonlarning qisqa, o'rta va uzoq muddatli iqtisodiy, ekologik va ijtimoiy oqibatlarini hisobga olgan holda amalga oshirishga","ok":true,"why":"ст.11¹ birinchi qismining aynan mazmuni — uch xil muddat va uch xil oqibat turi qayd etilgan"},{"t":"Faqat qayta tiklanadigan energiya manbalaridan foydalanishga","ok":false,"why":"Bu ст.32 oxirgi qismidagi ekologik baholash mezonlaridan biri, printsipning to'liq mazmuni emas"},{"t":"Mahalliy ishlab chiqaruvchilarga imtiyoz va preferentsiyalar berishga","ok":false,"why":"Bu ст.16 uchinchi qismidagi alohida qoida (kamida uchta mahalliy ishlab chiqaruvchi ishtirok etganda), barqarorlik printsipi emas"},{"t":"Shartnoma ijrosining uzluksiz monitoringini ta'minlashga","ok":false,"why":"Monitoring ст.74 bilan tartibga solinadi; barqarorlik printsipining mazmuni boshqa"}],"exp":"ст.11¹ barqarorlikni ehtiyojni aniqlash, xaridga tayyorgarlik, protseduralar, g'olibni aniqlash, shartnoma tuzish va hatto tovarni yo'q qilish (utilizatsiya) hamda yakuniy natijalarni baholashgacha bo'lgan jarayonlarning qisqa, o'rta va uzoq muddatli iqtisodiy, ekologik va ijtimoiy oqibatlarini hisobga olishga bog'laydi. Buyurtmachi hayotiy tsikl davomidagi xarajatlarni, atrof-muhitga ta'sirni va ijtimoiy oqibatlarni hisobga olishi kerak. Modda ЗРУ-1005 (27.11.2024) bilan kiritilgan va 01.03.2025 dan kuchga kirgan — 2026-08-03 holatiga amalda.","tags":["printsip","barqarorlik","hayotiy tsikl"]},{"id":"zru-a-18","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.13","difficulty":2,"q":"Korruptsiyaga yo'l qo'ymaslik printsipida ЗРУ-684 qaysi choralarni ustuvor deb belgilaydi?","options":[{"t":"Aybdorlarni Insofsiz ijrochilar reyestriga kiritish choralarini","ok":false,"why":"Bu ст.48 dagi sanksiya (2 yil ishtirok taqiqi) — sodir bo'lgan buzilishga javob, ustuvor deb ko'rsatilgan chora emas"},{"t":"Har bir xarid bo'yicha majburiy tekshiruv o'tkazish choralarini","ok":false,"why":"Tekshiruv ст.74 da nazoratning asosiy shakli sifatida ko'rsatilgan, lekin har bir xarid uchun majburiy emas"},{"t":"Shartnoma summasini majburiy kamaytirish choralarini","ok":false,"why":"Qonunda bunday chora umuman nazarda tutilmagan"},{"t":"Korruptsiyaning oldini olish (предупреждение) choralarini","ok":true,"why":"ст.13: «При этом приоритетными являются меры по предупреждению коррупции»"}],"exp":"ст.13 ga ko'ra xarid protseduralarini tashkil etish va o'tkazishga qo'yiladigan talablar korruptsiyaviy huquqbuzarliklarga yo'l qo'ymasligi kerak, bunda korruptsiyaning oldini olish choralari ustuvor hisoblanadi. Printsip halol raqobat va obyektiv mezonlar, samarali monitoring va nazorat tizimi, buzilish holatlarini ochiq manbalarda e'lon qilish orqali amalga oshiriladi. Qonunchilikda korruptsiyaning oldini olishning boshqa choralari ham nazarda tutilishi mumkin.","tags":["printsip","korruptsiya","profilaktika"]},{"id":"zru-a-19","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.14","difficulty":3,"q":"Mavjud yoki taxmin qilinayotgan manfaatlar to'qnashuvi haqida bilib qolgan shaxs kimga xabar berishi shart?","options":[{"t":"Faqat o'zining bevosita rahbariga","ok":false,"why":"Chala javob — ст.14 ikkita adresatni belgilaydi, faqat rahbar bilan cheklanmaydi"},{"t":"Bevosita rahbariga va davlat xaridlari sohasidagi vakolatli organga","ok":true,"why":"ст.14: «обязаны сообщить об этом непосредственному руководителю и уполномоченному органу в области государственных закупок»"},{"t":"Shikoyatlarni ko'rib chiqish komissiyasiga va prokuraturaga","ok":false,"why":"Bu organlar shikoyat va jinoyat masalalari bilan shug'ullanadi; ст.14 xabar berish zanjirida ular ko'rsatilmagan"},{"t":"Xarid komissiyasi raisiga va elektron tizim operatoriga","ok":false,"why":"Almashtirilgan subyektlar — Qonun rais yoki operatorni xabar adresati sifatida belgilamagan"}],"exp":"ст.14 ga ko'ra buyurtmachi, operator, ixtisoslashgan va ekspert tashkiloti xodimlari, xarid komissiyasi a'zolari va ekspertlar manfaatlar to'qnashuvi haqida bevosita rahbarga HAM vakolatli organga xabar berishi shart. Ma'lumot olgan rahbar o'z vaqtida uni bartaraf etish yoki tartibga solish choralarini ko'rishi va ko'rilgan choralar haqida vakolatli organga xabar berishi majburiy. Vakolatli organ esa tegishli ma'lumotni davlat nazoratini amalga oshiruvchi organlarga kiritadi.","tags":["manfaatlar to'qnashuvi","xabar","javobgarlik"]},{"id":"zru-a-20","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.15","difficulty":2,"q":"Davlat xavfsizligi manfaatlarini himoya qilish bilan bog'liq ma'lumotni oshkor qilish to'g'risidagi qaror kim tomonidan qabul qilinadi?","options":[{"t":"Davlat buyurtmachisining rahbari","ok":false,"why":"Buyurtmachi xodimi bunday ma'lumotni oshkor qilishga haqli emas — qaror uning vakolatida emas"},{"t":"Davlat xaridlari elektron tizimi operatori","ok":false,"why":"Operator xodimi ham cheklangan subyekt: u bunday ma'lumotni oshkor qila olmaydi"},{"t":"Davlat xaridlari sohasidagi vakolatli organ","ok":true,"why":"ст.15: «если только уполномоченный орган ... не примет решение о раскрытии такой информации» — qaror aynan unga tegishli"},{"t":"Xarid komissiyasi ko'pchilik ovoz bilan","ok":false,"why":"Komissiya vakolatlari ст.20 da sanab o'tilgan; maxfiy ma'lumotni oshkor qilish ular orasida yo'q"}],"exp":"ст.15 ga ko'ra buyurtmachi yoki operator xodimi davlat xavfsizligi manfaatlari bilan bog'liq ma'lumotni, shuningdek oshkor qilinishi qonunga zid bo'ladigan, qonunchilikka rioya etilishiga to'sqinlik qiladigan, subyektlarning qonuniy manfaatlariga zarar yetkazadigan yoki halol raqobatga to'sqinlik qiladigan ma'lumotni oshkor qila olmaydi — bundan vakolatli organning oshkor qilish haqidagi qarori mustasno. Bunday qaror qabul qilinganda uning shartlariga rioya etiladi. Shu bilan birga ishtirokchi protsedurada qatnashish orqali o'z taklifidagi ma'lumotlar oshkor etilishiga rozilik bildiradi.","tags":["maxfiylik","oshkor qilish"]},{"id":"zru-a-21","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.19","difficulty":2,"q":"Yuridik shaxs ЗРУ-684 bo'yicha korporativ buyurtmachi hisoblanishi uchun uning ustav fondidagi (ustav kapitalidagi) davlat ulushi qanday bo'lishi kerak?","options":[{"t":"50 foiz va undan ortiq","ok":true,"why":"ст.19 п.2: «юридические лица с долей государства ... в размере 50 процентов и более». Bu mezon ЗРУ-1025 dan keyin ham saqlanib qolgan"},{"t":"25 foizdan ortiq","ok":false,"why":"Qo'shni chegara bilan chalg'itish — Qonunda 25 foiz mezoni yo'q"},{"t":"30 foiz va undan ortiq","ok":false,"why":"Qonunda bunday chegara belgilanmagan"},{"t":"75 foiz va undan ortiq","ok":false,"why":"Nazorat paketi bo'yicha intuitiv, ammo noto'g'ri chegara — Qonun 50 foizdan boshlaydi"}],"exp":"ст.19 davlat buyurtmachilarini ikkiga bo'ladi: byudjet buyurtmachilari (davlat organlari va muassasalari, byudjet tashkilotlari, byudjet mablag'lari oluvchilar, davlat maqsadli fondlari va byudjet tashkilotlarida tashkil etilgan fondlar) va korporativ buyurtmachilar. ⚠️ MUHIM YANGILANISH: korporativ buyurtmachilar ro'yxatining birinchi qatori bo'lgan «государственные предприятия» (davlat korxonalari) bandi ЗРУ-1025 (07.02.2025) bilan 08.05.2025 dan CHIQARILGAN. Endi korporativ buyurtmachi deganda ustav fondida davlat ulushi 50 foiz va undan ortiq bo'lgan yuridik shaxslar hamda ular orqali bilvosita 50 foiz va undan ortiq ulushga ega tuzilmalar tushuniladi. Ro'yxatni Davlat aktivlarini boshqarish agentligi yuritadi va u maxsus axborot portalida shakllantiriladi. Toifa muhim, chunki summa chegaralari har xil (ст.56 va ст.64: byudjet buyurtmachilari uchun 6 000 БҲМ, korporativ buyurtmachilar uchun 25 000 БҲМ).","tags":["buyurtmachi","korporativ","chegara"]},{"id":"zru-a-22","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.19","difficulty":2,"q":"Davlat buyurtmachisi bo'lajak davlat xaridlari to'g'risidagi e'lonni elektron tizim va OAVda qachon joylashtirishi mumkin?","options":[{"t":"Yillik reja-grafik portalda joylashtirilganidan keyin darhol","ok":false,"why":"Reja-grafik — rejalashtirish hujjati (ст.29); u moliyalashtirish tasdig'i o'rnini bosmaydi"},{"t":"Xarid komissiyasi tuzilgan va uning tarkibi tasdiqlangandan keyin","ok":false,"why":"Komissiya tuzilishi (ст.20) alohida masala; ст.19 e'lon uchun boshqa shart belgilaydi"},{"t":"Yuqori turuvchi tashkilot bilan yozma kelishilganidan keyin","ok":false,"why":"Qonunda bunday kelishuv sharti yo'q — o'ylab topilgan protsedura"},{"t":"Faqat moliyalashtirish manbalari va hajmlari mavjudligi tasdiqlanganda","ok":true,"why":"ст.19 majburiyati: «только при подтверждении наличия источников и размеров финансирования»"}],"exp":"ст.19 ga ko'ra buyurtmachi bo'lajak xaridlar haqidagi e'lonni faqat moliyalashtirish manbalari va hajmlari mavjudligi tasdiqlanganda joylashtirishi shart; ixtisoslashgan tashkilotga ham shunga o'xshash talab qo'yilgan — u e'lonni faqat moliyalashtirish manbalari mavjudligi tasdiqlanganda joylashtiradi (ст.21). Buning teskari tomoni ст.46 da taqiq shaklida takrorlangan: moliyalashtirish manbasi va hajmi tasdiqlanmagan yoki ajratilgan mablag'dan ortiq summadagi xaridni o'tkazish mumkin emas. Ekspertizada moliyalashtirish tasdig'i yo'qligi jiddiy kamchilik hisoblanadi.","tags":["e'lon","moliyalashtirish","majburiyat"]},{"id":"zru-a-23","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.20","difficulty":2,"q":"Xarid komissiyasida ovozlar teng bo'lib qolganda qanday qoida qo'llaniladi?","options":[{"t":"Qaror qabul qilinmaydi va masala keyingi majlisga o'tkaziladi","ok":false,"why":"Qonun bunday kechiktirish mexanizmini nazarda tutmaydi"},{"t":"Hal qiluvchi ovoz komissiyaning mas'ul kotibiga tegishli bo'ladi","ok":false,"why":"Mas'ul kotib umuman ovoz berish huquqisiz ishlaydi (ст.20)"},{"t":"Komissiya raisining ovozi hal qiluvchi hisoblanadi","ok":true,"why":"ст.20: «В случае равенства голосов голос председателя закупочной комиссии является решающим»"},{"t":"Qarorni davlat buyurtmachisining rahbari mustaqil qabul qiladi","ok":false,"why":"Komissiya o'z vakolati doirasidagi qarorni o'zi qabul qiladi va u buyurtmachi uchun majburiy"}],"exp":"ст.20 ga ko'ra xarid komissiyasi toq sonli a'zolardan iborat bo'ladi, qarorlar a'zolarning umumiy sonidan ko'pchilik ovoz bilan qabul qilinadi, ovozlar teng bo'lganda esa rais ovozi hal qiluvchi hisoblanadi. Rais ovoz berishdan bosh torta olmaydi, mas'ul kotib esa ovoz berish huquqisiz operativ ishni tashkil qiladi. Komissiya o'z vakolati doirasida qabul qilgan qarorlar buyurtmachi va ishtirokchilar uchun majburiydir.","tags":["komissiya","ovoz berish"]},{"id":"zru-a-24","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.20","difficulty":3,"q":"Quyidagilardan qaysi biri ЗРУ-684 20-moddasida sanab o'tilgan xarid komissiyasi funksiyalariga KIRMAYDI?","options":[{"t":"G'olib bilan shartnoma tuzish va uni imzolash","ok":true,"why":"Shartnomani tuzish va imzolash — davlat buyurtmachisining majburiyati (ст.19, ст.21); ст.20 funksiyalari ro'yxatida yo'q"},{"t":"Xarid hujjatlarini kelishish","ok":false,"why":"ст.20 funksiyalari ro'yxatining birinchi bandi"},{"t":"Takliflarni ochish protseduralarini hamda baholash mezon va usullarini belgilash","ok":false,"why":"Ikkalasi ham ст.20 dagi funksiyalar ro'yxatida bevosita ko'rsatilgan"},{"t":"G'olibni va zarur bo'lganda rezerv g'olibni aniqlash yoki savdolarni bo'lib o'tmagan deb topish","ok":false,"why":"ст.20 funksiyalari ro'yxatining oxirgi bandi"}],"exp":"ст.20 komissiya funksiyalarini sanaydi: xarid hujjatlarini kelishish, takliflarni qabul qilish muddatlarini va ochish protseduralarini belgilash, baholash mezon va usullarini hamda taklif ta'minotining tartibi, miqdori va shaklini belgilash, takliflarni ochish, oldindan kvalifikatsiya tanlovini o'tkazish va uning natijalarini hisobga olgan qaror qabul qilish, baholash guruhini tuzish, g'olib va rezerv g'olibni aniqlash yoki savdolarni bo'lib o'tmagan deb topish. Shartnomani tuzish va imzolash bu ro'yxatga kirmaydi — bu buyurtmachining majburiyati. Komissiya protseduralarning qonunchilikka muvofiqligi va o'z qarorlarining asoslanganligi uchun javobgar, boshqa subyektlar harakati uchun esa javob bermaydi.","tags":["komissiya","funksiya","javobgarlik"]},{"id":"zru-a-25","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.21","difficulty":3,"q":"Ixtisoslashgan tashkilot jalb qilinganda shartnomaning muhim shartlarini belgilash va shartnomani imzolashni kim amalga oshiradi?","options":[{"t":"Ixtisoslashgan tashkilot davlat buyurtmachisi nomidan","ok":false,"why":"Ixtisoslashgan tashkilot faqat shartnoma loyihalarini tayyorlaydi, muhim shartlarni belgilamaydi va imzolamaydi"},{"t":"Faqat davlat buyurtmachisining o'zi","ok":true,"why":"ст.21: «Определение существенных условий договора и подписание договора осуществляются исключительно государственным заказчиком»"},{"t":"Xarid komissiyasining raisi","ok":false,"why":"Rais komissiya majlislari protokollarini imzolaydi (ст.20), shartnomani emas"},{"t":"Davlat xaridlari elektron tizimi operatori","ok":false,"why":"Operatorga xarid va narx shakllantirish jarayoniga aralashish taqiqlangan (ст.25)"}],"exp":"ст.21 ga ko'ra ixtisoslashgan tashkilot buyurtmachi topshirig'i bilan pullik asosda xaridni tashkil etish xizmatini ko'rsatadi: boshlang'ich narxni (стартовая цена) aniqlaydi, e'lon matnlari va xarid hujjatlarini rasmiylashtiradi, g'oliblar bilan imzolanadigan shartnoma loyihalarini tayyorlaydi. Biroq shartnomaning muhim shartlarini belgilash va shartnomani imzolash faqat davlat buyurtmachisi tomonidan amalga oshiriladi. Ixtisoslashgan tashkilot yoki uning affiliatsiya qilingan shaxsi o'zi tashkil etayotgan protsedurada ishtirokchi bo'la olmaydi, buzilish yuz berganda esa javobgarlik buyurtmachi va ixtisoslashgan tashkilotga birga yuklanadi.","tags":["ixtisoslashgan tashkilot","shartnoma","javobgarlik"]},{"id":"zru-a-26","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.22","difficulty":2,"q":"Ekspert va ekspert tashkiloti xarid protseduralariga qanday asosda jalb qilinadi?","options":[{"t":"Faqat vakolatli organning topshirig'i bilan va faqat bepul asosda","ok":false,"why":"Jalb qilish protsedurani tashkil etish jarayonida amalga oshiriladi, vakolatli organ topshirig'i talab qilinmaydi"},{"t":"Faqat pullik shartnoma asosida","ok":false,"why":"«Faqat pullik» — Qonun bepul (безвозмездная) asosni ham ochiq nazarda tutgan"},{"t":"Buyurtmachi rahbarining buyrug'i bilan, shartnomasiz","ok":false,"why":"ст.22 asos sifatida aynan tegishli shartnomani ko'rsatadi"},{"t":"Tegishli shartnoma asosida, shu jumladan tekin (bepul) asosda ham","ok":true,"why":"ст.22: «на основании соответствующего договора, в том числе на безвозмездной основе»"}],"exp":"ст.22 ga ko'ra takliflarni ko'rib chiqish, baholash va solishtirish bo'yicha konsultatsiya va (yoki) xulosa olish uchun ekspertlar va ekspert tashkilotlari tegishli shartnoma asosida, shu jumladan tekin asosda jalb qilinishi mumkin. Ekspert — xarid predmeti sohasida maxsus bilimga ega jismoniy shaxs, ekspert tashkiloti esa xodimlari shunday bilimga ega yuridik shaxs. Ular xizmatni davlat xaridlari to'g'risidagi qonunchilikka rioya qilgan holda ko'rsatadi.","tags":["ekspert","subyektlar"]},{"id":"zru-a-27","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.25","difficulty":2,"q":"ЗРУ-684 25-moddasi davlat xaridlari elektron tizimi operatoriga nisbatan quyidagi talablardan qaysi birini belgilaydi?","options":[{"t":"Operator har bir xarid komissiyasiga kamida bitta o'z vakilini kiritadi","ok":false,"why":"Qonunda bunday talab yo'q; aksincha, vakolatli organ vakilini boshqa buyurtmachi komissiyasiga kiritish taqiqlangan (ст.20)"},{"t":"Operator o'z elektron resursini O'zbekiston Respublikasi hududida joylashgan apparat-texnik vositalarda joylashtiradi","ok":true,"why":"ст.25 dagi aynan majburiyat — ma'lumot infratuzilmasi mamlakat hududida bo'lishi shart"},{"t":"Operator boshlang'ich narxni (стартовая цена) aniqlashda buyurtmachi bilan birga qatnashadi","ok":false,"why":"Operatorga narx shakllantirish jarayoniga aralashish bevosita taqiqlangan"},{"t":"Operator ishtirokchilar taqdim etgan hujjatlarning haqqoniyligini tekshiradi","ok":false,"why":"ст.25 operatorga elektron hujjatlar haqqoniyligini nazorat qilish yoki tekshirishni taqiqlaydi (qonunchilik yoki shartnomada boshqacha bo'lmasa)"}],"exp":"ст.25 ga ko'ra operator elektron tizimning uzluksiz ishlashini, ma'lumot butligi va saqlanishini ta'minlaydi hamda o'z elektron resursini O'zbekiston Respublikasi hududidagi apparat-texnik vositalarda joylashtiradi. Operatorga xaridda ishtirokchi, ijrochi yoki o'z tizimida buyurtmachi sifatida qatnashish, narx shakllantirishga aralashish, hujjatlar mazmunini o'zgartirish va ularning haqqoniyligini tekshirish taqiqlanadi. Shu bilan birga u subyektlar joylashtirgan elektron hujjatlar mazmuni uchun huquqiy javobgarlik ko'tarmaydi. Operatorning o'zi ЗРУ-1005 dan keyin vakolatli organ beradigan ruxsat xususiyatiga ega hujjat asosida faoliyat yuritadi.","tags":["operator","cheklov","axborot xavfsizligi"]},{"id":"zru-a-28","doc":"ЗРУ-684","topic":"Umumiy","ref":"ст.29","difficulty":3,"q":"Byudjet buyurtmachilari davlat xaridlarining yillik reja-grafigini maxsus axborot portalida qachongacha joylashtiradi?","options":[{"t":"O'tgan yilning 25-dekabriga qadar","ok":false,"why":"25-dekabr — korporativ buyurtmachilar uchun keyingi yilga mo'ljallangan reja-grafik muddati"},{"t":"Joriy yilning 1-yanvariga qadar","ok":false,"why":"Qonunda bunday sana umuman yo'q — moliyaviy yil boshi bilan chalg'itish"},{"t":"Joriy yilning 25-martiga qadar","ok":true,"why":"ст.29: «Годовой план-график ... размещается бюджетными заказчиками до 25 марта текущего года»"},{"t":"Joriy chorakning oxirgi oyi 25-sanasiga qadar","ok":false,"why":"Bu choraklik reja-grafik muddati, yillik reja-grafik uchun emas"}],"exp":"ст.29 uchta muddatni belgilaydi: byudjet buyurtmachilari yillik reja-grafikni joriy yilning 25-martiga qadar; korporativ buyurtmachilar keyingi yilga mo'ljallangan yillik reja-grafikni joriy yilning 25-dekabriga qadar; barcha davlat buyurtmachilari keyingi chorakka mo'ljallangan choraklik reja-grafikni joriy chorak oxirgi oyining 25-sanasiga qadar portalda joylashtiradi. Rejalashtirish xarid jarayonining birinchi bosqichi (ст.26) va byudjet buyurtmachilari uchun to'lov shartlaridan biri (ст.27 — g'aznachilik to'lovi rejalashtirish, protsedura, shartnoma tuzish, ma'lumot joylashtirish va shartnomani g'aznachilikda ro'yxatdan o'tkazish yakunlangandan keyin amalga oshiriladi). Reja-grafikda aks etmagan xarid — protsedura buzilishining birinchi belgisi.","tags":["muddat","reja-grafik","rejalashtirish"]},{"id":"pp-b-01","doc":"ПП-332","topic":"Ekspertiza","ref":"ПП-332, п.3(а)","difficulty":2,"q":"ПП-332 п.3(а) нинг АМАЛДАГИ (ПҚ-104, 13.03.2026) таҳририга кўра тендер бўйича харид ҳужжатлари ва ТЗ экспертизаси ҳақи қандай ҳисобланади?","options":[{"t":"Харид предмети қийматининг 0,1 фоизи, лекин 100 БҲМ дан ортиқ эмас","ok":false,"why":"100 БҲМ — ЭСКИ чегара. ПҚ-104 (13.03.2026) уни 200 БҲМ га оширди; эски рақам фақат уйғунлаштирилмаган Прил.4 п.6 да қолиб кетган"},{"t":"ҚҚСсиз харид предмети қийматининг 0,1 фоизи (тендер ҳужжатлари ва ТЗ бўйича — ҳар бир лотнинг дастлабки қийматидан, қўшимча келишув бўйича — қўшимча келишув суммасидан), лекин 200 БҲМ дан ортиқ эмас, устига ҚҚС қўшилади","ok":true,"why":"п.3(а) амалдаги таҳрири айнан шундай: 0,1 % ҚҚСсиз, ҳар бир лотнинг дастлабки суммасидан, максимум 200 БҲМ, ҚҚС алоҳида қўшилади"},{"t":"Харид предмети қийматининг 0,03 фоизи, лекин 200 БҲМ дан ортиқ эмас","ok":false,"why":"Чегара тўғри, аммо ставка нотўғри: 0,03 % — бу ТЭО экспертизаси ставкаси (п.3(б)), тендер/ТЗ учун эмас"},{"t":"Тендер (лотлар) умумий суммасининг 0,1 фоизи, лекин 50 БҲМ дан ортиқ эмас","ok":false,"why":"База ҳам, чегара ҳам нотўғри: база — ҳар бир лотнинг ДАСТЛАБКИ суммаси, чегара эса 50 эмас, 200 БҲМ"}],"exp":"ПП-332 п.3(а) (ПҚ-104 таҳрири): тендер бўйича харид ҳужжатлари ва давлат харидига доир ТЗ, шунингдек шартнома, импорт контракт ва уларга қўшимча келишув лойиҳалари (шартнома ва импорт контракт қиймати ошган ҳолларда) экспертизаси ҳақи — харид предмети қийматининг 0,1 % (ҚҚСсиз), лекин 200 БҲМ дан ортиқ эмас, ҚҚС алоҳида қўшилади. Тендер ҳужжатлари ва ТЗ бўйича база — ҳар бир ЛОТНИНГ дастлабки суммаси, қўшимча келишув бўйича — қўшимча келишув суммаси. Шу банднинг иккинчи жумласига кўра бюджет ва Тикланиш-тараққиёт жамғармаси маблағлари ҳисобидан амалга ошириладиган тендер ҳужжатлари учун шу суммадан атиги 10 фоиз олинади. ⚠️ Прил.4 п.6 да ҳамон эски «100 БҲМ» рақами турибди — у ПҚ-104 билан уйғунлаштирилмаган, ҳисоб п.3(а) бўйича юритилади.","tags":["summa","chegara","ekspertiza haqi"]},{"id":"pp-b-02","doc":"ПП-332","topic":"Ekspertiza","ref":"ПП-332, п.3(а) (2-жумла)","difficulty":2,"q":"Бюджет тизими бюджетлари ва Тикланиш ва тараққиёт жамғармаси маблағлари ҳисобидан амалга ошириладиган тендер бўйича харид ҳужжатлари экспертизаси ҳақи АМАЛДАГИ таҳрирда қандай олинади?","options":[{"t":"Ҳақ умуман олинмайди — бундай тендер ҳужжатлари экспертизаси бепул","ok":false,"why":"Бу — ЭСКИ п.3(д) нормаси. У ПҚ-104 (13.03.2026) билан БУТУНЛАЙ бекор қилинган; ўрнига пасайтирилган ҳақ жорий этилди"},{"t":"Умумий тартибда ҳисобланган сумманинг 50 фоизи миқдорида","ok":false,"why":"50 фоиз — ТЭР экспертизаси коэффициенти (п.3(в), Ктэр = 0,5), тендер ҳужжатларига алоқаси йўқ"},{"t":"п.3(а) бўйича ҳисобланган сумманинг 10 фоизи миқдорида","ok":true,"why":"п.3(а) нинг иккинчи жумласи айнан шундай: бюджет ва ФРР маблағлари ҳисобидаги тендер ҳужжатлари учун «в размере 10 процентов суммы, определенной настоящим подпунктом»"},{"t":"Тўлиқ ҳажмда, ҳеч қандай имтиёзсиз — молия манбаси аҳамиятга эга эмас","ok":false,"why":"Имтиёз йўқолмади, у ўзгарди: тўлиқ бепуллик ўрнига 10 фоизли пасайтирилган ставка қўлланади"}],"exp":"Илгари ПП-332 п.3(д) бюджет тизими бюджетлари ва Тикланиш ва тараққиёт жамғармаси маблағлари ҳисобидан амалга ошириладиган тендер ҳужжатлари ҳамда предпроект ҳужжатларини ишлаб чиқишга доир ТЗ экспертизасини БЕПУЛ деб белгилаган эди. ПҚ-104 (13.03.2026) п.3(д) ни бутунлай чиқариб ташлади ва имтиёзни п.3(а) нинг иккинчи жумласига кўчирди: бундай тендер ҳужжатлари учун умумий тартибда ҳисобланган сумманинг 10 фоизи олинади. Диққат: имтиёз ҳамон МОЛИЯ МАНБАСИГА боғланган (буюртмачи турига эмас) ва фақат тендер ҳужжатларига тегишли — давлат харидига доир ТЗ, ТЭО/ТЭР ва шартнома экспертизаси тўлиқ ҳақ билан.","tags":["ekspertiza haqi","imtiyoz","byudjet"]},{"id":"pp-b-03","doc":"ПП-332","topic":"Shartnoma","ref":"ПП-332, п.2(б)","difficulty":1,"q":"ПП-332 п.2(б) га кўра Марказ шартнома ва импорт контракт лойиҳалари билан нима қилади?","options":[{"t":"Фақат экспертиза қилади, рўйхатга олиш Адлия вазирлиги томонидан амалга оширилади","ok":false,"why":"Рўйхатга олиш ҳам айнан Марказ вазифаси, Адлия вазирлиги эмас"},{"t":"Фақат рўйхатга олади, экспертиза буюртмачининг ўзи томонидан ўтказилади","ok":false,"why":"Тескари: п.2(б) да ҳам экспертиза, ҳам рўйхатга олиш Марказга юклатилган"},{"t":"Тендер натижалари бўйича тузилган БАРЧА шартномаларни экспертиза қилади ва рўйхатга олади","ok":false,"why":"п.2(б) тўғридан-тўғри музокаралар асосидаги шартномаларга тегишли; тендер натижасидаги ҳар қандай шартнома автоматик тушмайди"},{"t":"Қонунчиликда белгиланган тартибда тўғридан-тўғри музокаралар асосида давлат буюртмачилари томонидан тузиладиган шартнома, импорт контракт ва уларга қўшимча келишув лойиҳаларини экспертиза қилади ва рўйхатга олади","ok":true,"why":"п.2(б) матни айнан шундай: «экспертизу и регистрацию проектов договоров, импортных контрактов и дополнительных соглашений… на основе прямых переговоров»"}],"exp":"ПП-332 п.2 Марказнинг икки блок вазифасини белгилайди: (а) комплекс экспертиза — предпроект ҳужжатлари ҳамда тендер бўйича харид ҳужжатлари ва давлат харидига доир ТЗ; (б) тўғридан-тўғри музокаралар асосида тузиладиган шартнома, импорт контракт ва қўшимча келишув лойиҳаларини экспертиза қилиш ВА РЎЙХАТГА ОЛИШ. Диққат: ПҚ-104 (13.03.2026) п.2(а) дан «предпроект ҳужжатларини ишлаб чиқишга доир ТЗ» ни чиқариб ташлади — эндиликда бу ТЗ Марказ экспертизаси предмети эмас. Рўйхатга олиш тартиби Прил.3 п.34 да берилган: замечаниясиз хат олингач бир ой ичида имзоланган асл нусха киритилади, 5 иш куни ичида рўйхатга олинади.","tags":["Markaz vazifasi","ro'yxatga olish"]},{"id":"pp-b-04","doc":"ПП-332","topic":"Umumiy","ref":"ПП-332, п.2 (тақиқ ҳақидаги хатбоши)","difficulty":3,"q":"ПП-332 п.2 да норматив-ҳуқуқий ҳужжатларга нисбатан белгиланган тақиқ нимадан иборат?","options":[{"t":"Норматив-ҳуқуқий ҳужжатларда аниқ етказиб берувчи номи ва/ёки товар (иш, хизмат) қийматини кўрсатиш умуман ҳар қандай ҳолатда тақиқланади","ok":false,"why":"Тақиқ шартли: Марказ билан келишилган бўлса кўрсатиш мумкин"},{"t":"Монополияга қарши қўмита билан келишилмаган ҳолда етказиб берувчи номини кўрсатиш тақиқланади","ok":false,"why":"Субъект алмаштирилган: банд Марказ билан келишувни талаб қилади"},{"t":"Марказ билан харид предметининг нарх шакллантириши ва/ёки етказиб берувчини аниқлаш масалалари келишилмаган ҳолда норматив-ҳуқуқий ҳужжатларда аниқ етказиб берувчи номи ва/ёки товар (иш, хизмат) қийматини кўрсатиш тақиқланади","ok":true,"why":"Банд матни айнан шу — тақиқ Марказ билан келишув бўлмаганда амал қилади"},{"t":"Молия вазирлиги билан келишилмаган ҳолда товар қийматини кўрсатиш тақиқланади","ok":false,"why":"Субъект алмаштирилган: келишув Марказ билан, Молия вазирлиги билан эмас"}],"exp":"ПП-332 п.2: «запрещается указание в нормативно-правовых актах наименования конкретных поставщиков и (или) стоимости товаров (работ, услуг) при отсутствии согласования с Центром вопросов ценообразования предмета закупки и (или) определения поставщика». Бу банд амалда қарор лойиҳаларида олдиндан етказиб берувчи ёзиб қўйилиши ҳолатларини рад этиш асоси бўлади. Диққат: ПП-147 (21.04.2025) п.2 га еттинчи хатбоши қўшгандан кейин ушбу тақиқ энди п.2 нинг ОХИРГИ хатбошиси эмас — охиргиси хорижда ишлаб чиқарилган АКТ маҳсулотлари бўйича «Рақамли Ўзбекистон — 2030» Мувофиқлаштирувчи комиссияси ижобий қарори талабидир.","tags":["taqiq","nazorat"]},{"id":"pp-b-05","doc":"ПП-332","topic":"Ekspertiza","ref":"ПП-332, п.3(в)","difficulty":2,"q":"ПП-332 п.3(в) га кўра лойиҳалар ТЭР комплекс экспертизаси учун ҳақ қандай белгиланади?","options":[{"t":"Лойиҳанинг умумий суммасидан 0,03 фоиз миқдорида, ТЭО билан бир хил","ok":false,"why":"ТЭР ставкаси мустақил эмас — у ТЭО учун белгиланган суммадан ҳисобланади"},{"t":"ТЭО экспертизаси учун белгиланган суммадан 30 фоиз миқдорида","ok":false,"why":"Фоиз нотўғри: п.3(в) да 30 эмас, 50 фоиз"},{"t":"ТЭО экспертизаси учун белгиланган суммадан 50 фоиз миқдорида","ok":true,"why":"п.3(в) айнан шундай: «в размере 50 процентов от суммы, установленной для… ТЭО». Бу банд ПҚ-104 билан ўзгартирилмаган"},{"t":"Лойиҳа умумий суммасининг 50 фоизи миқдорида","ok":false,"why":"База алмаштирилган: 50 % лойиҳа суммасидан эмас, ТЭО экспертизаси ҳақидан ҳисобланади"}],"exp":"ПП-332 п.3(в): ТЭР комплекс экспертизаси ҳақи — ТЭО экспертизаси учун белгиланган суммадан 50 фоиз. Прил.4 п.2 да бу пасайтирувчи коэффициент Ктэр = 0,5 кўринишида формулага киритилган: Ц экс.тэр = Ц ос × Ктэр × 0,03 %, ва у ерда 2 минг — 25 минг АҚШ доллари чегараси турибди. ⚠️ ПҚ-104 (13.03.2026) п.3(б) да ТЭО юқори чегарасини 50 мингдан 100 минг долларга оширди, аммо Прил.4 нинг рақамлари уйғунлаштирилмади — шу боис ҳисоб-китобда асос сифатида п.3 нинг ўзи олинади.","tags":["ekspertiza haqi","TER"]},{"id":"pp-b-06","doc":"ПП-332","topic":"Ekspertiza","ref":"ПП-332, п.3(г)","difficulty":1,"q":"ПП-332 п.3(г) га кўра экспертиза қандай тўлов шарти билан ўтказилади?","options":[{"t":"100 фоизли олдиндан тўлов шарти билан","ok":true,"why":"п.3(г) матни: «экспертиза проводится с условием 100-процентной предоплаты»; худди шу қоида Прил.1 п.13 да такрорланган"},{"t":"50 фоизли аванс, қолгани хулоса берилгандан кейин","ok":false,"why":"Қисман аванс схемаси қарорда назарда тутилмаган"},{"t":"Тўлов ижобий хулоса берилгандан кейин амалга оширилади","ok":false,"why":"Тескари: тўлов экспертизадан ОЛДИН, тўлиқ ҳажмда амалга оширилади"},{"t":"30 фоиз аванс, қолгани рўйхатга олишда","ok":false,"why":"Бундай тартиб қарорда йўқ; олдиндан тўлов 100 фоиз"}],"exp":"ПП-332 п.3(г): экспертиза 100 % олдиндан тўлов шарти билан ўтказилади; шу қоида Прил.1 п.13 нинг иккинчи хатбошисида ҳам такрорланган. Оқибати амалий: Прил.1 п.15 (ПҚ-104 таҳрири) га кўра комплекс экспертиза муддатининг бошланиши — хизматлар қиймати тўланганлиги тасдиқланган САНА; Прил.2 п.21 ва Прил.3 п.29 да ҳам муддат «ҳужжатлар тақдим этилган ва хизмат ҳақи тўланган кундан» ҳисобланади. Яъни тўланмаган ариза бўйича муддат умуман юрмайди.","tags":["to'lov","tartib"]},{"id":"pp-b-07","doc":"ПП-332","topic":"Ekspertiza","ref":"ПП-332, п.3(б)","difficulty":3,"q":"ПП-332 п.3(б) нинг АМАЛДАГИ (ПҚ-104) таҳририга кўра лойиҳалар ТЭО комплекс экспертизаси ҳақининг ставкаси ва чегаралари қандай?","options":[{"t":"Лойиҳа умумий суммасининг 0,03 фоизи, 4 минг АҚШ долларидан кам эмас ва 50 минг АҚШ долларидан кўп эмас","ok":false,"why":"50 минг — ЭСКИ юқори чегара. ПҚ-104 (13.03.2026) уни 100 минг долларга оширди; эски рақам фақат уйғунлаштирилмаган Прил.4 п.1 да қолган"},{"t":"Лойиҳа умумий суммасининг 0,3 фоизи, 4 минг АҚШ долларидан кам эмас ва 100 минг АҚШ долларидан кўп эмас","ok":false,"why":"Ставка ўн баравар оширилган: п.3(б) да 0,3 эмас, 0,03 фоиз"},{"t":"ҚҚСсиз лойиҳа умумий суммасининг 0,03 фоизи, 4 минг АҚШ долларидан кам эмас ва эквивалентда 100 минг АҚШ долларидан кўп эмас, ҚҚС қўшимча олинади","ok":true,"why":"п.3(б) амалдаги таҳрири айнан шундай: 0,03 %, 4 минг USD дан кам эмас, 100 минг USD дан кўп эмас, ҚҚС алоҳида"},{"t":"Лойиҳа умумий суммасининг 0,03 фоизи, 2 минг АҚШ долларидан кам эмас ва 25 минг АҚШ долларидан кўп эмас","ok":false,"why":"2–25 минг доллар оралиғи ТЭР учун (Прил.4 п.2), ТЭО учун эмас"}],"exp":"ПП-332 п.3(б) (ПҚ-104 таҳрири): ТЭО комплекс экспертизаси ҳақи — ҚҚСсиз лойиҳа умумий суммасининг 0,03 фоизи, лекин 4 минг АҚШ долларидан кам эмас ва 100 минг АҚШ долларидан кўп эмас (эквивалентда), ҚҚС алоҳида қўшилади. Формула Прил.4 п.1 да: Ц экс.тэо = Ц ос × 0,03 %. ⚠️ Прил.4 п.1 матнида ва ундаги мисолларда (170 млн долларлик лойиҳа учун 51 → 50 минг долларга туширилиши) ҳамон эски «50 минг» чегараси турибди — Инструкция ПҚ-104 билан уйғунлаштирилмаган, устун норма п.3(б).","tags":["ekspertiza haqi","TEO","chegara"]},{"id":"pp-b-08","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.1, п.2(а)","difficulty":3,"q":"Прил.1 п.2(а) нинг АМАЛДАГИ (ПҚ-104) таҳририга кўра бюджет тизими бюджетлари, давлат мақсадли жамғармалари ва Тикланиш ва тараққиёт жамғармаси маблағлари ҳисобидан молиялаштириладиган лойиҳалар предпроект ҳужжатлари Марказ комплекс экспертизасига қайси қийматдан бошлаб тушади?","options":[{"t":"50 000 БҲМ ва ундан ортиқ","ok":false,"why":"Бу — ЭСКИ чегара. Амалдаги таҳрирда 50 000 БҲМ бошқа вазифани бажаради: қиймати ундан ошмайдиган лойиҳалар бўйича ИШ ЛОЙИҲАСИ ишлаб чиқилади ва у «Шаҳарсозлик ҳужжатлари экспертизаси республика маркази» ДУК да экспертиза қилинади"},{"t":"Эквивалентда 15 миллион АҚШ доллари ва ундан ортиқ","ok":true,"why":"п.2(а): «стоимостью в эквиваленте 15 миллионов долларов США и более» — ПҚ-104 киритган янги кириш чегараси"},{"t":"Эквивалентда 5 миллион АҚШ доллари ва ундан ортиқ","ok":false,"why":"5 млн доллар — п.2(д), яъни давлат ташқи қарзи ҳисобидан молиялаштириладиган лойиҳалар учун алоҳида чегара"},{"t":"6 000 БҲМ ва ундан ортиқ","ok":false,"why":"6 000 БҲМ — Прил.2 ва Прил.3 даги бюджет буюртмачилари учун тендер/шартнома чегараси, предпроект ҳужжатларига алоқаси йўқ"}],"exp":"Прил.1 п.2(а) (ПҚ-104, 13.03.2026 таҳрири): Низом амали қиймати эквивалентда 15 млн АҚШ доллари ва ундан ортиқ лойиҳаларга — бюджет тизими бюджетлари, давлат мақсадли жамғармалари, бошқа жамғармалар ва Тикланиш ва тараққиёт жамғармаси ҳисобидан молиялаштириладиган ҳамда корпоратив буюртмачилар амалга оширадиганларига — татбиқ этилади. Айни бандда 50 000 БҲМ энди КИРИШ чегараси эмас: қиймати 50 000 БҲМ дан ошмайдиган лойиҳалар бўйича иш лойиҳаси ишлаб чиқилади ва у «Шаҳарсозлик ҳужжатлари экспертизаси республика маркази» ДУК ва унинг ҳудудий бошқармаларида экспертизадан ўтади. Бошқа кириш чегаралари: п.2(в) — ДХШ (ГЧП) лойиҳалари учун 10 млн доллардан ортиқ; п.2(д) — давлат ташқи қарзи доирасида 5 млн доллар ва ундан ортиқ.","tags":["chegara","TEO","yurisdiksiya"]},{"id":"pp-b-09","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.1, п.14","difficulty":3,"q":"Прил.1 п.14 нинг АМАЛДАГИ (УП-259, 26.12.2025) таҳририга кўра предпроект ҳужжатлари комплекс экспертизасининг муддатлари қандай белгиланган?","options":[{"t":"ТЗ — 15 иш кунидан кўп эмас, ТЭО/ТЭР — 30 иш кунидан кўп эмас","ok":false,"why":"Бу — ЭСКИ таҳрир. УП-259 муддатларни лойиҳа ҚИЙМАТИГА боғлади, ПҚ-104 эса ТЗ ҳақидаги хатбошиларни п.14 дан умуман чиқариб ташлади"},{"t":"Барча предпроект ҳужжатлари учун ягона муддат — 30 иш куни","ok":false,"why":"Ягона муддат йўқ: банд лойиҳа қийматига қараб тўртта тоифани ажратади"},{"t":"Лойиҳа қийматига қараб: «кичик» (5–50 млн АҚШ долл.) — 20 иш куни, «ўрта» (50–200 млн) — 25 иш куни, «йирик» (200 млн — 1 млрд) — 30 иш куни, «мега-лойиҳа» (1 млрд ва ундан ортиқ) — 45 иш кунидан кўп эмас","ok":true,"why":"п.14 нинг УП-259 таҳриридаги тўрт тоифаси айнан шу рақамлар билан берилган"},{"t":"Лойиҳа қийматига қараб 10, 15, 20 ва 25 КАЛЕНДАРЬ кун","ok":false,"why":"Тоифалаш ғояси тўғри, аммо бу рақамлар Прил.2 п.21 дан — тендер ҳужжатлари/ТЗ учун календарь кунлар; Прил.1 да ИШ кунлари ҳисобланади"}],"exp":"Прил.1 п.14 (УП-259, 26.12.2025 таҳрири): муддат энди ҳужжат турига эмас, лойиҳа қийматига боғланган — «кичик» инвестиция лойиҳалари (5,0–50,0 млн АҚШ долл.) 20 иш кунигача, «ўрта» (50,0–200,0 млн) 25 иш кунигача, «йирик» (200,0 млн — 1,0 млрд) 30 иш кунигача, «мега-лойиҳалар» (1,0 млрд ва ундан ортиқ) 45 иш кунигача. ПҚ-104 п.14 нинг ТЗ ҳақидаги 2- ва 3-хатбошиларини чиқариб ташлади — предпроект ҳужжатларини ишлаб чиқишга доир ТЗ энди Марказ экспертизаси предмети эмас. Прил.1 п.15 га кўра муддат хизмат ҳақи тўланганлиги тасдиқланган санадан бошланади; п.16 бўйича комплектсизлик аниқланса, 3 иш куни ичида хабар қилинади ва муддат тўлдирилган ҳужжат киритилган санадан юради.","tags":["muddat","TEO"]},{"id":"pp-b-10","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.1, п.21","difficulty":3,"q":"Прил.1 п.21 нинг АМАЛДАГИ (ПҚ-104) таҳририга кўра инициатор камчиликларни бартараф этганидан кейин ҚАЙТА экспертиза муддати қанча?","options":[{"t":"ТЗ — 10 иш кунидан кўп эмас, ТЭО/ТЭР — 15 иш кунидан кўп эмас","ok":false,"why":"Бу — ЭСКИ таҳрир. ПҚ-104 дан кейин ТЗ Прил.1 предметидан чиқарилди ва муддат ягоналаштирилди"},{"t":"Ҳар икки ҳолатда ҳам 10 календарь кун","ok":false,"why":"10 календарь кун — Прил.2 п.27 (тендер ҳужжати/ТЗ) бўйича қайта кўриб чиқиш муддати"},{"t":"Ҳар икки ҳолатда ҳам 5 иш куни","ok":false,"why":"5 иш куни — Прил.3 п.40 бўйича шартнома лойиҳасини қайта кўриб чиқиш муддати"},{"t":"15 иш кунидан кўп эмас — ҳужжат турига қараб фарқланмайди","ok":true,"why":"п.21 амалдаги матни: «повторная экспертиза осуществляется в срок не более пятнадцати рабочих дней»"}],"exp":"Прил.1 п.21 (ПҚ-104 таҳрири): камчиликлар бартараф этилганда қайта экспертиза 15 иш кунидан ошмайди — эски ТЗ/ТЭО-ТЭР бўлиниши (10/15) олиб ташланган. Шу билан бирга п.22 га кўра қайта экспертизада олдинги хулосада кўрсатилмаган ЯНГИ асослар бўйича камчилик бериш мумкин эмас (қўшимча тақдим этилган материаллар билан боғлиқларидан ташқари). ПҚ-104 п.22 га яна бир хатбоши қўшди: Марказнинг камчилик ва таклифлари МАЖБУРИЙ равишда тармоқ норматив-ҳуқуқий ҳужжатлари, нормалар, талаблар ва стандартларга ҳавола билан расмийлаштирилади; ҳаволасиз камчилик АСОССИЗ ҳисобланади.","tags":["muddat","qayta ekspertiza"]},{"id":"pp-b-11","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.1, п.24","difficulty":3,"q":"Прил.1 п.24 нинг АМАЛДАГИ (ПҚ-104) таҳририга кўра предпроект ҳужжатлари қайси ҳолда комплекс экспертизага ЯНГИДАН киритилган ҳисобланади?","options":[{"t":"Марказнинг ижобий хулосаси олингандан кейин бир йил (365 календарь кун) ичида предпроект ҳужжатлари тасдиқланмаса","ok":true,"why":"п.24 нинг амалдаги таҳририда ягона асос айнан шу — «при ее неутверждении в течение одного года (365 календарных дней)»"},{"t":"Ижобий хулосадан кейин 365 кун ичида тасдиқланмаса ЁКИ камчиликли хулосадан кейин 180 кун ичида қайта ишланган ҳужжат киритилмаса","ok":false,"why":"Иккинчи (180 кунлик) асос ЭСКИ таҳрирда бор эди — ПҚ-104 уни олиб ташлади, ҳозир п.24 да фақат битта асос қолган"},{"t":"Камчиликлар кўрсатилган хулоса олингандан кейин 180 календарь кун ичида қайта ишланган ТЭО/ТЭР киритилмаса","ok":false,"why":"Бу асос п.24 дан чиқарилган; олти ойлик муддат энди фақат Прил.2 п.18-19 ва Прил.3 п.41 да — такрорий кўриб чиқиш ҳақ билан ёки ҳақсиз бўлиши масаласида учрайди"},{"t":"Ҳар икки ҳолатда ҳам олти ой (180 кун) ўтганда","ok":false,"why":"п.24 да 180 кунлик муддат умуман қолмаган; амалдаги ягона муддат — 365 календарь кун"}],"exp":"Прил.1 п.24 (ПҚ-104 таҳрири): предпроект ҳужжатлари Марказнинг ижобий хулосаси олингандан кейин бир йил (365 календарь кун) ичида тасдиқланмаса, комплекс экспертизага янгидан киритилган ҳисобланади — яъни экспертиза ҳақи қайтадан ундирилади. Эски таҳрирдаги иккинчи асос (камчиликли хулосадан кейин 180 кун ичида қайта ишланган ҳужжат киритилмаслиги) чиқариб ташланган. Олти ойлик муддатни аралаштирмаслик керак: Прил.2 п.18-19 да у тендер ҳужжати/ТЗ ни такрорий киритишда ҳақ олинмаслик чегараси, Прил.3 п.41 да эса шартнома лойиҳаси учун худди шундай чегара.","tags":["muddat","to'lov","qayta kiritish"]},{"id":"pp-b-12","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.1, п.18","difficulty":2,"q":"Прил.1 п.18 га кўра комплекс экспертизага тақдим этилаётган предпроект ҳужжатларининг сифати, ишончлилиги ва тўлиқлиги учун ким жавобгар?","options":[{"t":"Фақат инициатор (буюртмачи)","ok":false,"why":"Рўйхат тўлиқ эмас: банд учта субъектни санайди"},{"t":"Инициатор (буюртмачи), ишлаб чиқувчи (разработчик) ва ОНТС","ok":true,"why":"Прил.1 п.18 матни айнан шу учтасини кўрсатади"},{"t":"Комплекс экспертизани ўтказган Марказ","ok":false,"why":"Марказ мансабдорлари фақат экспертиза НАТИЖАЛАРИНИНГ ишончлилиги ва холислиги учун жавобгар (п.29), ҳужжат сифати учун эмас"},{"t":"Инициатор ва Марказ биргаликда","ok":false,"why":"Марказ бу рўйхатда йўқ; ўрнига разработчик ва ОНТС кўрсатилган"}],"exp":"Прил.1 п.18: экспертизага тақдим этилаётган ҳужжатларнинг сифати, ишончлилиги ва тўлиқлиги учун жавобгарлик инициатор (буюртмачи), ишлаб чиқувчи ва тармоқ илмий-техник кенгаши (ОНТС) зиммасига юклатилади. Прил.2 п.16 да эса тендер ҳужжати ва ТЗ учун жавобгарлик фақат давлат буюртмачисига юклатилган — субъектлар доираси фарқ қилади.","tags":["javobgarlik","TEO"]},{"id":"pp-b-13","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.5 (2-хатбоши)","difficulty":3,"q":"Прил.3 п.5 нинг АМАЛДАГИ (УП-259, 26.12.2025) таҳририга кўра тўғридан-тўғри шартнома лойиҳалари Марказ экспертизасига қандай АСОС ва қандай СУММАДА мажбурий киритилади?","options":[{"t":"Президент фармон/қарорлари ва Вазирлар Маҳкамаси қарорлари асосида, бир шартнома бўйича 25 000 БҲМ дан (бюджет буюртмачилари учун — 6 000 БҲМ дан) ошган ҳолларда","ok":false,"why":"Сумма чегаралари тўғри, аммо АСОС эскирган: УП-259 дан кейин банд «Давлат харидлари тўғрисида»ги Қонун 71-моддаси биринчи қисмининг аниқ бандларига ҳавола қилади"},{"t":"«Давлат харидлари тўғрисида»ги Қонун 71-моддаси биринчи қисмининг 2, 5, 8, 12, 13, 15—21-бандлари асосида тузиладиган, бир шартнома бўйича қиймати 25 000 БҲМ дан (бюджет буюртмачилари учун — 6 000 БҲМ дан) ошган ҳолларда","ok":true,"why":"п.5 нинг иккинчи хатбошиси айнан шундай: ст.71 ч.1 нинг 2, 5, 8, 12, 13, 15—21-бандлари + 25 000 / 6 000 БҲМ чегараси"},{"t":"Қонун 71-моддаси асосида, барча буюртмачилар учун бир хил — 25 000 БҲМ дан ошганда","ok":false,"why":"Бюджет буюртмачилари учун пасайтирилган чегара — 6 000 БҲМ назарда тутилган"},{"t":"Қонун 71-моддаси асосида, бир шартнома бўйича 50 000 БҲМ дан ошганда","ok":false,"why":"50 000 БҲМ — Прил.1 п.2(а) даги иш лойиҳаси чегараси, шартномага алоқаси йўқ"}],"exp":"Прил.3 п.5 иккинчи хатбошиси (УП-259, 26.12.2025 таҳрири): «Давлат харидлари тўғрисида»ги Қонун 71-моддаси биринчи қисмининг 2, 5, 8, 12, 13, 15—21-бандлари асосида тўғридан-тўғри шартнома бўйича харидга йўл қўйилган ҳолларда, БИР шартнома бўйича қиймати 25 000 БҲМ дан (бюджет буюртмачилари учун — 6 000 БҲМ дан) ошса, лойиҳа мажбурий экспертизага тушади (қонунчиликда белгиланган истиснолардан ташқари). Эски таҳрир асос сифатида умумий тарзда Президент ва Ҳукумат қарорларини кўрсатар эди — энди ҳавола аниқ қонун бандларига. Бу — мажбурийлик чегараси; ундан паст суммалар п.6 бўйича фақат ихтиёрий асосда киритилиши мумкин.","tags":["chegara","summa","majburiy"]},{"id":"pp-b-14","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.6","difficulty":3,"q":"Прил.3 п.5 да кўрсатилмаган давлат буюртмачилари ва тадбиркорлик субъектлари шартнома лойиҳаларини Марказга ихтиёрий шартномавий асосда қайси суммадан бошлаб киритиши мумкин?","options":[{"t":"6 000 БҲМ дан ошган суммага","ok":true,"why":"Прил.3 п.6 матни айнан шундай: «на сумму, превышающую шеститысячекратный размер базовой расчетной величины»"},{"t":"Ҳар қандай суммага, чегарасиз","ok":false,"why":"Ихтиёрийлик чегарани бекор қилмайди: п.6 да ҳам 6 000 БҲМ пастки чегараси бор"},{"t":"25 000 БҲМ дан ошган суммага","ok":false,"why":"25 000 БҲМ — п.5 бўйича МАЖБУРИЙ экспертиза чегараси, ихтиёрий эмас"},{"t":"5 000 БҲМ дан ошган суммага","ok":false,"why":"5 000 БҲМ — Прил.2 п.3 даги ТЕХНИК ТОПШИРИҚ бўйича ихтиёрий оралиқнинг қуйи чети, Прил.3 га тегишли эмас"}],"exp":"Прил.3 п.6: п.5 да кўрсатилмаган давлат буюртмачилари ва тадбиркорлик субъектлари 6 000 БҲМ дан ОШГАН суммадаги шартнома, импорт контракт ва қўшимча келишув лойиҳаларини ихтиёрий шартномавий асосда киритиши мумкин. Демак 6 000 БҲМ — ПАСТКИ чегара: ундан паст суммадаги шартнома на п.5 (мажбурий), на п.6 (ихтиёрий) бўйича Марказ экспертизасига тушмайди — бу юрисдикция масаласи ва қайтариш асоси бўлади.","tags":["chegara","ixtiyoriy","возврат"]},{"id":"pp-b-15","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.5 (импорт контракт ҳақидаги хатбоши)","difficulty":3,"q":"Прил.3 п.5 га кўра қайси импорт контракт лойиҳалари Марказ экспертизасига мажбурий тушади?","options":[{"t":"Давлат ташқи қарзи ҳисобидан молиялаштириладиган лойиҳалар доирасидаги, эквивалентда 100 минг АҚШ долларидан ортиқ импорт контрактлар","ok":false,"why":"Чегара 100 минг эмас — 1 миллион АҚШ доллари эквиваленти"},{"t":"Тендер ҳужжатлари Марказда комплекс экспертизадан ўтказилмаган ҳолда тузиладиган, давлат ташқи қарзи ҳисобидан молиялаштириладиган лойиҳалар доирасидаги, эквивалентда 1 миллион АҚШ долларига тенг ва ундан ортиқ импорт контрактлар (ХМИ ва хорижий ҳукумат молия ташкилотлари қарзларидан ташқари)","ok":true,"why":"Прил.3 п.5 нинг ушбу хатбошиси айнан шу тўртта шартни бирга талаб қилади"},{"t":"Эквивалентда 5 миллион АҚШ долларидан ортиқ ҳар қандай импорт контракт","ok":false,"why":"5 млн АҚШ доллари — Прил.1 п.2(д) даги предпроект ҳужжатлари чегараси; бунда молия манбаси шарти ҳам тушиб қолган"},{"t":"1 миллион АҚШ долларидан ортиқ барча импорт контрактлар, шу жумладан халқаро молия институтлари қарзлари ҳисобидан молиялаштирилганлари","ok":false,"why":"ХМИ ва хорижий ҳукумат молия ташкилотлари қарзлари бандда АЙНАН истисно қилинган"}],"exp":"Прил.3 п.5: давлат ташқи қарзи ҳисобидан молиялаштириладиган лойиҳалар доирасида, тендер ҳужжатлари Марказда комплекс экспертизадан ўтказилмасдан тузиладиган, қиймати 1 млн АҚШ доллари эквивалентига тенг ва ундан ортиқ импорт контракт ва уларга қўшимча келишув лойиҳалари экспертизага тушади. Халқаро молия институтлари (ХМИ) ва хорижий ҳукумат молия ташкилотлари қарз маблағлари истисно қилинган. Худди шу мазмундаги норма Прил.2 п.3(б) да тендер ҳужжатлари учун ҳам берилган.","tags":["import kontrakt","chegara","tashqi qarz"]},{"id":"pp-b-16","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.4","difficulty":2,"q":"Прил.3 п.4 га кўра қайси ҳужжатлар Марказда экспертиза қилинМАЙДИ?","options":[{"t":"Фақат мажбуриятлари тўлиқ бажарилган шартномалар","ok":false,"why":"Рўйхат кенгроқ: қисман бажарилганлар ва экспертизадан ўтмаган асосий шартномага қўшимча келишувлар ҳам кирмайди"},{"t":"Тарафлар томонидан бекор қилинган шартномалар","ok":false,"why":"Бандда бекор қилиш эмас, мажбуриятларнинг бажарилиши мезон қилиб олинган"},{"t":"Суммаси 6 000 БҲМ дан паст барча шартномалар","ok":false,"why":"Бу сумма чегараси п.5–п.6 масаласи; п.4 бошқа асосни — бажарилганлик ва аввалги экспертиза йўқлигини белгилайди"},{"t":"Мажбуриятлари тўлиқ ёки қисман бажарилган шартнома ва импорт контрактлар, шунингдек лойиҳалари илгари Марказда экспертизадан ўтмаган шартнома ва импорт контрактларга қўшимча келишувлар","ok":true,"why":"Прил.3 п.4 нинг охирги жумласи айнан шу икки ҳолатни санайди"}],"exp":"Прил.3 п.4: мажбуриятлари тўлиқ ёки ҚИСМАН бажарилган шартнома/импорт контрактлар, шунингдек лойиҳалари илгари Марказда экспертизадан ўтмаган шартномаларга қўшимча келишувлар Марказда экспертиза қилинмайди. Амалда бу — Босқич 0 (юрисдикция) фильтри: аллақачон ижро бошланган шартнома ёки «ота» шартномаси экспертизадан ўтмаган ДС қайтарилади.","tags":["yurisdiksiya","возврат","допсоглашение"]},{"id":"pp-b-17","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.8","difficulty":2,"q":"Прил.3 п.8 да талаб қилинадиган «юридик хулоса (юридическое заключение)» нимани англатади?","options":[{"t":"Адлия вазирлигининг ҳуқуқий экспертиза хулосаси","ok":false,"why":"Субъект алмаштирилган: бандда буюртмачининг ички юридик хизмати назарда тутилган"},{"t":"Нотариал тасдиқланган адвокатлик хулосаси","ok":false,"why":"Нотариал ёки адвокатлик хулосаси бандда талаб қилинмайди"},{"t":"Буюртмачининг юридик хизмати визаси — шартнома/импорт контракт лойиҳасининг Ўзбекистон Республикаси қонунчилигига мувофиқлиги тўғрисида","ok":true,"why":"Прил.3 п.8: «юридическое заключение (виза юридической службы) о соответствии проекта… законодательству»"},{"t":"Марказ юристининг дастлабки хулосаси","ok":false,"why":"Марказ ўз хулосасини экспертиза натижасида беради; кириш пакетидаги юридик хулоса буюртмачидан талаб қилинади"}],"exp":"Прил.3 п.8 га кўра шартнома/импорт контракт лойиҳасини экспертизага киритишда буюртмачининг ЮРИДИК ХИЗМАТИ ВИЗАСИ — лойиҳанинг Ўзбекистон Республикаси қонунчилигига мувофиқлиги тўғрисидаги юридик хулоса тақдим этилиши шарт. У пакет комплектлигининг элементи бўлгани учун йўқлиги п.36 бўйича «ҳужжатлар тўлиқ ҳажмда эмас» асосида қайтаришга олиб келади.","tags":["hujjatlar","komplektlik"]},{"id":"pp-b-18","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.8","difficulty":2,"q":"Агар шартнома ёки импорт контракт лойиҳаси қонунчиликка мувофиқ харид процедуралари натижалари бўйича тузилган бўлса, нарх шакллантириш асослари (обоснование ценообразования) ЎРНИГА нима тақдим этилади?","options":[{"t":"Харид комиссияси ёки идоравий харид комиссияси баённомасининг нусхаси","ok":true,"why":"Прил.3 п.8: «вместо обоснования ценообразования представляется копия протокола закупочной комиссии или ведомственной закупочной комиссии»"},{"t":"Камида учта тижорат таклифи ва биржа котировкалари","ok":false,"why":"Айнан шу ҳужжатлар нарх асосларининг ўзи; процедура ўтказилган бўлса улар талаб қилинмайди"},{"t":"Марказнинг тендер ҳужжатлари бўйича ижобий хулосаси","ok":false,"why":"Ижобий хулоса алоҳида ҳужжат; п.8 да нарх асоси ўрнига айнан комиссия баённомаси кўрсатилган"},{"t":"Махсус ахборот порталидаги тендер эълони матни","ok":false,"why":"Эълон нархни тасдиқловчи ҳужжат эмас; ғолиб ва нарх комиссия баённомасида қайд этилади"}],"exp":"Прил.3 п.8: одатда буюртмачининг биринчи раҳбари имзоси билан тасдиқланган нарх шакллантириш асослари (сўровлар, тижорат таклифлари, биржа/ассоциация котировкалари, прайс-листлар) тақдим этилади. Аммо шартнома харид процедуралари натижаси бўйича тузилган бўлса, улар ўрнига харид комиссияси ёки идоравий харид комиссияси баённомаси нусхаси берилади — чунки нарх рақобат орқали шаклланган.","tags":["narx asoslash","hujjatlar"]},{"id":"pp-b-19","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.29","difficulty":3,"q":"Прил.3 п.29 га кўра шартнома, импорт контракт ва қўшимча келишув лойиҳалари экспертизаси муддатлари қандай?","options":[{"t":"Умумий ҳолатда 20 календарь кун, махсус ҳолатда 5 календарь кун","ok":false,"why":"Рақамлар тўғри, аммо кун тури нотўғри: п.29 да календарь эмас, ИШ кунлари ҳисобланади"},{"t":"Умумий ҳолатда 30 календарь кун, махсус ҳолатда 10 календарь кун","ok":false,"why":"30 календарь кун — УП-259 (26.12.2025) гача амал қилган ЭСКИ Прил.2 нормаси, ҳозир бундай муддат ПП-332 матнида умуман йўқ; амалдаги тендер ҳужжатлари муддати харид тоифаси ва позициялар сонига қараб 10–25 календарь кун. Прил.3 да эса иш кунлари амал қилади"},{"t":"Керакли ҳужжатлар тақдим этилган ва хизматлар учун тўлов амалга оширилган кундан 20 иш куни; Президент/Ҳукумат қарорлари асосида (етказиб берувчи ва нарх белгиланган) ёки тасдиқланган ТЭО параметрлари доирасида тузиладиган шартномалар бўйича — 5 иш куни","ok":true,"why":"Прил.3 п.29 нинг иккала хатбошиси айнан шундай; Прил.3 га илова схемада ҳам 4-босқич «20 (йигирма) иш куни»"},{"t":"Умумий ҳолатда 15 иш куни, махсус ҳолатда 5 иш куни","ok":false,"why":"15 иш куни — Прил.1 п.21 даги ТЭО/ТЭР нинг ҚАЙТА экспертизаси муддати, шартномага алоқаси йўқ; Прил.3 да асосий муддат 20 иш куни"}],"exp":"Прил.3 п.29: асосий муддат — керакли ҳужжатлар тақдим этилган ва тўлов амалга оширилган кундан бошлаб 20 ИШ КУНИ. Қисқартирилган 5 иш кунлик муддат — етказиб берувчи ва нарх Президент/Ҳукумат қарорларида белгиланган ёки тасдиқланган ТЭО параметрлари доирасидаги шартномалар учун. Прил.3 схемасида ҳам 4-босқич 20 иш куни. МУҲИМ: «30 календарь кун» деган чалғитувчи вариант эски (УП-259 дан олдинги) Прил.2 нормаси — бугун ПП-332 матнида 30 календарь кунлик муддат умуман қолмаган.","tags":["muddat","shartnoma"]},{"id":"pp-b-20","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.30","difficulty":2,"q":"Прил.3 п.30 га кўра Марказ шартнома/импорт контракт лойиҳаси экспертизасида нимани текширади?","options":[{"t":"Фақат контракт нархларининг халқаро бозор конъюнктурасига мувофиқлигини","ok":false,"why":"Рўйхат уч элементдан иборат; маҳаллий бозор ва ҳужжатлар/шартлар мувофиқлиги ҳам киради"},{"t":"Буюртмачининг бюджет интизоми ва маблағлардан мақсадли фойдаланишини","ok":false,"why":"Бу молия назорати/аудит вазифаси, п.30 предметига кирмайди"},{"t":"Етказиб берувчининг солиқ қарзи ва молиявий барқарорлигини","ok":false,"why":"п.10 да фақат етказиб берувчини идентификациялаш маълумотлари сўралади; солиқ қарзини баҳолаш п.30 да йўқ"},{"t":"Тўлов валютаси ва товар келиб чиқиш мамлакатига қараб контракт нархларининг халқаро бозор конъюнктурасига ҳамда маҳаллий бозордаги ўхшаш товарлар нарх даражасига мувофиқлигини; тақдим этилган ҳужжатларнинг Низом талабларига мувофиқлигини; шартнома шартларининг халқаро ва ички савдонинг умумқабул нормаларига мувофиқлигини","ok":true,"why":"Прил.3 п.30 нинг учала хатбошиси айнан шу учта текширув йўналишини белгилайди"}],"exp":"Прил.3 п.30: экспертизада учта нарса ўрганилади — (1) контракт нархларининг халқаро ва маҳаллий бозор даражасига мувофиқлиги, (2) тақдим этилган ҳужжатларнинг Низом талабларига мувофиқлиги, (3) шартнома шартларининг халқаро ва ички савдо нормаларига мувофиқлиги. п.31 га кўра бунда бозор конъюнктураси, ОАВ ва Интернет нашрлари, заводлар/ишлаб чиқарувчилар ва расмий дилерлардан бевосита олинган маълумотлар манба сифатида ишлатилади.","tags":["mezon","narx","shartnoma"]},{"id":"pp-b-21","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.34","difficulty":2,"q":"Марказдан «эътирозлар йўқлиги тўғрисидаги хат» олингандан кейин рўйхатга олиш қандай амалга оширилади?","options":[{"t":"Буюртмачи 10 иш куни ичида оригинални киритади, рўйхатга олиш 20 иш куни ичида амалга оширилади","ok":false,"why":"Иккала муддат ҳам нотўғри: оригинал учун бир ой, рўйхатга олиш учун 5 иш куни белгиланган"},{"t":"Шартнома Марказ хатининг ўзи асосида автоматик рўйхатга олинган ҳисобланади","ok":false,"why":"Хат — рўйхатга олиш эмас; рўйхатга олиш имзоланган оригинал киритилгандан кейин алоҳида амалга оширилади"},{"t":"Буюртмачи бир ой муддатда тарафлар томонидан имзоланган оригинални Марказга киритади; ҳужжатлар тақдим этилгандан кейин 5 иш куни ичида шартнома рўйхатга олинади, ҳар бир саҳифага штамп қўйилади ва идентификацион рақам берилади","ok":true,"why":"Прил.3 п.34 нинг биринчи ва иккинчи хатбошилари айнан шундай"},{"t":"Буюртмачи уч ой муддатда оригинални киритади, рўйхатга олиш 5 иш куни ичида амалга оширилади","ok":false,"why":"Оригинални киритиш муддати уч ой эмас — бир ой"}],"exp":"Прил.3 п.34: эътирозлар йўқлиги тўғрисидаги хат олингач, буюртмачи БИР ОЙ ичида имзоланган оригинални ва аввал экспертизадан ўтган лойиҳа нусхаларини Марказга киритади; ҳужжатлар тақдим этилгандан кейин 5 иш куни ичида рўйхатга олинади ва Прил.3 шакли бўйича хулоса берилади, ҳар бир саҳифага штамп қўйилади, идентификацион рақам берилади. Бир ой ичида киритмаса — буюртмачи хулоса олиш ҳуқуқини йўқотади.","tags":["ro'yxatga olish","muddat"]},{"id":"pp-b-22","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.36","difficulty":1,"q":"Қуйидагилардан қайси бири Прил.3 п.36 бўйича экспертиза ва рўйхатга олишни РАД ЭТИШ асоси ҳисобланади?","options":[{"t":"Импорт контракт бўйича тўловнинг имтиёзли солиқ режими берадиган ва/ёки молиявий операцияларда ахборотни ошкор этишни назарда тутмайдиган давлат (офшор зона) да рўйхатдан ўтган норезидент фойдасига амалга оширилиши","ok":true,"why":"Прил.3 п.36 нинг биринчи хатбошиси айнан шу асосни белгилайди"},{"t":"Шартнома матнининг рус тилида тузилгани","ok":false,"why":"п.27 га кўра давлат тили ҳам, рус тили ҳам бир хилда жоиз; бу рад асоси эмас"},{"t":"Етказиб берувчининг хорижий юридик шахс экани","ok":false,"why":"Норезидент билан шартнома — бу импорт контракт, у Прил.3 предметининг ўзи; рад асоси эмас"},{"t":"Шартнома суммасининг 25 000 БҲМ дан кам экани","ok":false,"why":"Бу — юрисдикция/мажбурийлик масаласи (п.5–п.6), п.36 даги рад асослари рўйхатида йўқ"}],"exp":"Прил.3 п.36 да олтита рад асоси саналган: офшор зонада рўйхатдан ўтган норезидент фойдасига тўлов; ҳужжатларнинг тўлиқ ҳажмда тақдим этилмагани; ишончсиз ёки бузиб кўрсатилган маълумотлар; харид процедураларининг бузилиши; нархларнинг ўртача бозор нархларидан ошиб кетиши; ҳужжатларнинг мазкур Низом талабларига мувофиқ эмаслиги. Шу банднинг охирги хатбошисига кўра Марказ замечанияларини ҳисобга олмасдан шартнома имзоланса, буюртмачи мансабдорлари жавобгар бўлади.","tags":["возврат","rad asosi","ofshor"]},{"id":"pp-b-23","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.40","difficulty":2,"q":"Прил.3 п.40 га кўра буюртмачи рад этиш асоси бўлган сабабларни бартараф этганидан кейин экспертиза ва рўйхатга олиш қанча муддатда амалга оширилади?","options":[{"t":"10 календарь кундан кўп бўлмаган муддатда","ok":false,"why":"10 календарь кун — Прил.2 п.27 (тендер ҳужжати/ТЗ) қайта кўриб чиқиш муддати"},{"t":"5 иш кунидан кўп бўлмаган муддатда","ok":true,"why":"Прил.3 п.40 матни айнан шундай; схеманинг 10-босқичида ҳам 5 иш куни кўрсатилган"},{"t":"20 иш куни — биринчи экспертиза билан бир хил муддатда","ok":false,"why":"20 иш куни — п.29 бўйича БИРЛАМЧИ экспертиза муддати; қайтасига қисқартирилган муддат амал қилади"},{"t":"15 иш кунидан кўп бўлмаган муддатда","ok":false,"why":"15 иш куни — Прил.1 п.21 даги ТЭО/ТЭР қайта экспертизаси муддати"}],"exp":"Прил.3 п.40: рад этиш сабаблари бартараф этилганда, шартнома/импорт контракт/қўшимча келишув лойиҳаси ва сабаблар бартараф этилганини тасдиқловчи ҳужжатлар олинган кундан бошлаб 5 иш кунидан кўп бўлмаган муддатда экспертиза ва рўйхатга олиш амалга оширилади. п.41 га кўра 6 ой ичида қайта киритилса, қайта кўриб чиқиш учун ҳақ олинмайди.","tags":["muddat","qayta ekspertiza"]},{"id":"pp-b-24","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.41","difficulty":2,"q":"Прил.3 п.41 га кўра қайта тақдим этилган шартнома лойиҳаси учун ҳақ қандай ундирилади?","options":[{"t":"Қайта кўриб чиқиш ҳар доим бепул — муддатдан қатъи назар","ok":false,"why":"Бепуллик 6 ойлик муддат билан чекланган; ундан кейин тўлиқ ҳақ ундирилади"},{"t":"Уч ой ичида киритилса бепул, ундан кейин ҳақ ундирилади","ok":false,"why":"Муддат уч ой эмас — олти ой"},{"t":"Бир йил ичида киритилса бепул, ундан кейин ҳақ ундирилади","ok":false,"why":"Бир йил (365 календарь кун) — Прил.1 п.24 даги ТЭО/ТЭР тасдиқлаш муддати, бу ерга алоқаси йўқ"},{"t":"Эътирозлар кўрсатилган хулоса олинган кундан 6 ой ичида қайта киритилса ҳақ олинмайди; 6 ой ўтгач киритилса — янги ҳужжат экспертизаси учун белгиланган миқдорда ундирилади","ok":true,"why":"Прил.3 п.41 нинг иккала хатбошиси айнан шундай"}],"exp":"Прил.3 п.41: эътирозли хулоса олинган кундан 6 ой ичида қайта киритилган ҳужжат учун ҳақ олинмайди; 6 ойлик муддат ўтгач киритилса — янги ҳужжат учун белгиланган миқдорда ҳақ ундирилади. Схеманинг изоҳида ҳам «6 ой ўтгач қайта киритилган лойиҳалар янгидан киритилган ҳисобланади» деб қайд этилган.","tags":["to'lov","muddat","qayta kiritish"]},{"id":"pp-b-25","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.27","difficulty":2,"q":"Прил.3 п.27 га кўра шартнома ва импорт контракт лойиҳаси матнининг тилига қандай талаб қўйилади?","options":[{"t":"Фақат давлат тилида тузилиши шарт, бошқа тиллар йўл қўйилмайди","ok":false,"why":"Банд давлат тили билан бир қаторда рус тилини ҳам тенг равишда жоиз деб белгилайди"},{"t":"Ҳар қандай тилда тузилиши мумкин, таржима талаб қилинмайди","ok":false,"why":"Бошқа тилдаги матн давлат ёки рус тилига таржима қилиниб, белгиланган тартибда тасдиқланиши шарт"},{"t":"Давлат ёки рус тилида баён этилади; бошқа тилдаги матн давлат ёки рус тилига таржима қилиниб тасдиқланади; икки тилда тузилса — саҳифанинг чап ва ўнг томонида параллель таржима шаклида расмийлаштирилиб, ҳар икки матнга бир хил юридик куч берилади ва ихтилоф юзага келганда қайси матн устунлик қилиши кўрсатилади","ok":true,"why":"Прил.3 п.27 нинг тўлиқ мазмуни айнан шундай"},{"t":"Икки тилда тузилганда ихтилоф юзага келса ҳар доим рус тилидаги матн устун ҳисобланади","ok":false,"why":"Қайси матн устунлиги қонунда эмас, шартноманинг ўзида кўрсатилиши шарт — автоматик рус тили устунлиги йўқ"}],"exp":"Прил.3 п.27: матн давлат ёки рус тилида баён этилади; бошқа тилда бўлса — таржима қилиниб, белгиланган тартибда тасдиқланади. Икки тилда тузилганда параллель таржима (чап/ўнг томон) шаклида расмийлаштирилади, иккала матн тенг юридик кучга эга бўлади, аммо ихтилоф ҳолати учун қайси матн устун экани шартноманинг ўзида кўрсатилиши шарт — бу банд кўпинча импорт контрактларда камчилик сифатида қайд этилади.","tags":["til","shartnoma sharti"]},{"id":"pp-b-26","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.23","difficulty":2,"q":"Прил.3 п.23 («Применимое право») га кўра шартнома/импорт контракт лойиҳасида қўлланиладиган ҳуқуқ қандай белгиланади?","options":[{"t":"Тарафлар ўзаро муносабатларини тартибга солувчи ҳуқуқни аниқлаши ва кўрсатиши шарт","ok":true,"why":"Прил.3 п.23 матни: «Стороны обязаны определить и указать право, регулирующее взаимоотношения сторон»"},{"t":"Ҳар доим Ўзбекистон Республикаси ҳуқуқи қўлланилиши мажбурий","ok":false,"why":"Банд қўлланиладиган ҳуқуқни аниқлашни тарафлар зиммасига юклайди, аниқ ҳуқуқ тизимини мажбурламайди"},{"t":"Қўлланиладиган ҳуқуқни экспертиза жараёнида Марказ белгилайди","ok":false,"why":"Марказ мувофиқликни текширади, тарафлар ўрнига ҳуқуқ танламайди"},{"t":"Бу шарт ихтиёрий — тарафлар хоҳласа кўрсатмаслиги мумкин","ok":false,"why":"Банд «обязаны» сўзи билан ифодаланган: кўрсатиш мажбурий"}],"exp":"Прил.3 п.23: тарафлар ўзаро муносабатларни тартибга солувчи ҳуқуқни аниқлаши ва шартномада кўрсатиши шарт. Бу билан бирга п.24 га кўра импорт контракт лойиҳасида музокаралар йўли билан ҳал этилмайдиган низоларни кўриб чиқиш тартиби, шу жумладан кўриб чиқиш ЖОЙИ ва ОРГАНИ кўрсатилиши лозим. Иккала банд ҳам шартнома экспертизасининг стандарт текширув элементлари ҳисобланади.","tags":["qo'llaniladigan huquq","nizo"]},{"id":"pp-b-27","doc":"ПП-332","topic":"Shartnoma","ref":"Прил.3, п.22","difficulty":2,"q":"Прил.3 п.22 («Гарантии») га кўра кафолат бўйича талаб қандай ифодаланган?","options":[{"t":"Кафолат муддати ҳар доим камида 12 ой қилиб белгиланиши шарт","ok":false,"why":"Низомда аниқ 12 ойлик минимум йўқ; муддат ва ҳажм шартномада белгиланади"},{"t":"Мувофиқлик сертификати олинишини назарда тутувчи импорт контракт лойиҳаларида ижрочи томонидан бериладиган кафолат муддатлари ва ҳажми белгиланади, шунингдек кафолат мажбуриятлари амал қила бошлаш санаси кўрсатилади","ok":true,"why":"Прил.3 п.22 нинг иккала хатбошиси айнан шу талабни беради"},{"t":"Кафолат мажбуриятлари фақат маҳаллий резидентлар билан тузилган шартномаларда белгиланади","ok":false,"why":"Тескари: банд айнан импорт контрактларга нисбатан кафолат муддати ва ҳажмини белгилашни талаб қилади"},{"t":"Кафолат муддатини экспертиза натижасида Марказ белгилайди","ok":false,"why":"Марказ кафолат шартининг мавжудлиги ва асосланганлигини текширади, муддатни ўзи белгиламайди"}],"exp":"Прил.3 п.22: мувофиқлик сертификати олинишини назарда тутувчи импорт контракт лойиҳаларида ижрочи берадиган кафолат муддатлари ва ҳажми белгиланади, ижрочи кафолат муддати давомида товар (иш, хизмат) сифати учун жавобгар бўлади ва кафолат мажбуриятларини бажариш тартиби кўрсатилади. Шартнома/контракт шартларида кафолат мажбуриятлари амал қила бошлаш САНАСИ ҳам белгиланиши шарт.","tags":["kafolat","shartnoma sharti"]},{"id":"pp-b-28","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.4, п.2","difficulty":3,"q":"Прил.4 п.2 га кўра ТЭР комплекс экспертизаси хизмати нархи қандай аниқланади?","options":[{"t":"Лойиҳа умумий суммасининг 0,03 фоизи, 4 минг АҚШ долларидан кам эмас ва 50 минг АҚШ долларидан кўп эмас","ok":false,"why":"Бу ТЭО учун белгиланган ставка ва чегаралар (Прил.4 п.1)"},{"t":"ТЭО учун белгиланган суммадан 50 фоиз, лекин 4 минг АҚШ долларидан кам эмас ва 50 минг АҚШ долларидан кўп эмас","ok":false,"why":"Фоиз тўғри, аммо чегаралар ТЭО дан кўчирилган: ТЭР учун 2–25 минг АҚШ доллари"},{"t":"Лойиҳа умумий суммасининг 30 фоизи, 2 минг АҚШ долларидан кам эмас","ok":false,"why":"Ҳам фоиз, ҳам база нотўғри: 50 фоиз ва ТЭО экспертизаси суммасидан ҳисобланади"},{"t":"ТЭО учун белгиланган тўлов суммасидан 50 фоиз (Ц экс.тэр = Ц ос × Ктэр × 0,03 %, бунда Ктэр = 0,5), лекин 2 минг АҚШ долларидан кам эмас ва эквивалентда 25 минг АҚШ долларидан кўп эмас, ҚҚС алоҳида","ok":true,"why":"Прил.4 п.2 нинг формуласи, коэффициенти ва чегаралари айнан шундай"}],"exp":"Прил.4 п.2: ТЭР экспертизаси ҳақи — ТЭО учун белгиланган суммадан 50 фоиз; формула Ц экс.тэр = Ц ос × Ктэр × 0,03 %, бунда Ктэр = 0,5 (пасайтирувчи коэффициент). Хизмат нархи 2 минг АҚШ долларидан кам ва 25 минг АҚШ доллари эквивалентидан кўп бўлиши мумкин эмас, ҚҚС алоҳида ундирилади.","tags":["ekspertiza haqi","TER","formula"]},{"id":"pp-b-29","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.4, п.3","difficulty":3,"q":"Прил.4 п.3 га кўра хизмат нархини миллий валютада аниқлашда хорижий валютанинг қайси санадаги курси қўлланилади?","options":[{"t":"Шартномага мувофиқ хизматлар тўлови учун ҳисоб-фактура (счёт) қўйилган санада Ўзбекистон Республикаси Марказий банки белгилаган курс","ok":true,"why":"Прил.4 п.3 матни: «на дату выставления счета на оплату услуг согласно договору»"},{"t":"Ариза Марказга киритилган санадаги Марказий банк курси","ok":false,"why":"Ариза санаси экспертиза муддатини ҳисоблашга тегишли, курсни аниқлашга эмас"},{"t":"Тўлов ҳақиқатда амалга оширилган санадаги Марказий банк курси","ok":false,"why":"Қўшни, аммо нотўғри сана: банд ҳисоб-фактура қўйилган санани белгилайди"},{"t":"Экспертиза шартномаси имзоланган санадаги Марказий банк курси","ok":false,"why":"Шартнома имзолаш санаси эмас, ҳисоб-фактура қўйилган сана мезон қилиб олинган"}],"exp":"Прил.4 п.3: хизмат нархини миллий валютада аниқлаш мақсадида шартномага мувофиқ хизматлар тўлови учун ҳисоб-фактура қўйилган санада Ўзбекистон Республикаси Марказий банки белгилаган хорижий валютанинг миллий валютага курси қўлланилади. Бу қоида долларда белгиланган ТЭО/ТЭР ҳақини сўмга ўтказишда амалий аҳамиятга эга.","tags":["kurs","ekspertiza haqi"]},{"id":"pp-b-30","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.4, п.6 ва п.8(б)","difficulty":3,"q":"Прил.4 п.8(б) мисолида лот суммаси ҚҚСсиз 60 000,0 млн сўм бўлиб, 0,1 % бўйича ҳисобланган ҳақ 60,0 млн сўмни ташкил этади. Инструкцияга кўра қайси сумма ундирилади?","options":[{"t":"60,0 млн сўм — ҳисоб-китоб бўйича тўлиқ сумма","ok":false,"why":"Ҳисоб-китоб суммаси 100 БҲМ дан ошгани учун чегарагача пасайтирилади"},{"t":"50 БҲМ миқдорида — чунки лот битта","ok":false,"why":"Инструкцияда 50 БҲМ чегараси йўқ; юқори чегара 100 БҲМ"},{"t":"100 БҲМ гача пасайтирилади — мисолда 300,0 минг сўм × 100 = 30 000,0 минг сўм (ҚҚСсиз), ҚҚС алоҳида қўшилади","ok":true,"why":"Прил.4 п.6 юқори чегарани 100 БҲМ қилиб белгилайди, п.8(б) мисоли айнан шу ҳисобни келтиради"},{"t":"100 БҲМ гача пасайтирилади, бунда ҚҚС ушбу чегара ичига киритилган ҳисобланади","ok":false,"why":"100 БҲМ — ҚҚССИЗ чегара; ҚҚС унинг устига қўшимча ундирилади"}],"exp":"Прил.4 п.6: ҳақ харид предмети қийматининг 0,1 фоизи миқдорида (тендер ҳужжатлари ва ТЗ бўйича — ҳар бир лотнинг дастлабки суммасидан), лекин 100 БҲМ дан ортиқ эмас, ҚҚС қўшилиб ундирилади. п.8(б) мисолида 69 000,0 млн сўмлик лот ҚҚСсиз 60 000,0 млн сўмга айлантирилади, 0,1 % — 60,0 млн сўм, бу 100 БҲМ дан ошгани учун 100 БҲМ гача (мисолда 30 000,0 минг сўм) пасайтирилади.","tags":["ekspertiza haqi","chegara","hisob-kitob"]},{"id":"pp-a-01","doc":"ПП-332","topic":"Tender","ref":"Прил.2, п.3(а)","difficulty":1,"q":"ПП-332 2-иловасига кўра, БЮДЖЕТ буюртмачисининг тендер ҳужжатлари битта шартнома бўйича қайси суммадан ошганда Марказ экспертизасига мажбурий киритилади?","options":[{"t":"5 000 БҲМ дан ошганда","ok":false,"why":"5 000 БҲМ — п.3 нинг охирги хатбошисидаги ИХТИЁРИЙ (добровольная договорная основа) киритиш оралиғининг пастки чегараси, мажбурий чегара эмас."},{"t":"25 000 БҲМ дан ошганда","ok":false,"why":"25 000 БҲМ — КОРПОРАТИВ буюртмачи учун белгиланган чегара; субъект алмаштирилган."},{"t":"6 000 БҲМ (базавий ҳисоблаш миқдори) дан ошганда","ok":true,"why":"Прил.2 п.3(а): «шеститысячекратный размер базовой расчетной величины, осуществляемым бюджетным заказчиком»."},{"t":"50 000 БҲМ дан ошганда","ok":false,"why":"50 000 БҲМ Прил.1 п.2(а) да бутунлай бошқа контекстда учрайди: шу суммадан ошмайдиган лойиҳалар бўйича иш лойиҳаси ишлаб чиқилиб, у ГУ «Республиканский центр экспертизы градостроительной документации» текширувига тушади — тендер ҳужжатларига алоқаси йўқ."}],"exp":"Прил.2 п.3(а) экспертиза доирасини суммавий чегара орқали белгилайди: бюджет буюртмачиси учун 6 000 БҲМ, корпоратив буюртмачи учун 25 000 БҲМ. Чегарадан паст сумма умуман мажбурий экспертизага тушмайди — бу Босқич 0 (юрисдикция) текшируви. Сумма ҳар доим нарх асослашидан (стартовая цена) олинади.","tags":["chegara","summa","byudjet"]},{"id":"pp-a-02","doc":"ПП-332","topic":"Tender","ref":"Прил.2, п.3(а)","difficulty":1,"q":"КОРПОРАТИВ буюртмачи учун тендер ҳужжатларини Марказ экспертизасига киритиш суммавий чегараси қанча?","options":[{"t":"6 000 БҲМ","ok":false,"why":"6 000 БҲМ — бюджет буюртмачиси учун; субъект алмаштирилган."},{"t":"25 000 БҲМ","ok":true,"why":"Прил.2 п.3(а): «двадцатипятитысячекратный размер базовой расчетной величины, осуществляемым корпоративным заказчиком»."},{"t":"1 миллион АҚШ доллари эквиваленти","ok":false,"why":"Бу п.3(б) — давлат ташқи қарзи ҳисобидан молиялаштириладиган лойиҳалар учун алоҳида асос, буюртмачи турига боғлиқ эмас."},{"t":"100 000 БҲМ","ok":false,"why":"100 000 БҲМ — амалдаги таҳрирда Прил.2 п.21 даги «сложные закупки» тоифасининг пастки чегараси, у экспертиза МУДДАТИНИ белгилайди, экспертизага киритиш чегарасини эмас."}],"exp":"Прил.2 п.3(а) иккита субъектга иккита чегара беради: бюджет — 6 000 БҲМ, корпоратив — 25 000 БҲМ. Корпоратив буюртмачилар — давлат корхоналари ва устав фондида давлат улуши 50% ва ундан ортиқ юридик шахслар (п.2 таърифи). Диққат: 100 000 БҲМ рақами амалдаги матнда бор, лекин у п.21 даги муддат тоифасига тегишли; экспертиза ҳақининг юқори чегараси эса асосий қарор п.3(а) да ПҚ-104 таҳриридан кейин 200 БҲМ.","tags":["chegara","korporativ","summa"]},{"id":"pp-a-03","doc":"ПП-332","topic":"Tender","ref":"Прил.2, п.3(а)","difficulty":2,"q":"Корпоратив буюртмачи харидни бюджет тизими маблағлари ҳисобидан амалга оширса, унга қайси чегара қўлланади?","options":[{"t":"Ўзининг корпоратив чегараси — 25 000 БҲМ сақланиб қолади","ok":false,"why":"Аксинча: молиялаштириш манбаи бюджет бўлса, корпоратив мақом эмас, бюджет мақоми қўлланади."},{"t":"У шу харид доирасида бюджет буюртмачиси сифатида кўрилади — 6 000 БҲМ","ok":true,"why":"Прил.2 п.3(а): «…корпоративный заказчик в рамках данной закупки рассматривается в качестве бюджетного заказчика»."},{"t":"Иккала чегаранинг ўртачаси — 15 500 БҲМ","ok":false,"why":"Қонунда ҳеч қандай «ўртача» чегара йўқ, бу ўйлаб топилган қоида."},{"t":"Чегара умуман қўлланмайди — сумма қатъи назар экспертиза мажбурий","ok":false,"why":"«Сумма қатъи назар» қоидаси фақат тендерсиз харид ҳуқуқи берилган ҳолатда харид процедураси турига (отбор) тегишли, экспертиза чегарасига эмас."}],"exp":"Прил.2 п.3(а) молиялаштириш манбаи мақомни белгилайди: корпоратив буюртмачи бюджет маблағини ишлатса, шу харид доирасида бюджет буюртмачиси ҳисобланади ва 6 000 БҲМ чегараси қўлланади. Ариза шаклида (Прил.№ 3) молиялаштириш манбаини кўрсатиш мажбурий — шу боис манба текширилиши шарт.","tags":["chegara","byudjet","subyekt"]},{"id":"pp-a-04","doc":"ПП-332","topic":"Tender","ref":"Прил.2, п.3(б)","difficulty":3,"q":"Давлат ташқи қарзи ҳисобидан молиялаштириладиган лойиҳалар доирасидаги тендер ҳужжатлари қайси суммадан бошлаб Марказ экспертизасига киритилади?","options":[{"t":"1 миллион АҚШ доллари эквивалентига тенг ва ундан ортиқ","ok":true,"why":"Прил.2 п.3(б): «стоимостью, равной эквиваленту 1 миллиона долларов США и более, в рамках реализации проектов, финансируемых за счет государственного внешнего долга»."},{"t":"25 000 БҲМ ва ундан ортиқ","ok":false,"why":"БҲМ чегаралари п.3(а) да — ички манбалар бўйича; п.3(б) да ўлчов бирлиги валютада."},{"t":"500 минг АҚШ доллари эквивалентидан ортиқ","ok":false,"why":"Қўшни рақам: бундай чегара ПП-332 да йўқ, тўғри қиймат икки баравар юқори."},{"t":"5 миллион АҚШ доллари эквивалентидан ортиқ","ok":false,"why":"5 млн АҚШ доллари — Прил.1 п.2(д) даги ЛОЙИҲАОЛДИ ҳужжатлари чегараси (давлат ташқи қарзи бўйича), тендер ҳужжатлари учун эмас."}],"exp":"Прил.2 п.3(б) — иккинчи мустақил асос: давлат ташқи қарзи ҳисобидан ≥1 млн АҚШ доллари. Икки истисно матнда бевосита: (1) халқаро молия институтлари ва чет эл ҳукумат молия ташкилотларининг қарз маблағлари; (2) тижорат банклари орқали давлат ташқи қарзи ҳисобидан қайта молиялаштириладиган лойиҳалар (бандга «не применяемая к проектам, рефинансируемым посредством коммерческих банков» изоҳи билан киритилган).","tags":["chegara","tashqi qarz","istisno"]},{"id":"pp-a-05","doc":"ПП-332","topic":"Texnik topshiriq","ref":"Прил.2, п.3 (тендерсиз харид ҳақидаги хатбоши)","difficulty":3,"q":"Президент/Вазирлар Маҳкамаси қарори билан буюртмачига тендерсиз харид ҳуқуқи берилган бўлса, Марказга нима ва қайси суммадан киритилади?","options":[{"t":"Тендер ҳужжатлари — қиймат 6 000 БҲМ дан ошса","ok":false,"why":"Тендерсиз харидда тендер ҳужжатлари шаклланмайди; экспертизага техник топшириқ киритилади."},{"t":"Шартнома лойиҳаси — қиймат 25 000 БҲМ дан ошса","ok":false,"why":"Шартнома лойиҳаси Прил.3 бўйича алоҳида тартибда киритилади, бу Прил.2 нинг предмети эмас."},{"t":"Ҳеч нарса киритилмайди — тендерсиз харид экспертизадан озод","ok":false,"why":"Аксинча, п.3 махсус равишда ТЗ киритилишини талаб қилади; тендерсизлик экспертизадан озод қилмайди."},{"t":"Техник топшириқ — қиймат 25 000 БҲМ (бюджет буюртмачилари учун 6 000 БҲМ) дан ошса","ok":true,"why":"Прил.2 п.3 нинг тендерсиз харид ҳақидаги хатбошиси айнан шу шартни белгилайди ва схема Прил.№ 2 бўйича ТЗ киритилишини кўрсатади."}],"exp":"Прил.2 п.3 га кўра тендерсиз харид ҳуқуқи берилганда харид процедураси суммадан қатъи назар ОТБОР орқали ўтказилади, экспертизага эса ТЗ киритилади — қиймат 25 000 БҲМ (бюджет буюртмачилари учун 6 000 БҲМ) дан ошса. Схема Прил.№ 2 (ТЗ схемаси) қўлланади. Муддат эса амалдаги п.21(б) бўйича ягона эмас — харид тоифаси (сумма) ва позициялар сонига қараб 10 дан 25 календарь кунгача (УП-259, 26.12.2025 таҳрири); илгариги ягона «20 календарь кун» нормаси бекор.","tags":["tendersiz","chegara","otbor"]},{"id":"pp-a-06","doc":"ПП-332","topic":"Texnik topshiriq","ref":"Прил.2, п.3 (охирги хатбоши)","difficulty":3,"q":"Буюртмачи ИХТИЁРИЙ шартномавий асосда ТЗ ни Марказга кирита оладиган сумма оралиғи қандай?","options":[{"t":"5 000 БҲМ дан 25 000 БҲМ гача, бюджет буюртмачилари учун эса 5 000 БҲМ дан 6 000 БҲМ гача","ok":true,"why":"Прил.2 п.3 нинг охирги хатбошиси айнан шу оралиқларни беради ва ҳақ молиялаштириш манбаидан қатъи назар ундирилишини кўрсатади."},{"t":"1 000 БҲМ дан 6 000 БҲМ гача (барча буюртмачилар учун)","ok":false,"why":"Пастки чегара 1 000 эмас, 5 000 БҲМ; юқори чегара буюртмачи турига боғлиқ."},{"t":"6 000 БҲМ дан 25 000 БҲМ гача (барча буюртмачилар учун)","ok":false,"why":"Бюджет буюртмачиси учун 6 000 БҲМ дан юқориси аллақачон МАЖБУРИЙ экспертиза зонаси, ихтиёрий эмас."},{"t":"5 000 БҲМ дан 50 000 БҲМ гача","ok":false,"why":"50 000 БҲМ Прил.2 да умуман йўқ — у Прил.1 п.2(а) да иш лойиҳаси (рабочий проект) ва Шаҳарсозлик ҳужжатлари экспертизаси маркази контекстида учрайди; бу ерда юқори чегара 25 000 БҲМ."}],"exp":"Прил.2 п.3 нинг охирги хатбошиси ихтиёрий (добровольная договорная основа) зонани очади: 5 000–25 000 БҲМ, бюджет буюртмачилари учун 5 000–6 000 БҲМ. Бунда экспертиза ҳақи ТЗ экспертизаси учун белгиланган ставка бўйича, молиялаштириш манбаидан қатъи назар ҳисобланади — яъни манбанинг бюджет эканлиги ҳақ ҳисоблашга таъсир қилмайди.","tags":["ixtiyoriy","chegara","to'lov"]},{"id":"pp-a-07","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.2, п.4","difficulty":2,"q":"Бино-иншоот ва муҳандислик коммуникацияларини капитал қуриш ҳамда таъмирлаш бўйича қиймати 25 000 БҲМ дан ошадиган харид ҳужжатлари Марказга қандай киритилади?","options":[{"t":"Фақат тендер ҳужжатлари кўринишида; ПСД талаб қилинмайди","ok":false,"why":"п.4 айнан ТЗ шаклини ва ПСД ни биргаликда талаб қилади."},{"t":"Техник топшириқ кўринишида, лекин экспертиза тўлиқ ҳажмда — п.5 нинг барча йўналишлари бўйича","ok":false,"why":"п.4 экспертиза доирасини атайлаб торайтиради: ҳажм ва нарх параметрлари асосланганлиги."},{"t":"Шартнома лойиҳаси билан бирга, Прил.3 тартибида","ok":false,"why":"Прил.3 — шартнома/импорт контракти учун; капитал қурилиш ТЗ си Прил.2 п.4 да."},{"t":"Техник топшириқ кўринишида, лойиҳа-смета ҳужжатлари (ПСД) билан бирга; экспертиза товарлар (ишлар, хизматлар) ҳажми ва уларнинг нарх параметрлари асосланганлиги қисмида ўтказилади","ok":true,"why":"Прил.2 п.4 нинг сўзма-сўз мазмуни: «вносится в Центр в виде технического задания вместе с проектно-сметной документацией… в части обоснованности объемов товаров (работ, услуг) и их ценовых параметров»."}],"exp":"Прил.2 п.4 (ПҚ-104, 13.03.2026 таҳрири) капитал қурилиш ва таъмирлаш учун махсус режим ўрнатади: банд энди суммавий чегарани ҳам ўз ичига олади — қиймат 25 000 БҲМ дан ошса, ҳужжат ТЗ шаклида, ПСД билан бирга киритилади, экспертиза эса товарлар (ишлар, хизматлар) ҳажми ва уларнинг нарх параметрлари асосланганлиги билан чекланади. Бунга боғлиқ ҳолда п.20 га кўра ҳақ манзилли рўйхат (адресный перечень) тасдиқлангандан кейин тўланади.","tags":["kapital qurilish","PSD","doira"]},{"id":"pp-a-08","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.2, п.5","difficulty":2,"q":"ПП-332 Прил.2 п.5 га кўра тендер ҳужжатлари ёки ТЗ экспертизасининг предметига қуйидагилардан қайси бири КИРАДИ?","options":[{"t":"Тендер ғолибини аниқлаш ва натижаларни тасдиқлаш","ok":false,"why":"Ғолибни харид комиссияси аниқлайди (п.2 таърифи); Марказ ғолибни аниқламайди."},{"t":"Иштирокчиларнинг тендер таклифларини баҳолаш ва рейтинглаш","ok":false,"why":"Марказ конкрет таклифларни баҳоламайди — у баҳолаш МЕЗОНЛАРИНИНГ объективлиги ва асосланганлигини текширади."},{"t":"Имзоланган шартномани рўйхатдан ўтказиш ва идентификацион рақам бериш","ok":false,"why":"Бу Прил.3 (шартнома/импорт контракти) функцияси, Прил.2 предметига кирмайди."},{"t":"Стартовая цена нинг ўртача бозор конъюнктурасига мослиги","ok":true,"why":"п.5 да «соответствия стартовой цены среднерыночной конъюнктуре» экспертиза предметларидан бири сифатида санаб ўтилган."}],"exp":"Прил.2 п.5 экспертиза предметларини етти йўналишда белгилайди: ушбу Низом талабларига мослик; харид асосланганлиги; ягона терминология; иштирокчиларга қонунчилик талаблари; баҳолаш мезонларининг объективлиги; стартовая цена нинг бозор конъюнктурасига мослиги; такрорий киритишда олдинги рад сабабларининг бартараф этилиши. Шу боис Марказ таклифларни эмас, ҲУЖЖАТНИ текширади.","tags":["mezon","narx","predmet"]},{"id":"pp-a-09","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.2, п.6 ва п.7","difficulty":3,"q":"Қуйидаги ҳужжатлардан қайси бири ТЕНДЕР ҲУЖЖАТЛАРИ пакетида (п.6) талаб қилинади, лекин ТЗ пакетида (п.7) талаб қилинмайди?","options":[{"t":"Коммерция таклифлари, биржа котировкалари ва прайс-листлар","ok":false,"why":"Нарх асослари иккала пакетда ҳам — п.6 да ҳам, п.7 да ҳам мажбурий."},{"t":"Портал ва ОАВда эълон қилиш учун тендер ўтказиш ҳақидаги эълоннинг тўлиқ матни","ok":true,"why":"п.6 да «полный текст объявления о проведении тендера» бор, п.7 (ТЗ) рўйхатида бу ҳужжат умуман йўқ — тендерсиз харидда эълон бўлмайди."},{"t":"Ваколатли ташкилотларнинг хулосалари (қонунчиликда талаб қилинган ҳолларда)","ok":false,"why":"Бу банд п.6 ва п.7 да сўзма-сўз бир хил такрорланади."},{"t":"Харид зарурлигини лойиҳаолди/лойиҳа ҳужжатлари ва ишлаб чиқариш нормативлари асосида асословчи ҳужжатлар","ok":false,"why":"Бу ҳам иккала рўйхатнинг охирги банди сифатида такрорланади."}],"exp":"п.6 (тендер ҳужжатлари) ва п.7 (ТЗ) рўйхатлари деярли бир хил; асосий фарқ — тендер эълонининг тўлиқ матни фақат п.6 да. Ариза шакли ҳам фарқ қилади: тендер учун Прил.№ 3, ТЗ учун Прил.№ 4 шакли. Пакет тўлиқ бўлмаса — п.24 бўйича рад асоси пайдо бўлади.","tags":["paket","hujjat","farq"]},{"id":"pp-a-10","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.2, п.6 (нарх асослари банди)","difficulty":2,"q":"Нарх шакллантириш асоси бўлган коммерция таклифлари ва прайс-листлар Марказга қандай шаклда тақдим этилиши шарт?","options":[{"t":"Нотариал тасдиқланган нусхалар кўринишида","ok":false,"why":"Низом нотариал тасдиқни талаб қилмайди — буюртмачининг имзоси/муҳри ёки QR-код етарли."},{"t":"Фақат энг арзон таклиф — қолганлари шарт эмас","ok":false,"why":"Аксинча, барча тақдим этилган таклифлар солиштирма жадвалда кўрсатилиши керак; битта таклиф билан ўртача даража аниқланмайди."},{"t":"Солиштирма жадвал (сопоставительная таблица) кўринишида; ҳар бир таклифда юридик манзил ва контакт маълумотлари бўлиши, буюртмачининг имзоси ва муҳри ёки QR-код билан тасдиқланиши шарт","ok":true,"why":"п.6 нинг нарх асослари банди айнан шу уч талабни — солиштирма жадвал, юридик манзил/контакт, буюртмачи тасдиғини — бир вақтда белгилайди."},{"t":"Етказиб берувчилар уларни бевосита Марказга электрон почта орқали юборади","ok":false,"why":"Ҳужжатларни буюртмачи (заявитель) тақдим этади ва ўзи тасдиқлайди; етказиб берувчидан тўғридан-тўғри қабул қилиш тартиби йўқ."}],"exp":"Прил.2 п.6/п.7 нарх асосларига учта шакл талабини қўяди: солиштирма жадвал, ҳар бир таклифда юридик манзил ва контакт маълумотлари, буюртмачи имзоси ва муҳри (ёки QR-код). Шунингдек таклифлар тендер ҳужжатлари ишлаб чиқилаётган даврда амалда бўлиши керак. Шу талаблар бузилса — нарх асослаш ҳужжати ҳисобга олинмайди.","tags":["narx","KP","sopostavitelnaya"]},{"id":"pp-a-11","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.2, п.8, 1-хатбоши","difficulty":2,"q":"Ҳар бир тендер ҳужжати ёки техник топшириқ Марказга қандай ва қачон киритилади?","options":[{"t":"Закупочные процедуры амалга оширилгунга қадар, алоҳида-алоҳида аризалар билан","ok":true,"why":"Прил.2 п.8, 1-хатбоши: «вносятся в Центр до осуществления закупочных процедур путем представления отдельных заявлений»."},{"t":"Тендер эълон қилингандан кейин, битта умумий ариза билан","ok":false,"why":"Иккита хато: эълон фақат ижобий хулосадан кейин жойлаштирилади (п.22), ва ариза ҳар бир ҳужжат учун алоҳида бўлиши шарт."},{"t":"Шартнома имзолангандан кейин, ҳужжатлар пакети сифатида","ok":false,"why":"Экспертиза харид процедураларигача — олдиндан ўтказилади; имзоланган шартнома Прил.3 предмети."},{"t":"Битта ариза билан, лекин ҳар бир лот учун алоҳида нарх асоси илова қилинган ҳолда","ok":false,"why":"Нарх асоси ҳақиқатан ҳар лот бўйича керак, аммо п.8 АРИЗАнинг ўзи алоҳида бўлишини талаб қилади — чалғитувчи ярим ҳақиқат."}],"exp":"Прил.2 п.8 нинг 1-хатбошиси иккита қоидани бирлаштиради: экспертиза харид процедураларидан ОЛДИН ўтказилади ва ҳар бир ҳужжат алоҳида ариза орқали киритилади. Бу қоида бир аризада бир нечта ТЗ ни бирлаштиришга йўл қўймайди ва экспертиза ҳақини ҳар лот бўйича алоҳида ҳисоблашга имкон беради (Прил.4 п.6 — «от первоначальной суммы каждого лота»).","tags":["ariza","tartib","muddat"]},{"id":"pp-a-12","doc":"ПП-332","topic":"Tender","ref":"Прил.2, п.8, 2-хатбоши","difficulty":2,"q":"Тендернинг ҳар бир лоти ёки техник топшириқ қандай принцип бўйича шакллантирилади?","options":[{"t":"Битта етказиб берувчи таклиф эта оладиган товарлар мажмуи бўйича","ok":false,"why":"Бу принцип аксинча иштирокчилар доирасини сунъий торайтиради ва п.12 нинг «ограничение количества участников» тақиғига зид."},{"t":"Битта молиялаштириш манбаи бўйича","ok":false,"why":"Молиялаштириш манбаи ариза шаклида кўрсатилади, лекин лот шакллантириш мезони эмас."},{"t":"Битта буюртмачи бўлинмаси эҳтиёжи бўйича","ok":false,"why":"Низом ташкилий тузилмани эмас, ТОВАР ТУРИНИ мезон қилиб олади."},{"t":"Битта товар туридан — фойдаланиш мақсадлари, функциялари ва техник хусусиятларига қараб","ok":true,"why":"п.8, 2-хатбоши: «каждый лот тендера или техническое задание формируются из одного вида товаров в зависимости от целей использования, функций и их технических особенностей»."}],"exp":"Прил.2 п.8 нинг 2-хатбошиси лотларга бўлиш талабини белгилайди: битта лот — битта товар тури. Амалиётда бу банд асосида сервер ва иш столи компьютери, аппарат ва дастурий таъминот, мебель ва компьютер техникаси алоҳида лотларга ажратилиши талаб қилинади. Аралаш лот — типик замечание асоси.","tags":["lot","mezon","замечание"]},{"id":"pp-a-13","doc":"ПП-332","topic":"Tender","ref":"Прил.2, п.9","difficulty":1,"q":"ПП-332 Прил.2 п.9 га кўра тендер ҳужжатлари қайси қисмлардан иборат бўлиши керак?","options":[{"t":"Ариза, техник топшириқ ва нарх ҳисоб-китоби — 3 та қисм","ok":false,"why":"Ариза — ҳужжатлар пакетининг элементи (п.6), тендер ҳужжатларининг таркибий қисми эмас."},{"t":"Тендер иштирокчиси учун йўриқнома (ИУТ), техник қисм, нарх қисми ва шартнома лойиҳаси — 4 та қисм","ok":true,"why":"п.9 айнан шу тўртта қисмни санаб ўтади."},{"t":"Техник қисм, нарх қисми ва баҳолаш мезонлари — 3 та қисм","ok":false,"why":"Баҳолаш мезонлари алоҳида қисм эмас — улар ИУТ таркибига киради (п.10)."},{"t":"ИУТ, техник қисм, нарх қисми, шартнома лойиҳаси ва Марказ хулосаси — 5 та қисм","ok":false,"why":"Марказ хулосаси экспертиза натижаси, тендер ҳужжатларининг қисми эмас."}],"exp":"Прил.2 п.9 тендер ҳужжатларининг тўртта мажбурий қисмини белгилайди: ИУТ (инструкция для участника тендера), техник қисм, нарх қисми ва шартнома лойиҳаси. Ҳар бир қисмга алоҳида банд қўйилган: ИУТ — п.10, техник қисм/ТЗ — п.11–13, нарх қисми — п.14, шартнома лойиҳаси — п.15.","tags":["tuzilma","tender"]},{"id":"pp-a-14","doc":"ПП-332","topic":"Tender","ref":"Прил.2, п.10","difficulty":2,"q":"Тендер иштирокчиси учун йўриқнома (ИУТ) таркибига қуйидагилардан қайси бири киради?","options":[{"t":"Товарнинг ишлаб чиқарилган йилига қўйиладиган талаб","ok":false,"why":"Бу п.11(а) — техник қисм/ТЗ талаби, ИУТ таркиби эмас."},{"t":"Стартовая цена ни ҳисоблаш ва молиялаштириш манбаини тасдиқловчи ҳужжатлар","ok":false,"why":"Бу п.14 — нарх қисми (ценовая часть) таркиби; ИУТ бу маълумотларни ўз ичига олмайди."},{"t":"Иштирокчилар томонидан коррупциявий ҳолатларга йўл қўймаслик тўғрисидаги аризани мажбурий тақдим этиш талаби","ok":true,"why":"п.10 да «требование об обязательном представлении заявления о недопущении коррупционных проявлений участниками тендера» бевосита ИУТ таркибида санаб ўтилган."},{"t":"Шартнома лойиҳасининг тўлиқ матни","ok":false,"why":"Шартнома лойиҳаси п.9 бўйича тендер ҳужжатларининг МУСТАҚИЛ тўртинчи қисми, ИУТ ичида эмас."}],"exp":"Прил.2 п.10 ИУТ нинг мажбурий мазмунини белгилайди: тендер шакли (очиқ/ёпиқ), ўтказиш манзили, таклифлар муддати, контакт шахслар, иштирокчиларга талаблар, коррупцияга қарши ариза талаби, олдиндан малака саралаш тартиби, таклифни расмийлаштириш, давлат тили талаби, техник ва нарх қисмларини баҳолаш тартиби, задаток, конфиденциаллик ҳамда баҳолаш мезонлари.","tags":["ИУТ","tarkib","korrupsiya"]},{"id":"pp-a-15","doc":"ПП-332","topic":"Texnik topshiriq","ref":"Прил.2, п.11(а)","difficulty":2,"q":"Товар харидига оид ТЗ да товарнинг янгилиги тўғрисида қандай кўрсатма бўлиши керак?","options":[{"t":"Товар янги, илгари фойдаланилмаган ва эксплуатация қилинмаган бўлиши — агар давлат хариди тавсифида бошқача назарда тутилмаган бўлса","ok":true,"why":"п.11(а): «товар должен быть новым, ранее не использованным, не эксплуатируемым, если иное не предусмотрено описанием государственной закупки»."},{"t":"Товар янги бўлиши шарт — ҳеч қандай истиснога йўл қўйилмайди","ok":false,"why":"Банд «если иное не предусмотрено описанием государственной закупки» деган истиснони сақлайди; мутлақ талаб эмас."},{"t":"Янгилик талаби фақат импорт товарларга нисбатан қўлланади","ok":false,"why":"Банд товарнинг келиб чиқишига боғлиқ эмас — барча товар харидларига тегишли."},{"t":"Янгилик талаби ТЗ да эмас, фақат шартнома лойиҳасида кўрсатилади","ok":false,"why":"Шартнома учун бу талаб Прил.3 п.13 да ҳам бор («как правило, товар должен быть новым и неиспользованным»), лекин ТЗ учун у айнан Прил.2 п.11(а) да мустақил равишда талаб қилинади."}],"exp":"Прил.2 п.11(а) товар харидида ТЗ нинг мажбурий маълумотларини санаб ўтади; улардан бири — товарнинг янги, илгари фойдаланилмаган ва эксплуатация қилинмаганлиги ҳақидаги кўрсатма, агар харид тавсифида бошқача назарда тутилмаган бўлса. Ушбу кўрсатманинг йўқлиги — стандарт замечание.","tags":["ТЗ","товар","yangilik"]},{"id":"pp-a-16","doc":"ПП-332","topic":"Texnik topshiriq","ref":"Прил.2, п.11(а)","difficulty":2,"q":"Товар харидига оид ТЗ нинг мажбурий маълумотлари рўйхатида қуйидагилардан қайси бири бор?","options":[{"t":"Етказиб берувчининг устав фонди ҳажми","ok":false,"why":"Устав фонди талаби п.11 да умуман йўқ; иштирокчиларга малака талаблари бошқа мантиқда — п.5 ва ИУТ (п.10) орқали қўйилади."},{"t":"Етказиб берувчининг сўнгги уч йиллик солиқ ҳисоботи","ok":false,"why":"Бундай ҳужжат Прил.2 нинг ҳеч бир бандида талаб қилинмайди."},{"t":"Интеллектуал мулк объектларига мутлақ ҳуқуқларни буюртмачига ўтказиш шартлари","ok":false,"why":"Муаллифлик ҳуқуқлари банди п.11(б) — ИШ ва ХИЗМАТ харидига оид рўйхатда; товар харидида эмас."},{"t":"Товарнинг ишлаб чиқарилган (чиқарилиш) йилига қўйиладиган талаблар","ok":true,"why":"п.11(а) нинг сўнгги банди: «требования к году производства/выпуска товаров»."}],"exp":"Прил.2 п.11(а) товар харидида ТЗ нинг мажбурий майдонларини беради: товар тавсифи, харид мақсади, лойиҳа асоси, суғурта, техник хусусиятлар, маркировка ва қадоқлаш, янгилик, комплектация, хизмат кўрсатиш, эҳтиёт қисмлар, техник регламентга мослик, миқдор ва етказиб бериш жойи, шефмонтаж, ходимларни ўқитиш, товар билан бериладиган ҳужжатлар, кафолатли ва постгарантия хизмати, яроқлилик муддати ва ишлаб чиқарилган йил.","tags":["ТЗ","majburiy maydon","товар"]},{"id":"pp-a-17","doc":"ПП-332","topic":"Texnik topshiriq","ref":"Прил.2, п.11(б)","difficulty":2,"q":"Иш ва хизмат харидига оид ТЗ да интеллектуал мулк масаласи қандай ҳал этилиши керак?","options":[{"t":"Мутлақ ҳуқуқлар ижрочида қолади, буюртмачига оддий (неисключительная) лицензия берилади","ok":false,"why":"Банд аксини талаб қилади — мутлақ ҳуқуқлар айнан буюртмачига ўтказилиши шарт."},{"t":"Ижро жараёнида юзага келган интеллектуал мулк объектларига мутлақ ҳуқуқларни давлат буюртмачисига ўтказиш шартлари кўрсатилиши шарт","ok":true,"why":"п.11(б): «авторские права с указанием условий о передаче государственному заказчику исключительных прав на объекты интеллектуальной собственности»."},{"t":"Муаллифлик ҳуқуқлари ТЗ да эмас, фақат шартнома лойиҳасида кўрсатилади","ok":false,"why":"п.11(б) бу шартларни айнан ТЗ/техник қисм мазмунига киритади."},{"t":"Ҳуқуқлар тарафлар ўртасида тенг улушда бўлинади","ok":false,"why":"Улушли бўлиниш ҳақида Низомда ҳеч қандай кўрсатма йўқ."}],"exp":"Прил.2 п.11(б) иш/хизмат харидида ТЗ нинг мажбурий майдонларидан бири сифатида муаллифлик ҳуқуқларини киритади: ижро натижасида юзага келган ИМ объектларига мутлақ ҳуқуқлар давлат буюртмачисига ўтказилиши шартлари кўрсатилади. Дастурий таъминот ва АТ ишланмалари харидида бу банднинг йўқлиги — доимий замечание.","tags":["ТЗ","muallifllik","xizmat"]},{"id":"pp-a-18","doc":"ПП-332","topic":"Texnik topshiriq","ref":"Прил.2, п.12 (1-шарт)","difficulty":2,"q":"Тендер ҳужжатлари ёки ТЗ да товар (иш, хизмат)га қўйиладиган талаблар қандай ифодаланиши керак?","options":[{"t":"Фақат матнли тавсиф кўринишида, рақамсиз","ok":false,"why":"Тўғридан-тўғри аксинча: банд рақамли қийматларни ва муқобилсиз кўрсаткичларни талаб қилади."},{"t":"Фақат ишлаб чиқарувчининг расмий техник паспортидан кўчириб","ok":false,"why":"Ишлаб чиқарувчи ҳужжатидан кўчириш кўпинча брендга боғланишга олиб келади ва п.12 нинг охирги хатбошисига зид."},{"t":"Ўлчанадиган бўлиши ва рақамли қийматларда ва/ёки муқобилсиз кўрсаткичлар шаклида (ҳа/йўқ, мавжуд/мавжуд эмас, дан/гача) ифодаланиши керак","ok":true,"why":"п.12 нинг биринчи шарти: «должны быть измеряемыми и выражаться в числовых значениях и/или в форме безальтернативных показателей (да/нет, наличие/отсутствие, от/до)»."},{"t":"Ўртача бозор кўрсаткичларидан 10 фоиз оралиқда белгиланиши керак","ok":false,"why":"10 фоиз оралиқ қоидаси Низомда йўқ; фоиз оралиғи техник эмас, нарх мезони билан чалғитади."}],"exp":"Прил.2 п.12 нинг биринчи шарти техник талабларнинг ўлчанувчанлигини талаб қилади: рақамли қиймат ёки муқобилсиз кўрсаткич (ҳа/йўқ, мавжуд/мавжуд эмас, дан/гача). Истисно — талабларни бир хилда шакллантириш ва тавсифлаш имконсиз бўлган товар (иш, хизмат) харидлари. «Юқори унумдорлик», «замонавий» каби баҳоловчи иборалар шу банд бўйича замечание тушади.","tags":["o'lchanuvchi","texnik talab","§12"]},{"id":"pp-a-19","doc":"ПП-332","topic":"Texnik topshiriq","ref":"Прил.2, п.12 (2-шарт)","difficulty":1,"q":"ПП-332 Прил.2 п.12 га кўра товар (иш, хизмат)га қўйиладиган талаблар қандай оқибатга олиб келмаслиги керак?","options":[{"t":"Харид муддатининг 30 календарь кундан ошиб кетишига","ok":false,"why":"Икки томонлама чалғитувчи вариант: биринчидан, экспертиза муддати талаблар мазмунига умуман алоқадор эмас; иккинчидан, 30 календарь кун — УП-259 (26.12.2025) билан БЕКОР ҚИЛИНГАН эски п.21 муддати. Ҳозирги п.21 да энг узун муддат 25 календарь кун."},{"t":"Лот суммасининг 6 000 БҲМ дан ошиб кетишига","ok":false,"why":"6 000 БҲМ — п.3(а) даги бюджет буюртмачиси учун экспертиза чегараси (пастки чегара), техник талаблар билан боғлиқ эмас."},{"t":"Давлат хариди иштирокчилари сонининг асоссиз чекланишига","ok":true,"why":"п.12 нинг иккинчи шарти: «не должны приводить к необоснованному ограничению количества участников государственной закупки»."},{"t":"Шартнома лойиҳасининг халқаро тижорат ҳуқуқига зид бўлишига","ok":false,"why":"Бу п.15 нинг предмети (шартнома лойиҳаси), п.12 эса техник талаблар ҳақида."}],"exp":"Прил.2 п.12 нинг иккинчи шарти — рақобатни ҳимоя қилувчи асосий норма: талаблар иштирокчилар сонининг АСОССИЗ чекланишига олиб келмаслиги керак. «Бозорда камида 10 йил», конкрет CPU/RAM комбинацияси, ягона вендор сертификати каби шартлар шу банд бўйича замечание олади.","tags":["raqobat","cheklov","§12"]},{"id":"pp-a-20","doc":"ПП-332","topic":"Texnik topshiriq","ref":"Прил.2, п.12 (охирги хатбоши)","difficulty":3,"q":"Давлат хариди объекти тавсифига конкрет товар белгиси, патент, конструкция ёки модель, келиб чиқиш манбаи ёхуд ишлаб чиқарувчига оид ҳавола киритилиши мумкинми?","options":[{"t":"Ҳа, буюртмачи ички зарурат билан асослаган ҳар қандай ҳолда","ok":false,"why":"Ички зарурат етарли асос эмас — Низом икки шартни бир вақтда талаб қилади."},{"t":"Йўқ, ҳеч қандай ҳолатда — бу мутлақ тақиқ","ok":false,"why":"Тақиқ мутлақ эмас: п.12 нинг ўзи «за исключением случаев…» истиснони назарда тутади."},{"t":"Ҳа, лекин фақат импорт товарлар харидида","ok":false,"why":"Товарнинг импорт ёки маҳаллийлиги банд мезони эмас; чалғитувчи белги."},{"t":"Йўқ, фақат икки шарт бир вақтда бажарилганда мумкин: хусусиятларни етарлича аниқ тавсифлашнинг бошқа усули бўлмаса ВА бошқа ишлаб чиқарувчининг эквивалент товари билан алмаштириш имконияти ҳақида изоҳ киритилса","ok":true,"why":"п.12 нинг охирги хатбошиси айнан шу икки шартли истисно конструкциясини беради."}],"exp":"Прил.2 п.12 нинг охирги хатбошиси — Марказ амалиётида энг кўп ишлатиладиган норма. Умумий қоида — тақиқ; истисно эса икки шартли: (1) бошқа етарлича аниқ тавсифлаш усули йўқлиги ва (2) эквивалент товар билан алмаштириш имконияти ҳақидаги изоҳ. «Ёки эквивалент» изоҳисиз бренд номи кўрсатилса — замечание.","tags":["brend","ekvivalent","§12"]},{"id":"pp-a-21","doc":"ПП-332","topic":"Texnik topshiriq","ref":"Прил.2, п.13","difficulty":2,"q":"Агар ТЗ ёки техник қисмда товар белгиси, хизмат кўрсатиш белгиси, патент, фойдали модель ёки ишлаб чиқарувчи номи кўрсатилган бўлса, буюртмачи қўшимча равишда нима тақдим этиши шарт?","options":[{"t":"Ишлаб чиқарувчининг Ўзбекистондаги расмий дилери билан тузилган шартнома нусхасини","ok":false,"why":"Дилерлик шартномаси Прил.2 нинг ҳеч бир бандида талаб қилинмайди; дилер прайс-листи фақат нарх асоси сифатида (п.14) эсланади."},{"t":"Шундай кўрсатмаларни асословчи қўшимча ахборотни, шу жумладан техник қисмда ёки ТЗ да эквивалент товар (иш, хизмат) етказиб бериш имконияти мавжудлигини","ok":true,"why":"п.13: «должна быть представлена дополнительная информация, обосновывающая эти указания, в том числе наличие… возможности поставки эквивалента товаров (работ, услуг)»."},{"t":"Рақобатчи ишлаб чиқарувчиларнинг рад этиш хатларини","ok":false,"why":"Рад хатлари — прямой контракт (ЗРУ-684 ст.71) асосини исботлаш амалиёти, п.13 талаби эмас."},{"t":"Кибербавфсизлик соҳасидаги ваколатли органнинг хулосасини","ok":false,"why":"Ваколатли ташкилот хулосаси п.6/п.7 бўйича фақат қонунчилик талаб қилган ҳолларда керак, товар белгиси кўрсатилиши билан боғлиқ эмас."}],"exp":"Прил.2 п.13 п.12 нинг истиснога процедуравий юк қўшади: товар белгиси кўрсатилса, буни асословчи қўшимча ахборот ва эквивалент етказиб бериш имконияти ҳужжатда бўлиши шарт. Шунингдек п.13 нинг 2-хатбошиси инвестиция лойиҳалари ва капитал қурилиш харидларида техник қисм тасдиқланган лойиҳаолди/лойиҳа ҳужжатлари параметрларига мос келишини талаб қилади.","tags":["brend","asoslash","ekvivalent"]},{"id":"pp-a-22","doc":"ПП-332","topic":"Tender","ref":"Прил.2, п.14","difficulty":2,"q":"Тендер ҳужжатларининг нарх қисми (ценовая часть) таркибига қуйидагилардан қайси бири киради?","options":[{"t":"Ғолиб иштирокчининг банк кафолати","ok":false,"why":"Таклифни таъминлаш (задаток/кафолат) шартлари ИУТ да (п.10) кўрсатилади ва ғолиб экспертизадан кейин аниқланади."},{"t":"Иштирокчиларнинг лицензия ва малака ҳужжатлари","ok":false,"why":"Иштирокчиларга талаблар ИУТ (п.10) ва п.5 предмети орқали текширилади, нарх қисми таркибига кирмайди."},{"t":"Бўлажак давлат харидини молиялаштириш манбалари мавжудлиги ва ҳажмини тасдиқловчи ҳужжатлар (кредит шартномаси, банк маълумотномаси, қурилиш манзилли рўйхати, давлат бошқаруви органи қарори ва бошқалар)","ok":true,"why":"п.14 нинг 4-банди айнан шу ҳужжатларни нарх қисми таркибига киритади."},{"t":"Интеллектуал мулк объектларига ҳуқуқларни ўтказиш шартлари","ok":false,"why":"Бу п.11(б) — иш/хизмат бўйича техник қисм талаби, нарх қисми эмас."}],"exp":"Прил.2 п.14 нарх қисмининг тўртта элементини белгилайди: етказиб бериш шартлари; тўлов шартлари ва графиги; биржа котировкалари, КП ва завод-ишлаб чиқарувчилар (ёки уларнинг расмий дилерлари) прайс-листлари асосида ҳисобланган стартовая цена; молиялаштириш манбалари ва ҳажмини тасдиқловчи ҳужжатлар. Манба тасдиғи йўқлиги — тез-тез учрайдиган комплектлик камчилиги.","tags":["narx qismi","moliya manbai"]},{"id":"pp-a-23","doc":"ПП-332","topic":"Tender","ref":"Прил.2, п.14 (охирги хатбошилар)","difficulty":3,"q":"Буюртмачи танлови бўйича давлат хариди учта ва ундан ортиқ МАҲАЛЛИЙ ишлаб чиқарувчилар ўртасида ўтказилаётган бўлса, нарх қисми экспертизаси қандай ўтказилади?","options":[{"t":"Халқаро биржа котировкалари асосида, чунки улар объективроқ","ok":false,"why":"Бу ҳолда айнан ички бозор маълумотлари асос қилиб олинади, халқаро котировкалар эмас."},{"t":"Экспертиза умуман ўтказилмайди — маҳаллийлаштириш имтиёзи қўлланади","ok":false,"why":"Ҳеч қандай имтиёз нарх экспертизасидан озод қилмайди; фақат маълумот манбаи ўзгаради."},{"t":"Маҳаллий ишлаб чиқарувчилар бозори конъюнктураси ва улардан (ёки расмий дилерларидан) бевосита олинган маълумот асосида, шунингдек иштирокчи-ишлаб чиқарувчиларда ишлаб чиқариш қувватлари мавжудлигини текшириш билан","ok":true,"why":"п.14 нинг охирги хатбошиси айнан шу уч элементни — ички бозор конъюнктураси, бевосита маълумот, қувватларнинг ишончлилигини текшириш — талаб қилади."},{"t":"Ўхшаш импорт контрактлари бўйича маълумотлар асосида","ok":false,"why":"Импорт контрактлари маълумоти — умумий ҳолатдаги манбалардан бири (п.14 нинг олдинги хатбошиси), 3+ маҳаллий ишлаб чиқарувчи режимида эмас."}],"exp":"Прил.2 п.14 маҳаллий ишлаб чиқарувчилар ўртасидаги харид учун махсус режим ўрнатади: нарх экспертизаси ички бозор маълумотларига таянади ва иштирокчиларнинг ишлаб чиқариш қувватлари текширилади. Бунда буюртмачи АРИЗАДА харид учта ва ундан ортиқ маҳаллий ишлаб чиқарувчи ўртасида ўтказилишини кўрсатиши ҳамда шуни тасдиқловчи маълумотларни тақдим этиши шарт.","tags":["mahalliy","narx","ariza"]},{"id":"pp-a-24","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.2, п.16","difficulty":1,"q":"Экспертизага тақдим этилган тендер ҳужжатлари ва техник топшириқнинг тўлиқлиги ва ишончлилиги учун ким жавобгар?","options":[{"t":"Марказ — экспертиза ўтказувчи ташкилот сифатида","ok":false,"why":"Марказ ҳужжат мазмунини баҳолайди, лекин унинг тўлиқлиги ва ишончлилиги учун жавобгар эмас; жавобгарлик буюртмачида."},{"t":"Электрон давлат харидлари тизими оператори","ok":false,"why":"Оператор закупочные процедуры бўйича хизмат кўрсатади (п.2 таърифи), ҳужжат мазмуни учун жавоб бермайди."},{"t":"Закупочная комиссия","ok":false,"why":"Закупочная комиссия ғолибни танлаш бўйича қарор қабул қилади (п.2 таърифи), ҳужжат ишончлилиги учун эмас."},{"t":"Давлат буюртмачиси","ok":true,"why":"п.16: «Ответственность за полноту и достоверность представленной на экспертизу тендерной документации и технического задания несет государственный заказчик»."}],"exp":"Прил.2 п.16 — Марказ хулосаларининг стандарт якуний параграфи асоси: тақдим этилган ҳужжатларнинг тўлиқлиги ва ишончлилиги учун давлат буюртмачиси жавобгар. Бу норма Марказ жавобгарлик чегарасини белгилайди ва ҳар бир Заключение якунида сўзма-сўз келтирилади.","tags":["javobgarlik","buyurtmachi","§16"]},{"id":"pp-a-25","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.2, п.18","difficulty":2,"q":"Замечаниялар билан қайтарилган тендер ҳужжатлари ёки ТЗ такроран киритилса, экспертиза ҳақи қандай ундирилади?","options":[{"t":"Рад этилгандан кейин олти ой ичида такроран киритилса — ҳақ ундирилмайди","ok":true,"why":"п.18: «При внесении… повторно в течение шести месяцев после отказа… плата не взимается»."},{"t":"Ҳар қандай такрорий киритишда ҳақнинг 50 фоизи ундирилади","ok":false,"why":"50 фоиз коэффициенти — Прил.4 п.2 даги ТЭР экспертизаси нархи учун (Ктэр = 0,5), такрорий экспертиза учун эмас."},{"t":"Уч ой ичида такроран киритилса ҳақ ундирилмайди","ok":false,"why":"Қўшни муддат: Низомда 3 ой эмас, 6 ой белгиланган."},{"t":"Такрорий киритишда ҳақ ҳар доим тўлиқ ҳажмда қайта ундирилади","ok":false,"why":"Бу қоида фақат 6 ой ўтгандан кейин амал қилади (п.19), 6 ой ичида эмас."}],"exp":"Прил.2 п.18 такрорий экспертизани 6 ой ичида бепул қилади. Муҳим процедуравий шарт: аризада ҳужжат олдинги рад (замечаниялар билан қайтариш)дан кейин 6 ой ичида ТАКРОРАН киритилаётгани кўрсатилиши шарт. Бу кўрсатма бўлмаса — ариза янги ҳужжат сифатида қабул қилиниши мумкин.","tags":["to'lov","takroriy","6 oy"]},{"id":"pp-a-26","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.2, п.19","difficulty":2,"q":"Дастлабки эътирозлар (замечаниялар) билан хулоса берилган кундан бошлаб олти ойлик муддат ўтгач киритилган тендер ҳужжатлари ёки ТЗ қандай кўриб чиқилади?","options":[{"t":"Такрорий кўриб чиқиш сифатида — 10 календарь кун ичида ва бепул","ok":false,"why":"10 календарь кун (п.27) ва бепуллик (п.18) режими фақат 6 ой ИЧИДАГИ такрорий киритишга тегишли; 6 ой ўтгач бу имтиёзлар йўқолади."},{"t":"Умуман қабул қилинмайди — буюртмачи харид предметини ўзгартириши шарт","ok":false,"why":"Низом қабул қилишни тақиқламайди, фақат мақомини ўзгартиради."},{"t":"Марказ раҳбарияти рухсати билан истисно тартибида кўрилади","ok":false,"why":"Бундай истисно тартиби Прил.2 да умуман назарда тутилмаган."},{"t":"ЯНГИ ҳужжат сифатида кўриб чиқилади","ok":true,"why":"п.19: «По истечении шестимесячного срока… подлежат рассмотрению в качестве нового документа». Шунга мос равишда тўлиқ муддат ва тўлиқ ҳақ қўлланади."}],"exp":"Прил.2 п.19 экспертиза хулосасининг амалий «яроқлилик» чегарасини белгилайди: замечаниялар билан хулоса берилган кундан 6 ой ўтса, қайта киритилган ҳужжат янги ҳужжат ҳисобланади — яъни п.21 бўйича тўлиқ муддат (УП-259 таҳририда харид тоифаси ва позициялар сонига қараб 10 дан 25 календарь кунгача) ва тўлиқ ҳақ қўлланади. Прил.2 нинг иккала схемасидаги 7-босқич изоҳи ҳам шуни такрорлайди: «При повторном внесении по истечении 6 месяцев… считается новой документацией».","tags":["6 oy","amal muddati","takroriy"]},{"id":"pp-a-27","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.2, п.21(б)","difficulty":3,"q":"УП-259 (26.12.2025) таҳриридаги Прил.2 п.21 га кўра, «мураккаб харидлар» (сложные закупки — 100 000 БҲМ ва ундан юқори) бўйича, позициялар сони 1 дан 20 гача бўлганда ТЕХНИК ТОПШИРИҚ экспертизаси муддати қанча?","options":[{"t":"20 календарь кун","ok":false,"why":"Икки томонлама тузоқ: 20 календарь кун — айнан шу тоифадаги ТЕНДЕР ҲУЖЖАТЛАРИ муддати (п.21«а») ҳамда «ўрта харидлар»да 21+ позиция муддати; шунингдек бу — ТЗ учун эски (УП-259 гача) ягона муддат эди."},{"t":"18 календарь кун","ok":true,"why":"п.21«б»: «для «сложных закупок» стоимостью 100 000 БРВ и более… от 1 до 20 — срок экспертизы до 18 календарных дней». Бу — жадвалдаги ягона асимметрия: ТЗ учун тендер ҳужжатларидан 2 кун қисқа."},{"t":"30 календарь кун","ok":false,"why":"30 календарь кун — УП-259 билан БЕКОР ҚИЛИНГАН эски п.21 даги тендер ҳужжатлари муддати. Ҳозирги таҳрирда 30 кунлик муддат умуман йўқ — энг узоғи 25 кун."},{"t":"25 календарь кун","ok":false,"why":"25 календарь кун — шу «мураккаб харидлар» тоифасида, лекин позициялар сони 21 ва ундан ортиқ бўлганда."}],"exp":"УП-259 (26.12.2025) п.21 ни бутунлай қайта ёзди: муддат энди ягона эмас, харид ТОИФАСИ (сумма) ва ПОЗИЦИЯЛАР СОНИга боғлиқ. «Малые закупки» 6 000–25 000 БҲМ: 1–20 поз. — 10 кун, 21+ — 15 кун. «Средние закупки» 25 000–100 000 БҲМ: 1–20 — 15 кун, 21+ — 20 кун. «Сложные закупки» 100 000 БҲМ ва ундан юқори: тендер ҳужжатлари учун 1–20 — 20 кун, 21+ — 25 кун; ТЗ учун 1–20 — 18 кун, 21+ — 25 кун. Ҳисоб п.6/п.7 даги ҳужжатлар тақдим этилиши ва хизмат ҳақи тўланиши кунидан бошланади, хулоса QR-код билан тасдиқланади. Шунингдек п.21 га янги хатбоши қўшилди: тендер ҳужжатлари хулосаси билан бирга Марказ бозор нархлари ҳақидаги маълумот нусхаларини (коммерческие предложения, биржевые цены, интернет ва СУНЪИЙ ИНТЕЛЛЕКТ маълумотлари) ҳам тақдим этади.","tags":["muddat","kalendar kun","УП-259"]},{"id":"pp-a-28","doc":"ПП-332","topic":"Tender","ref":"Прил.2, п.22","difficulty":1,"q":"Тендер ўтказиш ҳақидаги эълон махсус ахборот порталига қачон жойлаштирилади?","options":[{"t":"Ариза Марказга киритилган кундан кейин — экспертиза натижасини кутмасдан","ok":false,"why":"п.22 экспертиза натижасини кутишни шарт қилади; ариза киритиш ўзи асос эмас."},{"t":"Ҳужжатлар тўлиқлиги текширилиб, тўлов амалга оширилгандан кейин","ok":false,"why":"Бу схеманинг 2- ва 3-босқичлари; улардан кейин ҳали 4-босқич — экспертизанинг ўзи бор."},{"t":"Шартнома имзолангандан кейин","ok":false,"why":"Эълон харид процедурасини бошлайди — шартнома эса унинг натижаси; изчиллик тескари."},{"t":"Марказнинг ижобий хулосаси олингандан кейин","ok":true,"why":"п.22: «Объявление о проведении тендера размещается на портале после получения положительного заключения Центра»."}],"exp":"Прил.2 п.22 экспертизани харид процедурасининг олдинги шарти қилиб қўяди: эълон фақат Марказнинг ижобий хулосасидан кейин порталга жойлаштирилади. Бу п.8 нинг «до осуществления закупочных процедур» қоидаси билан бир бутунни ташкил этади; п.21 га кўра ижобий хулоса порталга автоматик равишда йўналтирилади.","tags":["e'lon","portal","izchillik"]},{"id":"pp-a-29","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.2, п.24","difficulty":3,"q":"Қуйидагилардан қайси бири Прил.2 п.24 бўйича ижобий хулоса беришни рад этиш асоси ҳисобланади?","options":[{"t":"Ариза берилган пайтдаги ўхшаш хусусият ва сифатли товарлар бўйича ўртача нарх ва шаклланган бозор конъюнктурасига нисбатан стартовая цена нинг ошириб юборилиши","ok":true,"why":"п.24 нинг 4-банди айнан шу асосни беради."},{"t":"Импорт контракт бўйича тўловнинг офшор зонада рўйхатдан ўтган норезидент фойдасига амалга оширилиши","ok":false,"why":"Бу Прил.3 п.36 (шартнома/импорт контракти) рад асоси; Прил.2 п.24 рўйхатида йўқ — қўшни илова билан чалғитиш."},{"t":"Закупочные процедуры ни амалга ошириш тартибининг бузилиши","ok":false,"why":"Бу ҳам Прил.3 п.36 асоси; Прил.2 экспертизаси ҳужжатларни процедуралардан ОЛДИН кўради."},{"t":"Буюртмачида бюджет олдида қарздорлик мавжудлиги","ok":false,"why":"Қарздорлик Прил.2 нинг ҳеч бир бандида рад асоси сифатида кўрсатилмаган."}],"exp":"Прил.2 п.24 тўртта рад асосини беради: ҳужжатларнинг тўлиқ ҳажмда тақдим этилмаганлиги; ишончсиз ёки бузиб кўрсатилган маълумотлар мавжудлиги; тақдим этилган ҳужжатларнинг ушбу Низом ва бошқа қонунчилик ҳужжатларига номувофиқлиги; стартовая цена нинг ўртача нарх ва бозор конъюнктурасидан ошиб кетиши. Офшор ва процедура бузилиши асослари эса Прил.3 п.36 да.","tags":["возврат","rad asosi","narx"]},{"id":"pp-a-30","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.2, п.27","difficulty":2,"q":"Буюртмачи рад асосларини бартараф этгач, Марказ такрорий кўриб чиқишни ва хулоса беришни қайси муддатда амалга оширади?","options":[{"t":"5 иш кунидан кўп бўлмаган муддатда","ok":false,"why":"5 иш куни — Прил.3 п.40 даги шартнома/импорт контракти бўйича такрорий экспертиза муддати; Прил.2 га тегишли эмас."},{"t":"20 календарь кундан кўп бўлмаган муддатда","ok":false,"why":"20 календарь кун — п.21 даги БИРИНЧИ экспертиза муддатларидан бири («ўрта харидлар»да 21+ позиция ёки «мураккаб харидлар»да 1–20 позицияли тендер ҳужжатлари), такрорий кўриб чиқиш муддати эмас."},{"t":"10 календарь кундан кўп бўлмаган муддатда","ok":true,"why":"п.27: «в срок, не более десяти календарных дней со дня получения доработанной тендерной документации или технического задания»."},{"t":"10 иш кунидан кўп бўлмаган муддатда","ok":false,"why":"Рақам тўғри, лекин турда хато: Прил.2 п.27 да календарь кун."}],"exp":"Прил.2 п.27 такрорий кўриб чиқиш муддатини 10 календарь кун қилиб белгилайди — ҳисоб қайта ишланган ҳужжатлар ва рад сабабларининг бартараф этилганини тасдиқловчи ҳужжатлар олинган кундан бошланади. Шу муддат ичида Марказ ижобий хулоса ёки такроран рад беради. Прил.2 нинг 1- ва 2-схемаларида бу 8-босқич — у ерда ҳам «в течение 10 (десяти) календарных дней» деб такрорланган. Диққат: бу муддат УП-259 ислоҳотидан кейин ҳам ЎЗГАРМАДИ — фақат п.21 даги БИРИНЧИ экспертиза муддатлари қайта ёзилди.","tags":["takroriy","muddat","kalendar kun"]},{"id":"pp-a-31","doc":"ПП-332","topic":"Umumiy","ref":"Асосий қарор, п.2 (охирги хатбоши)","difficulty":3,"q":"ПП-332 нинг асосий қарори 2-бандига кўра норматив-ҳуқуқий ҳужжатларда нима қилиш тақиқланади?","options":[{"t":"Тендерсиз (тўғридан-тўғри музокаралар йўли билан) харид ўтказишга рухсат бериш","ok":false,"why":"Тендерсиз харид ҳуқуқи Президент/ВМ қарорлари билан берилиши Прил.2 п.3 да очиқ назарда тутилган — тақиқ бу эмас."},{"t":"Харид предметини лотларга бўлмасдан ягона лот сифатида шакллантириш","ok":false,"why":"Лот шакллантириш қоидаси Прил.2 п.8 да, асосий қарор 2-бандидаги тақиққа алоқаси йўқ."},{"t":"Марказ билан харид предметининг нарх шакллантириш ва (ёки) етказиб берувчини аниқлаш масалалари келишилмаган ҳолда конкрет етказиб берувчилар номини ва (ёки) товарлар (ишлар, хизматлар) қийматини кўрсатиш","ok":true,"why":"Асосий қарор п.2 нинг охирги хатбошиси айнан шу тақиқни ўрнатади."},{"t":"Чет эл ишлаб чиқарувчиларини давлат харидларига жалб қилиш","ok":false,"why":"Аксинча, ариза шакли «барча иштирокчилар (маҳаллий ва хорижий)» вариантини очиқ назарда тутади."}],"exp":"ПП-332 асосий қарорининг 2-банди Марказ ваколатларини санаб ўтгач, муҳим тақиқ билан якунланади: Марказ билан нарх шакллантириш ва/ёки етказиб берувчини аниқлаш масалалари келишилмаган ҳолда НҲҲ ларда конкрет етказиб берувчи номи ва/ёки товар қийматини кўрсатиш тақиқланади. Бу норма қарор лойиҳаларида «ижрочи — фалон корхона» деб ёзиб қўйишга қарши асосий ҳимоя.","tags":["taqiq","yetkazib beruvchi","narx"]},{"id":"pp-a-32","doc":"ПП-332","topic":"Ekspertiza","ref":"Прил.2, № 1-илова (схема), 2-босқич","difficulty":3,"q":"ПП-332 2-ilovasining sxemalariga ko'ra, Markaz taqdim etilgan hujjatlar to'liqligini o'rganib, ariza maqomini («Документы загружены не полностью», «Оплата ожидается», «На рассмотрении» yoki «Отклонено») o'zgartirish uchun qancha vaqtga ega?","options":[{"t":"25 календарь кун","ok":false,"why":"25 календарь кун — 2-ilovaning 1-ilovasidagi sxemaning 4-bosqichi, ya'ni тендер ҳужжатлари ekspertizasining o'zi uchun eng uzun muddat (УП-259 tahriridagi п.21(а) bo'yicha «сложные закупки», 21 va undan ortiq позиция). To'liqlikni tekshirish bosqichi bilan aloqasi yo'q."},{"t":"5 иш куни","ok":true,"why":"Har ikkala sxemada ham (тендер ҳужжатлари — 1-ilova, техник топшириқ — 2-ilova) 2-bosqich Марказ uchun «5 (беш) иш куни ичида» deb belgilangan; УП-259 tahriri bu muddatni o'zgartirmagan."},{"t":"3 иш куни","ok":false,"why":"3 иш куни — ПП-332 1-ilovasining 16-bandi: loyihaoldi hujjatlar to'liq emasligi (nomukammalligi) haqida tashabbuskorni yozma xabardor qilish muddati; 2-ilova sxemasining 2-bosqichiga taalluqli emas."},{"t":"10 календарь кун","ok":false,"why":"10 календарь кун — 8-bosqich, ya'ni замечания bartaraf etilgandan keyingi такрорий кўриб чиқиш muddati (п.27). УП-259 dan keyin bu raqam «малые закупки» (1—20 позиция) uchun ekspertizaning eng qisqa muddati sifatida ham uchraydi, lekin 2-bosqich muddati emas."}],"exp":"ПП-332 2-ilovasining sxemalari ekspertizani 8 bosqichga ajratadi: 1) ariza beruvchi paketni tayyorlaydi; 2) Марказ 5 иш куни ichida to'liqlikni tekshirib ariza maqomini «Новая заявка» dan o'zgartiradi; 3) ariza beruvchi 5 иш куни ichida to'laydi; 4) Марказ ekspertiza o'tkazadi; 5/6) ijobiy xulosa yoki замечания bilan xulosa; 7) ariza beruvchi 6 oy ichida qayta ishlaydi; 8) Марказ 10 календарь кун ichida такроран ko'rib chiqadi. Muhim: 4-bosqich muddati УП-259 (26.12.2025) tahriridan keyin o'zgargan — тендер ҳужжатлари sxemasida 25 календарь кунгача, техник топшириқ sxemasida esa «товар сони ва қийматидан келиб чиқиб 10 дан 25 календарь кунгача». Eski tahrirdagi «30 календарь кун — тендер, 20 — ТЗ» raqamlari endi amal qilmaydi; п.21 muddatni харид тоифаси (6 000—25 000 / 25 000—100 000 / 100 000 БҲМ va undan yuqori) va позиция soniga bog'laydi.","tags":["bosqich","muddat","ish kuni"]},{"id":"pq-x-01","doc":"ПҚ-104","topic":"Umumiy","ref":"ПҚ-104 п.1(в), п.1(г)","difficulty":2,"q":"ПҚ-104 ning 1-bandida belgilangan asosiy maqsadlarga ko'ra byudjet mablag'lari qancha tejaladi va ko'rib chiqishning umumiy davomiyligi qancha qisqaradi?","options":[{"t":"Byudjet mablag'lari o'rtacha 10—15 foizga tejaladi, davomiylik 20—25 foizga qisqaradi","ok":false,"why":"Ikkala raqam ham pasaytirilgan — qarorda 15—20 va 25—30 foiz ko'rsatilgan"},{"t":"Byudjet mablag'lari o'rtacha 15—20 foizga tejaladi, ko'rib chiqishning umumiy davomiyligi 25—30 foizga qisqaradi","ok":true,"why":"п.1(в) — «бюджет маблағларини ўртача 15—20 фоизга тежаш»; п.1(г) — «кўриб чиқишнинг умумий давомийлигини 25—30 фоизга қисқартириш»"},{"t":"Byudjet mablag'lari o'rtacha 25—30 foizga tejaladi, davomiylik 15—20 foizga qisqaradi","ok":false,"why":"Raqamlar o'zaro almashtirilgan: 25—30 muddat uchun, 15—20 esa tejash uchun"},{"t":"Byudjet mablag'lari o'rtacha 15—20 foizga tejaladi, davomiylik 30—40 foizga qisqaradi","ok":false,"why":"Tejash to'g'ri, lekin muddat qisqarishi 30—40 emas, 25—30 foiz"}],"exp":"ПҚ-104 п.1 qarorning to'rtta asosiy maqsadini belgilaydi. Ulardan ikkitasi raqamli: (в) loyihaoldi va xarid hujjatlari qiymatini bozor kon'yunkturasi asosida maqbullashtirish hisobiga byudjet mablag'larini o'rtacha 15—20 foizga tejash; (г) kompleks ekspertiza muddatlarini maqbullashtirish va ko'rib chiqishning umumiy davomiyligini 25—30 foizga qisqartirish. Attestatsiyada bu ikki raqam ko'pincha o'rin almashtirilib beriladi.","tags":["maqsad","foiz","muddat"]},{"id":"pq-x-02","doc":"ПҚ-104","topic":"Umumiy","ref":"ПҚ-104 п.2(а), п.2(б)","difficulty":1,"q":"ПҚ-104 ning 2-bandiga muvofiq kompleks ekspertiza sohasidagi vakolatli organ qanday qayta tashkil etildi?","options":[{"t":"«Лойиҳалар ва импорт контрактларини комплекс экспертиза қилиш маркази» «Лойиҳалар ва харидлар самарадорлигини ошириш маркази» ДМ etib qayta tashkil etildi va faoliyati «ёрдамчи-маслаҳатчи» tamoyili asosida ishlash tizimiga o'tkazildi","ok":true,"why":"п.2(а) — yangi nom; п.2(б) — «ёрдамчи-маслаҳатчи» tamoyili asosida ishlash tizimiga o'tkazish taklifiga rozilik berilgan. ПП-332 ning amaldagi tahririda ham hamma joyda «ГУ «Центр повышения эффективности проектов и закупок»» yozuvi turibdi"},{"t":"Markaz «Ўзбекэкспертиза» АЖ tarkibiga qo'shildi va uning filialiga aylantirildi","ok":false,"why":"«Ўзбекэкспертиза» АЖга faqat ayrim funksiyalar (bojxona imtiyozlari ro'yxati — п.5(д)) o'tkaziladi, Markaz unga qo'shilmaydi"},{"t":"Markaz «Шаҳарсозлик ҳужжатларини экспертиза қилиш республика маркази» ДМ etib qayta nomlandi","ok":false,"why":"Bu boshqa tashkilot — unga п.5(г) bo'yicha kapital qurilish hujjatlari ekspertizasi o'tkaziladi, Markaz qayta nomlanmaydi"},{"t":"Markaz nomi saqlanib qoldi, faqat faoliyati «назорат қилувчи орган» tamoyiliga o'tkazildi","ok":false,"why":"Aksincha — nom o'zgardi, tamoyil esa nazorat emas, «ёрдамчи-маслаҳатчи» (yordamchi-maslahatchi)"}],"exp":"ПҚ-104 п.2 Iqtisodiyot va moliya vazirligi hamda Sanoat kooperatsiyasi va davlat xaridlari agentligining ikki taklifiga rozilik beradi: (а) Markazni «Лойиҳалар ва харидлар самарадорлигини ошириш маркази» ДМ etib qayta tashkil etish; (б) uning faoliyatini hujjatlarni ishlab chiqish bosqichidayoq sifatli tayyorlashda «ёрдамчи-маслаҳатчи» tamoyili asosida ishlash tizimiga o'tkazish. Amaliy ma'nosi: xulosalar sarlavhasi va imzo bloki yangi nom bilan yoziladi.","tags":["Markaz","nom","tamoyil"]},{"id":"pq-x-03","doc":"ПҚ-104","topic":"Umumiy","ref":"ПҚ-104 п.3—4, 1-илова","difficulty":2,"q":"Loyihaoldi va xarid hujjatlariga doir muammoli masalalarni hal etish bo'yicha respublika komissiyasiga kim raislik qiladi?","options":[{"t":"Sanoat kooperatsiyasi va davlat xaridlari agentligi direktori Б.Х.Хайдаров","ok":false,"why":"U — Respublika komissiyasi raisining O'RINBOSARI, rais emas"},{"t":"Prezident maslahatchisi О.А.Хакимов","ok":false,"why":"U п.18 bo'yicha qaror ijrosini NAZORAT qiluvchi shaxs, komissiya raisi emas"},{"t":"O'zbekiston Respublikasi Bosh vaziri А.Н.Арипов","ok":true,"why":"п.4 komissiya vazifalarini «(А.Арипов)» ga yuklaydi; 1-ilovada u Respublika komissiyasi raisi sifatida ko'rsatilgan"},{"t":"«Лойиҳалар ва харидлар самарадорлигини ошириш маркази» ДМ direktori","ok":false,"why":"Markaz direktori — komissiyaning KOTIBI (lavozimi bo'yicha), raisi emas"}],"exp":"ПҚ-104 п.3 Vazirlar Mahkamasining Respublika komissiyasini tashkil etish taklifini ma'qullaydi, п.4 esa unga uchta vazifa yuklaydi: 1 mart 2026 gacha kiritilgan hujjatlar ko'rib chiqilishini jadallashtirish, Markaz va buyurtmachi o'rtasidagi munozarali holatlarda maqbul yechim topishga ko'maklashish, rahbarlar faoliyatiga baho berish. 1-ilovadagi tarkib: rais — Bosh vazir А.Н.Арипов, o'rinbosar — Агентлик direktori Б.Х.Хайдаров, kotib — Markaz direktori (lavozimi bo'yicha).","tags":["komissiya","tarkib"]},{"id":"pq-x-04","doc":"ПҚ-104","topic":"Texnik topshiriq","ref":"ПҚ-104 п.5(а)","difficulty":2,"q":"Loyihaoldi hujjatlarni ishlab chiqish uchun texnik topshiriqlar qaysi sanadan boshlab Markazda kompleks ekspertizadan o'tkazilmaydi?","options":[{"t":"2026 yil 1 martdan — texnik topshiriq buyurtmachining o'zi tomonidan erkin shaklda tasdiqlanadi","ok":false,"why":"1 mart 2026 — п.4(а) dagi «shu sanaga qadar kiritilgan arizalar» chegarasi, bekor qilish sanasi emas"},{"t":"2026 yil 15 apreldan — ular «Шаҳарсозлик ҳужжатларини экспертиза қилиш республика маркази» ДМда ekspertiza qilinadi","ok":false,"why":"15 aprel — п.5(б) (15 mln dollardan kam loyihalar) sanasi; Шаҳарсозлик маркази esa п.5(г) bilan bog'liq"},{"t":"2026 yil 1 sentyabrdan — ular «Ўзбекэкспертиза» АЖда ekspertiza qilinadi","ok":false,"why":"1 sentyabr va «Ўзбекэкспертиза» АЖ — п.5(д), ya'ni bojxona imtiyozlari ro'yxatiga tegishli"},{"t":"2026 yil 1 apreldan — ular Markazning elektron axborot platformasida joylashtiriladigan namunaviy shakldan foydalangan holda ishlab chiqiladi","ok":true,"why":"п.5(а) aynan shu sanani va Platformadagi namunaviy shakl mexanizmini belgilaydi"}],"exp":"ПҚ-104 п.5 Markaz ekspertizasidan chiqariladigan beshta hujjat guruhini sanaydi. Birinchisi — loyihaoldi hujjatlarni ishlab chiqish uchun texnik topshiriqlar: 2026 yil 1 apreldan ular ekspertiza qilinmaydi, buning o'rniga Markaz Platformasida joylashtiriladigan namunaviy (типовой) shakl asosida tayyorlanadi. Namunaviy shakllarni ishlab chiqish 3-ilovaning 16-bandiga ko'ra 2026 yil 1 aprelga mo'ljallangan.","tags":["muddat","ТЗ","platforma"]},{"id":"pq-x-05","doc":"ПҚ-104","topic":"Ekspertiza","ref":"ПҚ-104 п.5(б); ПП-332 Прил.1 п.2(а)","difficulty":3,"q":"ПҚ-104 п.5(б) ga muvofiq 2026 yil 15 apreldan boshlab qaysi loyihalarning loyihaoldi hujjatlari Markaz ekspertizasidan chiqariladi?","options":[{"t":"Qiymati 15 million AQSh dollari ekvivalentidan KAM bo'lgan — byudjet tizimi byudjetlari, davlat maqsadli jamg'armalari, Tiklanish va taraqqiyot jamg'armasi hisobidan moliyalashtiriladigan hamda korporativ buyurtmachilar amalga oshirayotgan loyihalar","ok":true,"why":"п.5(б) aynan shu chegarani va ikki toifani ((i) byudjet/jamg'armalar, (ii) korporativ buyurtmachilar) ko'rsatadi; amaldagi ПП-332 Прил.1 п.2(а) ham «стоимостью в эквиваленте 15 миллионов долларов США и более» deb yozilgan"},{"t":"Qiymati 15 million AQSh dollari ekvivalentiga TENG va undan YUQORI bo'lgan loyihalar","ok":false,"why":"Aksincha — 15 mln va undan yuqori loyihalar ekspertizada QOLADI: ПП-332 Прил.1 п.2(а) (ПҚ-104 4-ilovasi tahririda) Nizomni aynan shu loyihalarga tatbiq etadi"},{"t":"Qiymati 5 million AQSh dollari ekvivalentidan kam bo'lgan davlat tashqi qarzi hisobidagi loyihalar","ok":false,"why":"5 mln dollar chegarasi — ПП-332 Прил.1 п.2(д) dagi davlat tashqi qarzi bandi va u «5 миллионов долларов США и более» deb yozilgan; п.5(б) ga aloqasi yo'q"},{"t":"Qiymati БҲМ ning 50 ming baravaridan kam bo'lgan barcha loyihalar","ok":false,"why":"50 ming БҲМ — ПП-332 Прил.1 п.2(а) dagi ishchi loyiha (рабочий проект) ishlab chiqish va uni «Шаҳарсозлик ҳужжатларини экспертиза қилиш республика маркази» ДМда ekspertiza qilish chegarasi, п.5(б) chegarasi emas"}],"exp":"ПҚ-104 п.5(б) 2026 yil 15 apreldan boshlab 15 million AQSh dollari ekvivalentidan KAM turadigan loyihalarning loyihaoldi hujjatlarini Markaz ekspertizasidan chiqaradi — bu byudjet tizimi/jamg'armalar mablag'lari hisobidan moliyalashtiriladigan va korporativ buyurtmachilar loyihalariga taalluqli. Bunga mos ravishda 4-ilova bilan ПП-332 1-ilovasining 2-bandi qayta bayon etilgan: amaldagi tahrirda п.2(а) «15 миллионов долларов США и более» chegarasini o'rnatadi, п.2(д) esa davlat tashqi qarzi loyihalari uchun 5 mln dollar chegarasini saqlaydi.","tags":["chegara","summa","muddat"]},{"id":"pq-x-06","doc":"ПҚ-104","topic":"Ekspertiza","ref":"ПҚ-104 п.5(в); ПП-332 Прил.1 п.3(г)","difficulty":2,"q":"Xususiy tadbirkorlik subyektlari tomonidan strategik foydali qazilmalarni qazib olish va (yoki) qayta ishlashni ko'zda tutuvchi loyihalarning loyihaoldi hujjatlari endi qayerda ekspertizadan o'tkaziladi?","options":[{"t":"«Ўзбекэкспертиза» АЖда","ok":false,"why":"«Ўзбекэкспертиза» АЖга п.5(д) bo'yicha faqat bojxona imtiyozlari qo'llanadigan import tovarlar ro'yxati funksiyasi o'tkaziladi"},{"t":"«Шаҳарсозлик ҳужжатларини экспертиза қилиш республика маркази» ДМда","ok":false,"why":"Bu tashkilot п.5(г) bo'yicha kapital qurilish/ta'mirlash hujjatlarini oladi, kon-geologiya loyihalarini emas"},{"t":"Tog'-kon sanoati va geologiya vazirligi huzuridagi «Ер қаъридан фойдаланиш маркази»da","ok":true,"why":"п.5(в) aynan shu organni belgilaydi; ПП-332 Прил.1 п.3(г) esa xususiy tadbirkorlik subyektlari loyihalarini (МТТБ/СОРП dan tashqari) Nizom amalidan chiqarib tashlaydi"},{"t":"Avvalgidek Markazda, faqat soddalashtirilgan tartibda","ok":false,"why":"Soddalashtirilgan tartib — п.9(а) (eskirgan uskunalarni yangilash) uchun; п.5(в) esa Markaz ekspertizasini butunlay bekor qiladi"}],"exp":"ПҚ-104 п.5(в) moliyalashtirish manbaidan qat'i nazar xususiy tadbirkorlik subyektlari amalga oshirayotgan strategik foydali qazilmalar loyihalarini Markaz ekspertizasidan chiqaradi va ularni Tog'-kon sanoati va geologiya vazirligi huzuridagi «Ер қаъридан фойдаланиш маркази»ga o'tkazadi. Istisno: mahsulotni taqsimlash to'g'risidagi bitimlarga (МТТБ/СОРП) muvofiq amalga oshirilayotgan loyihalar bu bandga kirmaydi — amaldagi ПП-332 Прил.1 п.3(г) da ham aynan shu istisno saqlangan.","tags":["yurisdiksiya","organ"]},{"id":"pq-x-07","doc":"ПҚ-104","topic":"Tender","ref":"ПҚ-104 п.5(г); ПП-332 Прил.2 п.4","difficulty":3,"q":"Binolar, inshootlar va muhandislik kommunikatsiyalarini kapital qurish va ta'mirlash bo'yicha qaysi qiymatdagi tender hujjatlari va texnik topshiriqlar Markaz ekspertizasidan chiqarildi hamda ular qayerda ekspertiza qilinadi?","options":[{"t":"БҲМ ning 6 000 baravarigacha bo'lganlari — avvalgidek Markazda","ok":false,"why":"6 000 БҲМ — ПП-332 2-ilovasining 3-bandidagi byudjet buyurtmachisi uchun umumiy tender chegarasi, п.5(г) chegarasi emas"},{"t":"БҲМ ning 50 000 baravarigacha bo'lganlari — «Шаҳарсозлик ҳужжатларини экспертиза қилиш республика маркази» ДМда","ok":false,"why":"Organ to'g'ri, lekin chegara noto'g'ri: bandda 25 000 baravar ko'rsatilgan (50 000 БҲМ — ПП-332 Прил.1 п.2(а) dagi ishchi loyiha chegarasi)"},{"t":"БҲМ ning 25 000 baravarigacha bo'lganlari — «Ўзбекэкспертиза» АЖда","ok":false,"why":"Chegara to'g'ri, lekin organ noto'g'ri: bu hujjatlar «Ўзбекэкспертиза» АЖга emas, Шаҳарсозлик маркази ДМга o'tadi"},{"t":"БҲМ ning 25 000 baravarigacha bo'lganlari — «Шаҳарсозлик ҳужжатларини экспертиза қилиш республика маркази» ДМ yoki uning hududiy boshqarmalarida","ok":true,"why":"п.5(г) aynan «йигирма беш минг бараваригача» chegarani va shu organni (hududiy boshqarmalari bilan) belgilaydi"}],"exp":"ПҚ-104 п.5(г) kapital qurish va ta'mirlash bo'yicha БҲМ ning 25 000 baravarigacha bo'lgan davlat xaridlariga doir tender hujjatlari va texnik topshiriqlarni Markaz ekspertizasidan chiqaradi — ularni «Шаҳарсозлик ҳужжатларини экспертиза қилиш республика маркази» ДМ yoki hududiy boshqarmalari ekspertiza qiladi. Ayni paytda 4-ilova bilan ПП-332 2-ilovasining 4-bandi qayta bayon etilgan va amaldagi tahrirda u shunday yangraydi: qiymati БҲМ ning 25 000 baravaridan ORTIQ bo'lgan kapital qurilish/ta'mirlash xaridi Markazga texnik topshiriq shaklida loyiha-smeta hujjatlari bilan kiritiladi, ekspertiza esa hajmlar va narx parametrlari asoslanganligi qismida o'tkaziladi — ya'ni 25 000 БҲМ ikki organ o'rtasidagi chegara chizig'idir.","tags":["chegara","БҲМ","organ"]},{"id":"pq-x-08","doc":"ПҚ-104","topic":"Ekspertiza","ref":"ПҚ-104 п.5(д)","difficulty":2,"q":"Bojxona to'lovlari bo'yicha imtiyozlar qo'llagan holda import qilinadigan tovarlar ro'yxatini ekspertiza qilish funksiyasi qachondan va kimga o'tkaziladi?","options":[{"t":"2026 yil 1 sentyabrdan — «Ўзбекэкспертиза» АЖга","ok":true,"why":"п.5(д) aynan shu sana va shu tashkilotni ko'rsatadi; 3-ilova (chora-tadbirlar rejasi) ning 21-bandi ham shu jarayonni raqamlashtirishni yuklaydi"},{"t":"2026 yil 1 apreldan — «Ўзбекэкспертиза» АЖга","ok":false,"why":"Tashkilot to'g'ri, sana xato: 1 aprel — п.5(а) (loyihaoldi ТЗ) sanasi"},{"t":"2026 yil 1 sentyabrdan — Bojxona qo'mitasiga","ok":false,"why":"Sana to'g'ri, lekin funksiya Bojxona qo'mitasiga emas, «Ўзбекэкспертиза» АЖга o'tkaziladi; Bojxona qo'mitasi faqat integratsiya ishtirokchisi"},{"t":"2026 yil 15 apreldan — «Ер қаъридан фойдаланиш маркази»га","ok":false,"why":"Ikkala element ham boshqa bandlardan: 15 aprel — п.5(б), Ер қаъридан фойдаланиш маркази — п.5(в)"}],"exp":"ПҚ-104 п.5(д) 2026 yil 1 sentyabrdan bojxona to'lovlari bo'yicha imtiyozlar qo'llangan holda import qilinadigan tovarlar ro'yxati ekspertizasini Markazdan «Ўзбекэкспертиза» АЖга o'tkazadi. 4-ilovaning 1-bandi bilan ПҚ-3756 va 6-bandi bilan ВМ-750 nizomidagi «Марказ» so'zlari ham «Ўзбекэкспертиза» АЖ ga almashtirilgan; o'sha nizom bo'yicha ekspertiza uchun БҲМ ning to'rt baravari miqdorida to'lov undiriladi. 4-ilova izohiga ko'ra aynan shu ikki band 2026 yil 1 sentyabrdan kuchga kiradi.","tags":["muddat","organ","bojxona"]},{"id":"pq-x-09","doc":"ПҚ-104","topic":"Umumiy","ref":"ПҚ-104 п.6(а)","difficulty":2,"q":"5-band bilan Markaz ekspertizasidan chiqarilgan loyihalarni amalga oshirishning maqsadga muvofiqligi va samaradorligi yuzasidan shaxsiy javobgarlik kimga yuklatiladi?","options":[{"t":"«Лойиҳалар ва харидлар самарадорлигини ошириш маркази» ДМ direktoriga","ok":false,"why":"Markaz bu loyihalarni umuman ekspertiza qilmaydi — javobgarlik unda qolmaydi"},{"t":"Tegishli vazirlik, idora va tashkilotning birinchi rahbariga; masala har chorakda kuzatuv kengashlari (mavjud bo'lganda) tomonidan muhokama qilinadi","ok":true,"why":"п.6(а) aynan shu subyektni va chorakda bir marta kuzatuv kengashi muhokamasini belgilaydi"},{"t":"Sanoat kooperatsiyasi va davlat xaridlari agentligi direktoriga","ok":false,"why":"Agentlik direktori п.17 bo'yicha QARORNING IJROSI uchun mas'ul, har bir loyiha samaradorligi uchun emas"},{"t":"Loyiha tashkiloti rahbariga; masala har yarim yilda Respublika komissiyasida muhokama qilinadi","ok":false,"why":"Subyekt ham, davriylik ham xato — javobgarlik buyurtmachi tashkilotning birinchi rahbarida, muhokama esa chorakda bir marta"}],"exp":"ПҚ-104 п.6(а) ekspertizadan chiqarish bilan birga javobgarlikni ham ko'chiradi: Markaz ekspertizasi olib tashlangan loyihalarning maqsadga muvofiqligi va samaradorligi uchun shaxsan tegishli vazirlik, idora yoki tashkilotning birinchi rahbari javob beradi, holat esa har chorakda kuzatuv kengashlarida (mavjud bo'lganda) muhokama qilinadi. Amaliy ma'nosi: ekspertizadan chiqarilgan hujjat «nazoratsiz» degani emas — nazorat idoraviy darajaga ko'chadi.","tags":["javobgarlik","birinchi rahbar"]},{"id":"pq-x-10","doc":"ПҚ-104","topic":"Ekspertiza","ref":"ПҚ-104 п.8(а), п.8(б)","difficulty":2,"q":"2026 yil 1 sentyabrdan Markazda loyihaoldi hujjatlarni kompleks ekspertiza qilishning qanday yangi tartib-taomillari joriy etiladi?","options":[{"t":"Faqat kichik loyihalar uchun parallel ekspertiza va barcha loyihalar uchun ixtiyoriy ekspertiza","ok":false,"why":"Parallel ekspertiza kichik loyihalar uchun emas — yirik va mega hamda ijobiy xulosa olgan loyihalarga o'xshash loyihalar uchun"},{"t":"Tezlashtirilgan ekspertiza buyurtmachining bir tomonlama talabiga ko'ra, hech qanday qo'shimcha shartsiz qo'llaniladi","ok":false,"why":"Tezlashtirilgan tartib Markazning TAKLIFI asosida va loyiha ilgari ekspertizadan o'tgan loyihaga o'xshash bo'lgandagina qo'llaniladi"},{"t":"Yirik va mega loyihalar hamda ijobiy xulosa olgan loyihalarga o'xshash loyihalar hujjatlarining tayyor bo'limlarini parallel ekspertizadan o'tkazish, hamda loyiha ilgari Markazda ekspertizadan o'tgan loyihaga o'xshash bo'lsa — Markaz taklifi asosida tezlashtirilgan ekspertiza","ok":true,"why":"п.8(а) parallel, п.8(б) tezlashtirilgan tartibni aynan shu shartlar bilan belgilaydi"},{"t":"Loyihaoldi hujjatlar ekspertizasini xalqaro akkreditatsiyadan o'tgan konsalting tashkilotlariga to'liq o'tkazish","ok":false,"why":"Bu п.7 — Agentlik va Iqtisodiyot va moliya vazirligiga uch oy muddatda TAKLIF kiritish topshirig'i, joriy etilgan tartib emas"}],"exp":"ПҚ-104 п.8 ikki yangi protsedurani joriy qiladi: (а) parallel ekspertiza — hujjat to'liq tayyor bo'lishini kutmasdan tayyor bo'limlarni ekspertizadan o'tkazish (yirik/mega loyihalar va ijobiy xulosa olgan loyihalarga o'xshash loyihalar); (б) tezlashtirilgan ekspertiza — taqdim etilgan loyiha ilgari Markazda ekspertizadan o'tgan loyihaga o'xshash bo'lsa, Markazning taklifi asosida. 3-ilovaning 5-bandiga ko'ra tezlashtirilgan ekspertiza muddati ikki baravarga qisqartiriladi va u to'lov evaziga ko'rsatiladi.","tags":["parallel","tezlashtirilgan","muddat"]},{"id":"pq-x-11","doc":"ПҚ-104","topic":"Ekspertiza","ref":"ПҚ-104 п.9(а)","difficulty":2,"q":"Mavjud obyektlarda jismonan va ma'nan eskirgan mashina, uskuna va texnologik liniyalarni yangilash loyihalari soddalashtirilgan tartibda ekspertiza qilinganda nima o'rganiladi?","options":[{"t":"Faqat tovar (ish, xizmat)lar narxlarining asoslanganligi","ok":false,"why":"Narx — ro'yxatning bir qismi; texnik-texnologik yechim va moliyaviy-iqtisodiy ko'rsatkichlar ham o'rganiladi"},{"t":"Ekologik va ijtimoiy bo'limlardan tashqari hujjatning barcha bo'limlari","ok":false,"why":"Band «фақат» so'zi bilan yopiq ro'yxat beradi — «qolganidan tashqari hammasi» tamoyili emas"},{"t":"Faqat moliyaviy-iqtisodiy samaradorlik va moliyalashtirish manbalarining mavjudligi","ok":false,"why":"Texnik-texnologik yechimlar va narx asoslanganligi tushirib qoldirilgan"},{"t":"Faqat texnik-texnologik, (zarur hollarda) arxitektura-qurilish yechimlari va moliyaviy-iqtisodiy ko'rsatkichlar hamda tovar (ish, xizmat)lar narxlarining asoslanganligi","ok":true,"why":"п.9(а) aynan shu to'rt elementni sanaydi va «зарур ҳолларда» izohi arxitektura-qurilish qismiga tegishli"}],"exp":"ПҚ-104 п.9(а) modernizatsiya loyihalari uchun soddalashtirilgan kompleks ekspertizani belgilaydi: yangi qurilish emas, mavjud obyektda eskirgan uskunani almashtirish bo'lgani uchun ekspertiza predmeti toraytiriladi — texnik-texnologik yechimlar, zarur bo'lsa arxitektura-qurilish yechimlari, moliyaviy-iqtisodiy ko'rsatkichlar va narxlar asoslanganligi. 3-ilovaning 6-bandi bu tartibni ishlab chiqishni 2026 yil 1 iyunga belgilagan.","tags":["soddalashtirilgan","modernizatsiya"]},{"id":"pq-x-12","doc":"ПҚ-104","topic":"Ekspertiza","ref":"ПҚ-104 п.9(б)","difficulty":2,"q":"«Бенчмаркинг» usuli ПҚ-104 ga muvofiq qaysi loyihalarda qo'llaniladi?","options":[{"t":"Yangi quriladigan yirik va mega loyihalar bo'yicha loyihaoldi hujjatlarni kompleks ekspertizadan o'tkazishda — loyiha xususiyatlarini hisobga olgan holda","ok":true,"why":"п.9(б) aynan «янги қуриладиган йирик ва мега лойиҳалар» ni ko'rsatadi"},{"t":"Barcha tender hujjatlarini ekspertiza qilishda, xarid summasidan qat'i nazar","ok":false,"why":"Benchmarking tender hujjatlariga emas, loyihaoldi hujjatlarga va faqat yirik/mega yangi qurilish loyihalariga nisbatan belgilangan"},{"t":"Mavjud obyektlarda uskunalarni modernizatsiya qilish loyihalarida","ok":false,"why":"Modernizatsiya loyihalari uchun п.9(а) dagi soddalashtirilgan tartib qo'llaniladi, benchmarking emas"},{"t":"Faqat davlat tashqi qarzi hisobiga moliyalashtiriladigan loyihalarda","ok":false,"why":"Moliyalashtirish manbai benchmarkingni qo'llash mezoni sifatida bandda umuman ko'rsatilmagan"}],"exp":"ПҚ-104 п.9(б) yangi quriladigan yirik va mega loyihalarning loyihaoldi hujjatlarini ekspertiza qilishda Markaz tomonidan «бенчмаркинг» usulini qo'llash amaliyotini kiritadi. 3-ilovadagi chora-tadbirlar rejasi mexanizmni aniqlashtiradi: agar loyihaning bir birlik qiymati o'xshash texnologik yechimga ega xalqaro va mahalliy (etalon) loyihalarning o'rtacha bozor qiymatidan PAST bo'lsa, loyihaning narx ko'rsatkichlari qismini ekspertizadan o'tkazish talab etilmaydi.","tags":["benchmarking","narx"]},{"id":"pq-x-13","doc":"ПҚ-104","topic":"Ekspertiza","ref":"ПҚ-104 п.9(в)","difficulty":2,"q":"ПҚ-104 ga muvofiq kompleks ekspertizada tovar (ish, xizmat)ning boshlang'ich narxidan tashqari yana nima inobatga olinadi?","options":[{"t":"Faqat yetkazib berish, montaj va ishga tushirish-sozlash xarajatlari","ok":false,"why":"Bu ro'yxat bandda berilgan ТСО tarkibini qamramaydi — energiya samaradorligi va utilizatsiya tushib qolgan"},{"t":"Umumiy egalik qilish qiymati (ТСО), shu jumladan energiya samaradorligi, ekspluatatsiya va utilizatsiya xarajatlari","ok":true,"why":"п.9(в) aynan «умумий эгалик қилиш қиймати (ТСО)» ni va uning uchta tarkibiy elementini sanaydi"},{"t":"Bojxona to'lovlari va qo'shilgan qiymat solig'i summasi","ok":false,"why":"Soliq va bojxona to'lovlari narx tarkibiga oid masala; ТСО esa hayotiy sikl davomidagi egalik qilish qiymati"},{"t":"Faqat kafolat muddati davomidagi xizmat ko'rsatish xarajatlari","ok":false,"why":"Kafolat xizmati — ТСО ning bir bo'lagi; band undan kengroq (butun ekspluatatsiya va utilizatsiya) doirani belgilaydi"}],"exp":"ПҚ-104 п.9(в) narx tahlili paradigmasini o'zgartiradi: ekspertizada nafaqat boshlang'ich narx, balki umumiy egalik qilish qiymati (Total Cost of Ownership — ТСО) ham baholanadi, unga energiya samaradorligi, ekspluatatsiya va utilizatsiya xarajatlari kiradi. 3-ilovadagi chora-tadbirlar rejasi ТСО ni hisobga olish tartibini 2026 yil 1 iyunga ishlab chiqishni yuklaydi. Amaliyotda bu — eng arzon taklif eng maqbul taklif emasligini normativ mustahkamlaydi.","tags":["ТСО","narx"]},{"id":"pq-x-14","doc":"ПҚ-104","topic":"Ekspertiza","ref":"ПҚ-104 п.9(г)","difficulty":3,"q":"Markaz bildirgan e'tiroz va kamchiliklarni bartaraf etish asosida qayta ishlangan loyihaoldi hujjatlar uchun ПҚ-104 nimani belgilaydi?","options":[{"t":"Takroriy ekspertiza uchun to'lovning 50 foizi undiriladi","ok":false,"why":"50 foiz — ПП-332 3-bandining «в» kichik bandidagi ТЭР ekspertizasi narxi (ТЭО uchun belgilangan summaning 50 foizi); takroriy to'lovga aloqasi yo'q"},{"t":"Takroran to'lov undirish amaliyoti bekor qilinadi va yangi asoslar bo'yicha e'tirozlar bildirishga yo'l qo'yilmaydi","ok":true,"why":"п.9(г) ikkala qoidani birga belgilaydi — to'lov ham, yangi asosli e'tiroz ham bekor"},{"t":"Takroran to'lov olinmaydi, biroq Markaz yangi asoslar bo'yicha e'tirozlar bildirishi mumkin","ok":false,"why":"Ikkinchi qismi teskari: band aynan YANGI asoslar bo'yicha e'tiroz bildirishga yo'l qo'ymaydi"},{"t":"To'lov to'liq undiriladi, lekin takroriy ekspertiza muddati ikki baravarga qisqartiriladi","ok":false,"why":"Band to'lov va e'tiroz asoslari haqida; muddat alohida masala — ПП-332 1-ilovasining 21-bandi takroriy ekspertizaga 15 ish kuni beradi, hech qanday «ikki baravar qisqartirish» sharti yo'q"}],"exp":"ПҚ-104 п.9(г) buyurtmachi uchun ikki himoya qoidasini o'rnatadi: (1) Markaz e'tirozlarini bartaraf etib qayta kiritilgan hujjat uchun takroran to'lov undirilmaydi; (2) takroriy ko'rib chiqishda Markaz YANGI asoslar bo'yicha e'tiroz bildira olmaydi. Bu ПП-332 1-ilovasining 22-bandidagi amaldagi tamoyilni kuchaytiradi — u yerda ham «qayta ishlangan hujjat ekspertizasida ilgari berilgan xulosada ko'rsatilmagan yangi asoslar bo'yicha e'tiroz taqdim etishga yo'l qo'yilmaydi» deb yozilgan (istisno — ilgarigi e'tirozlarni bartaraf etish doirasida QO'SHIMCHA taqdim etilgan materiallarga oid e'tirozlar).","tags":["takroriy","to'lov","e'tiroz"]},{"id":"pq-x-15","doc":"ПҚ-104","topic":"Umumiy","ref":"ПҚ-104 п.10","difficulty":3,"q":"ПҚ-104 ning 10-bandiga (Платформа) oid quyidagi tasdiqlardan qaysi biri TO'G'RI?","options":[{"t":"Har bir hujjat ekspertizasi jarayonining monitoringi faqat buyurtmachi uchun ochiq bo'ladi","ok":false,"why":"Band monitoring «жамоатчилик учун очиқ» ekanini belgilaydi (qonunchilikda nazarda tutilgan hollar bundan mustasno)"},{"t":"Tovar (ish, xizmat)lar narxlari bazasi yiliga bir marta yangilanadi","ok":false,"why":"Qo'shni raqam: bandda «доимий равишда (6 ойдан ошмаган муддатда)» yozilgan"},{"t":"Ijobiy xulosalar Ғазначилик ва Божхона қўмиталарига faqat buyurtmachi so'roviga ko'ra qog'ozda yuboriladi","ok":false,"why":"Aksincha — xulosalar «Электрон ҳукумат» idoralararo integratsiya platformasi orqali AVTOMATIK yuboriladi"},{"t":"Ijobiy xulosa berilgan hujjatlar va Markaz tahlillari asosidagi narxlar, texnik ko'rsatkichlar bazasi doimiy ravishda — 6 oydan oshmagan muddatda yangilab boriladi","ok":true,"why":"п.10(а)(iii) aynan shu davriylikni belgilaydi"}],"exp":"ПҚ-104 п.10 2026 yil 1 sentyabrdan Platforma bo'yicha uchta qoidani belgilaydi: (i) har bir loyihaoldi va xarid hujjati ekspertizasi jarayonining jamoatchilik uchun ochiq onlayn monitoringi; (ii) ijobiy xulosa olgan loyihalar doirasidagi xarid jarayonlarini tasdiqlangan asosiy texnik-iqtisodiy parametrlarga moslik yuzasidan monitoring qilish va «Ягона инвестиция платформаси»га integratsiya; (iii) narxlar va texnik ko'rsatkichlar bazasini 6 oydan oshmagan muddatda yangilash. п.10(б) esa ijobiy xulosalarni Ғазначилик хизмати қўмитаси, Божхона қўмитаси va boshqa organlarga «Электрон ҳукумат» orqali avtomatik yuborishni belgilaydi.","tags":["platforma","narx bazasi","muddat"]},{"id":"pq-x-16","doc":"ПҚ-104","topic":"Umumiy","ref":"ПҚ-104 п.12(а)","difficulty":2,"q":"Markaz yuritadigan loyiha institutlari va tashkilotlari Reytingida ular qanday darajalarga ajratiladi?","options":[{"t":"«А», «В» va «С» toifalarga","ok":false,"why":"Harfli toifa — «Шаффоф қурилиш» tizimidagi pudratchi/loyihachi toifasi; Markaz reytingi darajalari harf bilan emas, so'z bilan belgilangan"},{"t":"«Ишончли» va «ишончсиз» ikki darajaga","ok":false,"why":"Ikki daraja emas, uch daraja belgilangan — o'rta daraja tushib qolgan"},{"t":"«Юқори», «ўрта» va «паст» ishonchlilik darajalariga","ok":true,"why":"п.12(а)(i) aynan shu uch ishonchlilik darajasini belgilaydi"},{"t":"«Ишончли», «шартли ишончли» va «ишончсиз» darajalariga","ok":false,"why":"Daraja soni to'g'ri, lekin nomlari boshqacha: qaror «юқори/ўрта/паст» atamalarini ishlatadi"}],"exp":"ПҚ-104 п.12(а) 2026 yil 1 sentyabrdan Markaz tomonidan loyiha institutlari va tashkilotlari Reytingini yuritishni joriy qiladi: tarmoqlar kesimida ishlab chiqilgan loyihaoldi hujjatlarning kompleks ekspertiza natijalaridan kelib chiqib ular «юқори», «ўрта» va «паст» ishonchlilik darajalariga ajratiladi, Reyting Platformada joylashtirilib doimiy yangilanadi. ПҚ-104 3-ilovasi bo'yicha loyiha tashkiloti tanlanishida reytingda kamida «ўрта» daraja talab qilinadi. Diqqat: bu qoida ПП-332 matniga kiritilmagan — u ПҚ-104 ning o'z bandi.","tags":["reyting","loyiha tashkiloti"]},{"id":"pq-x-17","doc":"ПҚ-104","topic":"Umumiy","ref":"ПҚ-104 п.12(б)","difficulty":2,"q":"O'rta, yirik va mega loyihalarning loyihaoldi hujjatlarini ishlab chiqish uchun loyiha institutlari va tashkilotlarini tanlashda qanday mezon majburiy hisoblanadi?","options":[{"t":"«Энг арзон нарх» mezoni — byudjet mablag'larini tejash maqsadida","ok":false,"why":"Aynan shu mezondan VOZ KECHILADI; band «энг арзон нарх» dan voz kechishni to'g'ridan-to'g'ri yozadi"},{"t":"«Сифат ва муддат» mezoni","ok":false,"why":"Uch elementli formuladan ikkitasi almashtirilgan — «муддат» qarorda mezon sifatida yo'q"},{"t":"«Тажриба ва техник салоҳият» mezoni","ok":false,"why":"Sifat va narx elementlari tushib qolgan; texnik salohiyat (техническая оснащенность) — ПП-332 2-ilovasining 5-bandidagi tender ishtirokchisiga qo'yiladigan kvalifikatsiya talabi, loyihachi tanlash mezoni emas"},{"t":"«Сифат, тажриба ва нарх» mezoni — «энг арзон нарх» mezonidan voz kechilgan holda","ok":true,"why":"п.12(б) aynan shu formulani beradi va mezonni majburiy deb belgilaydi"}],"exp":"ПҚ-104 п.12(б) o'rta, yirik va mega loyihalar uchun loyiha tashkilotini tanlashda «энг арзон нарх» mezonidan voz kechib, «сифат, тажриба ва нарх» mezonini majburiy qiladi. ПҚ-104 3-ilovasi bu mezonning tarkibiy talablarini ochadi: sohada oldin loyihaoldi hujjat ishlab chiqqan bo'lishi; zamonaviy modellashtirish texnologiyalaridan (BIM, Micromine, CAD) foydalanishi; «Шаффоф қурилиш» tizimida tegishli toifaga ega bo'lishi; ilgarigi hujjatlari bo'yicha ijobiy xulosa olgan bo'lishi; Markaz reytingida kamida «ўрта» darajaga ega bo'lishi. Diqqat: bu talablar ПҚ-104 ning o'z ilovasida — ПП-332 matniga kiritilmagan.","tags":["mezon","tanlov"]},{"id":"pq-x-18","doc":"ПҚ-104","topic":"Ekspertiza","ref":"ПҚ-104 4-илова — ПП-332 п.3(а), (б)","difficulty":3,"q":"ПҚ-104 ning 4-ilovasi bilan ПП-332 ning 3-bandidagi ekspertiza haqi yuqori chegaralari qanday o'zgartirildi?","options":[{"t":"«а» kichik bandda 100 baravardan 150 baravarga, «б» kichik bandda 50 mingdan 75 ming dollargacha","ok":false,"why":"Oraliq raqamlar o'ylab topilgan — amaldagi tahrirda 200 baravar va 100 ming dollar ko'rsatilgan"},{"t":"«а» kichik bandda 200 baravardan 100 baravarga, «б» kichik bandda 100 mingdan 50 ming dollarga kamaytirildi","ok":false,"why":"Yo'nalish teskari: chegaralar kamaytirilmagan, balki ikki baravar OSHIRILGAN"},{"t":"«а» kichik bandda БҲМ ning 100 baravaridan 200 baravariga, «б» kichik bandda 50 ming AQSh dollaridan 100 ming AQSh dollariga oshirildi","ok":true,"why":"Amaldagi п.3(а): «но не более 200-кратного размера базовой расчетной величины»; п.3(б): «не более 100 тысяч долларов США в эквиваленте» — ikkalasi ham ПҚ-104 tahririda"},{"t":"«а» kichik bandda 100 baravardan 200 baravarga, «б» kichik bandda quyi chegara 4 mingdan 8 ming dollarga oshirildi","ok":false,"why":"Birinchi qismi to'g'ri, ikkinchisi xato: quyi chegara o'zgarmagan — п.3(б) hozir ham «не менее 4 тысяч долларов США»; oshgani YUQORI chegara (50→100 ming)"}],"exp":"ПП-332 ning 3-bandi ekspertiza haqini belgilaydi: (а) tender hujjatlari, ТЗ, shartnoma va import kontraktlari (hamda ularga qo'shimcha bitimlar) uchun — xarid predmeti qiymatining 0,1 foizi QQSsiz (tender hujjatlari va ТЗ bo'yicha — har lotning dastlabki qiymatidan), lekin БҲМ ning 200 baravaridan ortiq emas; (б) ТЭО uchun — loyiha umumiy summasining 0,03 foizi, 4 ming dollardan kam va 100 ming dollardan ortiq emas; (в) ТЭР uchun — ТЭО uchun belgilangan summaning 50 foizi; (г) ekspertiza 100 foizli oldindan to'lov sharti bilan. ПҚ-104 4-ilovasi «а» va «б» dagi ikki yuqori chegarani ikki baravar oshirdi.","tags":["summa","to'lov","chegara"]},{"id":"pq-x-19","doc":"ПҚ-104","topic":"Tender","ref":"ПҚ-104 4-илова — ПП-332 п.3(а), п.3(д)","difficulty":3,"q":"ПҚ-104 ning 4-ilovasi ПП-332 3-bandining «д» kichik bandiga nima qildi va byudjet mablag'lari hisobidagi tender xarid hujjatlari uchun qanday tartib belgilandi?","options":[{"t":"«д» kichik band saqlandi — bunday hujjatlar ekspertizasi avvalgidek to'liq bepul qoladi","ok":false,"why":"Amaldagi matnda «д» kichik band o'rnida faqat «подпункт «д» пункта 3 исключен» izohi turibdi — band butunlay chiqarib tashlangan"},{"t":"«д» kichik band chiqarib tashlandi va haq umumiy tartibda, to'liq (100 foiz) miqdorda undiriladi","ok":false,"why":"Band chiqarilgani to'g'ri, lekin byudjet manbali tender hujjatlari uchun imtiyozli stavka — 10 foiz belgilangan"},{"t":"«д» kichik band chiqarib tashlandi; byudjet tizimi byudjetlari va Tiklanish va taraqqiyot jamg'armasi mablag'lari hisobidagi tender xarid hujjatlari ekspertizasi uchun «а» kichik bandda belgilangan summaning 10 foizi miqdorida haq undiriladi","ok":true,"why":"Amaldagi п.3(а) ning ikkinchi jumlasi: «взимается плата в размере 10 процентов суммы, определенной настоящим подпунктом»; «д» esa ПҚ-104 bilan chiqarib tashlangan"},{"t":"«д» kichik band chiqarib tashlandi va haq belgilangan summaning 50 foizi miqdorida undiriladi","ok":false,"why":"50 foiz — 3-bandning «в» kichik bandidagi ТЭР ekspertizasi narxi; tender hujjatlari uchun 10 foiz belgilangan"}],"exp":"ПҚ-104 4-ilovasi ПП-332 3-bandini ikki tomondan o'zgartirdi: «д» kichik band butunlay chiqarib tashlandi, «а» kichik bandga esa yangi jumla qo'shildi — O'zbekiston Respublikasi byudjet tizimi byudjetlari va Tiklanish va taraqqiyot jamg'armasi mablag'lari hisobidan amalga oshiriladigan xaridlar bo'yicha tender hujjatlari kompleks ekspertizasi uchun shu bandda belgilangan summaning 10 foizi miqdorida haq undiriladi. Ya'ni byudjet manbali tender hujjatlari uchun ekspertiza endi bepul emas, balki imtiyozli stavkada pulli. Hisob-kitob asosi o'zgarmadi: 0,1 foiz (QQSsiz, har lotning dastlabki qiymatidan), lekin БҲМ ning 200 baravaridan ortiq emas.","tags":["to'lov","byudjet","bepul"]},{"id":"pq-x-20","doc":"ПҚ-104","topic":"Ekspertiza","ref":"ПҚ-104 4-илова — ПП-332 1-илова п.22","difficulty":2,"q":"ПҚ-104 4-ilovasi bilan Markazning hujjatlar bo'yicha e'tiroz va takliflariga qanday yangi talab qo'yildi?","options":[{"t":"E'tirozlar sohaviy normativ-huquqiy hujjatlar, me'yorlar, talablar, standartlarga majburiy tarzda havola qilingan holda shakllantiriladi; tegishli havolasi bo'lmagan e'tiroz va takliflar ASOSSIZ deb hisoblanadi","ok":true,"why":"22-bandga ПҚ-104 bilan qo'shilgan xatboshi aynan shunday: «замечания и предложения без соответствующих ссылок считаются безосновательными»"},{"t":"E'tirozlar faqat buyurtmachi bilan oldindan kelishilgan holda shakllantiriladi","ok":false,"why":"Kelishuv talabi yo'q; yagona talab — normativ hujjatga havola qilish"},{"t":"Havolasi bo'lmagan e'tirozlar takroriy ekspertizada qayta ko'rib chiqiladi","ok":false,"why":"Ular «qayta ko'rib chiqiladi» emas, to'g'ridan-to'g'ri «безосновательными» — asossiz deb hisoblanadi"},{"t":"E'tirozlar Respublika komissiyasi tomonidan tasdiqlangandan keyin yuboriladi","ok":false,"why":"22-bandda bunday tasdiqlash tartibi umuman nazarda tutilmagan; shart faqat normativ havola"}],"exp":"ПҚ-104 4-ilovasi ПП-332 1-ilovasining 22-bandini yangi xatboshi bilan to'ldirdi: Markazning e'tiroz va takliflari sohaviy normativ-huquqiy hujjatlar, me'yorlar, talablar, standartlar va boshqa normativ hujjatlarga MAJBURIY havola bilan shakllantiriladi, havolasi bo'lmagan e'tiroz esa asossiz deb hisoblanadi. Bandning birinchi xatboshisi bilan birga o'qiladi: qayta ishlangan hujjat ekspertizasida ilgarigi xulosada ko'rsatilmagan yangi asoslar bo'yicha e'tiroz berish taqiqlanadi (istisno — bartaraf etish doirasida qo'shimcha taqdim etilgan materiallarga oid e'tirozlar). Amaliy ma'nosi: har bir замечание matnda aniq band raqami bilan qo'llab-quvvatlanishi shart, aks holda u qonunan asossiz.","tags":["e'tiroz","havola","asoslash"]},{"id":"pq-x-21","doc":"ПҚ-104","topic":"Ekspertiza","ref":"ПҚ-104 4-илова — ПП-332 1-илова п.21, п.24","difficulty":3,"q":"ПҚ-104 4-ilovasi bilan ПП-332 1-ilovasining 21 va 24-bandlarida qanday muddatlar belgilandi?","options":[{"t":"Takroriy ekspertiza — 15 kalendar kun; ijobiy xulosa 180 kalendar kun amal qiladi","ok":false,"why":"Ikkala birlik ham xato: 21-band takroriy ekspertizani ISH kunida hisoblaydi, 24-band esa 365 kalendar kunni belgilaydi"},{"t":"E'tirozlar bartaraf etilganda takroriy ekspertiza — o'n besh (15) ish kunidan ortiq bo'lmagan muddatda; loyihaoldi hujjat ijobiy xulosa olingandan so'ng bir yil (365 kalendar kun) davomida tasdiqlanmasa, u yangidan kiritilgan hisoblanadi","ok":true,"why":"21-band: «повторная экспертиза осуществляется в срок не более пятнадцати рабочих дней»; 24-band: «в течение одного года (365 календарных дней)»"},{"t":"Takroriy ekspertiza — 10 ish kuni; ijobiy xulosa 365 kalendar kun amal qiladi","ok":false,"why":"Xulosa muddati to'g'ri, lekin takroriy ekspertiza muddati xato: amaldagi 21-band 15 ish kunini belgilaydi (10 ish kuni bu bandda yo'q)"},{"t":"Takroriy ekspertiza — 20 ish kuni; ijobiy xulosa 2 yil amal qiladi","ok":false,"why":"20 ish kuni — 14-banddagi «кичик» investitsiya loyihalari (5–50 mln AQSh dollari) uchun birlamchi ekspertiza muddati; xulosa amal qilish muddati 2 yil emas, 365 kalendar kun"}],"exp":"ПҚ-104 4-ilovasi ПП-332 1-ilovasining ikki muddatini yangi tahrirda bayon qildi: 21-bandda e'tirozlar tashabbuskor (buyurtmachi) tomonidan bartaraf etilganda takroriy ekspertiza 15 ish kunidan ortiq bo'lmagan muddatda o'tkaziladi; 24-bandda esa ijobiy xulosa olingandan so'ng loyihaoldi hujjat bir yil (365 kalendar kun) ichida tasdiqlanmasa, u belgilangan tartibda kompleks ekspertizaga yangidan kiritilgan hisoblanadi. Solishtirish uchun birlamchi ekspertiza muddatlari 14-bandda (УП-259 tahriri): «кичик» — 20, «ўрта» — 25, «йирик» — 30, «мега» — 45 ish kuni. Diqqat: «иш куни» va «календарь кун» farqi attestatsiyada eng ko'p chalg'itadigan nuqta.","tags":["muddat","takroriy","365"]},{"id":"pq-x-22","doc":"ПҚ-104","topic":"Ekspertiza","ref":"ПҚ-104 4-илова — ПП-332 1-илова п.15","difficulty":2,"q":"ПП-332 1-ilovasining 15-bandi yangi tahririga muvofiq kompleks ekspertizadan o'tkazish muddati qaysi kundan hisoblanadi?","options":[{"t":"Xizmatlar haqi to'langanligi tasdiqlangan kundan","ok":true,"why":"15-band to'liq matni: «Началом исчисления срока проведения комплексной экспертизы является дата подтверждения оплаты стоимости услуг»"},{"t":"Hujjatlar Markazga kelib tushgan kundan","ok":false,"why":"Amaldagi 15-bandda bunday mezon yo'q; hujjat taqdim etilgan sana faqat 16-bandning maxsus holatida (nokomplekt hujjat to'ldirilib qayta kiritilganda) rol o'ynaydi"},{"t":"Buyurtmachining arizasi Platformada ro'yxatga olingan kundan","ok":false,"why":"Ro'yxatga olish — texnik harakat; 15-band muddat boshlanishini faqat to'lov tasdig'iga bog'laydi"},{"t":"Hujjatlar to'plami to'liqligi tekshirilib bo'lgan kundan","ok":false,"why":"To'liqlik 16-bandda alohida hal qilinadi (nokomplektlik aniqlansa 3 ish kuni ichida xabar beriladi, boshlanish sanasi esa to'ldirilgan hujjat taqdim etilgan kun bo'ladi) — bu 15-bandning umumiy mezoni emas"}],"exp":"ПҚ-104 4-ilovasi ПП-332 1-ilovasining 15-bandini yangi tahrirda bayon qildi: kompleks ekspertiza muddatini hisoblash boshlanishi — xizmatlar qiymati to'langanligi tasdiqlangan sana. Bu qarorning 3-bandidagi «г» kichik band bilan mantiqan bog'liq: ekspertiza 100 foizli oldindan to'lov sharti bilan o'tkaziladi. Xuddi shu mantiq 2-ilovaning 21-bandida ham ko'rinadi — u yerda muddat hujjatlar taqdim etilgan VA ko'rsatilayotgan xizmatlar to'langan kundan hisoblanadi. Amaliy xulosa: to'lov kechiksa, ekspertiza soati umuman ishga tushmaydi. Alohida holat — 16-band: hujjatlar nokomplekt bo'lsa, Markaz 3 ish kuni ichida xabar beradi va boshlanish sanasi to'ldirilgan hujjat taqdim etilgan kun hisoblanadi.","tags":["muddat","to'lov"]},{"id":"pq-x-23","doc":"ПҚ-104","topic":"Tender","ref":"ПҚ-104 4-илова — ПП-332 2-илова п.4","difficulty":3,"q":"ПП-332 2-ilovasining 4-bandi yangi tahririga muvofiq kapital qurish va ta'mirlash bo'yicha qaysi hujjatlar Markazga qanday shaklda kiritiladi?","options":[{"t":"БҲМ ning 25 000 baravarigacha bo'lgan hujjatlar — texnik topshiriq shaklida","ok":false,"why":"Yo'nalish teskari: 4-band «свыше двадцатипятитысячкратного», ya'ni 25 000 БҲМ dan ORTIQ qiymatga taalluqli; undan pastdagilar bu band doirasiga kirmaydi"},{"t":"БҲМ ning 25 000 baravaridan ORTIQ qiymatdagi tovar (ish, xizmat)larni xarid qilish hujjatlari — texnik topshiriq shaklida loyiha-smeta hujjatlari bilan birgalikda; ekspertiza hajmlar va narx parametrlarining asosliligi yuzasidan o'tkaziladi","ok":true,"why":"4-band yangi tahriri aynan shunday: «свыше двадцатипятитысячкратного размера базовых расчетных величин, вносится в Центр в виде технического задания вместе с проектно-сметной документацией»"},{"t":"БҲМ ning 6 000 baravaridan ortiq barcha kapital qurilish hujjatlari — tender hujjatlari shaklida","ok":false,"why":"6 000 БҲМ — 3-banddagi byudjet buyurtmachisi uchun umumiy tender chegarasi; kapital qurilish uchun 4-bandda 25 000 БҲМ belgilangan"},{"t":"БҲМ ning 50 000 baravaridan ortiq hujjatlar — faqat loyiha-smeta hujjatlari shaklida, texnik topshiriqsiz","ok":false,"why":"Chegara ham, shakl ham xato: hujjat ТЗ shaklida, ЛСҲ bilan BIRGALIKDA kiritiladi"}],"exp":"ПП-332 2-ilovasining 4-bandi ПҚ-104 4-ilovasi bilan yangi tahrirda bayon qilindi: kapital qurish hamda bino, inshoot va muhandislik kommunikatsiyalarini ta'mirlash bo'yicha qiymati БҲМ ning 25 000 baravaridan ORTIQ bo'lgan xarid hujjatlari Markazga texnik topshiriq shaklida loyiha-smeta hujjatlari bilan BIRGALIKDA kiritiladi, ekspertiza esa faqat tovar (ish, xizmat) hajmlari va ularning narx parametrlari asosliligi qismida o'tkaziladi — ya'ni bu toifada ekspertiza predmeti toraytirilgan. Umumiy tender chegarasi (byudjet buyurtmachisi uchun 6 000, korporativ buyurtmachi uchun 25 000 БҲМ) 3-bandda alohida turadi va 4-band uni almashtirmaydi. Yana bir amaliy nuqta: 20-bandga ko'ra bunday ТЗ ekspertizasi uchun to'lov qurilish va ta'mirlash ishlari manzilli ro'yxati tasdiqlangandan keyin amalga oshiriladi.","tags":["chegara","kapital qurilish","ТЗ"]},{"id":"pq-x-24","doc":"ПҚ-104","topic":"Tender","ref":"ПҚ-104 4-илова — ПП-332 2-илова п.4¹","difficulty":2,"q":"ПП-332 2-ilovasiga qo'shilgan yangi 4¹-bandga muvofiq tender hujjatlari va texnik topshiriq qaysi holatda Markazda umuman ekspertizadan o'tkazilmaydi?","options":[{"t":"Buyurtmachi byudjet tashkiloti bo'lmaganda","ok":false,"why":"Korporativ buyurtmachi ham ekspertizadan chiqmaydi — 3-bandga ko'ra u uchun shunchaki boshqa (25 000 БҲМ) chegara amal qiladi"},{"t":"Buyurtmachi tarmoq ilmiy-texnik kengashining ijobiy xulosasini taqdim etganda","ok":false,"why":"ТИТК (ОНТС) xulosasi Markaz ekspertizasini almashtirmaydi — 1-ilovaning 18-bandi bo'yicha u faqat hujjat sifati uchun javobgarlikni bo'lishadi; 4¹-band esa faqat oliy darajadagi hujjat holatini nazarda tutadi"},{"t":"Tender hujjatlari va texnik topshiriq ISHLAB CHIQILGAN HOLDA qabul qilingan Prezident farmonlari va qarorlari, Vazirlar Mahkamasi qarorlarida nazarda tutilgan hollarda","ok":true,"why":"4¹-band: «не проводится экспертиза ... в случаях, предусмотренных указами и постановлениями Президента, постановлениями Кабинета Министров, принятыми с разработкой тендерной документации и технического задания»"},{"t":"Tender e'lon qilinganidan keyin hujjatlarga o'zgartirish kiritilganda","ok":false,"why":"E'lon Markaz ijobiy xulosasidan KEYIN chiqariladi (2-ilova 22-bandi); o'zgartirish kiritish ekspertizadan ozod qilmaydi"}],"exp":"ПҚ-104 4-ilovasi ПП-332 2-ilovasini yangi 4¹-band bilan to'ldirdi: agar tender hujjatlari va texnik topshiriq allaqachon ishlab chiqilgan holda Prezident farmoni/qarori yoki Vazirlar Mahkamasi qarori qabul qilingan bo'lsa va bunday holat o'sha hujjatda nazarda tutilgan bo'lsa, ular Markazda ekspertizadan o'tkazilmaydi. Shunga o'xshash qoida 1-ilovaning 3-bandiga ham «в» kichik band sifatida kiritilgan: loyihaoldi hujjat asosida qabul qilingan Prezident/VM hujjatlariga ko'ra kompleks ekspertizaga tortilmaydigan loyihalar Nizom doirasidan chiqariladi. Bosqich 0 (отказ triage) da bu — yurisdiksion asos: ariza mazmunan ko'rilmasdan oldin shu istisno tekshiriladi.","tags":["istisno","yurisdiksiya"]},{"id":"pq-x-26","doc":"Umumiy","topic":"Ekspertiza","ref":"ПҚ-4328 п.3 (УП-76); ПП-4024 п.7(в)","difficulty":2,"q":"AKT/ПО xaridida nima uchun ГУП «Центр кибербезопасности» xulosasi so'raladi?","options":[{"t":"Chunki u xaridning boshlang'ich narxini tasdiqlovchi hujjat hisoblanadi","ok":false,"why":"Kiberxavfsizlik markazi narxni baholamaydi; narx asoslash КП/birja kotirovkasi/прайс-лист orqali beriladi"},{"t":"Chunki ПП-4024 п.7(в) АКТ va dasturiy mahsulotlarga doir texnik topshiriqlarni Kiberxavfsizlik markazi bilan kelishishni majburiy qilgan","ok":false,"why":"YAQIN, LEKIN XATO: ПП-4024 п.7(в) haqiqatan ТЗ bo'yicha majburiy kelishuvni belgilaydi — ammo ГУП «Центр технического содействия» bilan, kiberxavfsizlik markazi bilan emas. ПП-4024 da «Центр кибербезопасности» umuman zikr etilmaydi"},{"t":"Chunki ЗРУ-547 bo'yicha shaxsiy ma'lumotlar operatorini davlat reyestriga u kiritadi","ok":false,"why":"Shaxsiy ma'lumotlar reyestri — ЗРУ-547 bo'yicha alohida vakolatli organ ishi, Kiberxavfsizlik markazi xulosasining maqsadi emas"},{"t":"Chunki ПҚ-4328 п.3 ga ko'ra axborot tizimi va ma'lumotlar bazasini reyestrga olish hamda amalda joriy etishga ruxsat Raqamli texnologiyalar vazirligi va Kiberxavfsizlik markazining ijobiy xulosasidan keyin beriladi","ok":true,"why":"ПҚ-4328 п.3 (УП-76, 24.05.2023) — xulosasiz ekspluatatsiyaga qabul, ishga tushirish va integratsiya TAQIQLANADI"}],"exp":"ГУП «Центр кибербезопасности» xulosasining aniq asosi — **ПҚ-4328 п.3**, УП-76 (24.05.2023) bilan qo'shilgan 5- va 6-xatboshilar: «Цифровое правительство» Yagona reyestriga olish va amalda joriy etishga ruxsat Raqamli texnologiyalar vazirligi va ГУП «Центр кибербезопасности» ijobiy xulosalaridan keyin beriladi; xulosasiz ekspluatatsiyaga qabul, ishga tushirish va integratsiya TAQIQLANADI.\n⚠️ IKKI MARKAZNI ADASHTIRMANG. ПП-4024 п.7(в) (01.01.2019 dan) ham ТЗ bo'yicha xulosani talab qiladi, lekin BOSHQA tashkilot bilan: АКТ, apparat vositalari, dasturiy mahsulotlar va himoya vositalariga doir texnik topshiriqlar bo'yicha xulosalar **ГУП «Центр технического содействия»** bilan majburiy kelishiladi; davlat organlari obyektlarida joriy etilayotgan apparat va ПО esa o'sha Markazda attestatsiya va ekspertizadan o'tadi. ПП-4024 matnida «Центр кибербезопасности» umuman uchramaydi (0 marta) — u ПҚ-4328 hujjati.","tags":["old shart","kiberxavfsizlik","возврат"]},{"id":"pq-x-27","doc":"Umumiy","topic":"Ekspertiza","ref":"ПҚ-104 п.6(б)","difficulty":2,"q":"Nima uchun loyihaoldi va xarid hujjatlari bo'yicha tarmoq ilmiy-texnik kengashi xulosasi so'raladi va u qanday rasmiylashtirilishi shart?","options":[{"t":"Kengash xulosasi loyihaning narx ko'rsatkichlarini tasdiqlaydi va uni Sanoat kooperatsiyasi va davlat xaridlari agentligi tasdiqlaydi","ok":false,"why":"ТИТК — ilmiy-texnik organ, narxni tasdiqlamaydi; ПҚ-104 п.6(б) bo'yicha xulosani Agentlik emas, buyurtmachi tashkilotning birinchi rahbari tasdiqlaydi"},{"t":"Kengash xulosasi loyihaning texnik-texnologik yechimi tarmoq darajasida qabul qilinganini tasdiqlaydi; ПҚ-104 п.6(б) ga muvofiq uning qarori (xulosasi) tegishli vazirlik, idora va tashkilotning birinchi rahbari tomonidan tasdiqlanishi SHART","ok":true,"why":"п.6(б) aynan shu talabni belgilaydi — tasdiqlanmagan ТИТК xulosasi to'liq hujjat hisoblanmaydi"},{"t":"Kengash xulosasini «Лойиҳалар ва харидлар самарадорлигини ошириш маркази» ДМ direktori tasdiqlaydi","ok":false,"why":"Markaz tashqi organ xulosasini tasdiqlamaydi — u faqat paketda mavjudligini va rasmiylashtirilganini tekshiradi"},{"t":"Kengash xulosasi tavsiyaviy xarakterga ega bo'lib, hech kim tomonidan tasdiqlanishi talab etilmaydi","ok":false,"why":"п.6(б) da «тасдиқланиши шарт» deb aniq majburiyat qo'yilgan"}],"exp":"ПҚ-104 п.6(б) tarmoq ilmiy-texnik kengashlarining loyihaoldi va xarid hujjatlari bo'yicha qarorlari (xulosalari) tegishli vazirlik, idora va tashkilotning birinchi rahbari tomonidan tasdiqlanishi shartligini belgilaydi. Ekspertizada bu ikki tomonlama tekshiriladi: (1) ТИТК xulosasi paketda bormi; (2) u birinchi rahbar tomonidan tasdiqlanganmi. Ayniqsa Markaz ekspertizasidan chiqarilgan loyihalarda bu — texnik yechim uchun asosiy sifat filtri.","tags":["old shart","ТИТК","tasdiqlash"]},{"id":"pq-x-28","doc":"Umumiy","topic":"Ekspertiza","ref":"ПҚ-104 п.10(а)(ii)","difficulty":2,"q":"Nima uchun xarid hujjatlari tasdiqlangan ТЭО/ТЭР ning asosiy texnik-iqtisodiy parametrlariga moslik yuzasidan tekshiriladi?","options":[{"t":"Chunki xarid summasi 6 000 БҲМ dan oshgan taqdirdagina ТЭО/ТЭР talab qilinadi","ok":false,"why":"6 000 БҲМ — byudjet buyurtmachisi uchun tender hujjatlari ekspertizasi chegarasi; ТЭО/ТЭР ga moslik tekshiruvining sharti emas"},{"t":"Kompleks ekspertizadan ijobiy xulosa olingan loyihalar doirasidagi xarid jarayonlari tasdiqlangan asosiy texnik-iqtisodiy parametrlarga mosligi yuzasidan monitoring qilinadi — hajm yoki narx parametri o'zgarsa, xarid tasdiqlangan bazadan chiqib ketadi","ok":true,"why":"ПҚ-104 п.10(а)(ii) aynan shu monitoringni va «Ягона инвестиция платформаси»га integratsiyani belgilaydi"},{"t":"Chunki ТЭО/ТЭР xulosasi tender e'lonini e'lon qilish o'rnini bosadi","ok":false,"why":"E'lon Markaz ijobiy xulosasidan keyin portalga qo'yiladi (ПП-332 2-ilova п.22); ТЭО/ТЭР xulosasi uni almashtirmaydi"},{"t":"Chunki ТЭО/ТЭР ekspertizasi «Шаҳарсозлик ҳужжатларини экспертиза қилиш республика маркази» ДМ tomonidan o'tkaziladi","ok":false,"why":"Шаҳарсозлик маркази — kapital qurilish tender hujjatlari va 50 ming БҲМ dan kam ishchi loyihalarga tegishli, ТЭО/ТЭР ga umuman emas"}],"exp":"ПҚ-104 п.10(а)(ii) Platformada ijobiy xulosa olgan loyihalar doirasidagi xarid jarayonlarini tasdiqlangan asosiy texnik-iqtisodiy parametrlarga (ТЭП) moslik yuzasidan monitoring qilishni va ma'lumotlarni «Ягона инвестиция платформаси» AT ga avtomatik uzatishni belgilaydi. Amaliyotda bu shuni bildiradi: xarid hajmi yoki narx parametri tasdiqlangan ТЭО/ТЭР dan chetlashsa, hujjat qayta ТЭО/ТЭР qatlamiga qaytadi — bu Markaz ekspertizasi doirasidagi oddiy замечание emas.","tags":["ТЭО","monitoring","parametr"]},{"id":"pq-x-29","doc":"Umumiy","topic":"Tender","ref":"ПП-332 Прил.2 п.14, п.24; п.6","difficulty":2,"q":"Nima uchun ekspertizaga kommersiya takliflari (КП) va solishtirma (сравнительная) jadval talab qilinadi?","options":[{"t":"КП faqat kelajakdagi yetkazib beruvchini oldindan tanlash uchun kerak","ok":false,"why":"Yetkazib beruvchi xarid protsedurasi natijasida aniqlanadi; КП esa narxni asoslash hujjati"},{"t":"Сравнительная jadval buyurtmachining yuridik xizmati xulosasi o'rnini bosadi","ok":false,"why":"Yuridik xulosa alohida hujjat (ПП-332 3-ilova п.8) va u narx asoslashni almashtirmaydi"},{"t":"Boshlang'ich narx birja kotirovkalari, КП va прайс-листлар asosida shakllantiriladi; Markaz uni bozor o'rtacha kon'yunkturasi bilan solishtiradi, boshlang'ich narx bozor o'rtachasidan oshsa — ijobiy xulosa berishdan rad etish asosi paydo bo'ladi","ok":true,"why":"ПП-332 2-ilova п.14 narx qismining manbalarini, п.24 esa bozor narxidan oshib ketish rad asosi ekanini belgilaydi"},{"t":"КП faqat import kontraktlar bo'yicha talab qilinadi","ok":false,"why":"Narx asoslash ichki xaridlarda ham majburiy — 2-ilovaning 6 va 7-bandlaridagi hujjatlar ro'yxatiga kiradi"}],"exp":"ПП-332 2-ilovasining 6 va 7-bandlariga ko'ra КП, birja kotirovkalari va прайс-листлар solishtirma jadval (сопоставительная таблица) ko'rinishida taqdim etiladi, barcha takliflar yuridik manzil va kontakt ma'lumotlarini o'z ichiga olishi hamda buyurtmachi imzosi/muhri yoki QR-kod bilan tasdiqlanishi shart. п.14 boshlang'ich narxni shu manbalar asosida shakllantirishni, п.5 narxning bozor o'rtachasiga mos bo'lishini, п.24 esa bozor o'rtachasidan oshib ketishni rad asosi sifatida belgilaydi. ПҚ-104 п.9(в) bu tahlilga ТСО ni ham qo'shdi.","tags":["narx","КП","rad asosi"]},{"id":"pq-x-30","doc":"Umumiy","topic":"Tender","ref":"ПП-332 Прил.2 п.5, п.10","difficulty":2,"q":"Nima uchun tender hujjatlarida ishtirokchining litsenziya (ruxsat) va boshqa kvalifikatsiya talablariga muvofiqligini tasdiqlash talab qilinadi?","options":[{"t":"Chunki litsenziya talabi har qanday holatda ishtirokchilar sonini asossiz cheklaydi va ekspertizada olib tashlanishi kerak","ok":false,"why":"Qonun hujjatlarida belgilangan litsenziya talabi qonuniy; asossiz cheklov — bu ПП-332 2-ilova п.12 dagi brend/model va o'lchanmaydigan talablar"},{"t":"ПП-332 2-ilovasining 5-bandiga muvofiq ishtirokchilar tomonidan qonun hujjatlarida belgilangan talablarga (litsenziya mavjudligi, ish tajribasi, moliyaviy holat, texnik jihozlanganlik) rioya etilishi ekspertiza predmetiga kiradi","ok":true,"why":"5-band aynan shu ro'yxatni beradi; ИУТ tarkibida ishtirokchiga talablar п.10 bo'yicha ko'rsatiladi"},{"t":"Chunki litsenziya faqat shartnoma Markazda ro'yxatga olinayotganda tekshiriladi","ok":false,"why":"Ro'yxatga olish — keyingi bosqich; kvalifikatsiya talablari tender hujjatlari ekspertizasida baholanadi"},{"t":"Chunki litsenziya talabi faqat qurilish sohasidagi xaridlarda qo'llaniladi","ok":false,"why":"5-band kvalifikatsiya talablarini «xarid obyektiga qarab» nazarda tutadi, soha bilan cheklamaydi"}],"exp":"ПП-332 2-ilovasining 5-bandi ekspertiza predmetini sanaydi, ular orasida — ishtirokchilar tomonidan qonun hujjatlarida belgilangan talablarga rioya etilishi (litsenziya mavjudligi, ish tajribasi, moliyaviy holat, texnik jihozlanganlik va xarid obyektiga qarab boshqa kvalifikatsiya talablari). Bu talablar ИУТ da (п.10) aks etadi. Ekspertizada ikki tomon baholanadi: talab qonuniy asosga egami va u ishtirokchilar doirasini asossiz toraytirmaydimi (п.12).","tags":["ИУТ","litsenziya","kvalifikatsiya"]},{"id":"pq-x-31","doc":"Umumiy","topic":"Texnik topshiriq","ref":"ЗРУ-547 «Шахсий маълумотлар тўғрисида»","difficulty":2,"q":"Nima uchun axborot tizimi loyihasida shaxsiy ma'lumotlarni qayta ishlash uchun ishlatiladigan texnik vositalarning joylashuvi tekshiriladi?","options":[{"t":"Chunki xorijiy bulut xizmatlari qo'shilgan qiymat solig'idan ozod qilinmaydi","ok":false,"why":"Bu soliq masalasi; ЗРУ-547 talabi soliq emas, ma'lumotlar lokalizatsiyasi bilan bog'liq"},{"t":"Chunki serverlar xorijda bo'lsa bojxona imtiyozlari berilmaydi","ok":false,"why":"Bojxona imtiyozlari boshqa tartib bilan (ВМ-750 nizomi, «Ўзбекэкспертиза» АЖ) tartibga solinadi"},{"t":"Chunki ЗРУ-547 xorijiy dasturiy ta'minotdan foydalanishni butunlay taqiqlaydi","ok":false,"why":"Qonun xorijiy ПО ni taqiqlamaydi — u ma'lumotlarni qayta ishlash texnik vositalarining joylashuviga talab qo'yadi"},{"t":"Chunki ЗРУ-547 ga muvofiq O'zbekiston Respublikasi fuqarolarining shaxsiy ma'lumotlarini qayta ishlash uchun foydalaniladigan texnik vositalar (serverlar, ma'lumotlar bazasi) O'zbekiston Respublikasi hududida joylashishi shart","ok":true,"why":"Lokalizatsiya talabi — ЗРУ-547 ning asosiy qoidasi; xorijiy bulutda (AWS/Azure) joylashtirish uni buzadi"}],"exp":"ЗРУ-547 «Шахсий маълумотлар тўғрисида» qonuni shaxsiy ma'lumotlarni yig'ish, qayta ishlash, saqlash va himoya qilish munosabatlarini tartibga soladi va O'zbekiston fuqarolarining shaxsiy ma'lumotlarini qayta ishlashda foydalaniladigan texnik vositalar mamlakat hududida joylashishini talab qiladi. Amaliyotda bu talab biometrik ma'lumot (yuz, holat), tibbiy ma'lumot yoki uzluksiz kuzatuv bilan ishlaydigan AI tizimlarda va xorijiy bulut infratuzilmasi ko'rsatilgan ТЗ larda tekshiriladi.","tags":["shaxsiy ma'lumot","lokalizatsiya","AI"]},{"id":"pq-x-32","doc":"Umumiy","topic":"Tender","ref":"ЗРУ-684 ст.46","difficulty":2,"q":"Xarid hajmini qismlarga bo'lish (дробление) qaysi holatda qonun buzilishi hisoblanadi?","options":[{"t":"Har qanday lotlarga bo'lish — xarid bir necha lotdan iborat bo'lishining o'zi buzilish","ok":false,"why":"Lot shakllantirish qonuniy: ПП-332 2-ilova п.8 har bir lot bir tur tovardan, foydalanish maqsadi va texnik xususiyatlariga qarab tuzilishini talab qiladi"},{"t":"Faqat bir kun ichida e'lon qilingan bir necha xarid bo'lgandagina","ok":false,"why":"Qonunda vaqt mezoni yo'q — mezon MAQSAD: raqobatli usuldan qochish"},{"t":"Davlat xaridi hajmini raqobatli xarid usullaridan qochish MAQSADIDA qismlarga bo'lish — ЗРУ-684 ning 46-moddasi bilan taqiqlangan","ok":true,"why":"ст.46 «Ограничения в процессе государственных закупок» ro'yxatida aynan shu formula bor"},{"t":"Faqat byudjet buyurtmachilariga nisbatan taqiqlanadi","ok":false,"why":"ст.46 cheklovlari davlat xaridi jarayoniga umuman taalluqli, buyurtmachi turiga qarab ajratilmagan"}],"exp":"ЗРУ-684 ning 46-moddasi davlat xaridi jarayonidagi cheklovlarni sanaydi, ular orasida — raqobatli xarid usullaridan qochish maqsadida xarid hajmini qismlarga bo'lish. Shu moddada texnologik va funksional jihatdan o'zaro bog'liq bo'lmagan tovar (ish, xizmat)larni bir xarid tarkibiga kiritish ham taqiqlanadi — ya'ni sun'iy ravishda birlashtirish ham, sun'iy bo'lish ham buzilish. Amaliy belgilar: bir buyurtmachi, bir predmet, yaqin sanalar, har biri chegaradan sal past summalar, bir xil ТЗ matni.","tags":["дробление","ст.46","raqobat"]},{"id":"pq-x-33","doc":"Umumiy","topic":"Shartnoma","ref":"ПП-332 Прил.3 п.8","difficulty":2,"q":"Nima uchun shartnoma (import kontrakti) ekspertizasida yuridik xulosa (юридическое заключение) talab qilinadi?","options":[{"t":"ПП-332 3-ilovasining 8-bandiga muvofiq hujjatlar to'plamiga yuridik xizmatning vizasi (yuridik xulosa) kiradi — u shartnoma loyihasining O'zbekiston Respublikasi qonunchiligiga muvofiqligini tasdiqlaydi","ok":true,"why":"8-band «юридическое заключение (виза юридической службы) о соответствии проекта договора ... законодательству» ni majburiy hujjat sifatida sanaydi"},{"t":"Chunki yuridik xulosa shartnoma narxining bozor darajasiga mosligini tasdiqlaydi","ok":false,"why":"Narx muvofiqligi alohida hujjatlar (КП, birja kotirovkasi, прайс-лист) bilan asoslanadi"},{"t":"Chunki yuridik xulosa ГУП «Центр кибербезопасности» xulosasi o'rnini bosadi","ok":false,"why":"Ular turli predmetlar: biri huquqiy muvofiqlik, ikkinchisi axborot xavfsizligi; biri ikkinchisini almashtirmaydi"},{"t":"Chunki yuridik xulosa faqat norezident bilan tuziladigan import kontraktlarda talab qilinadi","ok":false,"why":"8-band shartnoma va import kontrakti loyihalarining har ikkisi uchun bir xil hujjatlar ro'yxatini belgilaydi"}],"exp":"ПП-332 3-ilovasining 8-bandi shartnoma va import kontrakti loyihalarini ekspertiza va ro'yxatga olish uchun taqdim etiladigan hujjatlar ro'yxatini beradi: ariza, shartnoma loyihasi nusxasi, yuridik xizmat vizasi (yuridik xulosa), vakolatni tasdiqlovchi hujjat, narx asoslash, loyiha-smeta hujjati (kapital qurilish/ta'mirlashda), shartnoma zarurligining asoslanishi, tasdiqlangan ТЗ nusxasi, Prezident/Hukumat qarorlari nusxalari va moliyalashtirish manbai to'g'risidagi tasdiqlovchi xat. (Shartnoma loyihasining Ms Word/Ms Excel formatidagi elektron nusxasi esa 10-band bo'yicha Markaz talabiga ko'ra beriladi.) Hujjat to'plami to'liq bo'lmasa — 3-ilovaning 36-bandiga ko'ra ariza rad etiladi.","tags":["shartnoma","hujjat to'plami","возврат"]},{"id":"pq-x-34","doc":"Umumiy","topic":"Tender","ref":"ПП-332 Прил.2 п.14; ЗРУ-684 ст.46","difficulty":3,"q":"Nima uchun xarid hujjatlariga moliyalashtirish manbalari va miqdorini tasdiqlovchi hujjatlar ilova qilinishi so'raladi?","options":[{"t":"Chunki manba hujjati Markaz ekspertizasi to'lovi miqdorini belgilaydi","ok":false,"why":"To'lov xarid predmeti qiymatidan hisoblanadi (ПП-332 п.3(а)), moliyalashtirish manbasidan emas"},{"t":"ПП-332 2-ilovasining 14-bandiga muvofiq narx qismi tarkibiga moliyalashtirish manbalari va miqdorini tasdiqlovchi hujjatlar (kredit shartnomasi, bank ma'lumotnomasi, manzilli ro'yxat, organ qarori) kiradi; ЗРУ-684 ning 46-moddasi esa manba va miqdori tasdiqlanmagan yoxud ajratilgan mablag'dan ortiq summadagi xaridni taqiqlaydi","ok":true,"why":"Ikki norma birga ishlaydi: biri hujjat tarkibini, ikkinchisi taqiqni belgilaydi"},{"t":"Chunki bu talab faqat davlat tashqi qarzi hisobidan moliyalashtiriladigan xaridlarga qo'llaniladi","ok":false,"why":"14-band har qanday tender hujjatlarining narx qismiga taalluqli, moliyalashtirish manbaidan qat'i nazar"},{"t":"Chunki manba hujjati bojxona imtiyozini olish uchun asos bo'ladi","ok":false,"why":"Bojxona imtiyozlari alohida tartib bilan (imtiyozlar ro'yxati, «Ўзбекэкспертиза» АЖ) rasmiylashtiriladi"}],"exp":"ПП-332 2-ilovasining 14-bandi tender hujjatlari narx qismining majburiy tarkibini belgilaydi: yetkazib berish shartlari, to'lov shartlari va grafigi, boshlang'ich narx va uning manbalari, hamda kelgusi davlat xaridlarini moliyalashtirish manbalari va miqdorini tasdiqlovchi hujjatlar. ЗРУ-684 ning 46-moddasi esa moliyalashtirish manbalari va miqdorlari to'g'risida tasdiq bo'lmagan yoki ajratilgan mablag' hajmidan oshadigan summadagi davlat xaridini o'tkazishni taqiqlaydi. Shu sababli manba xati — komplektlik (Qatlam A) elementi.","tags":["moliyalashtirish","narx","возврат"]},{"id":"pq-x-35","doc":"Umumiy","topic":"Texnik topshiriq","ref":"ПП-332 Прил.2 п.11","difficulty":2,"q":"Nima uchun tasdiqlangan texnik topshiriqning tahrirlanadigan (Word) nusxasi va uning ПП-332 2-ilovasi 11-bandi bo'yicha to'liqligi talab qilinadi?","options":[{"t":"Chunki Word formati faqat Markaz arxivini yuritish uchun kerak","ok":false,"why":"Format so'rovi arxiv uchun emas — u ТЗ matnini 11-band maydonlari bo'yicha band-ma-band tekshirish va tuzatish imkonini beradi"},{"t":"Chunki 11-band boshlang'ich narxni hisoblash formulasini belgilaydi","ok":false,"why":"Narx hisoblash formulalari 4-ilovada (Инструкция); 11-band esa ТЗ mazmunini belgilaydi"},{"t":"Chunki 11-band ТЗ (tender hujjatlarining texnik qismi) mazmunining majburiy elementlarini belgilaydi — texnik xususiyatlar, markirovka/qadoqlash/tashish, tovar yangiligi va ishlab chiqarilgan yili, komplektatsiya, yetkazib berish joyi va muddati, kafolat va kafolatdan keyingi xizmat ko'rsatish, xodimlarni o'qitish, mualliflik huquqlari va boshqalar","ok":true,"why":"11-band «а» (tovar) va «б» (ish/xizmat) kichik bandlarida aynan shu majburiy maydonlar ro'yxatini beradi"},{"t":"Chunki 11-band shartnoma loyihasining majburiy bo'limlarini belgilaydi","ok":false,"why":"Shartnoma loyihasining majburiy tarkibi 3-ilovaning 13-bandida; 2-ilova п.11 — ТЗ mazmuni"}],"exp":"ПП-332 2-ilovasining 11-bandi texnik qism/ТЗ ning majburiy mazmunini ikki blokda beradi: tovar xaridi uchun (tavsif, sotib olish maqsadi, texnik xususiyatlar, markirovka va qadoqlash, tovar yangi va ishlatilmaganligi, komplektatsiya, xizmat ko'rsatish, miqdor va yetkazib berish joyi, kafolat va kafolatdan keyingi xizmat, ishlab chiqarilgan yili) va ish/xizmat xaridi uchun (nomi va maqsadi, hajm, aniq manzil, bajarish muddatlari, topshirish-qabul qilish tartibi, kafolat, mualliflik huquqlarining buyurtmachiga o'tishi). Markaz amaliyotida ТЗ ning Word (docx) nusxasi aynan shu maydonlarni band-ma-band tekshirish uchun so'raladi; hujjat to'liq bo'lmasa ariza qaytariladi.","tags":["ТЗ","majburiy maydon","format"]},{"id":"pq-x-36","doc":"Umumiy","topic":"Shartnoma","ref":"ПП-332 Прил.3 п.4","difficulty":3,"q":"Nima uchun qo'shimcha kelishuv (допсоглашение) ekspertizasida asosiy shartnoma ilgari Markaz ekspertizasidan o'tganligi so'raladi?","options":[{"t":"Chunki qo'shimcha kelishuv bo'yicha ekspertiza to'lovi ikki baravar undiriladi","ok":false,"why":"To'lov qo'shimcha kelishuv summasidan hisoblanadi (ПП-332 п.3(а)), ikki baravar qoidasi yo'q"},{"t":"Chunki qo'shimcha kelishuv faqat shartnoma summasi oshgan taqdirdagina ekspertiza qilinadi","ok":false,"why":"Summa va nomenklatura oshishi qo'shimcha hujjatlar talabini keltirib chiqaradi (3-ilova п.9), ekspertizaga tushish-tushmaslikni belgilovchi mezon esa 4-band"},{"t":"Chunki asosiy shartnoma nusxasi narx asoslash hujjati sifatida qabul qilinadi","ok":false,"why":"Narx asoslash КП, birja kotirovkasi va прайс-лист bilan beriladi; asosiy shartnoma bu yerda yurisdiksiya masalasini hal qiladi"},{"t":"ПП-332 3-ilovasining 4-bandiga muvofiq loyihasi ilgari Markaz ekspertizasidan O'TMAGAN shartnoma va import kontraktlariga doir qo'shimcha kelishuvlar, shuningdek majburiyatlari to'liq yoki qisman BAJARILGAN kontraktlar Markazda ekspertiza qilinmaydi","ok":true,"why":"4-band ikkala holatni ham ekspertiza doirasidan chiqaradi — bu yurisdiksion (Qatlam 0) asos"}],"exp":"ПП-332 3-ilovasining 4-bandi ikki yurisdiksion istisnoni belgilaydi: (1) tomonlarning majburiyatlari to'liq yoki qisman bajarilgan shartnoma/import kontrakti va ularga qo'shimcha kelishuvlar; (2) loyihasi ilgari Markaz ekspertizasidan o'tmagan shartnoma/import kontraktiga doir qo'shimcha kelishuvlar — Markazda ekspertiza qilinmaydi. Shuning uchun triage bosqichida birinchi savol: asosiy shartnoma Markazdan o'tganmi va majburiyatlar bajarilganmi. Javob salbiy bo'lsa mazmuniy ekspertizaga umuman o'tilmaydi, rasmiy xat bilan qaytariladi.","tags":["допсоглашение","yurisdiksiya","возврат"]}];
